class MCPCallError(RuntimeError):
    """A structured MCP request failed or returned a tool error."""


class MCPExecutionBoundaryError(RuntimeError):
    """An action-capable MCP request bypassed the Executor-owned port."""


class _MCPExecutionAuthority:
    """Unforgeable in-process authority held only by an Executor port."""


class _ExecutorMCPPort:
    """Narrow action transport created privately by :class:`MCPClient`.

    The port owns no planning, risk, verification, or observation logic. It
    exists solely to prevent a general ``MCPClient.call_tool`` from becoming an
    action API reachable by unrelated runtime modules.
    """

    def __init__(self, client: "MCPClient", authority: _MCPExecutionAuthority) -> None:
        self._client = client
        self._authority = authority

    def call_tool(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        return self._client._execute_tool(self._authority, name, arguments)


@dataclass(frozen=True)
class Snapshot:
    """The minimum observation the planner is allowed to reason over."""

    frontmost_name: str
    frontmost_bundle_id: str
    element_count: int
    source: str
    elements: tuple[dict[str, Any], ...]

    @classmethod
    def from_payload(cls, payload: dict[str, Any]) -> "Snapshot":
        frontmost = payload.get("frontmost") or {}
        raw_elements = payload.get("elements") or []
        elements = tuple(item for item in raw_elements if isinstance(item, dict))
        return cls(
            frontmost_name=str(frontmost.get("name") or ""),
            frontmost_bundle_id=str(frontmost.get("bundleId") or ""),
            element_count=int(payload.get("element_count") or len(elements)),
            source=str(payload.get("source") or "unknown"),
            elements=elements,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "frontmost": {
                "name": self.frontmost_name,
                "bundle_id": self.frontmost_bundle_id,
            },
            "element_count": self.element_count,
            "source": self.source,
        }


class ObservationUnavailable(RuntimeError):
    """A configured observation provider cannot produce a safe result."""


@dataclass(frozen=True)
class Observation:
    """Privacy-filtered, in-memory state returned by an observation provider.

    This is deliberately separate from ``Snapshot``. Snapshot remains the
    TEST-11 through TEST-20 runtime contract, including its live AX payload
    fields. Observation is the TEST-21 provider-facing schema: it never
    retains screenshots, text values, labels, coordinates, or raw responses.
    """

    source: str
    timestamp: int
    confidence: float
    elements: tuple[dict[str, Any], ...]
    semantic_labels: tuple[str, ...]

    SAFE_ROLES = frozenset(
        {"button", "switch", "slider", "text_field", "search_field", "image", "text", "other"}
    )
    SAFE_ELEMENT_KEYS = frozenset({"role", "interactive"})

    @classmethod
    def from_ax_payload(cls, payload: dict[str, Any]) -> "Observation":
        raw_elements = payload.get("elements") or []
        elements: list[dict[str, Any]] = []
        semantic_labels: list[str] = []
        for raw_element in raw_elements:
            if not isinstance(raw_element, dict):
                continue
            role = cls._safe_role(raw_element)
            element = {
                "role": role,
                "interactive": bool(
                    raw_element.get("clickable")
                    or raw_element.get("interactive")
                    or raw_element.get("enabled")
                ),
            }
            elements.append(element)
            if role not in semantic_labels:
                semantic_labels.append(role)

        return cls(
            source="AX",
            timestamp=int(time.time()),
            confidence=0.95 if elements else 0.70,
            elements=tuple(elements),
            semantic_labels=tuple(semantic_labels),
        )

    @classmethod
    def from_semantic_payload(
        cls,
        source: str,
        payload: dict[str, Any],
        *,
        element_keys: tuple[str, ...],
        default_role: str,
        default_confidence: float,
    ) -> "Observation":
        """Reduce a visual or OCR response before it crosses the provider boundary.

        Provider payloads may contain recognized text, rectangles, tap points,
        screenshots, or other replay-capable fields. This method consumes those
        values only long enough to classify a safe semantic role; none are kept
        in the returned Observation.
        """

        if source not in ObservationProviderRouter.PROVIDER_ORDER:
            raise ObservationUnavailable("unsupported observation source: %s" % source)
        if not isinstance(payload, dict):
            raise ObservationUnavailable("%s provider returned a non-object observation" % source)

        raw_elements: list[dict[str, Any]] = []
        for key in element_keys:
            candidate = payload.get(key)
            if not isinstance(candidate, list):
                continue
            raw_elements = [item for item in candidate if isinstance(item, dict)]
            if raw_elements:
                break

        elements: list[dict[str, Any]] = []
        semantic_labels: list[str] = []
        confidences: list[float] = []
        for raw_element in raw_elements:
            role = cls._safe_role(raw_element)
            if role == "other":
                role = default_role
            element = {
                "role": role,
                "interactive": bool(
                    raw_element.get("clickable")
                    or raw_element.get("interactive")
                    or raw_element.get("enabled")
                    or raw_element.get("actionable")
                ),
            }
            elements.append(element)
            if role not in semantic_labels:
                semantic_labels.append(role)
            candidate_confidence = raw_element.get("confidence")
            if isinstance(candidate_confidence, (int, float)) and not isinstance(candidate_confidence, bool):
                if 0.0 <= float(candidate_confidence) <= 1.0:
                    confidences.append(float(candidate_confidence))

        confidence = default_confidence if elements else 0.0
        if confidences:
            confidence = sum(confidences) / len(confidences)
        return cls(
            source=source,
            timestamp=int(time.time()),
            confidence=confidence,
            elements=tuple(elements),
            semantic_labels=tuple(semantic_labels),
        )

    @staticmethod
    def _safe_role(element: dict[str, Any]) -> str:
        """Classify only element type metadata; never export visible content."""

        candidates = (
            element.get("role"),
            element.get("element_type"),
            element.get("type"),
            element.get("class"),
            element.get("kind"),
        )
        value = next((str(item).casefold() for item in candidates if isinstance(item, str)), "")
        if "button" in value:
            return "button"
        if "switch" in value:
            return "switch"
        if "slider" in value:
            return "slider"
        if "text" in value and ("field" in value or "input" in value):
            return "text_field"
        if "search" in value:
            return "search_field"
        if "image" in value:
            return "image"
        if "text" in value or "label" in value:
            return "text"
        return "other"

    def schema(self) -> dict[str, Any]:
        """Return the public schema without raw AX, OCR, or visual payloads."""

        return {
            "source": self.source,
            "timestamp": self.timestamp,
            "confidence": self.confidence,
            "elements": [dict(element) for element in self.elements],
            "semantic_labels": list(self.semantic_labels),
        }

    def validate_public_schema(self) -> None:
        """Reject a future provider result that tries to add private payloads."""

        if not 0.0 <= self.confidence <= 1.0:
            raise ObservationUnavailable("observation confidence must be within 0.0 through 1.0")
        for element in self.elements:
            if set(element) != self.SAFE_ELEMENT_KEYS:
                raise ObservationUnavailable("observation element contains unsupported fields")
            if element.get("role") not in self.SAFE_ROLES:
                raise ObservationUnavailable("observation element has an unsupported semantic role")
            if not isinstance(element.get("interactive"), bool):
                raise ObservationUnavailable("observation element interaction metadata must be boolean")
        if any(label not in self.SAFE_ROLES for label in self.semantic_labels):
            raise ObservationUnavailable("observation contains an unsupported semantic label")


class ObservationProvider:
    """Read-only provider contract used by the TEST-21 observation router."""

    source = "unknown"

    def observe(self, read_screen: Callable[[], dict[str, Any]]) -> Observation:
        raise NotImplementedError


class AXObservationProvider(ObservationProvider):
    """Primary provider backed only by a read-only describe_screen transport."""

    source = "AX"

    def observe(self, read_screen: Callable[[], dict[str, Any]]) -> Observation:
        payload = read_screen()
        if not isinstance(payload, dict):
            raise ObservationUnavailable("AX provider returned a non-object observation")
        return Observation.from_ax_payload(payload)


class UnavailableObservationProvider(ObservationProvider):
    """Explicit interface placeholder for providers not connected in TEST-21."""

    def __init__(self, source: str) -> None:
        self.source = source

    def observe(self, read_screen: Callable[[], dict[str, Any]]) -> Observation:
        del read_screen
        raise ObservationUnavailable("%s provider is not connected" % self.source)


class VisionObservationProvider(ObservationProvider):
    """Optional read-only adapter for a future visual-region analyzer.

    TEST-22 defines the safe interface but does not connect a screenshot or VLM
    transport. An injected analyzer may describe UI regions, and its raw result
    is immediately reduced to the public Observation schema.
    """

    source = "Vision"

    def __init__(self, visual_reader: Callable[[], dict[str, Any]] | None = None) -> None:
        self._visual_reader = visual_reader

    def observe(self, read_screen: Callable[[], dict[str, Any]]) -> Observation:
        del read_screen
        if self._visual_reader is None:
            raise ObservationUnavailable("Vision provider is not connected")
        return Observation.from_semantic_payload(
            self.source,
            self._visual_reader(),
            element_keys=("semantic_elements", "regions", "elements"),
            default_role="other",
            default_confidence=0.80,
        )


class OCRObservationProvider(ObservationProvider):
    """Optional read-only adapter for describe_screen's OCR layer.

    The injected reader is deliberately narrower than MCPClient: it can only
    return one already-read OCR payload. OCR text and geometry never leave this
    method because Observation.from_semantic_payload strips them immediately.
    """

    source = "OCR"

    def __init__(self, ocr_reader: Callable[[], dict[str, Any]] | None = None) -> None:
        self._ocr_reader = ocr_reader

    def observe(self, read_screen: Callable[[], dict[str, Any]]) -> Observation:
        del read_screen
        if self._ocr_reader is None:
            raise ObservationUnavailable("OCR provider is not connected")
        return Observation.from_semantic_payload(
            self.source,
            self._ocr_reader(),
            element_keys=("ocr_texts", "ocr_elements", "text_blocks", "semantic_elements"),
            default_role="text",
            default_confidence=0.80,
        )


class VLMObservationProvider(UnavailableObservationProvider):
    def __init__(self) -> None:
        super().__init__("VLM")


class ObservationProviderRouter:
    """Try providers in the fixed AX, Vision, OCR, VLM priority order.

    Providers receive only a read-screen callable. They have no action-tool
    capability and cannot tap, type, launch, execute shell commands, or alter
    the device.
    """

    PROVIDER_ORDER = ("AX", "Vision", "OCR", "VLM")

    def __init__(self, providers: Iterable[ObservationProvider] | None = None) -> None:
        self.providers = tuple(
            providers
            or (
                AXObservationProvider(),
                VisionObservationProvider(),
                OCRObservationProvider(),
                VLMObservationProvider(),
            )
        )
        previous_index = -1
        for provider in self.providers:
            if provider.source not in self.PROVIDER_ORDER:
                raise ValueError("unsupported observation provider: %s" % provider.source)
            index = self.PROVIDER_ORDER.index(provider.source)
            if index <= previous_index:
                raise ValueError("observation providers must use the AX, Vision, OCR, VLM priority order")
            previous_index = index

    def observe(self, read_screen: Callable[[], dict[str, Any]]) -> Observation:
        failures = []
        for provider in self.providers:
            try:
                observation = provider.observe(read_screen)
            except ObservationUnavailable as error:
                failures.append("%s: %s" % (provider.source, error))
                continue
            if observation.source != provider.source:
                raise ObservationUnavailable("%s provider returned mismatched source" % provider.source)
            observation.validate_public_schema()
            if not self._is_sufficient(observation):
                failures.append("%s: insufficient safe semantic elements" % provider.source)
                continue
            return observation
        detail = "; ".join(failures) or "no providers configured"
        raise ObservationUnavailable("No observation provider produced a result: %s" % detail)

    @staticmethod
    def _is_sufficient(observation: Observation) -> bool:
        """Allow visual fallbacks only when no safe AX semantics were observed."""

        return bool(observation.elements)


class ObservationVerifier:
    """Pure verifier adapter for Observation; it never mutates observations."""

    def verify_nonempty(self, observation: Observation, minimum_element_count: int = 1) -> dict[str, Any]:
        if observation.source not in ObservationProviderRouter.PROVIDER_ORDER:
            return {"passed": False, "reason": "unknown_observation_source"}
        if not 0.0 <= observation.confidence <= 1.0:
            return {"passed": False, "reason": "invalid_observation_confidence"}
        return {
            "passed": len(observation.elements) >= max(0, int(minimum_element_count)),
            "source": observation.source,
            "confidence": observation.confidence,
            "observed_element_count": len(observation.elements),
        }


@dataclass(frozen=True)
class SemanticObservation:
    """A privacy-minimized semantic summary derived from one Observation.

    This is intentionally an aggregate. It contains no UI identifiers, element
    ordering, geometry, visible content, application identity, or original
    provider data, so it cannot serve as a replay script or private UI record.
    """

    source: str
    timestamp: int
    confidence: float
    page_type: str
    intents: tuple[dict[str, Any], ...]
    actionable: bool

    SAFE_PAGE_TYPES = frozenset({"search", "form", "settings", "content", "visual", "unknown"})
    SAFE_INTENTS = frozenset({"search", "text_entry", "activate", "toggle", "adjust", "inspect", "unknown"})
    SAFE_INTENT_KEYS = frozenset({"intent", "count", "actionable"})

    def schema(self) -> dict[str, Any]:
        """Return the public, aggregate-only semantic observation schema."""

        return {
            "source": self.source,
            "timestamp": self.timestamp,
            "confidence": self.confidence,
            "page_type": self.page_type,
            "intents": [dict(intent) for intent in self.intents],
            "actionable": self.actionable,
        }

    def validate_public_schema(self) -> None:
        """Reject private, replay-capable, or structurally invalid summaries."""

        if self.source not in ObservationProviderRouter.PROVIDER_ORDER:
            raise ObservationUnavailable("semantic observation has an unsupported source")
        if not isinstance(self.timestamp, int) or self.timestamp < 0:
            raise ObservationUnavailable("semantic observation timestamp must be a non-negative integer")
        if not 0.0 <= self.confidence <= 1.0:
            raise ObservationUnavailable("semantic observation confidence must be within 0.0 through 1.0")
        if self.page_type not in self.SAFE_PAGE_TYPES:
            raise ObservationUnavailable("semantic observation has an unsupported page type")
        if not isinstance(self.actionable, bool):
            raise ObservationUnavailable("semantic observation actionability must be boolean")
        for intent in self.intents:
            if set(intent) != self.SAFE_INTENT_KEYS:
                raise ObservationUnavailable("semantic observation intent contains unsupported fields")
            if intent.get("intent") not in self.SAFE_INTENTS:
                raise ObservationUnavailable("semantic observation has an unsupported element intent")
            if not isinstance(intent.get("count"), int) or intent["count"] < 1:
                raise ObservationUnavailable("semantic observation intent count must be positive")
            if not isinstance(intent.get("actionable"), bool):
                raise ObservationUnavailable("semantic observation intent actionability must be boolean")


class SemanticObservationIntelligence:
    """Classify only safe Observation metadata; it cannot observe or act."""

    _ROLE_TO_INTENT = {
        "search_field": "search",
        "text_field": "text_entry",
        "button": "activate",
        "switch": "toggle",
        "slider": "adjust",
        "text": "inspect",
        "image": "inspect",
        "other": "unknown",
    }

    def summarize(self, observation: Observation) -> SemanticObservation:
        """Build a deterministic aggregate without retaining provider payload data."""

        observation.validate_public_schema()
        intent_counts: dict[str, int] = {}
        intent_actionable: dict[str, bool] = {}
        roles: list[str] = []
        for element in observation.elements:
            role = str(element["role"])
            intent = self._ROLE_TO_INTENT[role]
            intent_counts[intent] = intent_counts.get(intent, 0) + 1
            intent_actionable[intent] = intent_actionable.get(intent, False) or bool(element["interactive"])
            roles.append(role)

        page_type = self._classify_page_type(roles)
        intents = tuple(
            {
                "intent": intent,
                "count": intent_counts[intent],
                "actionable": intent_actionable[intent],
            }
            for intent in self._ordered_intents(intent_counts)
        )
        confidence = self._semantic_confidence(observation.confidence, roles)
        semantic_observation = SemanticObservation(
            source=observation.source,
            timestamp=observation.timestamp,
            confidence=confidence,
            page_type=page_type,
            intents=intents,
            actionable=any(intent_actionable.values()),
        )
        semantic_observation.validate_public_schema()
        return semantic_observation

    @staticmethod
    def _classify_page_type(roles: Iterable[str]) -> str:
        role_set = set(roles)
        if "search_field" in role_set:
            return "search"
        if "text_field" in role_set:
            return "form"
        if "switch" in role_set or "slider" in role_set:
            return "settings"
        if "image" in role_set and role_set <= {"image", "text", "other"}:
            return "visual"
        if role_set:
            return "content"
        return "unknown"

    @classmethod
    def _ordered_intents(cls, intent_counts: dict[str, int]) -> tuple[str, ...]:
        return tuple(intent for intent in sorted(SemanticObservation.SAFE_INTENTS) if intent in intent_counts)

    @staticmethod
    def _semantic_confidence(provider_confidence: float, roles: Iterable[str]) -> float:
        role_list = tuple(roles)
        if not role_list:
            return 0.0
        resolved_count = sum(role != "other" for role in role_list)
        coverage = resolved_count / len(role_list)
        return round(provider_confidence * (0.65 + 0.35 * coverage), 4)


class SemanticUIGraphError(ObservationUnavailable):
    """A TEST-29 semantic graph violated its privacy or read-only contract."""


@dataclass(frozen=True)
class SemanticUIGraph:
    """An aggregate, non-executable graph for one provider-backed observation.

    Nodes describe semantic page and affordance categories, not individual UI
    elements.  The graph intentionally has no element identifier, ordering,
    visible label, coordinate, rectangle, screenshot, raw AX/OCR value, or
    opaque TEST-25 action binding.  It is therefore useful for understanding
    screen state but cannot function as a replayable action script.
    """

    graph_version: str
    source: str
    timestamp: int
    confidence: float
    state: str
    nodes: tuple[dict[str, Any], ...]
    edges: tuple[dict[str, Any], ...]

    SAFE_GRAPH_KEYS = frozenset({"graph_version", "source", "timestamp", "confidence", "state", "nodes", "edges"})
    SAFE_NODE_KEYS = frozenset({"type", "role", "capability", "state", "confidence", "source", "timestamp", "count"})
    SAFE_EDGE_KEYS = frozenset(
        {"from_type", "from_role", "relation", "to_type", "to_role", "confidence", "source", "timestamp"}
    )
    SAFE_GRAPH_STATES = frozenset({"verified", "ambiguous", "insufficient"})
    SAFE_NODE_STATES = frozenset({"verified", "ambiguous", "insufficient", "actionable", "read_only"})
    SAFE_NODE_TYPES = frozenset({"page", "affordance"})
    PAGE_CAPABILITY = "screen_context"
    AFFORDANCE_CAPABILITIES = {
        "search": "search_content",
        "text_entry": "enter_text",
        "activate": "activate_control",
        "toggle": "change_binary_value",
        "adjust": "adjust_value",
        "inspect": "inspect_content",
        "unknown": "unknown",
    }

    def schema(self) -> dict[str, Any]:
        """Return the exact public graph without provider or action payloads."""

        return {
            "graph_version": self.graph_version,
            "source": self.source,
            "timestamp": self.timestamp,
            "confidence": self.confidence,
            "state": self.state,
            "nodes": [dict(node) for node in self.nodes],
            "edges": [dict(edge) for edge in self.edges],
        }

    def validate_public_schema(self) -> None:
        """Reject private fields and any shape that could encode a UI replay."""

        if self.graph_version != SEMANTIC_UI_GRAPH_VERSION:
            raise SemanticUIGraphError("semantic UI graph has an unsupported version")
        if self.source not in ObservationProviderRouter.PROVIDER_ORDER:
            raise SemanticUIGraphError("semantic UI graph has an unsupported source")
        if not isinstance(self.timestamp, int) or isinstance(self.timestamp, bool) or self.timestamp < 0:
            raise SemanticUIGraphError("semantic UI graph timestamp must be a non-negative integer")
        self._validate_confidence(self.confidence, "semantic UI graph")
        if self.state not in self.SAFE_GRAPH_STATES:
            raise SemanticUIGraphError("semantic UI graph has an unsupported state")
        if not self.nodes:
            raise SemanticUIGraphError("semantic UI graph must contain one aggregate page node")

        page_roles: set[str] = set()
        affordance_roles: set[str] = set()
        for node in self.nodes:
            if set(node) != self.SAFE_NODE_KEYS:
                raise SemanticUIGraphError("semantic UI graph node contains unsupported fields")
            node_type = node.get("type")
            role = node.get("role")
            capability = node.get("capability")
            state = node.get("state")
            if node_type not in self.SAFE_NODE_TYPES:
                raise SemanticUIGraphError("semantic UI graph node has an unsupported type")
            if state not in self.SAFE_NODE_STATES:
                raise SemanticUIGraphError("semantic UI graph node has an unsupported state")
            if node.get("source") != self.source or node.get("timestamp") != self.timestamp:
                raise SemanticUIGraphError("semantic UI graph node provenance must match its graph")
            self._validate_confidence(node.get("confidence"), "semantic UI graph node")
            if not isinstance(node.get("count"), int) or isinstance(node.get("count"), bool) or node["count"] < 1:
                raise SemanticUIGraphError("semantic UI graph node count must be a positive integer")
            if node_type == "page":
                if role not in SemanticObservation.SAFE_PAGE_TYPES or capability != self.PAGE_CAPABILITY:
                    raise SemanticUIGraphError("semantic UI graph page node is invalid")
                if state != self.state or node["count"] != 1:
                    raise SemanticUIGraphError("semantic UI graph page node must describe this graph state")
                page_roles.add(role)
            else:
                if role not in SemanticObservation.SAFE_INTENTS or capability != self.AFFORDANCE_CAPABILITIES.get(role):
                    raise SemanticUIGraphError("semantic UI graph affordance node is invalid")
                if self.state != "verified" and state != self.state:
                    raise SemanticUIGraphError("uncertain graph nodes must retain the graph uncertainty state")
                affordance_roles.add(role)

        if len(page_roles) != 1:
            raise SemanticUIGraphError("semantic UI graph must contain exactly one page category")
        if len(affordance_roles) != len([node for node in self.nodes if node["type"] == "affordance"]):
            raise SemanticUIGraphError("semantic UI graph cannot duplicate affordance categories")

        for edge in self.edges:
            if set(edge) != self.SAFE_EDGE_KEYS:
                raise SemanticUIGraphError("semantic UI graph edge contains unsupported fields")
            if (
                edge.get("from_type") != "page"
                or edge.get("to_type") != "affordance"
                or edge.get("relation") != "contains"
                or edge.get("from_role") not in page_roles
                or edge.get("to_role") not in affordance_roles
            ):
                raise SemanticUIGraphError("semantic UI graph edge has an unsupported relation")
            if edge.get("source") != self.source or edge.get("timestamp") != self.timestamp:
                raise SemanticUIGraphError("semantic UI graph edge provenance must match its graph")
            self._validate_confidence(edge.get("confidence"), "semantic UI graph edge")

        if len(self.edges) != len(affordance_roles):
            raise SemanticUIGraphError("semantic UI graph must contain one aggregate edge per affordance category")

    @staticmethod
    def _validate_confidence(value: Any, subject: str) -> None:
        if not isinstance(value, (int, float)) or isinstance(value, bool) or not 0.0 <= float(value) <= 1.0:
            raise SemanticUIGraphError("%s confidence must be within 0.0 through 1.0" % subject)


class SemanticUIGraphBuilder:
    """Build a read-only semantic graph from one existing Provider Observation.

    The builder deliberately accepts an ``Observation`` rather than a client,
    provider, Plan, Skill, or action binding.  It has no device connection and
    cannot make a tool call.  The existing TEST-23 classifier is reused so
    TEST-29 does not create a second raw-observation interpretation path.
    """

    def __init__(self, intelligence: SemanticObservationIntelligence | None = None) -> None:
        self._intelligence = intelligence if intelligence is not None else SemanticObservationIntelligence()
        if not isinstance(self._intelligence, SemanticObservationIntelligence):
            raise TypeError("SemanticUIGraphBuilder requires SemanticObservationIntelligence")

    def build(self, observation: Observation) -> SemanticUIGraph:
        if not isinstance(observation, Observation):
            raise SemanticUIGraphError("semantic UI graph requires a provider Observation")
        observation.validate_public_schema()
        try:
            semantic = self._intelligence.summarize(observation)
        except ObservationUnavailable as error:
            raise SemanticUIGraphError("semantic UI graph requires a valid observation") from error
        state = self._graph_state(semantic)
        page_node = self._page_node(semantic, state)
        affordance_nodes = tuple(self._affordance_node(semantic, intent, state) for intent in semantic.intents)
        nodes = (page_node,) + affordance_nodes
        edges = tuple(self._edge(semantic, intent) for intent in semantic.intents)
        graph = SemanticUIGraph(
            graph_version=SEMANTIC_UI_GRAPH_VERSION,
            source=semantic.source,
            timestamp=semantic.timestamp,
            confidence=semantic.confidence,
            state=state,
            nodes=nodes,
            edges=edges,
        )
        graph.validate_public_schema()
        return graph

    @staticmethod
    def _graph_state(semantic: SemanticObservation) -> str:
        if not semantic.intents:
            return "insufficient"
        if semantic.source == "AX" and semantic.confidence >= 0.80:
            return "verified"
        return "ambiguous"

    @staticmethod
    def _page_node(semantic: SemanticObservation, state: str) -> dict[str, Any]:
        return {
            "type": "page",
            "role": semantic.page_type,
            "capability": SemanticUIGraph.PAGE_CAPABILITY,
            "state": state,
            "confidence": semantic.confidence,
            "source": semantic.source,
            "timestamp": semantic.timestamp,
            "count": 1,
        }

    @staticmethod
    def _affordance_node(semantic: SemanticObservation, intent: dict[str, Any], graph_state: str) -> dict[str, Any]:
        role = str(intent["intent"])
        state = graph_state if graph_state != "verified" else ("actionable" if intent["actionable"] else "read_only")
        return {
            "type": "affordance",
            "role": role,
            "capability": SemanticUIGraph.AFFORDANCE_CAPABILITIES[role],
            "state": state,
            "confidence": semantic.confidence,
            "source": semantic.source,
            "timestamp": semantic.timestamp,
            "count": int(intent["count"]),
        }

    @staticmethod
    def _edge(semantic: SemanticObservation, intent: dict[str, Any]) -> dict[str, Any]:
        return {
            "from_type": "page",
            "from_role": semantic.page_type,
            "relation": "contains",
            "to_type": "affordance",
            "to_role": str(intent["intent"]),
            "confidence": semantic.confidence,
            "source": semantic.source,
            "timestamp": semantic.timestamp,
        }


@dataclass(frozen=True)
class SemanticUIGraphDelta:
    """A bounded, aggregate-only state change between two semantic graphs."""

    source: str
    timestamp: int
    previous_state: str | None
    current_state: str
    state_changed: bool
    source_changed: bool
    added_roles: tuple[str, ...]
    removed_roles: tuple[str, ...]
    confidence_delta: float
    history_size: int

    SAFE_KEYS = frozenset(
        {
            "source",
            "timestamp",
            "previous_state",
            "current_state",
            "state_changed",
            "source_changed",
            "added_roles",
            "removed_roles",
            "confidence_delta",
            "history_size",
        }
    )

    def schema(self) -> dict[str, Any]:
        return {
            "source": self.source,
            "timestamp": self.timestamp,
            "previous_state": self.previous_state,
            "current_state": self.current_state,
            "state_changed": self.state_changed,
            "source_changed": self.source_changed,
            "added_roles": list(self.added_roles),
            "removed_roles": list(self.removed_roles),
            "confidence_delta": self.confidence_delta,
            "history_size": self.history_size,
        }

    def validate_public_schema(self, *, maximum_history: int) -> None:
        if set(self.schema()) != self.SAFE_KEYS:
            raise SemanticUIGraphError("semantic UI graph delta contains unsupported fields")
        if self.source not in ObservationProviderRouter.PROVIDER_ORDER:
            raise SemanticUIGraphError("semantic UI graph delta has an unsupported source")
        if not isinstance(self.timestamp, int) or isinstance(self.timestamp, bool) or self.timestamp < 0:
            raise SemanticUIGraphError("semantic UI graph delta timestamp is invalid")
        if self.previous_state is not None and self.previous_state not in SemanticUIGraph.SAFE_GRAPH_STATES:
            raise SemanticUIGraphError("semantic UI graph delta previous state is invalid")
        if self.current_state not in SemanticUIGraph.SAFE_GRAPH_STATES:
            raise SemanticUIGraphError("semantic UI graph delta current state is invalid")
        if not isinstance(self.state_changed, bool) or not isinstance(self.source_changed, bool):
            raise SemanticUIGraphError("semantic UI graph delta change flags must be boolean")
        if not isinstance(self.confidence_delta, (int, float)) or isinstance(self.confidence_delta, bool):
            raise SemanticUIGraphError("semantic UI graph delta confidence change is invalid")
        if not -1.0 <= float(self.confidence_delta) <= 1.0:
            raise SemanticUIGraphError("semantic UI graph delta confidence change is outside the valid range")
        if not isinstance(self.history_size, int) or isinstance(self.history_size, bool) or not 1 <= self.history_size <= maximum_history:
            raise SemanticUIGraphError("semantic UI graph delta history size is invalid")
        safe_roles = SemanticObservation.SAFE_INTENTS
        if any(role not in safe_roles for role in self.added_roles + self.removed_roles):
            raise SemanticUIGraphError("semantic UI graph delta contains an unsupported affordance role")


class GUIStateTracker:
    """Keep a short, in-memory observation window for one task owner.

    This tracker neither persists graphs nor reads a device.  It has no task
    identifier or user content input, so it cannot become a workflow log or a
    cross-task behavioral profile.  Its only output is a safe aggregate delta.
    """

    MAX_HISTORY_LIMIT = 5
    MAX_TTL_SECONDS = 300

    def __init__(self, *, max_history: int = 3, ttl_seconds: int = 30) -> None:
        if not isinstance(max_history, int) or isinstance(max_history, bool) or not 1 <= max_history <= self.MAX_HISTORY_LIMIT:
            raise ValueError("GUIStateTracker max_history must be between 1 and %d" % self.MAX_HISTORY_LIMIT)
        if not isinstance(ttl_seconds, int) or isinstance(ttl_seconds, bool) or not 1 <= ttl_seconds <= self.MAX_TTL_SECONDS:
            raise ValueError("GUIStateTracker ttl_seconds must be between 1 and %d" % self.MAX_TTL_SECONDS)
        self._max_history = max_history
        self._ttl_seconds = ttl_seconds
        self._history: list[SemanticUIGraph] = []

    def record(self, graph: SemanticUIGraph, *, now: int | None = None) -> SemanticUIGraphDelta:
        if not isinstance(graph, SemanticUIGraph):
            raise SemanticUIGraphError("GUIStateTracker requires SemanticUIGraph")
        graph.validate_public_schema()
        observed_at = graph.timestamp if now is None else now
        if not isinstance(observed_at, int) or isinstance(observed_at, bool) or observed_at < graph.timestamp:
            raise SemanticUIGraphError("GUIStateTracker now must be a current non-negative timestamp")
        self._history = [item for item in self._history if item.timestamp >= observed_at - self._ttl_seconds]
        if self._history and graph.timestamp < self._history[-1].timestamp:
            raise SemanticUIGraphError("GUIStateTracker graph timestamps must be non-decreasing")
        previous = self._history[-1] if self._history else None
        delta = self._build_delta(previous, graph, history_size=min(len(self._history) + 1, self._max_history))
        self._history.append(graph)
        self._history = self._history[-self._max_history :]
        delta.validate_public_schema(maximum_history=self._max_history)
        return delta

    @staticmethod
    def _build_delta(
        previous: SemanticUIGraph | None,
        current: SemanticUIGraph,
        *,
        history_size: int,
    ) -> SemanticUIGraphDelta:
        previous_roles = GUIStateTracker._affordance_roles(previous) if previous is not None else frozenset()
        current_roles = GUIStateTracker._affordance_roles(current)
        previous_confidence = previous.confidence if previous is not None else current.confidence
        return SemanticUIGraphDelta(
            source=current.source,
            timestamp=current.timestamp,
            previous_state=previous.state if previous is not None else None,
            current_state=current.state,
            state_changed=previous is not None and previous.state != current.state,
            source_changed=previous is not None and previous.source != current.source,
            added_roles=tuple(sorted(current_roles.difference(previous_roles))),
            removed_roles=tuple(sorted(previous_roles.difference(current_roles))),
            confidence_delta=round(float(current.confidence - previous_confidence), 4),
            history_size=history_size,
        )

    @staticmethod
    def _affordance_roles(graph: SemanticUIGraph) -> frozenset[str]:
        return frozenset(str(node["role"]) for node in graph.nodes if node["type"] == "affordance")


class VisualIntelligencePolicyError(ValueError):
    """A TEST-40.1 visual contract attempted to retain unsafe or ambiguous data."""


class ActiveVisionStateError(VisualIntelligencePolicyError):
    """The visual state machine received an unsafe lifecycle transition."""


@dataclass(frozen=True)
class VisualEvidence:
    """One redacted semantic evidence item for a visual interpretation.

    Evidence is intentionally not a capture record. It can say that a safe
    semantic graph or domain signal was observed, but cannot retain pixels,
    text, geometry, app identity, or a device action target.
    """

    source_type: str
    confidence: float
    timestamp: int
    entity_type: str
    evidence_class: str

    SAFE_ENTITY_TYPES = frozenset(
        {"screen_context", "interaction_affordance", "domain_context", "unknown"}
    )
    SAFE_EVIDENCE_CLASSES = frozenset({"semantic_graph", "domain_signal"})
    SAFE_KEYS = frozenset({"source_type", "confidence", "timestamp", "entity_type", "evidence_class"})

    def schema(self) -> dict[str, Any]:
        return {
            "source_type": self.source_type,
            "confidence": self.confidence,
            "timestamp": self.timestamp,
            "entity_type": self.entity_type,
            "evidence_class": self.evidence_class,
        }

    def validate_public_schema(self) -> None:
        if set(self.schema()) != self.SAFE_KEYS:
            raise VisualIntelligencePolicyError("visual evidence contains unsupported fields")
        if self.source_type not in ObservationProviderRouter.PROVIDER_ORDER:
            raise VisualIntelligencePolicyError("visual evidence has an unsupported source")
        if not isinstance(self.confidence, (int, float)) or isinstance(self.confidence, bool):
            raise VisualIntelligencePolicyError("visual evidence confidence is invalid")
        if not 0.0 <= float(self.confidence) <= 1.0:
            raise VisualIntelligencePolicyError("visual evidence confidence is outside safe bounds")
        if not isinstance(self.timestamp, int) or isinstance(self.timestamp, bool) or self.timestamp < 0:
            raise VisualIntelligencePolicyError("visual evidence timestamp is invalid")
        if self.entity_type not in self.SAFE_ENTITY_TYPES:
            raise VisualIntelligencePolicyError("visual evidence has an unsupported entity type")
        if self.evidence_class not in self.SAFE_EVIDENCE_CLASSES:
            raise VisualIntelligencePolicyError("visual evidence has an unsupported evidence class")


class VisualEvidenceLayer:
    """Bounded in-memory evidence store with no capture, OCR, or action data."""

    MAX_RECORDS = 32

    def __init__(self, *, capacity: int = MAX_RECORDS) -> None:
        if not isinstance(capacity, int) or isinstance(capacity, bool) or not 1 <= capacity <= self.MAX_RECORDS:
            raise VisualIntelligencePolicyError("visual evidence capacity is invalid")
        self._capacity = capacity
        self._records: list[VisualEvidence] = []

    def record(self, evidence: VisualEvidence) -> VisualEvidence:
        if not isinstance(evidence, VisualEvidence):
            raise VisualIntelligencePolicyError("visual evidence layer accepts only VisualEvidence")
        evidence.validate_public_schema()
        self._records.append(evidence)
        self._records = self._records[-self._capacity :]
        return evidence

    def records(self) -> tuple[VisualEvidence, ...]:
        return tuple(self._records)


@dataclass(frozen=True)
class VisualDomainSignal:
    """A pre-filtered, non-textual domain signal from a future provider."""

    domain: str
    source_type: str
    confidence: float
    timestamp: int

    def validate(self) -> None:
        if VisualDomainResolver._DOMAIN_ID_RE.fullmatch(self.domain) is None:
            raise VisualIntelligencePolicyError("visual domain signal has an invalid domain")
        if self.source_type not in ObservationProviderRouter.PROVIDER_ORDER:
            raise VisualIntelligencePolicyError("visual domain signal has an unsupported source")
        if not isinstance(self.confidence, (int, float)) or isinstance(self.confidence, bool):
            raise VisualIntelligencePolicyError("visual domain signal confidence is invalid")
        if not 0.0 <= float(self.confidence) <= 1.0:
            raise VisualIntelligencePolicyError("visual domain signal confidence is outside safe bounds")
        if not isinstance(self.timestamp, int) or isinstance(self.timestamp, bool) or self.timestamp < 0:
            raise VisualIntelligencePolicyError("visual domain signal timestamp is invalid")


@dataclass(frozen=True)
class VisualDomainResolution:
    """A deterministic domain outcome; never a private knowledge query."""

    domain: str
    status: str
    confidence: float
    reason_codes: tuple[str, ...]

    RESOLVED = "RESOLVED"
    NEEDS_CONFIRMATION = "NEEDS_CONFIRMATION"


class VisualDomainResolver:
    """Resolve only registered semantic domain IDs using bounded signals.

    The resolver does not inspect an image, read a document, query Knowledge,
    or infer a domain from free text. Future adapters must first reduce their
    output to :class:`VisualDomainSignal`.
    """

    MIN_DOMAIN_CONFIDENCE = 0.80
    CONFLICT_DELTA = 0.05
    MAX_SIGNALS = 4
    _DOMAIN_ID_RE = re.compile(r"^[a-z][a-z0-9_]{2,47}$")

    def __init__(self, registered_domains: Iterable[str] = ()) -> None:
        normalized_domains = frozenset(self._domain_id(value) for value in registered_domains)
        self._registered_domains = normalized_domains

    def resolve(self, signals: Iterable[VisualDomainSignal]) -> VisualDomainResolution:
        collected = tuple(signals)
        if len(collected) > self.MAX_SIGNALS:
            raise VisualIntelligencePolicyError("visual domain signal capacity exceeded")
        for signal in collected:
            if not isinstance(signal, VisualDomainSignal):
                raise VisualIntelligencePolicyError("visual domain resolver requires VisualDomainSignal values")
            signal.validate()
        if not collected:
            return VisualDomainResolution("UNKNOWN_DOMAIN", "NEEDS_CONFIRMATION", 0.0, ("missing_domain_signal",))

        registered = tuple(signal for signal in collected if signal.domain in self._registered_domains)
        if not registered:
            return VisualDomainResolution(
                "UNKNOWN_DOMAIN", "NEEDS_CONFIRMATION", 0.0, ("unregistered_domain_signal",)
            )

        ordered = tuple(sorted(registered, key=lambda signal: (-float(signal.confidence), signal.domain)))
        highest = ordered[0]
        alternatives = tuple(signal for signal in ordered[1:] if signal.domain != highest.domain)
        if alternatives and float(highest.confidence) - float(alternatives[0].confidence) <= self.CONFLICT_DELTA:
            return VisualDomainResolution(
                "UNKNOWN_DOMAIN",
                "NEEDS_CONFIRMATION",
                round(float(highest.confidence), 4),
                ("conflicting_domain_signals",),
            )
        if float(highest.confidence) < self.MIN_DOMAIN_CONFIDENCE:
            return VisualDomainResolution(
                highest.domain,
                "NEEDS_CONFIRMATION",
                round(float(highest.confidence), 4),
                ("low_domain_confidence",),
            )
        return VisualDomainResolution(
            highest.domain,
            "RESOLVED",
            round(float(highest.confidence), 4),
            ("domain_resolved",),
        )

    @classmethod
    def _domain_id(cls, value: Any) -> str:
        normalized = str(value or "").strip()
        if cls._DOMAIN_ID_RE.fullmatch(normalized) is None:
            raise VisualIntelligencePolicyError("registered visual domain must be a semantic identifier")
        return normalized


@dataclass(frozen=True)
class VisualSemanticCandidate:
    """Safe candidate output for a future Planner integration.

    This value is deliberately informational. It has no tool, selector,
    application, capture, or execution field, so it cannot cause a device
    operation by itself.
    """

    visual_intelligence_version: str
    candidate_id: str
    status: str
    confidence: float
    detected_entity_types: tuple[str, ...]
    domain: str
    source_types: tuple[str, ...]
    evidence: tuple[VisualEvidence, ...]
    reason_codes: tuple[str, ...]
    timestamp: int
    expires_at: int

    SAFE_KEYS = frozenset(
        {
            "visual_intelligence_version",
            "candidate_id",
            "status",
            "confidence",
            "detected_entity_types",
            "domain",
            "source_types",
            "evidence",
            "reason_codes",
            "timestamp",
            "expires_at",
            "decision_effect",
            "execution_authority",
        }
    )
    SAFE_STATUSES = frozenset({"READY", "NEEDS_CONFIRMATION"})
    SAFE_REASON_CODES = frozenset(
        {
            "low_visual_confidence",
            "confidence_uncalibrated",
            "no_text_detected",
            "graph_not_verified",
            "missing_domain_signal",
            "unregistered_domain_signal",
            "conflicting_domain_signals",
            "low_domain_confidence",
        }
    )
    _CANDIDATE_ID_RE = re.compile(r"^visual\.[0-9a-f]{32}$")

    def schema(self) -> dict[str, Any]:
        return {
            "visual_intelligence_version": self.visual_intelligence_version,
            "candidate_id": self.candidate_id,
            "status": self.status,
            "confidence": self.confidence,
            "detected_entity_types": list(self.detected_entity_types),
            "domain": self.domain,
            "source_types": list(self.source_types),
            "evidence": [item.schema() for item in self.evidence],
            "reason_codes": list(self.reason_codes),
            "timestamp": self.timestamp,
            "expires_at": self.expires_at,
            "decision_effect": "none",
            "execution_authority": "none",
        }

    def validate_public_schema(self) -> None:
        if set(self.schema()) != self.SAFE_KEYS:
            raise VisualIntelligencePolicyError("visual semantic candidate contains unsupported fields")
        if self.visual_intelligence_version != VISUAL_INTELLIGENCE_FOUNDATION_VERSION:
            raise VisualIntelligencePolicyError("visual semantic candidate has an unsupported version")
        if self._CANDIDATE_ID_RE.fullmatch(self.candidate_id) is None:
            raise VisualIntelligencePolicyError("visual semantic candidate ID is invalid")
        if self.status not in self.SAFE_STATUSES:
            raise VisualIntelligencePolicyError("visual semantic candidate has an unsupported status")
        if not isinstance(self.confidence, (int, float)) or isinstance(self.confidence, bool):
            raise VisualIntelligencePolicyError("visual semantic candidate confidence is invalid")
        if not 0.0 <= float(self.confidence) <= 1.0:
            raise VisualIntelligencePolicyError("visual semantic candidate confidence is outside safe bounds")
        if not self.detected_entity_types or any(
            item not in VisualEvidence.SAFE_ENTITY_TYPES.difference({"domain_context"})
            for item in self.detected_entity_types
        ):
            raise VisualIntelligencePolicyError("visual semantic candidate has invalid entity types")
        canonical_entity_order = tuple(
            entity_type
            for entity_type in ("screen_context", "interaction_affordance", "unknown")
            if entity_type in self.detected_entity_types
        )
        if canonical_entity_order != self.detected_entity_types:
            raise VisualIntelligencePolicyError("visual semantic candidate entity types must be unique and ordered")
        if self.domain != "UNKNOWN_DOMAIN" and VisualDomainResolver._DOMAIN_ID_RE.fullmatch(self.domain) is None:
            raise VisualIntelligencePolicyError("visual semantic candidate has an invalid domain")
        if not self.source_types or any(item not in ObservationProviderRouter.PROVIDER_ORDER for item in self.source_types):
            raise VisualIntelligencePolicyError("visual semantic candidate has invalid source metadata")
        if tuple(sorted(set(self.source_types), key=ObservationProviderRouter.PROVIDER_ORDER.index)) != self.source_types:
            raise VisualIntelligencePolicyError("visual semantic candidate source metadata must be ordered and unique")
        if not self.evidence:
            raise VisualIntelligencePolicyError("visual semantic candidate requires evidence")
        for item in self.evidence:
            if not isinstance(item, VisualEvidence):
                raise VisualIntelligencePolicyError("visual semantic candidate has invalid evidence")
            item.validate_public_schema()
        if set(item.source_type for item in self.evidence) != set(self.source_types):
            raise VisualIntelligencePolicyError("visual semantic candidate source evidence is inconsistent")
        if any(code not in self.SAFE_REASON_CODES for code in self.reason_codes):
            raise VisualIntelligencePolicyError("visual semantic candidate has an unsupported reason code")
        if tuple(sorted(set(self.reason_codes))) != self.reason_codes:
            raise VisualIntelligencePolicyError("visual semantic candidate reason codes must be unique and ordered")
        if not isinstance(self.timestamp, int) or isinstance(self.timestamp, bool) or self.timestamp < 0:
            raise VisualIntelligencePolicyError("visual semantic candidate timestamp is invalid")
        if not isinstance(self.expires_at, int) or isinstance(self.expires_at, bool) or self.expires_at <= self.timestamp:
            raise VisualIntelligencePolicyError("visual semantic candidate expiry is invalid")
        if self.status == "READY" and (self.domain == "UNKNOWN_DOMAIN" or self.reason_codes):
            raise VisualIntelligencePolicyError("ready visual semantic candidate cannot be unresolved")
        if self.status == "NEEDS_CONFIRMATION" and not self.reason_codes:
            raise VisualIntelligencePolicyError("unresolved visual semantic candidate requires an explanation")


@dataclass(frozen=True)
class VisualScreenPattern:
    """A bounded aggregate-only future visual memory entry."""

    visual_intelligence_version: str
    pattern_id: str
    pattern_class: str
    domain: str
    source_types: tuple[str, ...]
    detected_entity_types: tuple[str, ...]
    mean_confidence: float
    observed_count: int
    first_observed_at: int
    last_observed_at: int

    SAFE_PATTERN_CLASSES = SemanticObservation.SAFE_PAGE_TYPES
    SAFE_KEYS = frozenset(
        {
            "visual_intelligence_version",
            "pattern_id",
            "pattern_class",
            "domain",
            "source_types",
            "detected_entity_types",
            "mean_confidence",
            "observed_count",
            "first_observed_at",
            "last_observed_at",
        }
    )
    _PATTERN_ID_RE = re.compile(r"^pattern\.[0-9a-f]{32}$")

    def schema(self) -> dict[str, Any]:
        return {
            "visual_intelligence_version": self.visual_intelligence_version,
            "pattern_id": self.pattern_id,
            "pattern_class": self.pattern_class,
            "domain": self.domain,
            "source_types": list(self.source_types),
            "detected_entity_types": list(self.detected_entity_types),
            "mean_confidence": self.mean_confidence,
            "observed_count": self.observed_count,
            "first_observed_at": self.first_observed_at,
            "last_observed_at": self.last_observed_at,
        }

    def validate_public_schema(self) -> None:
        if set(self.schema()) != self.SAFE_KEYS:
            raise VisualIntelligencePolicyError("visual screen pattern contains unsupported fields")
        if self.visual_intelligence_version != VISUAL_INTELLIGENCE_FOUNDATION_VERSION:
            raise VisualIntelligencePolicyError("visual screen pattern has an unsupported version")
        if self._PATTERN_ID_RE.fullmatch(self.pattern_id) is None:
            raise VisualIntelligencePolicyError("visual screen pattern ID is invalid")
        if self.pattern_class not in self.SAFE_PATTERN_CLASSES:
            raise VisualIntelligencePolicyError("visual screen pattern has an unsupported class")
        if VisualDomainResolver._DOMAIN_ID_RE.fullmatch(self.domain) is None:
            raise VisualIntelligencePolicyError("visual screen pattern domain is invalid")
        if not self.source_types or any(item not in ObservationProviderRouter.PROVIDER_ORDER for item in self.source_types):
            raise VisualIntelligencePolicyError("visual screen pattern has invalid source metadata")
        if not self.detected_entity_types or any(
            item not in VisualEvidence.SAFE_ENTITY_TYPES.difference({"domain_context"})
            for item in self.detected_entity_types
        ):
            raise VisualIntelligencePolicyError("visual screen pattern has invalid entity types")
        if not isinstance(self.mean_confidence, (int, float)) or isinstance(self.mean_confidence, bool):
            raise VisualIntelligencePolicyError("visual screen pattern confidence is invalid")
        if not 0.0 <= float(self.mean_confidence) <= 1.0:
            raise VisualIntelligencePolicyError("visual screen pattern confidence is outside safe bounds")
        if not isinstance(self.observed_count, int) or isinstance(self.observed_count, bool) or self.observed_count < 1:
            raise VisualIntelligencePolicyError("visual screen pattern observation count is invalid")
        if not isinstance(self.first_observed_at, int) or not isinstance(self.last_observed_at, int):
            raise VisualIntelligencePolicyError("visual screen pattern timestamps are invalid")
        if self.first_observed_at < 0 or self.last_observed_at < self.first_observed_at:
            raise VisualIntelligencePolicyError("visual screen pattern timestamp ordering is invalid")


class VisualMemoryInterface:
    """Store bounded semantic pattern statistics without images or action data.

    This interface is intentionally in-memory. It is not Agent Memory, a
    Knowledge store, a screenshot cache, or a workflow recorder. Any durable
    visual-learning design requires its own later consent and retention review.
    """

    MAX_PATTERNS = 16

    def __init__(self, *, capacity: int = MAX_PATTERNS) -> None:
        if not isinstance(capacity, int) or isinstance(capacity, bool) or not 1 <= capacity <= self.MAX_PATTERNS:
            raise VisualIntelligencePolicyError("visual memory capacity is invalid")
        self._capacity = capacity
        self._patterns: dict[tuple[str, str, tuple[str, ...], tuple[str, ...]], VisualScreenPattern] = {}

    def record_pattern(self, candidate: VisualSemanticCandidate, *, pattern_class: str) -> VisualScreenPattern:
        if not isinstance(candidate, VisualSemanticCandidate):
            raise VisualIntelligencePolicyError("visual memory requires a visual semantic candidate")
        candidate.validate_public_schema()
        if candidate.status != "READY":
            raise VisualIntelligencePolicyError("visual memory cannot learn from an unresolved candidate")
        if pattern_class not in VisualScreenPattern.SAFE_PATTERN_CLASSES:
            raise VisualIntelligencePolicyError("visual memory pattern class is invalid")
        key = (candidate.domain, pattern_class, candidate.source_types, candidate.detected_entity_types)
        previous = self._patterns.get(key)
        if previous is None:
            if len(self._patterns) >= self._capacity:
                oldest_key = min(
                    self._patterns,
                    key=lambda existing: self._patterns[existing].last_observed_at,
                )
                del self._patterns[oldest_key]
            pattern = VisualScreenPattern(
                visual_intelligence_version=VISUAL_INTELLIGENCE_FOUNDATION_VERSION,
                pattern_id="pattern.%s" % uuid4().hex,
                pattern_class=pattern_class,
                domain=candidate.domain,
                source_types=candidate.source_types,
                detected_entity_types=candidate.detected_entity_types,
                mean_confidence=round(float(candidate.confidence), 4),
                observed_count=1,
                first_observed_at=candidate.timestamp,
                last_observed_at=candidate.timestamp,
            )
        else:
            observed_count = previous.observed_count + 1
            pattern = replace(
                previous,
                mean_confidence=round(
                    ((previous.mean_confidence * previous.observed_count) + float(candidate.confidence)) / observed_count,
                    4,
                ),
                observed_count=observed_count,
                last_observed_at=max(previous.last_observed_at, candidate.timestamp),
            )
        pattern.validate_public_schema()
        self._patterns[key] = pattern
        return pattern

    def patterns(self) -> tuple[VisualScreenPattern, ...]:
        return tuple(sorted(self._patterns.values(), key=lambda item: (item.last_observed_at, item.pattern_id)))


class ActiveVisionStateMachine:
    """Track future visual lifecycle state without observation or action authority.

    `TASK_EXECUTION` is a state signal for a future orchestrator. This class
    cannot execute a task, reach MCP, or replay an observed visual pattern.
    """

    STATES = frozenset({"OFF", "USER_REQUESTED", "ACTIVE_OBSERVATION", "TASK_EXECUTION", "VERIFY", "STOP"})
    TRANSITIONS = {
        "OFF": frozenset({"USER_REQUESTED"}),
        "USER_REQUESTED": frozenset({"ACTIVE_OBSERVATION", "STOP"}),
        "ACTIVE_OBSERVATION": frozenset({"TASK_EXECUTION", "VERIFY", "STOP"}),
        "TASK_EXECUTION": frozenset({"VERIFY", "STOP"}),
        "VERIFY": frozenset({"STOP"}),
        "STOP": frozenset({"OFF"}),
    }

    def __init__(self) -> None:
        self._state = "OFF"
        self._history: list[dict[str, Any]] = [{"state": "OFF", "timestamp": 0}]

    @property
    def state(self) -> str:
        return self._state

    def request(self, *, timestamp: int | None = None) -> str:
        return self._transition("USER_REQUESTED", timestamp)

    def begin_observation(self, *, timestamp: int | None = None) -> str:
        return self._transition("ACTIVE_OBSERVATION", timestamp)

    def begin_task_execution(self, *, timestamp: int | None = None) -> str:
        return self._transition("TASK_EXECUTION", timestamp)

    def begin_verification(self, *, timestamp: int | None = None) -> str:
        return self._transition("VERIFY", timestamp)

    def stop(self, *, timestamp: int | None = None) -> str:
        return self._transition("STOP", timestamp)

    def reset(self, *, timestamp: int | None = None) -> str:
        return self._transition("OFF", timestamp)

    def history(self) -> tuple[dict[str, int | str], ...]:
        return tuple(dict(item) for item in self._history)

    def _transition(self, target: str, timestamp: int | None) -> str:
        if target not in self.STATES or target not in self.TRANSITIONS[self._state]:
            raise ActiveVisionStateError("active vision state transition is not allowed")
        observed_at = int(time.time()) if timestamp is None else timestamp
        if not isinstance(observed_at, int) or isinstance(observed_at, bool) or observed_at < self._history[-1]["timestamp"]:
            raise ActiveVisionStateError("active vision timestamp is invalid")
        self._state = target
        self._history.append({"state": target, "timestamp": observed_at})
        return self._state


class VisualIntelligenceFoundation:
    """Create safe visual candidates from an existing Semantic UI Graph only."""

    MIN_READY_CONFIDENCE = 0.80
    MAX_TTL_SECONDS = 300

    def __init__(
        self,
        *,
        domain_resolver: VisualDomainResolver | None = None,
        evidence_layer: VisualEvidenceLayer | None = None,
        visual_memory: VisualMemoryInterface | None = None,
    ) -> None:
        self._domain_resolver = domain_resolver if domain_resolver is not None else VisualDomainResolver()
        self._evidence_layer = evidence_layer if evidence_layer is not None else VisualEvidenceLayer()
        self._visual_memory = visual_memory if visual_memory is not None else VisualMemoryInterface()
        if not isinstance(self._domain_resolver, VisualDomainResolver):
            raise TypeError("VisualIntelligenceFoundation requires VisualDomainResolver")
        if not isinstance(self._evidence_layer, VisualEvidenceLayer):
            raise TypeError("VisualIntelligenceFoundation requires VisualEvidenceLayer")
        if not isinstance(self._visual_memory, VisualMemoryInterface):
            raise TypeError("VisualIntelligenceFoundation requires VisualMemoryInterface")

    def interpret(
        self,
        graph: SemanticUIGraph,
        *,
        domain_signals: Iterable[VisualDomainSignal] = (),
        expires_in_seconds: int = 60,
    ) -> VisualSemanticCandidate:
        if not isinstance(graph, SemanticUIGraph):
            raise VisualIntelligencePolicyError("visual intelligence requires an existing SemanticUIGraph")
        graph.validate_public_schema()
        if not isinstance(expires_in_seconds, int) or isinstance(expires_in_seconds, bool):
            raise VisualIntelligencePolicyError("visual semantic candidate expiry is invalid")
        if not 1 <= expires_in_seconds <= self.MAX_TTL_SECONDS:
            raise VisualIntelligencePolicyError("visual semantic candidate expiry is outside safe bounds")

        signals = tuple(domain_signals)
        resolution = self._domain_resolver.resolve(signals)
        evidence = list(self._graph_evidence(graph))
        evidence.extend(self._domain_evidence(signal) for signal in signals)
        for item in evidence:
            self._evidence_layer.record(item)

        detected_entity_types = self._entity_types(graph)
        confidence = float(graph.confidence)
        if resolution.status == VisualDomainResolution.RESOLVED:
            confidence = min(confidence, float(resolution.confidence))
        confidence = round(confidence, 4)
        reason_codes: set[str] = set()
        if graph.state != "verified":
            reason_codes.add("graph_not_verified")
        if confidence < self.MIN_READY_CONFIDENCE:
            reason_codes.add("low_visual_confidence")
        if resolution.status == VisualDomainResolution.NEEDS_CONFIRMATION:
            reason_codes.update(resolution.reason_codes)
        ordered_reasons = tuple(sorted(reason_codes))
        candidate = VisualSemanticCandidate(
            visual_intelligence_version=VISUAL_INTELLIGENCE_FOUNDATION_VERSION,
            candidate_id="visual.%s" % uuid4().hex,
            status="READY" if not ordered_reasons else "NEEDS_CONFIRMATION",
            confidence=confidence,
            detected_entity_types=detected_entity_types,
            domain=resolution.domain,
            source_types=tuple(
                source
                for source in ObservationProviderRouter.PROVIDER_ORDER
                if any(item.source_type == source for item in evidence)
            ),
            evidence=tuple(evidence),
            reason_codes=ordered_reasons,
            timestamp=graph.timestamp,
            expires_at=graph.timestamp + expires_in_seconds,
        )
        candidate.validate_public_schema()
        return candidate

    @staticmethod
    def _graph_evidence(graph: SemanticUIGraph) -> tuple[VisualEvidence, ...]:
        evidence = [
            VisualEvidence(
                source_type=graph.source,
                confidence=graph.confidence,
                timestamp=graph.timestamp,
                entity_type="screen_context",
                evidence_class="semantic_graph",
            )
        ]
        if any(node["type"] == "affordance" for node in graph.nodes):
            evidence.append(
                VisualEvidence(
                    source_type=graph.source,
                    confidence=graph.confidence,
                    timestamp=graph.timestamp,
                    entity_type="interaction_affordance",
                    evidence_class="semantic_graph",
                )
            )
        return tuple(evidence)

    @staticmethod
    def _domain_evidence(signal: VisualDomainSignal) -> VisualEvidence:
        signal.validate()
        return VisualEvidence(
            source_type=signal.source_type,
            confidence=signal.confidence,
            timestamp=signal.timestamp,
            entity_type="domain_context",
            evidence_class="domain_signal",
        )

    @staticmethod
    def _entity_types(graph: SemanticUIGraph) -> tuple[str, ...]:
        entity_types = ["screen_context"]
        if any(node["type"] == "affordance" for node in graph.nodes):
            entity_types.append("interaction_affordance")
        return tuple(entity_types)


@dataclass(frozen=True)
class PlannerSemanticContext:
    """The only TEST-24 semantic input accepted by the new Planner entry point.

    This context is copied from one already-filtered ``SemanticObservation``.
    It intentionally has no reference to a provider payload, Snapshot, UI
    element, visible string, application identity, coordinate, screenshot, or
    MCP client. It is advisory planning context, never an action request.
    """

    context_version: str
    source: str
    timestamp: int
    confidence: float
    page_type: str
    intents: tuple[dict[str, Any], ...]
    actionable: bool

    SAFE_CONTEXT_KEYS = frozenset(
        {"context_version", "source", "timestamp", "confidence", "page_type", "intents", "actionable"}
    )

    @classmethod
    def from_semantic_observation(cls, observation: SemanticObservation) -> "PlannerSemanticContext":
        if not isinstance(observation, SemanticObservation):
            raise ValueError("Planner semantic context requires a SemanticObservation")
        observation.validate_public_schema()
        context = cls(
            context_version=PLANNER_SEMANTIC_CONTEXT_VERSION,
            source=observation.source,
            timestamp=observation.timestamp,
            confidence=observation.confidence,
            page_type=observation.page_type,
            intents=tuple(dict(intent) for intent in observation.intents),
            actionable=observation.actionable,
        )
        context.validate_public_schema()
        return context

    def schema(self) -> dict[str, Any]:
        """Return the exact aggregate-only context visible to Planner."""

        return {
            "context_version": self.context_version,
            "source": self.source,
            "timestamp": self.timestamp,
            "confidence": self.confidence,
            "page_type": self.page_type,
            "intents": [dict(intent) for intent in self.intents],
            "actionable": self.actionable,
        }

    def validate_public_schema(self) -> None:
        """Reject malformed, private, or replay-capable planner context."""

        if self.context_version != PLANNER_SEMANTIC_CONTEXT_VERSION:
            raise ValueError("Planner semantic context has an unsupported version")
        if set(self.schema()) != self.SAFE_CONTEXT_KEYS:
            raise ValueError("Planner semantic context contains unsupported fields")
        SemanticObservation(
            source=self.source,
            timestamp=self.timestamp,
            confidence=self.confidence,
            page_type=self.page_type,
            intents=self.intents,
            actionable=self.actionable,
        ).validate_public_schema()

    def registry_snapshot(self) -> Snapshot:
        """Adapt aggregate metadata for existing Skill precondition checks.

        The Skill Registry has not been changed. Its TEST-11 read-only Skill
        needs only a fresh observation source. This adapter deliberately has no
        UI elements or application identity, so the registry cannot receive raw
        AX/OCR information through the semantic Planner path.
        """

        self.validate_public_schema()
        return Snapshot(
            frontmost_name="",
            frontmost_bundle_id="",
            element_count=sum(intent["count"] for intent in self.intents),
            source=self.source,
            elements=tuple(),
        )


class SemanticActionBindingError(RuntimeError):
    """A private, short-lived semantic control binding is unavailable or unsafe."""


class InstalledAppLaunchBindingError(RuntimeError):
    """A one-time TEST-49 installed-app binding was invalid or unavailable."""


class PublicDestinationBindingError(RuntimeError):
    """A one-time TEST-50 public-destination binding was invalid or unavailable."""


@dataclass(frozen=True)
class BoundSemanticControl:
    """Public metadata for one ephemeral, individually verified control.

    The binding deliberately does not reveal the observed AX/OCR label,
    coordinate, rectangle, frontmost application, screenshot, or action
    arguments. Its opaque identifier is valid only within its owning
    ``SemanticActionBindingStore`` and is consumed before the first action.
    """

    binding_version: str
    binding_id: str
    semantic_role: str
    source: str
    candidate_count: int
    expires_at: int

    SAFE_KEYS = frozenset(
        {"binding_version", "binding_id", "semantic_role", "source", "candidate_count", "expires_at"}
    )
    UUID_PATTERN = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")

    def schema(self) -> dict[str, Any]:
        return {
            "binding_version": self.binding_version,
            "binding_id": self.binding_id,
            "semantic_role": self.semantic_role,
            "source": self.source,
            "candidate_count": self.candidate_count,
            "expires_at": self.expires_at,
        }

    def validate_public_schema(self) -> None:
        if self.binding_version != SEMANTIC_EXECUTION_VERSION:
            raise SemanticActionBindingError("semantic control binding has an unsupported version")
        if set(self.schema()) != self.SAFE_KEYS:
            raise SemanticActionBindingError("semantic control binding contains unsupported fields")
        if not self.UUID_PATTERN.fullmatch(self.binding_id):
            raise SemanticActionBindingError("semantic control binding id is invalid")
        if self.semantic_role != "search_control":
            raise SemanticActionBindingError("semantic control binding has an unsupported role")
        if self.source not in ObservationProviderRouter.PROVIDER_ORDER:
            raise SemanticActionBindingError("semantic control binding has an unsupported source")
        if self.candidate_count != 1:
            raise SemanticActionBindingError("semantic control binding must represent one unique control")
        if not isinstance(self.expires_at, int) or self.expires_at < 0:
            raise SemanticActionBindingError("semantic control binding expiry is invalid")

    def registry_snapshot(self) -> Snapshot:
        """Adapt a verified semantic role without exposing its raw selector.

        ``SkillRegistry`` is unchanged. It receives a generic role token only,
        never the original control label or a raw screen observation.
        """

        self.validate_public_schema()
        return Snapshot(
            frontmost_name="",
            frontmost_bundle_id="",
            element_count=1,
            source=self.source,
            elements=({"text": "search", "clickable": True},),
        )


class SemanticActionBindingStore:
    """Keep one observed selector private until a bounded action consumes it.

    This is not Memory and has no persistence API. It accepts a raw Snapshot
    only to prove that exactly one current search control exists, then retains
    the minimum selector needed by the existing ``tap_element`` MCP contract.
    Planner and PlanExecutor receive only ``BoundSemanticControl`` metadata;
    the executor resolves the selector immediately before its one tool call.
    """

    MAX_BINDINGS = 8
    DEFAULT_TTL_SECONDS = 30

    def __init__(self, ttl_seconds: int = DEFAULT_TTL_SECONDS, capacity: int = MAX_BINDINGS) -> None:
        if ttl_seconds < 1:
            raise ValueError("semantic binding ttl must be positive")
        if capacity < 1:
            raise ValueError("semantic binding capacity must be positive")
        self.ttl_seconds = int(ttl_seconds)
        self.capacity = int(capacity)
        self._private_actions: dict[str, dict[str, Any]] = {}
        self._lock = threading.RLock()

    def bind_search_control(
        self,
        snapshot: Snapshot,
        semantic_context: PlannerSemanticContext,
        *,
        now: int | None = None,
    ) -> BoundSemanticControl:
        """Create one action binding only after semantic and raw checks agree."""

        if not isinstance(snapshot, Snapshot):
            raise SemanticActionBindingError("semantic action binding requires a current Snapshot")
        if not isinstance(semantic_context, PlannerSemanticContext):
            raise SemanticActionBindingError("semantic action binding requires PlannerSemanticContext")
        semantic_context.validate_public_schema()
        if not self._has_actionable_search_intent(semantic_context):
            raise SemanticActionBindingError("semantic context does not declare an actionable search control")

        candidates = SkillRegistry.search_candidates(snapshot.elements)
        if len(candidates) != 1:
            raise SemanticActionBindingError("current screen does not expose one unique semantic search control")
        label = str(candidates[0].get("text") or "").strip()
        if not label or len(label) > 256:
            raise SemanticActionBindingError("observed search selector is invalid")

        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            if len(self._private_actions) >= self.capacity:
                raise SemanticActionBindingError("semantic binding capacity reached")

            binding = BoundSemanticControl(
                binding_version=SEMANTIC_EXECUTION_VERSION,
                binding_id=str(uuid4()),
                semantic_role="search_control",
                source=semantic_context.source,
                candidate_count=1,
                expires_at=current_time + self.ttl_seconds,
            )
            binding.validate_public_schema()
            self._private_actions[binding.binding_id] = {
                "tool": "tap_element",
                "step_id": "focus-bound-search-control",
                "arguments": {"text": label, "match": "exact"},
                "expires_at": binding.expires_at,
            }
            return binding

    def resolve(
        self,
        binding_id: str,
        *,
        tool: str,
        step_id: str,
        now: int | None = None,
    ) -> dict[str, Any]:
        """Consume a binding and materialize its private action arguments once."""

        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            entry = self._private_actions.get(str(binding_id))
            if entry is None:
                raise SemanticActionBindingError("semantic control binding is unavailable, expired, or already consumed")
            if tool != entry["tool"] or step_id != entry["step_id"]:
                raise SemanticActionBindingError("semantic control binding does not authorize this step")
            arguments = entry.get("arguments")
            if not isinstance(arguments, dict) or set(arguments) != {"text", "match"}:
                raise SemanticActionBindingError("semantic control binding has invalid private arguments")
            # Consume before the MCP request so a failed action cannot be replayed.
            del self._private_actions[str(binding_id)]
            return dict(arguments)

    @staticmethod
    def _has_actionable_search_intent(context: PlannerSemanticContext) -> bool:
        return any(
            entry.get("intent") == "search" and bool(entry.get("actionable"))
            for entry in context.intents
        )

    def _purge_expired(self, current_time: int) -> None:
        expired = [
            binding_id
            for binding_id, entry in self._private_actions.items()
            if int(entry.get("expires_at") or 0) <= current_time
        ]
        for binding_id in expired:
            del self._private_actions[binding_id]


class SemanticSearchPolicyError(SemanticActionBindingError):
    """A TEST-51 query, field, or one-time step binding failed closed."""


TEST52_AX_SOURCE_PROBE_SCHEMA = "phoneharness.test52.ax_source_probe.v1"
TEST52_AX_SOURCE_PROBE_FIELDS = (
    "semantic_role",
    "editable",
    "secure",
    "enabled",
    "focused",
    "visible",
    "actionable",
)
TEST52_AX_SOURCE_PROBE_COUNTERS = (
    "attribute_present_count",
    "ax_batch_read_success_count",
    "ax_single_read_success_count",
    "xc_read_success_count",
    "settable_or_availability_count",
    "unavailable_count",
)
TEST52_AX_SOURCE_PROBE_ERROR_RE = re.compile(r"[a-z][a-z_]{0,63}")


class SemanticSourceProbeError(ValueError):
    """A TEST-52 developer diagnostic payload violated its aggregate contract."""


@dataclass(frozen=True)
class SemanticAXSourceProbe:
    """Strictly aggregate TEST-52 source evidence; never stores UI content."""

    node_count: int
    same_leaf_identity_count: int
    fields: dict[str, dict[str, Any]]

    @staticmethod
    def _count(value: Any, field: str, *, maximum: int | None = None) -> int:
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise SemanticSourceProbeError("%s must be a non-negative integer" % field)
        if maximum is not None and value > maximum:
            raise SemanticSourceProbeError("%s exceeds node_count" % field)
        return value

    @classmethod
    def from_payload(cls, payload: Any) -> "SemanticAXSourceProbe":
        if not isinstance(payload, dict):
            raise SemanticSourceProbeError("source probe payload must be an object")
        diagnostic = payload.get("semantic_diagnostics")
        if not isinstance(diagnostic, dict):
            raise SemanticSourceProbeError("source probe aggregate is unavailable")
        if set(diagnostic) != {"schema", "node_count", "same_leaf_identity_count", "fields"}:
            raise SemanticSourceProbeError("source probe aggregate schema is invalid")
        if diagnostic.get("schema") != TEST52_AX_SOURCE_PROBE_SCHEMA:
            raise SemanticSourceProbeError("source probe schema version is invalid")
        node_count = cls._count(diagnostic.get("node_count"), "node_count")
        same_leaf_identity_count = cls._count(
            diagnostic.get("same_leaf_identity_count"),
            "same_leaf_identity_count",
            maximum=node_count,
        )
        raw_fields = diagnostic.get("fields")
        if not isinstance(raw_fields, dict) or set(raw_fields) != set(TEST52_AX_SOURCE_PROBE_FIELDS):
            raise SemanticSourceProbeError("source probe field set is invalid")

        fields: dict[str, dict[str, Any]] = {}
        for field in TEST52_AX_SOURCE_PROBE_FIELDS:
            raw_counts = raw_fields.get(field)
            expected = set(TEST52_AX_SOURCE_PROBE_COUNTERS) | {"error_category_counts"}
            if not isinstance(raw_counts, dict) or set(raw_counts) != expected:
                raise SemanticSourceProbeError("source probe counters are invalid")
            counts = {
                key: cls._count(raw_counts.get(key), "%s.%s" % (field, key), maximum=node_count)
                for key in TEST52_AX_SOURCE_PROBE_COUNTERS
            }
            raw_errors = raw_counts.get("error_category_counts")
            if not isinstance(raw_errors, dict):
                raise SemanticSourceProbeError("source probe error categories are invalid")
            errors: dict[str, int] = {}
            for category, count in raw_errors.items():
                if not isinstance(category, str) or TEST52_AX_SOURCE_PROBE_ERROR_RE.fullmatch(category) is None:
                    raise SemanticSourceProbeError("source probe error category is invalid")
                errors[category] = cls._count(
                    count,
                    "%s.error_category_counts.%s" % (field, category),
                    maximum=node_count,
                )
            counts["error_category_counts"] = dict(sorted(errors.items()))
            fields[field] = counts
        return cls(node_count=node_count, same_leaf_identity_count=same_leaf_identity_count, fields=fields)

    def safe_summary(self) -> dict[str, Any]:
        return {
            "schema": TEST52_AX_SOURCE_PROBE_SCHEMA,
            "node_count": self.node_count,
            "same_leaf_identity_count": self.same_leaf_identity_count,
            "fields": self.fields,
        }


@dataclass(frozen=True)
class NormalizedInputAuthorizationEvidence:
    """Privacy-safe provider-neutral facts used by input authorization policy.

    This value contains no selector, text, coordinate, native object, request
    nonce, or replayable action parameter.  Provider adapters are responsible
    for establishing provenance before constructing it.
    """

    provider: str
    scope: str
    grantable: bool
    source_valid: bool
    same_target: bool
    role_allowed: bool
    role_provenance_valid: bool
    editable_state: str
    editable_provenance_valid: bool
    secure_state: str
    secure_provenance_valid: bool
    enabled_state: str
    enabled_provenance_valid: bool
    presentation_state: str
    presentation_provenance_valid: bool
    actionable_state: str
    actionable_provenance_valid: bool
    focus_state: str
    focus_provenance_valid: bool
    selector_state: str
    fresh_request_binding: bool = True
    target_hidden_state: str = "UNAVAILABLE"
    target_hidden_presence: str = "UNAVAILABLE"
    target_hidden_provenance: str = "UNAVAILABLE"
    target_hidden_getter: str = "UNAVAILABLE"

    def __post_init__(self) -> None:
        if self.editable_state not in {"TRUE", "FALSE", "UNAVAILABLE", "NOT_APPLICABLE"}:
            raise ValueError("invalid normalized editable state")
        for name in ("secure_state", "enabled_state", "presentation_state",
                     "actionable_state", "focus_state", "selector_state",
                     "target_hidden_state"):
            if getattr(self, name) not in {"TRUE", "FALSE", "UNAVAILABLE", "NOT_APPLICABLE"}:
                raise ValueError("invalid normalized input state")
        expected_presence = {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE",
            "UNAVAILABLE": "UNAVAILABLE", "NOT_APPLICABLE": "UNAVAILABLE",
        }[self.target_hidden_state]
        if self.target_hidden_presence != expected_presence:
            raise ValueError("invalid normalized target hidden presence")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "provider": self.provider,
            "scope": self.scope,
            "grantable": self.grantable,
            "editable_state": self.editable_state,
            "secure_state": self.secure_state,
            "enabled_state": self.enabled_state,
            "presentation_state": self.presentation_state,
            "actionable_state": self.actionable_state,
            "focus_state": self.focus_state,
            "target_hidden_state": self.target_hidden_state,
            "target_hidden_provenance": self.target_hidden_provenance,
            "target_hidden_getter": self.target_hidden_getter,
            "fresh_request_binding": self.fresh_request_binding,
        }


@dataclass(frozen=True)
class InputAuthorizationEvaluation:
    """A side-effect-free and privacy-safe canonical policy decision."""

    decision: str
    failed_predicates: tuple[str, ...]
    provider: str
    scope: str
    grantable: bool

    def safe_summary(self) -> dict[str, Any]:
        return {
            "decision": self.decision,
            "failed_predicates": list(self.failed_predicates),
            "provider": self.provider,
            "scope": self.scope,
            "grantable": self.grantable,
        }


class InputAuthorizationPredicateEvaluator:
    """Canonical input predicates shared by AX and controlled Native evidence."""

    AX_ELIGIBILITY_PREDICATES = (
        "SOURCE", "SAME_TARGET", "ROLE", "ROLE_PROVENANCE", "EDITABLE",
        "SECURE", "ENABLED", "PRESENTATION", "ACTIONABLE", "SELECTOR",
    )
    AX_FOCUS_PREDICATES = ("SAME_TARGET", "FOCUS")
    NATIVE_DIAGNOSTIC_PREDICATES = (
        "FRESH_REQUEST_BINDING", "SOURCE", "SAME_TARGET", "ROLE",
        "ROLE_PROVENANCE", "EDITABLE", "SECURE", "ENABLED",
        "PRESENTATION", "ACTIONABLE", "FOCUS", "GRANTABLE",
    )
    NATIVE_V3_DIAGNOSTIC_PREDICATES = (
        "FRESH_REQUEST_BINDING", "SOURCE", "SAME_TARGET", "ROLE",
        "ROLE_PROVENANCE", "TARGET_HIDDEN", "PRESENTATION", "GRANTABLE",
    )

    @staticmethod
    def _state_failure(name: str, state: str, provenance_valid: bool,
                       *, false_reason: str | None = None) -> str | None:
        if state == "UNAVAILABLE":
            return "%s_UNAVAILABLE" % name
        if state == "NOT_APPLICABLE":
            return "%s_NOT_APPLICABLE" % name
        if not provenance_valid:
            return "%s_PROVENANCE_INVALID" % name
        if state == "FALSE":
            return false_reason or "%s_FALSE" % name
        return None

    @classmethod
    def evaluate(
        cls,
        evidence: NormalizedInputAuthorizationEvidence,
        *,
        predicates: Iterable[str] | None = None,
    ) -> InputAuthorizationEvaluation:
        if not isinstance(evidence, NormalizedInputAuthorizationEvidence):
            raise TypeError("normalized input authorization evidence is required")
        selected = tuple(predicates or cls.NATIVE_DIAGNOSTIC_PREDICATES)
        failures: list[str] = []
        for predicate in selected:
            failure = None
            if predicate == "FRESH_REQUEST_BINDING" and not evidence.fresh_request_binding:
                failure = "FRESH_REQUEST_BINDING_REQUIRED"
            elif predicate == "SOURCE" and not evidence.source_valid:
                failure = "EVIDENCE_SOURCE_INVALID"
            elif predicate == "SAME_TARGET" and not evidence.same_target:
                failure = "SAME_TARGET_UNPROVEN"
            elif predicate == "ROLE" and not evidence.role_allowed:
                failure = "ROLE_INELIGIBLE"
            elif predicate == "ROLE_PROVENANCE" and not evidence.role_provenance_valid:
                failure = "ROLE_PROVENANCE_INVALID"
            elif predicate == "EDITABLE":
                failure = cls._state_failure(
                    "EDITABLE", evidence.editable_state,
                    evidence.editable_provenance_valid,
                    false_reason="EDITABLE_FALSE",
                )
            elif predicate == "SECURE":
                if evidence.secure_state == "UNAVAILABLE":
                    failure = "SECURE_UNAVAILABLE"
                elif evidence.secure_state == "NOT_APPLICABLE":
                    failure = "SECURE_NOT_APPLICABLE"
                elif not evidence.secure_provenance_valid:
                    failure = "SECURE_PROVENANCE_INVALID"
                elif evidence.secure_state == "TRUE":
                    failure = "SECURE_TRUE"
            elif predicate == "ENABLED":
                failure = cls._state_failure(
                    "ENABLED", evidence.enabled_state,
                    evidence.enabled_provenance_valid,
                )
            elif predicate == "PRESENTATION":
                failure = cls._state_failure(
                    "PRESENTATION", evidence.presentation_state,
                    evidence.presentation_provenance_valid,
                )
            elif predicate == "TARGET_HIDDEN":
                if evidence.target_hidden_state in {"UNAVAILABLE", "NOT_APPLICABLE"}:
                    failure = "TARGET_HIDDEN_UNAVAILABLE"
                elif (evidence.target_hidden_provenance != "DIRECT_NATIVE_GETTER"
                      or evidence.target_hidden_getter != "TYPED_UIVIEW_ISHIDDEN"):
                    failure = "TARGET_HIDDEN_PROVENANCE_INVALID"
                elif evidence.target_hidden_state == "TRUE":
                    failure = "TARGET_HIDDEN"
            elif predicate == "ACTIONABLE":
                failure = cls._state_failure(
                    "ACTIONABLE", evidence.actionable_state,
                    evidence.actionable_provenance_valid,
                )
            elif predicate == "FOCUS":
                failure = cls._state_failure(
                    "FOCUS", evidence.focus_state,
                    evidence.focus_provenance_valid,
                )
            elif predicate == "SELECTOR":
                failure = cls._state_failure("SELECTOR", evidence.selector_state, True)
            elif predicate == "GRANTABLE" and not evidence.grantable:
                failure = "PROVIDER_SCOPE_NOT_GRANTABLE"
            elif predicate not in {
                "FRESH_REQUEST_BINDING", "SOURCE", "SAME_TARGET", "ROLE",
                "ROLE_PROVENANCE", "EDITABLE", "SECURE", "ENABLED",
                "PRESENTATION", "TARGET_HIDDEN", "ACTIONABLE", "FOCUS", "SELECTOR", "GRANTABLE",
            }:
                raise ValueError("unknown input authorization predicate")
            if failure is not None:
                failures.append(failure)
        return InputAuthorizationEvaluation(
            decision="DENY" if failures else "ALLOW",
            failed_predicates=tuple(failures),
            provider=evidence.provider,
            scope=evidence.scope,
            grantable=evidence.grantable,
        )


class AXInputAuthorizationEvidenceAdapter:
    """Normalize an existing typed AX field without changing its semantics."""

    @staticmethod
    def _state(value: bool | None) -> str:
        return "TRUE" if value is True else "FALSE" if value is False else "UNAVAILABLE"

    @classmethod
    def adapt(cls, field: "SemanticSearchFieldEvidence") -> NormalizedInputAuthorizationEvidence:
        if not isinstance(field, SemanticSearchFieldEvidence):
            raise TypeError("SemanticSearchFieldEvidence is required")
        return NormalizedInputAuthorizationEvidence(
            provider="AX_SAME_LEAF",
            scope="PRODUCTION_AX",
            grantable=True,
            source_valid=field.source == "AX",
            same_target=field.has_same_leaf_identity(),
            role_allowed=field.role in {"search_field", "editable_text_field", "text_field"},
            role_provenance_valid=field.role_source in field.ROLE_SOURCES,
            editable_state=cls._state(field.editable),
            editable_provenance_valid=field.editable_source in field.DIRECT_SOURCES,
            secure_state=cls._state(False if field.secure is False else True if field.secure is True else None),
            secure_provenance_valid=field.secure_source in field.DIRECT_SOURCES,
            enabled_state=cls._state(field.enabled),
            enabled_provenance_valid=field.enabled_source in field.DIRECT_SOURCES,
            presentation_state=cls._state(field.visible),
            presentation_provenance_valid=field.visible_source in field.DIRECT_SOURCES,
            actionable_state=cls._state(field.actionable),
            actionable_provenance_valid=field.actionable_source in field.DIRECT_SOURCES,
            focus_state=cls._state(field.focused),
            focus_provenance_valid=field.focused_source in field.DIRECT_SOURCES,
            selector_state="TRUE" if bool(field.selector_text.strip()) else "FALSE",
        )


class NativeV1InputEvidenceAdapterError(ValueError):
    """Native V1 evidence was not a validated, bounded transaction result."""


class ValidatedNativeV1AuthorizationEvidence:
    """Sealed Native V1 semantic facts; never an authorization credential."""

    _SEAL = object()

    def __init__(self, seal: object, facts: dict[str, Any], *, fresh_request_binding: bool) -> None:
        if seal is not self._SEAL:
            raise NativeV1InputEvidenceAdapterError("validated Native V1 evidence is required")
        self._facts = dict(facts)
        self.fresh_request_binding = bool(fresh_request_binding)

    @staticmethod
    def _bool(value: Any, field_name: str) -> bool:
        if type(value) is not bool:
            raise NativeV1InputEvidenceAdapterError("%s must be a JSON boolean" % field_name)
        return value

    @staticmethod
    def _enum(value: Any, allowed: set[str], field_name: str) -> str:
        if not isinstance(value, str) or value not in allowed:
            raise NativeV1InputEvidenceAdapterError("%s is invalid" % field_name)
        return value

    @classmethod
    def _validated_facts(
        cls,
        response: dict[str, Any],
        *,
        require_wire_binding: bool,
    ) -> dict[str, Any]:
        if not isinstance(response, dict):
            raise NativeV1InputEvidenceAdapterError("Native V1 response object is required")
        exact = {
            "schema": "ph.controlled_fixture.native_evidence.response.v1",
            "provider": "NATIVE_UIKIT_SINGLE_PROVIDER",
            "scope": "CONTROLLED_FIXTURE_ONLY",
            "target_slot": "read_only",
            "expected_class": "UITextView",
            "runtime_cdhash_status": "PASS",
            "process_instance_status": "PASS",
            "lifecycle_epoch_status": "PASS",
        }
        for key, expected in exact.items():
            if response.get(key) != expected:
                raise NativeV1InputEvidenceAdapterError("Native V1 %s mismatch" % key)
        if (response.get("bundle") != "com.charles.phoneharness.test52.c1"
                or type(response.get("peer_pid")) is not int or response["peer_pid"] < 1
                or type(response.get("peer_version")) is not int or response["peer_version"] < 1):
            raise NativeV1InputEvidenceAdapterError("Native V1 process binding is invalid")
        if require_wire_binding:
            nonce = response.get("request_nonce")
            try:
                canonical_nonce = str(nonce)
                parsed_nonce = UUID(canonical_nonce)
            except (ValueError, AttributeError, TypeError):
                raise NativeV1InputEvidenceAdapterError("Native V1 request nonce is invalid") from None
            if str(parsed_nonce) != canonical_nonce:
                raise NativeV1InputEvidenceAdapterError("Native V1 request nonce is not canonical")
        for key in (
            "slot_bound", "expected_class_match", "native_object_present",
            "native_same_target", "object_generation_consistency",
            "evidence_generation_consistency",
        ):
            if cls._bool(response.get(key), key) is not True:
                raise NativeV1InputEvidenceAdapterError("Native V1 %s failed" % key)
        if response.get("runtime_cdhash_provenance") != "DIRECT_KERNEL_AUDIT_TOKEN_CDHASH":
            raise NativeV1InputEvidenceAdapterError("Native V1 runtime identity provenance is invalid")
        if response.get("status") not in {"DIAGNOSTIC_ONLY", "FAIL_CLOSED"}:
            raise NativeV1InputEvidenceAdapterError("Native V1 status is invalid")
        if not isinstance(response.get("failure_code"), str):
            raise NativeV1InputEvidenceAdapterError("Native V1 failure code is invalid")
        if response.get("status") == "DIAGNOSTIC_ONLY" and response.get("failure_code") != "NONE":
            raise NativeV1InputEvidenceAdapterError("Native V1 success/failure state is inconsistent")
        if (response.get("enabled_state") != "NOT_APPLICABLE"
                or response.get("fixture_text_mutation_state") != "NOT_APPLICABLE"
                or response.get("capsule_store_mutation") != 0
                or response.get("test_setup_action_count_delta") != 0
                or response.get("device_action_count_delta") != 0
                or response.get("device_action_count") != 0):
            raise NativeV1InputEvidenceAdapterError("Native V1 side-effect contract is invalid")
        editable_state = cls._enum(
            response.get("editable_state"), {"TRUE", "FALSE", "UNAVAILABLE"}, "editable_state",
        )
        editable_presence = cls._enum(
            response.get("editable_presence"),
            {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"}, "editable_presence",
        )
        expected_presence = {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
        }[editable_state]
        if editable_presence != expected_presence:
            raise NativeV1InputEvidenceAdapterError("Native V1 editable presence mismatch")
        focused_state = cls._enum(
            response.get("focused_state"), {"TRUE", "FALSE", "UNAVAILABLE"}, "focused_state",
        )
        focused_presence = cls._enum(
            response.get("focused_presence"),
            {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"}, "focused_presence",
        )
        if focused_presence != {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
        }[focused_state]:
            raise NativeV1InputEvidenceAdapterError("Native V1 focus presence mismatch")
        interaction_state = cls._enum(
            response.get("user_interaction_enabled_state"),
            {"TRUE", "FALSE", "UNAVAILABLE"}, "user_interaction_enabled_state",
        )
        interaction_presence = cls._enum(
            response.get("user_interaction_enabled_presence"),
            {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"},
            "user_interaction_enabled_presence",
        )
        if interaction_presence != {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
        }[interaction_state]:
            raise NativeV1InputEvidenceAdapterError("Native V1 interaction presence mismatch")
        can_become_state = cls._enum(
            response.get("can_become_first_responder_state"),
            {"TRUE", "FALSE", "UNAVAILABLE"}, "can_become_first_responder_state",
        )
        can_become_presence = cls._enum(
            response.get("can_become_first_responder_presence"),
            {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"},
            "can_become_first_responder_presence",
        )
        if can_become_presence != {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
        }[can_become_state]:
            raise NativeV1InputEvidenceAdapterError("Native V1 responder presence mismatch")
        presentation = cls._enum(
            response.get("presentation"),
            {"PRESENTED_IN_CONTROLLED_FIXTURE", "NOT_PRESENTED", "UNAVAILABLE"},
            "presentation",
        )
        return {
            "editable_state": editable_state,
            "editable_presence": editable_presence,
            "editable_provenance": response.get("editable_provenance"),
            "editable_getter": response.get("editable_getter"),
            "focused_state": focused_state,
            "interaction_state": interaction_state,
            "presentation": presentation,
        }

    @classmethod
    def from_frozen_device_artifact(cls, artifact: dict[str, Any]) -> "ValidatedNativeV1AuthorizationEvidence":
        if not isinstance(artifact, dict):
            raise NativeV1InputEvidenceAdapterError("frozen Native V1 artifact object is required")
        if (artifact.get("schema") != "phoneharness.test52.native-evidence-v1.read-only-device-gate.v1"
                or artifact.get("state") != "PASS" or artifact.get("request_count") != 1
                or artifact.get("retry_count") != 0 or artifact.get("fallback_count") != 0
                or artifact.get("device_action_count") != 0
                or artifact.get("response_nonce_match") is not True
                or artifact.get("mcp_is_error") is not False
                or artifact.get("mismatched_success_fields") != []
                or not isinstance(artifact.get("request_nonce_sha256"), str)
                or re.fullmatch(r"[0-9a-f]{64}", artifact["request_nonce_sha256"]) is None):
            raise NativeV1InputEvidenceAdapterError("frozen Native V1 artifact trust envelope is invalid")
        facts = cls._validated_facts(artifact.get("response"), require_wire_binding=False)
        # A frozen artifact is test input only. Its historical nonce digest can
        # never satisfy a current request binding or become action authority.
        return cls(cls._SEAL, facts, fresh_request_binding=False)

    @classmethod
    def from_authenticated_transaction(
        cls,
        response: dict[str, Any],
        *,
        request_nonce_match: bool,
        c1_initial_auth_pass: bool,
        c1_post_auth_pass: bool,
        received_at: int,
        now: int | None = None,
        max_age_seconds: int = 60,
    ) -> "ValidatedNativeV1AuthorizationEvidence":
        current = int(time.time()) if now is None else int(now)
        if (request_nonce_match is not True or c1_initial_auth_pass is not True
                or c1_post_auth_pass is not True or type(received_at) is not int
                or not 0 <= current - received_at <= max_age_seconds):
            raise NativeV1InputEvidenceAdapterError("fresh authenticated Native V1 request binding is required")
        return cls(
            cls._SEAL,
            cls._validated_facts(response, require_wire_binding=True),
            fresh_request_binding=True,
        )


class NativeV1InputAuthorizationEvidenceAdapter:
    """Normalize validated controlled-fixture Native V1 evidence for diagnostics."""

    @staticmethod
    def adapt(value: ValidatedNativeV1AuthorizationEvidence) -> NormalizedInputAuthorizationEvidence:
        if not isinstance(value, ValidatedNativeV1AuthorizationEvidence):
            raise NativeV1InputEvidenceAdapterError("validated Native V1 evidence is required")
        facts = value._facts
        editable_provenance_valid = (
            facts["editable_provenance"] == "DIRECT_NATIVE_GETTER"
            and facts["editable_getter"] == "TYPED_UITEXTVIEW_ISEDITABLE"
        )
        presentation = {
            "PRESENTED_IN_CONTROLLED_FIXTURE": "TRUE",
            "NOT_PRESENTED": "FALSE",
            "UNAVAILABLE": "UNAVAILABLE",
        }[facts["presentation"]]
        return NormalizedInputAuthorizationEvidence(
            provider="NATIVE_UIKIT_SINGLE_PROVIDER",
            scope="CONTROLLED_FIXTURE_ONLY",
            grantable=False,
            source_valid=True,
            same_target=True,
            role_allowed=True,
            role_provenance_valid=True,
            editable_state=facts["editable_state"],
            editable_provenance_valid=editable_provenance_valid,
            # Native V1 currently does not export secure state, and UITextView
            # enabled remains explicitly NOT_APPLICABLE. Both stay fail closed.
            secure_state="UNAVAILABLE",
            secure_provenance_valid=False,
            enabled_state="NOT_APPLICABLE",
            enabled_provenance_valid=False,
            presentation_state=presentation,
            presentation_provenance_valid=presentation != "UNAVAILABLE",
            actionable_state=facts["interaction_state"],
            actionable_provenance_valid=facts["interaction_state"] != "UNAVAILABLE",
            focus_state=facts["focused_state"],
            focus_provenance_valid=facts["focused_state"] != "UNAVAILABLE",
            selector_state="NOT_APPLICABLE",
            fresh_request_binding=value.fresh_request_binding,
        )


class NativeV2InputEvidenceAdapterError(ValueError):
    """Native V2 disabled evidence was not a validated transaction result."""


class ValidatedNativeV2AuthorizationEvidence:
    """Sealed disabled-only Native V2 facts; never an authorization credential."""

    _SEAL = object()
    RESPONSE_KEYS = frozenset({
        "schema", "scope", "provider", "status", "failure_code", "request_nonce",
        "bundle", "peer_pid", "peer_version", "runtime_cdhash_status",
        "runtime_cdhash_provenance", "process_instance_status", "lifecycle_epoch_status",
        "target_slot", "slot_bound", "expected_class", "expected_class_match",
        "native_object_present", "native_same_target", "object_generation_consistency",
        "evidence_generation_consistency", "enabled_state", "enabled_presence",
        "enabled_provenance", "enabled_getter", "editable_state", "secure_state",
        "secure_presence", "focused_state", "focused_presence",
        "can_become_first_responder_state", "can_become_first_responder_presence",
        "user_interaction_enabled_state", "user_interaction_enabled_presence",
        "fixture_text_mutation_state", "fixture_text_mutation_provenance", "presentation",
        "capsule_side_effect_count", "authorization_capsule_issued",
        "risk_authorization_receipt_count", "input_grant_count", "executor_dispatch_count",
        "external_input_dispatch_count", "text_event_count", "test_setup_action_count_delta",
        "device_action_count_delta", "device_action_count",
    })

    def __init__(self, seal: object, facts: dict[str, Any], *, fresh_request_binding: bool) -> None:
        if seal is not self._SEAL:
            raise NativeV2InputEvidenceAdapterError("validated Native V2 evidence is required")
        self._facts = dict(facts)
        self.fresh_request_binding = bool(fresh_request_binding)

    @staticmethod
    def _bool(value: Any, field_name: str) -> bool:
        if type(value) is not bool:
            raise NativeV2InputEvidenceAdapterError("%s must be a JSON boolean" % field_name)
        return value

    @staticmethod
    def _enum(value: Any, allowed: set[str], field_name: str) -> str:
        if not isinstance(value, str) or value not in allowed:
            raise NativeV2InputEvidenceAdapterError("Native V2 %s is invalid" % field_name)
        return value

    @classmethod
    def _validated_facts(cls, response: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(response, dict) or set(response) != cls.RESPONSE_KEYS:
            raise NativeV2InputEvidenceAdapterError("Native V2 exact response shape is invalid")
        exact = {
            "schema": "ph.controlled_fixture.native_evidence.response.v2",
            "scope": "CONTROLLED_FIXTURE_ONLY",
            "provider": "NATIVE_UIKIT_SINGLE_PROVIDER",
            "status": "DIAGNOSTIC_ONLY",
            "failure_code": "NONE",
            "bundle": "com.charles.phoneharness.test52.c1",
            "runtime_cdhash_status": "PASS",
            "runtime_cdhash_provenance": "DIRECT_KERNEL_AUDIT_TOKEN_CDHASH",
            "process_instance_status": "PASS",
            "lifecycle_epoch_status": "PASS",
            "target_slot": "disabled",
            "expected_class": "UITextField",
            "enabled_provenance": "DIRECT_NATIVE_GETTER",
            "enabled_getter": "TYPED_UITEXTFIELD_ISENABLED",
            "editable_state": "NOT_APPLICABLE",
            "fixture_text_mutation_provenance": "DIRECT_FIXTURE_CONTRACT",
            "presentation": "PRESENTED_IN_CONTROLLED_FIXTURE",
        }
        for key, expected in exact.items():
            if response.get(key) != expected:
                raise NativeV2InputEvidenceAdapterError("Native V2 %s mismatch" % key)
        try:
            nonce = str(response.get("request_nonce"))
            parsed_nonce = UUID(nonce)
        except (ValueError, AttributeError, TypeError):
            raise NativeV2InputEvidenceAdapterError("Native V2 request nonce is invalid") from None
        if str(parsed_nonce) != nonce:
            raise NativeV2InputEvidenceAdapterError("Native V2 request nonce is not canonical")
        if (type(response.get("peer_pid")) is not int or response["peer_pid"] < 1
                or type(response.get("peer_version")) is not int or response["peer_version"] < 1):
            raise NativeV2InputEvidenceAdapterError("Native V2 process binding is invalid")
        for key in (
            "slot_bound", "expected_class_match", "native_object_present", "native_same_target",
            "object_generation_consistency", "evidence_generation_consistency",
        ):
            if cls._bool(response.get(key), key) is not True:
                raise NativeV2InputEvidenceAdapterError("Native V2 %s failed" % key)
        if cls._bool(response.get("authorization_capsule_issued"), "authorization_capsule_issued"):
            raise NativeV2InputEvidenceAdapterError("Native V2 cannot issue an authorization capsule")
        for key in (
            "capsule_side_effect_count", "risk_authorization_receipt_count", "input_grant_count",
            "executor_dispatch_count", "external_input_dispatch_count", "text_event_count",
            "test_setup_action_count_delta", "device_action_count_delta", "device_action_count",
        ):
            if type(response.get(key)) is not int or response[key] != 0:
                raise NativeV2InputEvidenceAdapterError("Native V2 side-effect contract is invalid")
        enabled_state = cls._enum(
            response.get("enabled_state"), {"TRUE", "FALSE", "UNAVAILABLE"}, "enabled_state",
        )
        enabled_presence = cls._enum(
            response.get("enabled_presence"),
            {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"}, "enabled_presence",
        )
        if enabled_presence != {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
        }[enabled_state]:
            raise NativeV2InputEvidenceAdapterError("Native V2 enabled presence mismatch")
        if enabled_state != "FALSE" or enabled_presence != "PRESENT_FALSE":
            raise NativeV2InputEvidenceAdapterError("Native V2 disabled semantic is not proven")
        states: dict[str, str] = {}
        for field, presence_field in (
            ("secure_state", "secure_presence"),
            ("focused_state", "focused_presence"),
            ("can_become_first_responder_state", "can_become_first_responder_presence"),
            ("user_interaction_enabled_state", "user_interaction_enabled_presence"),
        ):
            state = cls._enum(response.get(field), {"TRUE", "FALSE", "UNAVAILABLE"}, field)
            presence = cls._enum(
                response.get(presence_field),
                {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"}, presence_field,
            )
            if presence != {
                "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
            }[state]:
                raise NativeV2InputEvidenceAdapterError("Native V2 %s mismatch" % presence_field)
            states[field] = state
        mutation_state = cls._enum(
            response.get("fixture_text_mutation_state"),
            {"TRUE", "FALSE", "UNAVAILABLE"}, "fixture_text_mutation_state",
        )
        if mutation_state != "TRUE":
            raise NativeV2InputEvidenceAdapterError("Native V2 Fixture mutation contract mismatch")
        return {
            "enabled_state": enabled_state,
            "enabled_presence": enabled_presence,
            "enabled_provenance": response["enabled_provenance"],
            "enabled_getter": response["enabled_getter"],
            "focused_state": states["focused_state"],
            "interaction_state": states["user_interaction_enabled_state"],
            "presentation": response["presentation"],
        }

    @classmethod
    def from_authenticated_transaction(
        cls,
        response: dict[str, Any],
        *,
        request_nonce_match: bool,
        c1_initial_auth_pass: bool,
        c1_post_auth_pass: bool,
        received_at: int,
        now: int | None = None,
        max_age_seconds: int = 60,
    ) -> "ValidatedNativeV2AuthorizationEvidence":
        current = int(time.time()) if now is None else int(now)
        if (request_nonce_match is not True or c1_initial_auth_pass is not True
                or c1_post_auth_pass is not True or type(received_at) is not int
                or not 0 <= current - received_at <= max_age_seconds):
            raise NativeV2InputEvidenceAdapterError(
                "fresh authenticated Native V2 request binding is required"
            )
        return cls(cls._SEAL, cls._validated_facts(response), fresh_request_binding=True)


class NativeV2InputAuthorizationEvidenceAdapter:
    """Normalize validated disabled-only Native V2 evidence for diagnostics."""

    @staticmethod
    def adapt(value: ValidatedNativeV2AuthorizationEvidence) -> NormalizedInputAuthorizationEvidence:
        if not isinstance(value, ValidatedNativeV2AuthorizationEvidence):
            raise NativeV2InputEvidenceAdapterError("validated Native V2 evidence is required")
        facts = value._facts
        enabled_provenance_valid = (
            facts["enabled_provenance"] == "DIRECT_NATIVE_GETTER"
            and facts["enabled_getter"] == "TYPED_UITEXTFIELD_ISENABLED"
        )
        presentation = {
            "PRESENTED_IN_CONTROLLED_FIXTURE": "TRUE",
            "NOT_PRESENTED": "FALSE",
            "UNAVAILABLE": "UNAVAILABLE",
        }[facts["presentation"]]
        return NormalizedInputAuthorizationEvidence(
            provider="NATIVE_UIKIT_SINGLE_PROVIDER",
            scope="CONTROLLED_FIXTURE_ONLY",
            grantable=False,
            source_valid=True,
            same_target=True,
            role_allowed=True,
            role_provenance_valid=True,
            editable_state="NOT_APPLICABLE",
            editable_provenance_valid=False,
            secure_state="UNAVAILABLE",
            secure_provenance_valid=False,
            enabled_state=facts["enabled_state"],
            enabled_provenance_valid=enabled_provenance_valid,
            presentation_state=presentation,
            presentation_provenance_valid=presentation != "UNAVAILABLE",
            actionable_state=facts["interaction_state"],
            actionable_provenance_valid=facts["interaction_state"] != "UNAVAILABLE",
            focus_state=facts["focused_state"],
            focus_provenance_valid=facts["focused_state"] != "UNAVAILABLE",
            selector_state="NOT_APPLICABLE",
            fresh_request_binding=value.fresh_request_binding,
        )


class NativeV3InputEvidenceAdapterError(ValueError):
    """Native V3 hidden/presentation evidence was not a validated transaction."""


class ValidatedNativeV3AuthorizationEvidence:
    """Sealed hidden-only Native V3 facts; never an authorization credential."""

    _SEAL = object()
    RESPONSE_KEYS = frozenset({
        "schema", "scope", "provider", "status", "failure_code", "request_nonce",
        "bundle", "peer_pid", "peer_version", "runtime_cdhash_status",
        "runtime_cdhash_provenance", "process_instance_status", "lifecycle_epoch_status",
        "target_slot", "slot_bound", "expected_class", "expected_class_match",
        "native_object_present", "native_same_target", "object_generation_consistency",
        "evidence_generation_consistency", "hidden_state", "hidden_presence",
        "hidden_provenance", "hidden_getter", "controlled_presentation",
        "presentation_provenance", "presentation_component_digest",
        "capsule_side_effect_count", "authorization_capsule_issued",
        "risk_authorization_receipt_count", "input_grant_count", "executor_dispatch_count",
        "external_input_dispatch_count", "text_event_count", "test_setup_action_count_delta",
        "device_action_count_delta", "device_action_count",
    })

    def __init__(self, seal: object, facts: dict[str, Any], *, fresh_request_binding: bool) -> None:
        if seal is not self._SEAL:
            raise NativeV3InputEvidenceAdapterError("validated Native V3 evidence is required")
        self._facts = dict(facts)
        self.fresh_request_binding = bool(fresh_request_binding)

    @staticmethod
    def _bool(value: Any, field_name: str) -> bool:
        if type(value) is not bool:
            raise NativeV3InputEvidenceAdapterError("%s must be a JSON boolean" % field_name)
        return value

    @staticmethod
    def _enum(value: Any, allowed: set[str], field_name: str) -> str:
        if not isinstance(value, str) or value not in allowed:
            raise NativeV3InputEvidenceAdapterError("Native V3 %s is invalid" % field_name)
        return value

    @classmethod
    def _validated_facts(cls, response: dict[str, Any]) -> dict[str, Any]:
        if not isinstance(response, dict) or set(response) != cls.RESPONSE_KEYS:
            raise NativeV3InputEvidenceAdapterError("Native V3 exact response shape is invalid")
        exact = {
            "schema": "ph.controlled_fixture.native_evidence.response.v3",
            "scope": "CONTROLLED_FIXTURE_ONLY",
            "provider": "NATIVE_UIKIT_SINGLE_PROVIDER",
            "bundle": "com.charles.phoneharness.test52.c1",
            "runtime_cdhash_status": "PASS",
            "runtime_cdhash_provenance": "DIRECT_KERNEL_AUDIT_TOKEN_CDHASH",
            "process_instance_status": "PASS",
            "lifecycle_epoch_status": "PASS",
            "target_slot": "hidden",
            "expected_class": "UITextField",
        }
        for key, expected in exact.items():
            if response.get(key) != expected:
                raise NativeV3InputEvidenceAdapterError("Native V3 %s mismatch" % key)
        try:
            nonce = str(response.get("request_nonce"))
            parsed_nonce = UUID(nonce)
        except (ValueError, AttributeError, TypeError):
            raise NativeV3InputEvidenceAdapterError("Native V3 request nonce is invalid") from None
        if str(parsed_nonce) != nonce:
            raise NativeV3InputEvidenceAdapterError("Native V3 request nonce is not canonical")
        if (type(response.get("peer_pid")) is not int or response["peer_pid"] < 1
                or type(response.get("peer_version")) is not int or response["peer_version"] < 1):
            raise NativeV3InputEvidenceAdapterError("Native V3 process binding is invalid")
        for key in (
            "slot_bound", "expected_class_match", "native_object_present", "native_same_target",
            "object_generation_consistency", "evidence_generation_consistency",
        ):
            if cls._bool(response.get(key), key) is not True:
                raise NativeV3InputEvidenceAdapterError("Native V3 %s failed" % key)
        status = cls._enum(response.get("status"), {"DIAGNOSTIC_ONLY", "FAIL_CLOSED"}, "status")
        failure = response.get("failure_code")
        if not isinstance(failure, str):
            raise NativeV3InputEvidenceAdapterError("Native V3 failure code is invalid")
        if status == "DIAGNOSTIC_ONLY" and failure != "NONE":
            raise NativeV3InputEvidenceAdapterError("Native V3 success/failure state is inconsistent")
        if cls._bool(response.get("authorization_capsule_issued"),
                     "authorization_capsule_issued"):
            raise NativeV3InputEvidenceAdapterError("Native V3 cannot issue an authorization capsule")
        for key in (
            "capsule_side_effect_count", "risk_authorization_receipt_count", "input_grant_count",
            "executor_dispatch_count", "external_input_dispatch_count", "text_event_count",
            "test_setup_action_count_delta", "device_action_count_delta", "device_action_count",
        ):
            if type(response.get(key)) is not int or response[key] != 0:
                raise NativeV3InputEvidenceAdapterError("Native V3 side-effect contract is invalid")
        hidden_state = cls._enum(
            response.get("hidden_state"), {"TRUE", "FALSE", "UNAVAILABLE"}, "hidden_state",
        )
        hidden_presence = cls._enum(
            response.get("hidden_presence"),
            {"PRESENT_TRUE", "PRESENT_FALSE", "UNAVAILABLE"}, "hidden_presence",
        )
        if hidden_presence != {
            "TRUE": "PRESENT_TRUE", "FALSE": "PRESENT_FALSE", "UNAVAILABLE": "UNAVAILABLE",
        }[hidden_state]:
            raise NativeV3InputEvidenceAdapterError("Native V3 hidden presence mismatch")
        hidden_provenance = cls._enum(
            response.get("hidden_provenance"), {"DIRECT_NATIVE_GETTER", "UNAVAILABLE"},
            "hidden_provenance",
        )
        hidden_getter = cls._enum(
            response.get("hidden_getter"), {"TYPED_UIVIEW_ISHIDDEN", "UNAVAILABLE"},
            "hidden_getter",
        )
        if hidden_state == "UNAVAILABLE":
            if hidden_provenance != "UNAVAILABLE" or hidden_getter != "UNAVAILABLE":
                raise NativeV3InputEvidenceAdapterError("Native V3 unavailable hidden state is inconsistent")
        elif (hidden_provenance != "DIRECT_NATIVE_GETTER"
              or hidden_getter != "TYPED_UIVIEW_ISHIDDEN"):
            raise NativeV3InputEvidenceAdapterError("Native V3 hidden provenance is invalid")
        presentation = cls._enum(
            response.get("controlled_presentation"),
            {"PRESENTED_IN_CONTROLLED_FIXTURE", "NOT_PRESENTED_IN_CONTROLLED_FIXTURE", "UNAVAILABLE"},
            "controlled_presentation",
        )
        presentation_provenance = cls._enum(
            response.get("presentation_provenance"),
            {"CONTROLLED_FIXTURE_PRESENTATION_COMPOSITE", "UNAVAILABLE"},
            "presentation_provenance",
        )
        digest = response.get("presentation_component_digest")
        if presentation == "UNAVAILABLE":
            if presentation_provenance != "UNAVAILABLE" or digest != "UNAVAILABLE":
                raise NativeV3InputEvidenceAdapterError("Native V3 unavailable presentation is inconsistent")
        elif (presentation_provenance != "CONTROLLED_FIXTURE_PRESENTATION_COMPOSITE"
              or not isinstance(digest, str) or len(digest) != 64
              or any(character not in "0123456789abcdef" for character in digest)):
            raise NativeV3InputEvidenceAdapterError("Native V3 presentation provenance is invalid")
        if status == "DIAGNOSTIC_ONLY" and (hidden_state != "TRUE"
                or presentation != "NOT_PRESENTED_IN_CONTROLLED_FIXTURE"):
            raise NativeV3InputEvidenceAdapterError("Native V3 hidden target semantic is invalid")
        return {
            "hidden_state": hidden_state,
            "hidden_presence": hidden_presence,
            "hidden_provenance": hidden_provenance,
            "hidden_getter": hidden_getter,
            "presentation": presentation,
            "presentation_provenance": presentation_provenance,
        }

    @classmethod
    def from_authenticated_transaction(
        cls,
        response: dict[str, Any],
        *,
        request_nonce_match: bool,
        c1_initial_auth_pass: bool,
        c1_post_auth_pass: bool,
        received_at: int,
        now: int | None = None,
        max_age_seconds: int = 60,
    ) -> "ValidatedNativeV3AuthorizationEvidence":
        current = int(time.time()) if now is None else int(now)
        if (request_nonce_match is not True or c1_initial_auth_pass is not True
                or c1_post_auth_pass is not True or type(received_at) is not int
                or not 0 <= current - received_at <= max_age_seconds):
            raise NativeV3InputEvidenceAdapterError(
                "fresh authenticated Native V3 request binding is required"
            )
        return cls(cls._SEAL, cls._validated_facts(response), fresh_request_binding=True)


class NativeV3InputAuthorizationEvidenceAdapter:
    """Normalize validated hidden-only Native V3 evidence for diagnostics."""

    @staticmethod
    def adapt(value: ValidatedNativeV3AuthorizationEvidence) -> NormalizedInputAuthorizationEvidence:
        if not isinstance(value, ValidatedNativeV3AuthorizationEvidence):
            raise NativeV3InputEvidenceAdapterError("validated Native V3 evidence is required")
        facts = value._facts
        presentation = {
            "PRESENTED_IN_CONTROLLED_FIXTURE": "TRUE",
            "NOT_PRESENTED_IN_CONTROLLED_FIXTURE": "FALSE",
            "UNAVAILABLE": "UNAVAILABLE",
        }[facts["presentation"]]
        return NormalizedInputAuthorizationEvidence(
            provider="NATIVE_UIKIT_SINGLE_PROVIDER",
            scope="CONTROLLED_FIXTURE_ONLY",
            grantable=False,
            source_valid=True,
            same_target=True,
            role_allowed=True,
            role_provenance_valid=True,
            editable_state="NOT_APPLICABLE",
            editable_provenance_valid=False,
            secure_state="UNAVAILABLE",
            secure_provenance_valid=False,
            enabled_state="UNAVAILABLE",
            enabled_provenance_valid=False,
            presentation_state=presentation,
            presentation_provenance_valid=(
                facts["presentation_provenance"] == "CONTROLLED_FIXTURE_PRESENTATION_COMPOSITE"
            ),
            actionable_state="UNAVAILABLE",
            actionable_provenance_valid=False,
            focus_state="UNAVAILABLE",
            focus_provenance_valid=False,
            selector_state="NOT_APPLICABLE",
            fresh_request_binding=value.fresh_request_binding,
            target_hidden_state=facts["hidden_state"],
            target_hidden_presence=facts["hidden_presence"],
            target_hidden_provenance=facts["hidden_provenance"],
            target_hidden_getter=facts["hidden_getter"],
        )


@dataclass(frozen=True)
class SemanticSearchFieldEvidence:
    """Ephemeral, same-leaf AX evidence for one semantic text field.

    Boolean state is tri-state: ``True``, ``False`` or ``None`` (unknown).
    Authorization requires direct observed provenance.  Inferred state remains
    useful diagnostics but can never make a field action-authoritative.
    ``selector_text`` is a private one-time action input; raw field values are
    never exposed to the Host runtime.
    """

    DIRECT_SOURCES = frozenset({"ax_attribute", "xc_attribute"})
    ROLE_SOURCES = frozenset({"ax_attribute", "xc_attribute", "trait"})
    STATE_SOURCES = frozenset({"ax_attribute", "xc_attribute", "trait", "inferred", "unavailable"})

    field_ref: str
    source: str
    role: str
    role_source: str
    editable: bool | None
    editable_source: str
    secure: bool | None
    secure_source: str
    enabled: bool | None
    enabled_source: str
    visible: bool | None
    visible_source: str
    actionable: bool | None
    actionable_source: str
    focused: bool | None
    focused_source: str
    same_leaf_identity: bool | None
    selector_text: str
    value_matches_expected: bool | None = None
    value_match_source: str = "unavailable"
    same_leaf_source: str = "unavailable"
    snapshot_ref: str | None = None

    @classmethod
    def from_compact_element(cls, element: Any) -> "SemanticSearchFieldEvidence | None":
        if not isinstance(element, dict):
            return None
        state = element.get("semantic_state")
        field_ref = element.get("semantic_leaf_ref")
        if not isinstance(state, dict) or not isinstance(field_ref, str) or not field_ref:
            return None

        def state_value(key: str) -> tuple[bool | None, str]:
            entry = state.get(key)
            if not isinstance(entry, dict):
                return None, "unavailable"
            source = entry.get("source")
            if not isinstance(source, str) or source not in cls.STATE_SOURCES or source == "unavailable":
                return None, "unavailable"
            value = entry.get("value")
            if value is True or value is False:
                return value, source
            return None, "unavailable"

        role_entry = state.get("semantic_role")
        role = "unknown"
        role_source = "unavailable"
        if isinstance(role_entry, dict):
            candidate_role = role_entry.get("value")
            candidate_source = role_entry.get("source")
            if (isinstance(candidate_role, str) and candidate_role in {
                    "search_field", "text_field", "secure_text_field", "editable_text_field", "button", "link", "browser"
                } and isinstance(candidate_source, str) and candidate_source in cls.STATE_SOURCES
                    and candidate_source != "unavailable"):
                role = candidate_role
                role_source = candidate_source

        editable, editable_source = state_value("editable")
        secure, secure_source = state_value("secure")
        enabled, enabled_source = state_value("enabled")
        visible, visible_source = state_value("visible")
        actionable, actionable_source = state_value("actionable")
        focused, focused_source = state_value("focused")
        value_matches_expected, value_match_source = state_value("value_match")
        selector = str(element.get("text") or "").strip()
        return cls(
            field_ref=field_ref,
            source="AX",
            role=role,
            role_source=role_source,
            editable=editable,
            editable_source=editable_source,
            secure=secure,
            secure_source=secure_source,
            enabled=enabled,
            enabled_source=enabled_source,
            visible=visible,
            visible_source=visible_source,
            actionable=actionable,
            actionable_source=actionable_source,
            focused=focused,
            focused_source=focused_source,
            # The current compact crawler performs separate live AX reads.
            # No raw flag or invented generation can turn it into a snapshot.
            same_leaf_identity=None,
            selector_text=selector,
            value_matches_expected=value_matches_expected,
            value_match_source=value_match_source,
        )

    def eligible(self) -> bool:
        evidence = AXInputAuthorizationEvidenceAdapter.adapt(self)
        result = InputAuthorizationPredicateEvaluator.evaluate(
            evidence,
            predicates=InputAuthorizationPredicateEvaluator.AX_ELIGIBILITY_PREDICATES,
        )
        return result.decision == "ALLOW"

    def has_same_leaf_identity(self) -> bool:
        return (self.same_leaf_identity is True and self.same_leaf_source == "direct_snapshot"
                and isinstance(self.snapshot_ref, str) and bool(self.snapshot_ref))

    def focus_is_verified(self) -> bool:
        evidence = AXInputAuthorizationEvidenceAdapter.adapt(self)
        result = InputAuthorizationPredicateEvaluator.evaluate(
            evidence,
            predicates=InputAuthorizationPredicateEvaluator.AX_FOCUS_PREDICATES,
        )
        return result.decision == "ALLOW"

    def expected_value_is_verified(self) -> bool:
        return (self.has_same_leaf_identity() and self.value_matches_expected is True
                and self.value_match_source in self.DIRECT_SOURCES)

    def safe_summary(self) -> dict[str, Any]:
        return {
            "field_ref": self.field_ref,
            "source": self.source,
            "role": self.role,
            "role_source": self.role_source,
            "editable": self.editable,
            "editable_source": self.editable_source,
            "secure": self.secure,
            "secure_source": self.secure_source,
            "enabled": self.enabled,
            "enabled_source": self.enabled_source,
            "visible": self.visible,
            "visible_source": self.visible_source,
            "actionable": self.actionable,
            "actionable_source": self.actionable_source,
            "focused": self.focused,
            "focused_source": self.focused_source,
            "same_leaf_identity": self.same_leaf_identity,
            "same_leaf_source": self.same_leaf_source,
            "snapshot_ref": self.snapshot_ref,
            "value_matches_expected": self.value_matches_expected,
            "value_match_source": self.value_match_source,
        }


@dataclass(frozen=True)
class SemanticSearchPageObservation:
    """Fresh, task-scoped page state used only during a TEST-51 transaction."""

    source: str
    observed_at: int
    observation_version: int
    page_fingerprint: str
    task_id: str
    context_id: str
    fields: tuple[SemanticSearchFieldEvidence, ...]
    result_state: bool = False
    freshness_source: str = "unavailable"
    device_generation: str | None = None
    device_generation_source: str = "unavailable"

    def snapshot_is_correlated(self) -> bool:
        return (self.device_generation_source == "direct_snapshot"
                and isinstance(self.device_generation, str) and bool(self.device_generation)
                and all(field.has_same_leaf_identity() and field.snapshot_ref == self.device_generation
                        for field in self.fields))

    def safe_summary(self) -> dict[str, Any]:
        return {
            "source": self.source,
            "observed_at": self.observed_at,
            "observation_version": self.observation_version,
            "page_fingerprint": self.page_fingerprint,
            "task_id": self.task_id,
            "context_id": self.context_id,
            "eligible_field_count": sum(1 for field in self.fields if field.eligible()),
            "result_state": self.result_state,
            "freshness_source": self.freshness_source,
            "device_generation": self.device_generation,
            "device_generation_source": self.device_generation_source,
        }


class EvidenceGrade(Enum):
    """Provider evidence category, deliberately not an authorization ordering."""

    L4_STRUCTURED = "L4_STRUCTURED"
    L3_NATIVE_EXACT = "L3_NATIVE_EXACT"
    L2_STRUCTURAL_AX = "L2_STRUCTURAL_AX"
    L1_VISION_SEMANTIC = "L1_VISION_SEMANTIC"


class EvidenceSemantic(Enum):
    ROLE_ALLOWED = "ROLE_ALLOWED"
    EDITABLE = "EDITABLE"
    SECURE = "SECURE"
    ENABLED = "ENABLED"
    PRESENTATION = "PRESENTATION"
    ACTIONABLE = "ACTIONABLE"
    FOCUS = "FOCUS"
    SAME_LEAF_IDENTITY = "SAME_LEAF_IDENTITY"
    SNAPSHOT_FRESHNESS = "SNAPSHOT_FRESHNESS"
    EXPECTED_VALUE_MATCH = "EXPECTED_VALUE_MATCH"
    TARGET_HIDDEN = "TARGET_HIDDEN"
    CONTROLLED_PRESENTATION = "CONTROLLED_PRESENTATION"
    GENERIC_VISIBILITY = "GENERIC_VISIBILITY"


class EvidenceState(Enum):
    TRUE = "TRUE"
    FALSE = "FALSE"
    UNAVAILABLE = "UNAVAILABLE"
    NOT_APPLICABLE = "NOT_APPLICABLE"


class EvidenceProviderKind(Enum):
    STRUCTURED = "STRUCTURED"
    NATIVE_EXACT = "NATIVE_EXACT"
    CONTROLLED_NATIVE = "CONTROLLED_NATIVE"
    STRUCTURAL_AX = "STRUCTURAL_AX"
    VISION_SEMANTIC = "VISION_SEMANTIC"


class EvidenceProviderScope(Enum):
    STRUCTURED_RUNTIME = "STRUCTURED_RUNTIME"
    CONTROLLED_FIXTURE_ONLY = "CONTROLLED_FIXTURE_ONLY"
    PRODUCTION_AX = "PRODUCTION_AX"
    FRAME_SCOPED = "FRAME_SCOPED"


class EvidenceIdentityRequirement(Enum):
    NONE = "NONE"
    SAME_PROVIDER_LEAF = "SAME_PROVIDER_LEAF"
    EXACT_TARGET = "EXACT_TARGET"


class EvidenceCombinationPolicy(Enum):
    SINGLE_PROVIDER_ONLY = "SINGLE_PROVIDER_ONLY"
    EXPLICIT_CORRELATED = "EXPLICIT_CORRELATED"


class EvidencePrivacyClass(Enum):
    SAFE_TYPED_METADATA = "SAFE_TYPED_METADATA"


class EvidenceConfirmationRequirement(Enum):
    NOT_REQUIRED = "NOT_REQUIRED"
    CURRENT_CONFIRMATION_REQUIRED = "CURRENT_CONFIRMATION_REQUIRED"


class EvidenceCaptureStatus(Enum):
    CAPTURED = "CAPTURED"
    UNAVAILABLE = "UNAVAILABLE"
    INVALID = "INVALID"


class EvidenceValidationStatus(Enum):
    VALID = "VALID"
    INVALID = "INVALID"


def _evidence_contract_identifier(value: Any, field_name: str) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > 255:
        raise ValueError("%s must be a nonempty bounded identifier" % field_name)
    return value


@dataclass(frozen=True)
class EvidenceClaimRequirement:
    semantic: EvidenceSemantic
    expected_state: EvidenceState
    accepted_provenance: frozenset[str]

    def __post_init__(self) -> None:
        if not isinstance(self.semantic, EvidenceSemantic) or not isinstance(self.expected_state, EvidenceState):
            raise TypeError("typed evidence semantic and state are required")
        if (not isinstance(self.accepted_provenance, frozenset)
                or not self.accepted_provenance
                or any(not isinstance(item, str) or not item for item in self.accepted_provenance)):
            raise TypeError("accepted provenance must be a nonempty frozenset")


@dataclass(frozen=True)
class EvidenceRequirement:
    """Immutable Risk-owned requirement; it is not Planner or provider policy."""

    requirement_id: str
    capability_id: str
    action_class: str
    claims: tuple[EvidenceClaimRequirement, ...]
    identity_requirement: EvidenceIdentityRequirement
    maximum_age_seconds: int
    evaluation_time: int
    permitted_provider_ids: frozenset[str]
    permitted_provider_kinds: frozenset[EvidenceProviderKind]
    combination_policy: EvidenceCombinationPolicy
    privacy_class: EvidencePrivacyClass
    confirmation_requirement: EvidenceConfirmationRequirement
    verifier_contract: str
    required_task_id: str | None = None
    required_plan_id: str | None = None
    required_planning_revision: int | None = None
    required_step_id: str | None = None
    required_context_id: str | None = None
    required_context_version: int | None = None
    required_observation_generation: str | None = None
    permitted_provider_scopes: frozenset[EvidenceProviderScope] = frozenset()
    require_generation_binding: bool = False

    def __post_init__(self) -> None:
        for name in ("requirement_id", "capability_id", "action_class", "verifier_contract"):
            _evidence_contract_identifier(getattr(self, name), name)
        if (not isinstance(self.claims, tuple) or not self.claims
                or any(not isinstance(item, EvidenceClaimRequirement) for item in self.claims)):
            raise TypeError("claims must be a nonempty tuple of typed requirements")
        if len({item.semantic for item in self.claims}) != len(self.claims):
            raise ValueError("evidence requirement semantics must be unique")
        if not isinstance(self.identity_requirement, EvidenceIdentityRequirement):
            raise TypeError("typed identity requirement is required")
        if type(self.maximum_age_seconds) is not int or self.maximum_age_seconds < 0:
            raise ValueError("maximum evidence age must be nonnegative")
        if type(self.evaluation_time) is not int or self.evaluation_time < 0:
            raise ValueError("evaluation time must be nonnegative")
        if (not isinstance(self.permitted_provider_ids, frozenset)
                or any(not isinstance(item, str) or not item for item in self.permitted_provider_ids)):
            raise TypeError("permitted provider ids must be an immutable set")
        if (not isinstance(self.permitted_provider_kinds, frozenset)
                or any(not isinstance(item, EvidenceProviderKind) for item in self.permitted_provider_kinds)):
            raise TypeError("permitted provider kinds must be an immutable typed set")
        if (not isinstance(self.permitted_provider_scopes, frozenset)
                or any(not isinstance(item, EvidenceProviderScope)
                       for item in self.permitted_provider_scopes)):
            raise TypeError("permitted provider scopes must be an immutable typed set")
        if not self.permitted_provider_ids and not self.permitted_provider_kinds:
            raise ValueError("Risk must constrain provider identity or kind")
        if not isinstance(self.combination_policy, EvidenceCombinationPolicy):
            raise TypeError("typed combination policy is required")
        if not isinstance(self.privacy_class, EvidencePrivacyClass):
            raise TypeError("typed privacy class is required")
        if not isinstance(self.confirmation_requirement, EvidenceConfirmationRequirement):
            raise TypeError("typed confirmation requirement is required")
        for name in ("required_task_id", "required_plan_id", "required_step_id", "required_context_id",
                     "required_observation_generation"):
            value = getattr(self, name)
            if value is not None:
                _evidence_contract_identifier(value, name)
        for name in ("required_planning_revision", "required_context_version"):
            value = getattr(self, name)
            if value is not None and (type(value) is not int or value < 1):
                raise ValueError("%s must be a positive integer" % name)
        if type(self.require_generation_binding) is not bool:
            raise TypeError("generation binding requirement must be a boolean")


@dataclass(frozen=True)
class GovernedEvidenceRequirement(EvidenceRequirement):
    """Risk-stamped requirement whose authorized routing purpose is fixed.

    The stamp is written once by the Risk-owned builder. An unstamped or
    differently stamped requirement can never be routed for AUTHORIZATION;
    the router fails closed instead of inferring privilege.
    """

    routing_purpose: EvidenceRoutingPurpose | None = None

    def __post_init__(self) -> None:
        super().__post_init__()
        if self.routing_purpose is not None and not isinstance(self.routing_purpose, EvidenceRoutingPurpose):
            raise TypeError("typed routing purpose stamp is required")


@dataclass(frozen=True)
class GovernedEvidenceProviderDescriptor:
    provider_id: str
    provider_kind: EvidenceProviderKind
    grade: EvidenceGrade
    supported_semantics: frozenset[EvidenceSemantic]
    scope: EvidenceProviderScope
    identity_guarantees: frozenset[EvidenceIdentityRequirement]
    provenance_guarantees: frozenset[str]
    freshness_capabilities: frozenset[str]
    privacy_class: EvidencePrivacyClass
    authorization_grantable: bool

    def __post_init__(self) -> None:
        _evidence_contract_identifier(self.provider_id, "provider_id")
        if not isinstance(self.provider_kind, EvidenceProviderKind) or not isinstance(self.grade, EvidenceGrade):
            raise TypeError("typed provider kind and evidence grade are required")
        if (not isinstance(self.supported_semantics, frozenset)
                or any(not isinstance(item, EvidenceSemantic) for item in self.supported_semantics)):
            raise TypeError("supported semantics must be an immutable typed set")
        if not isinstance(self.scope, EvidenceProviderScope):
            raise TypeError("typed provider scope is required")
        if (not isinstance(self.identity_guarantees, frozenset)
                or any(not isinstance(item, EvidenceIdentityRequirement) for item in self.identity_guarantees)):
            raise TypeError("identity guarantees must be an immutable typed set")
        for name in ("provenance_guarantees", "freshness_capabilities"):
            value = getattr(self, name)
            if (not isinstance(value, frozenset)
                    or any(not isinstance(item, str) or not item for item in value)):
                raise TypeError("%s must be an immutable string set" % name)
        if not isinstance(self.privacy_class, EvidencePrivacyClass) or type(self.authorization_grantable) is not bool:
            raise TypeError("typed privacy and grantability metadata are required")


@dataclass(frozen=True)
class EvidenceCaptureRequest:
    """Provider-neutral need and context; intentionally has no provider override."""

    requirement_id: str
    task_id: str
    plan_id: str
    planning_revision: int
    step_id: str
    capability_id: str
    action_class: str
    target_ref: str
    context_id: str
    context_version: int
    observation_generation: str | None
    requested_at: int
    max_age_seconds: int
    required_semantics: frozenset[EvidenceSemantic]

    def __post_init__(self) -> None:
        for name in ("requirement_id", "task_id", "plan_id", "step_id", "capability_id", "action_class",
                     "target_ref", "context_id"):
            _evidence_contract_identifier(getattr(self, name), name)
        for name in ("planning_revision", "context_version"):
            if type(getattr(self, name)) is not int or getattr(self, name) < 1:
                raise ValueError("%s must be a positive integer" % name)
        if self.observation_generation is not None:
            _evidence_contract_identifier(self.observation_generation, "observation_generation")
        if type(self.requested_at) is not int or self.requested_at < 0:
            raise ValueError("requested_at must be nonnegative")
        if type(self.max_age_seconds) is not int or self.max_age_seconds < 0:
            raise ValueError("max_age_seconds must be nonnegative")
        if (not isinstance(self.required_semantics, frozenset)
                or not self.required_semantics
                or any(not isinstance(item, EvidenceSemantic) for item in self.required_semantics)):
            raise TypeError("required semantics must be a nonempty immutable typed set")


@dataclass(frozen=True)
class GovernedEvidenceFact:
    semantic: EvidenceSemantic
    state: EvidenceState
    provenance: str
    direct: bool
    presence: str = "UNAVAILABLE"
    getter: str = "UNAVAILABLE"

    def __post_init__(self) -> None:
        if not isinstance(self.semantic, EvidenceSemantic) or not isinstance(self.state, EvidenceState):
            raise TypeError("typed evidence fact is required")
        _evidence_contract_identifier(self.provenance, "provenance")
        if type(self.direct) is not bool:
            raise TypeError("direct must be a boolean")
        for name in ("presence", "getter"):
            _evidence_contract_identifier(getattr(self, name), name)


EvidencePayload = TypeVar("EvidencePayload")


@dataclass(frozen=True)
class GovernedEvidenceResult(Generic[EvidencePayload]):
    capture_status: EvidenceCaptureStatus
    provider_id: str
    provider_kind: EvidenceProviderKind
    grade: EvidenceGrade
    scope: EvidenceProviderScope
    requirement_id: str
    capability_id: str
    action_class: str
    task_id: str | None
    plan_id: str | None
    planning_revision: int | None
    step_id: str | None
    target_ref: str | None
    context_id: str | None
    context_version: int | None
    observation_generation: str | None
    requested_at: int
    captured_at: int | None
    facts: tuple[GovernedEvidenceFact, ...]
    identity_binding: bool
    freshness_binding: bool
    generation_binding: bool
    privacy_class: EvidencePrivacyClass
    evidence: EvidencePayload | None
    failure_codes: tuple[str, ...] = ()
    source_provider_id: str | None = None
    target_class: str | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.capture_status, EvidenceCaptureStatus):
            raise TypeError("typed capture status is required")
        _evidence_contract_identifier(self.provider_id, "provider_id")
        if (not isinstance(self.provider_kind, EvidenceProviderKind)
                or not isinstance(self.grade, EvidenceGrade)
                or not isinstance(self.scope, EvidenceProviderScope)):
            raise TypeError("typed provider result metadata is required")
        for name in ("requirement_id", "capability_id", "action_class"):
            _evidence_contract_identifier(getattr(self, name), name)
        if (not isinstance(self.facts, tuple)
                or any(not isinstance(item, GovernedEvidenceFact) for item in self.facts)):
            raise TypeError("facts must be an immutable typed tuple")
        if len({item.semantic for item in self.facts}) != len(self.facts):
            raise ValueError("captured semantics must be unique")
        if (type(self.identity_binding) is not bool or type(self.freshness_binding) is not bool
                or type(self.generation_binding) is not bool):
            raise TypeError("identity, freshness, and generation bindings must be booleans")
        if not isinstance(self.privacy_class, EvidencePrivacyClass):
            raise TypeError("typed privacy class is required")
        if self.capture_status is EvidenceCaptureStatus.CAPTURED and self.evidence is None:
            raise ValueError("captured evidence payload is required")
        if self.capture_status is not EvidenceCaptureStatus.CAPTURED and self.evidence is not None:
            raise ValueError("failed capture cannot carry evidence")
        if (not isinstance(self.failure_codes, tuple)
                or any(not isinstance(item, str) or not item for item in self.failure_codes)):
            raise TypeError("failure codes must be an immutable string tuple")
        for name in ("source_provider_id", "target_class"):
            value = getattr(self, name)
            if value is not None:
                _evidence_contract_identifier(value, name)

    def safe_summary(self) -> dict[str, Any]:
        return {
            "capture_status": self.capture_status.value,
            "provider_id": self.provider_id,
            "source_provider_id": self.source_provider_id,
            "provider_kind": self.provider_kind.value,
            "grade": self.grade.value,
            "scope": self.scope.value,
            "captured_semantics": [item.semantic.value for item in self.facts],
            "target_class": self.target_class,
            "identity_binding": self.identity_binding,
            "freshness_binding": self.freshness_binding,
            "generation_binding": self.generation_binding,
            "privacy_class": self.privacy_class.value,
            "failure_codes": list(self.failure_codes),
        }


@dataclass(frozen=True)
class EvidenceValidationResult:
    status: EvidenceValidationStatus
    failure_codes: tuple[str, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.status, EvidenceValidationStatus):
            raise TypeError("typed evidence validation status is required")
        if (not isinstance(self.failure_codes, tuple)
                or any(not isinstance(item, str) or not item for item in self.failure_codes)):
            raise TypeError("failure codes must be an immutable string tuple")
        if self.status is EvidenceValidationStatus.VALID and self.failure_codes:
            raise ValueError("valid evidence cannot contain failure codes")


@runtime_checkable
class GovernedEvidenceProvider(Protocol[EvidencePayload]):
    """Evidence-only provider contract with no authorization or action authority."""

    @property
    def descriptor(self) -> GovernedEvidenceProviderDescriptor:
        ...

    def capture(self, request: EvidenceCaptureRequest) -> GovernedEvidenceResult[EvidencePayload]:
        ...

    def validate(
        self,
        evidence: GovernedEvidenceResult[EvidencePayload],
        requirement: EvidenceRequirement,
    ) -> EvidenceValidationResult:
        ...


class AXL2GovernedEvidenceProvider:
    """Dormant shadow adapter over the existing authorization-grade AX model."""

    _DESCRIPTOR = GovernedEvidenceProviderDescriptor(
        provider_id="phoneharness.ax.same_leaf.v1",
        provider_kind=EvidenceProviderKind.STRUCTURAL_AX,
        grade=EvidenceGrade.L2_STRUCTURAL_AX,
        supported_semantics=frozenset({
            EvidenceSemantic.ROLE_ALLOWED,
            EvidenceSemantic.EDITABLE,
            EvidenceSemantic.SECURE,
            EvidenceSemantic.ENABLED,
            EvidenceSemantic.PRESENTATION,
            EvidenceSemantic.ACTIONABLE,
            EvidenceSemantic.FOCUS,
            EvidenceSemantic.SAME_LEAF_IDENTITY,
            EvidenceSemantic.SNAPSHOT_FRESHNESS,
            EvidenceSemantic.EXPECTED_VALUE_MATCH,
        }),
        scope=EvidenceProviderScope.PRODUCTION_AX,
        identity_guarantees=frozenset({EvidenceIdentityRequirement.SAME_PROVIDER_LEAF}),
        provenance_guarantees=frozenset({"ax_attribute", "xc_attribute", "trait", "direct_snapshot"}),
        freshness_capabilities=frozenset({"HOST_CAPTURE_TIME", "DIRECT_SNAPSHOT_GENERATION"}),
        privacy_class=EvidencePrivacyClass.SAFE_TYPED_METADATA,
        authorization_grantable=True,
    )

    def __init__(self, observation: SemanticSearchPageObservation) -> None:
        if not isinstance(observation, SemanticSearchPageObservation):
            raise TypeError("SemanticSearchPageObservation is required")
        self._observation = observation

    @property
    def descriptor(self) -> GovernedEvidenceProviderDescriptor:
        return self._DESCRIPTOR

    @staticmethod
    def _state(value: str | bool | None) -> EvidenceState:
        if value is True or value == "TRUE":
            return EvidenceState.TRUE
        if value is False or value == "FALSE":
            return EvidenceState.FALSE
        if value == "NOT_APPLICABLE":
            return EvidenceState.NOT_APPLICABLE
        return EvidenceState.UNAVAILABLE

    @classmethod
    def _facts(
        cls,
        field: SemanticSearchFieldEvidence,
        normalized: NormalizedInputAuthorizationEvidence,
        observation: SemanticSearchPageObservation,
    ) -> tuple[GovernedEvidenceFact, ...]:
        correlated = observation.snapshot_is_correlated()
        fresh_snapshot = correlated and observation.freshness_source == "direct_snapshot"
        expected_direct = field.value_match_source in field.DIRECT_SOURCES
        return (
            GovernedEvidenceFact(EvidenceSemantic.ROLE_ALLOWED, cls._state(normalized.role_allowed),
                                 field.role_source, normalized.role_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.EDITABLE, cls._state(normalized.editable_state),
                                 field.editable_source, normalized.editable_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.SECURE, cls._state(normalized.secure_state),
                                 field.secure_source, normalized.secure_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.ENABLED, cls._state(normalized.enabled_state),
                                 field.enabled_source, normalized.enabled_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.PRESENTATION, cls._state(normalized.presentation_state),
                                 field.visible_source, normalized.presentation_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.ACTIONABLE, cls._state(normalized.actionable_state),
                                 field.actionable_source, normalized.actionable_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.FOCUS, cls._state(normalized.focus_state),
                                 field.focused_source, normalized.focus_provenance_valid),
            GovernedEvidenceFact(EvidenceSemantic.SAME_LEAF_IDENTITY,
                                 EvidenceState.TRUE if normalized.same_target else EvidenceState.UNAVAILABLE,
                                 field.same_leaf_source, normalized.same_target),
            GovernedEvidenceFact(EvidenceSemantic.SNAPSHOT_FRESHNESS,
                                 EvidenceState.TRUE if fresh_snapshot else EvidenceState.UNAVAILABLE,
                                 observation.freshness_source, fresh_snapshot),
            GovernedEvidenceFact(EvidenceSemantic.EXPECTED_VALUE_MATCH,
                                 cls._state(field.value_matches_expected), field.value_match_source,
                                 expected_direct),
        )

    def _failed_result(
        self,
        request: EvidenceCaptureRequest,
        *failure_codes: str,
    ) -> GovernedEvidenceResult[NormalizedInputAuthorizationEvidence]:
        return GovernedEvidenceResult(
            capture_status=EvidenceCaptureStatus.INVALID,
            provider_id=self.descriptor.provider_id,
            provider_kind=self.descriptor.provider_kind,
            grade=self.descriptor.grade,
            scope=self.descriptor.scope,
            requirement_id=request.requirement_id,
            capability_id=request.capability_id,
            action_class=request.action_class,
            task_id=None,
            plan_id=None,
            planning_revision=None,
            step_id=None,
            target_ref=None,
            context_id=None,
            context_version=None,
            observation_generation=None,
            requested_at=request.requested_at,
            captured_at=None,
            facts=(),
            identity_binding=False,
            freshness_binding=False,
            generation_binding=False,
            privacy_class=self.descriptor.privacy_class,
            evidence=None,
            failure_codes=tuple(failure_codes),
        )

    def capture(
        self,
        request: EvidenceCaptureRequest,
    ) -> GovernedEvidenceResult[NormalizedInputAuthorizationEvidence]:
        if not isinstance(request, EvidenceCaptureRequest):
            raise TypeError("EvidenceCaptureRequest is required")
        observation = self._observation
        if not request.required_semantics.issubset(self.descriptor.supported_semantics):
            return self._failed_result(request, "UNSUPPORTED_SEMANTIC")
        if observation.source != "AX":
            return self._failed_result(request, "AX_SOURCE_REQUIRED")
        if observation.task_id != request.task_id or observation.context_id != request.context_id:
            return self._failed_result(request, "REQUEST_CONTEXT_MISMATCH")
        matches = tuple(field for field in observation.fields if field.field_ref == request.target_ref)
        if len(matches) != 1:
            return self._failed_result(request, "TARGET_LEAF_NOT_UNIQUE")
        field = matches[0]
        normalized = AXInputAuthorizationEvidenceAdapter.adapt(field)
        correlated = observation.snapshot_is_correlated()
        generation = observation.device_generation if correlated else None
        if request.observation_generation is not None and generation != request.observation_generation:
            return self._failed_result(request, "REQUEST_GENERATION_MISMATCH")
        return GovernedEvidenceResult(
            capture_status=EvidenceCaptureStatus.CAPTURED,
            provider_id=self.descriptor.provider_id,
            provider_kind=self.descriptor.provider_kind,
            grade=self.descriptor.grade,
            scope=self.descriptor.scope,
            requirement_id=request.requirement_id,
            capability_id=request.capability_id,
            action_class=request.action_class,
            task_id=observation.task_id,
            plan_id=None,
            planning_revision=None,
            step_id=None,
            target_ref=field.field_ref,
            context_id=observation.context_id,
            context_version=None,
            observation_generation=generation,
            requested_at=request.requested_at,
            captured_at=observation.observed_at,
            facts=self._facts(field, normalized, observation),
            identity_binding=normalized.same_target,
            freshness_binding=correlated and observation.freshness_source == "direct_snapshot",
            generation_binding=correlated,
            privacy_class=self.descriptor.privacy_class,
            evidence=normalized,
        )

    def validate(
        self,
        evidence: GovernedEvidenceResult[NormalizedInputAuthorizationEvidence],
        requirement: EvidenceRequirement,
    ) -> EvidenceValidationResult:
        if not isinstance(evidence, GovernedEvidenceResult) or not isinstance(requirement, EvidenceRequirement):
            raise TypeError("typed evidence result and requirement are required")
        failures: list[str] = []
        if evidence.capture_status is not EvidenceCaptureStatus.CAPTURED:
            failures.extend(evidence.failure_codes or ("EVIDENCE_NOT_CAPTURED",))
        if (evidence.provider_id != self.descriptor.provider_id
                or evidence.provider_kind is not self.descriptor.provider_kind
                or evidence.grade is not self.descriptor.grade
                or evidence.scope is not self.descriptor.scope):
            failures.append("PROVIDER_DESCRIPTOR_MISMATCH")
        if requirement.permitted_provider_ids and evidence.provider_id not in requirement.permitted_provider_ids:
            failures.append("PROVIDER_ID_NOT_PERMITTED")
        if requirement.permitted_provider_kinds and evidence.provider_kind not in requirement.permitted_provider_kinds:
            failures.append("PROVIDER_KIND_NOT_PERMITTED")
        if requirement.permitted_provider_scopes and evidence.scope not in requirement.permitted_provider_scopes:
            failures.append("PROVIDER_SCOPE_NOT_PERMITTED")
        if evidence.privacy_class is not requirement.privacy_class:
            failures.append("PRIVACY_CLASS_MISMATCH")
        if (evidence.requirement_id != requirement.requirement_id
                or evidence.capability_id != requirement.capability_id
                or evidence.action_class != requirement.action_class
                or evidence.requested_at != requirement.evaluation_time):
            failures.append("REQUIREMENT_BINDING_MISMATCH")
        bindings = (
            ("TASK", requirement.required_task_id, evidence.task_id),
            ("PLAN", requirement.required_plan_id, evidence.plan_id),
            ("PLANNING_REVISION", requirement.required_planning_revision, evidence.planning_revision),
            ("STEP", requirement.required_step_id, evidence.step_id),
            ("CONTEXT", requirement.required_context_id, evidence.context_id),
        )
        for label, expected, actual in bindings:
            if expected is not None and actual != expected:
                failures.append("%s_BINDING_MISMATCH" % label)
        if requirement.required_context_version is not None:
            if evidence.context_version != requirement.required_context_version:
                failures.append(
                    "CONTEXT_VERSION_UNAVAILABLE" if evidence.context_version is None
                    else "CONTEXT_VERSION_MISMATCH"
                )
        if requirement.required_observation_generation is not None:
            if evidence.observation_generation is None:
                failures.append("OBSERVATION_GENERATION_UNAVAILABLE")
            elif evidence.observation_generation != requirement.required_observation_generation:
                failures.append("OBSERVATION_GENERATION_MISMATCH")
        if requirement.require_generation_binding and not evidence.generation_binding:
            failures.append("GENERATION_BINDING_UNSATISFIED")
        if (requirement.identity_requirement is not EvidenceIdentityRequirement.NONE
                and (requirement.identity_requirement not in self.descriptor.identity_guarantees
                     or not evidence.identity_binding)):
            failures.append("IDENTITY_REQUIREMENT_UNSATISFIED")
        if (evidence.captured_at is None
                or requirement.evaluation_time < evidence.captured_at
                or requirement.evaluation_time - evidence.captured_at > requirement.maximum_age_seconds):
            failures.append("EVIDENCE_STALE")
        facts = {item.semantic: item for item in evidence.facts}
        for claim in requirement.claims:
            fact = facts.get(claim.semantic)
            if fact is None:
                failures.append("%s_UNAVAILABLE" % claim.semantic.value)
                continue
            if fact.state is not claim.expected_state:
                failures.append("%s_STATE_MISMATCH" % claim.semantic.value)
            if not fact.direct or fact.provenance not in claim.accepted_provenance:
                failures.append("%s_PROVENANCE_UNACCEPTED" % claim.semantic.value)
        unique_failures = tuple(dict.fromkeys(failures))
        return EvidenceValidationResult(
            EvidenceValidationStatus.INVALID if unique_failures else EvidenceValidationStatus.VALID,
            unique_failures,
        )


class ControlledNativeL3EvidenceError(ValueError):
    """Controlled Native L3 input was not an existing sealed evidence value."""


class ControlledNativeL3GovernedEvidenceProvider:
    """Dormant, non-grantable wrapper for frozen controlled-fixture Native L3 facts."""

    _DESCRIPTOR = GovernedEvidenceProviderDescriptor(
        provider_id="controlled_native_l3",
        provider_kind=EvidenceProviderKind.CONTROLLED_NATIVE,
        grade=EvidenceGrade.L3_NATIVE_EXACT,
        supported_semantics=frozenset({
            EvidenceSemantic.EDITABLE,
            EvidenceSemantic.ENABLED,
            EvidenceSemantic.TARGET_HIDDEN,
            EvidenceSemantic.CONTROLLED_PRESENTATION,
        }),
        scope=EvidenceProviderScope.CONTROLLED_FIXTURE_ONLY,
        identity_guarantees=frozenset({EvidenceIdentityRequirement.EXACT_TARGET}),
        provenance_guarantees=frozenset({
            "DIRECT_NATIVE_GETTER",
            "CONTROLLED_FIXTURE_PRESENTATION_COMPOSITE",
        }),
        freshness_capabilities=frozenset({
            "AUTHENTICATED_CURRENT_REQUEST",
            "PROCESS_LIFECYCLE_GENERATION_BOUND",
        }),
        privacy_class=EvidencePrivacyClass.SAFE_TYPED_METADATA,
        authorization_grantable=False,
    )

    _TARGETS = {
        ValidatedNativeV1AuthorizationEvidence: "read_only",
        ValidatedNativeV2AuthorizationEvidence: "disabled",
        ValidatedNativeV3AuthorizationEvidence: "hidden",
    }
    _TARGET_CLASSES = {
        ValidatedNativeV1AuthorizationEvidence: "UITextView",
        ValidatedNativeV2AuthorizationEvidence: "UITextField",
        ValidatedNativeV3AuthorizationEvidence: "UITextField",
    }

    @property
    def descriptor(self) -> GovernedEvidenceProviderDescriptor:
        return self._DESCRIPTOR

    @staticmethod
    def _state(value: str) -> EvidenceState:
        return {
            "TRUE": EvidenceState.TRUE,
            "FALSE": EvidenceState.FALSE,
            "NOT_APPLICABLE": EvidenceState.NOT_APPLICABLE,
        }.get(value, EvidenceState.UNAVAILABLE)

    def _failed_result(
        self,
        request: EvidenceCaptureRequest,
        *failure_codes: str,
    ) -> GovernedEvidenceResult[Any]:
        return GovernedEvidenceResult(
            capture_status=EvidenceCaptureStatus.UNAVAILABLE,
            provider_id=self.descriptor.provider_id,
            provider_kind=self.descriptor.provider_kind,
            grade=self.descriptor.grade,
            scope=self.descriptor.scope,
            requirement_id=request.requirement_id,
            capability_id=request.capability_id,
            action_class=request.action_class,
            task_id=None,
            plan_id=None,
            planning_revision=None,
            step_id=None,
            target_ref=None,
            context_id=None,
            context_version=None,
            observation_generation=None,
            requested_at=request.requested_at,
            captured_at=None,
            facts=(),
            identity_binding=False,
            freshness_binding=False,
            generation_binding=False,
            privacy_class=self.descriptor.privacy_class,
            evidence=None,
            failure_codes=tuple(failure_codes),
        )

    def capture(self, request: EvidenceCaptureRequest) -> GovernedEvidenceResult[Any]:
        if not isinstance(request, EvidenceCaptureRequest):
            raise TypeError("EvidenceCaptureRequest is required")
        return self._failed_result(request, "PRODUCTION_DORMANT")

    def wrap_validated(
        self,
        request: EvidenceCaptureRequest,
        evidence: ValidatedNativeV1AuthorizationEvidence
        | ValidatedNativeV2AuthorizationEvidence
        | ValidatedNativeV3AuthorizationEvidence,
    ) -> GovernedEvidenceResult[Any]:
        if not isinstance(request, EvidenceCaptureRequest):
            raise TypeError("EvidenceCaptureRequest is required")
        evidence_type = type(evidence)
        if evidence_type not in self._TARGETS:
            raise ControlledNativeL3EvidenceError("sealed Native V1/V2/V3 evidence is required")
        target_ref = self._TARGETS[evidence_type]
        if request.target_ref != target_ref:
            raise ControlledNativeL3EvidenceError("controlled Native target does not match the request")
        values = evidence._facts
        if evidence_type is ValidatedNativeV1AuthorizationEvidence:
            facts = (
                GovernedEvidenceFact(
                    EvidenceSemantic.EDITABLE,
                    self._state(values["editable_state"]),
                    values["editable_provenance"],
                    values["editable_provenance"] == "DIRECT_NATIVE_GETTER"
                    and values["editable_getter"] == "TYPED_UITEXTVIEW_ISEDITABLE",
                    values["editable_presence"],
                    values["editable_getter"],
                ),
            )
        elif evidence_type is ValidatedNativeV2AuthorizationEvidence:
            facts = (
                GovernedEvidenceFact(
                    EvidenceSemantic.ENABLED,
                    self._state(values["enabled_state"]),
                    values["enabled_provenance"],
                    values["enabled_provenance"] == "DIRECT_NATIVE_GETTER"
                    and values["enabled_getter"] == "TYPED_UITEXTFIELD_ISENABLED",
                    values["enabled_presence"],
                    values["enabled_getter"],
                ),
            )
        else:
            presentation_state = {
                "PRESENTED_IN_CONTROLLED_FIXTURE": EvidenceState.TRUE,
                "NOT_PRESENTED_IN_CONTROLLED_FIXTURE": EvidenceState.FALSE,
            }.get(values["presentation"], EvidenceState.UNAVAILABLE)
            facts = (
                GovernedEvidenceFact(
                    EvidenceSemantic.TARGET_HIDDEN,
                    self._state(values["hidden_state"]),
                    values["hidden_provenance"],
                    values["hidden_provenance"] == "DIRECT_NATIVE_GETTER"
                    and values["hidden_getter"] == "TYPED_UIVIEW_ISHIDDEN",
                    values["hidden_presence"],
                    values["hidden_getter"],
                ),
                GovernedEvidenceFact(
                    EvidenceSemantic.CONTROLLED_PRESENTATION,
                    presentation_state,
                    values["presentation_provenance"],
                    values["presentation_provenance"]
                    == "CONTROLLED_FIXTURE_PRESENTATION_COMPOSITE",
                    "PRESENT_%s" % presentation_state.value
                    if presentation_state in {EvidenceState.TRUE, EvidenceState.FALSE}
                    else "UNAVAILABLE",
                    "UNAVAILABLE",
                ),
            )
        fresh = evidence.fresh_request_binding
        return GovernedEvidenceResult(
            capture_status=EvidenceCaptureStatus.CAPTURED,
            provider_id=self.descriptor.provider_id,
            provider_kind=self.descriptor.provider_kind,
            grade=self.descriptor.grade,
            scope=self.descriptor.scope,
            requirement_id=request.requirement_id,
            capability_id=request.capability_id,
            action_class=request.action_class,
            task_id=None,
            plan_id=None,
            planning_revision=None,
            step_id=None,
            target_ref=target_ref,
            context_id=None,
            context_version=None,
            observation_generation=None,
            requested_at=request.requested_at,
            captured_at=request.requested_at if fresh else None,
            facts=facts,
            identity_binding=True,
            freshness_binding=fresh,
            generation_binding=True,
            privacy_class=self.descriptor.privacy_class,
            evidence=evidence,
            source_provider_id="NATIVE_UIKIT_SINGLE_PROVIDER",
            target_class=self._TARGET_CLASSES[evidence_type],
        )

    def validate(
        self,
        evidence: GovernedEvidenceResult[Any],
        requirement: EvidenceRequirement,
    ) -> EvidenceValidationResult:
        if not isinstance(evidence, GovernedEvidenceResult) or not isinstance(requirement, EvidenceRequirement):
            raise TypeError("typed evidence result and requirement are required")
        failures: list[str] = []
        if evidence.capture_status is not EvidenceCaptureStatus.CAPTURED:
            failures.extend(evidence.failure_codes or ("EVIDENCE_NOT_CAPTURED",))
        if (evidence.provider_id != self.descriptor.provider_id
                or evidence.provider_kind is not self.descriptor.provider_kind
                or evidence.grade is not self.descriptor.grade
                or evidence.scope is not self.descriptor.scope):
            failures.append("PROVIDER_DESCRIPTOR_MISMATCH")
        if requirement.permitted_provider_ids and evidence.provider_id not in requirement.permitted_provider_ids:
            failures.append("PROVIDER_ID_NOT_PERMITTED")
        if requirement.permitted_provider_kinds and evidence.provider_kind not in requirement.permitted_provider_kinds:
            failures.append("PROVIDER_KIND_NOT_PERMITTED")
        if requirement.permitted_provider_scopes and evidence.scope not in requirement.permitted_provider_scopes:
            failures.append("PROVIDER_SCOPE_NOT_PERMITTED")
        if evidence.privacy_class is not requirement.privacy_class:
            failures.append("PRIVACY_CLASS_MISMATCH")
        if (evidence.requirement_id != requirement.requirement_id
                or evidence.capability_id != requirement.capability_id
                or evidence.action_class != requirement.action_class
                or evidence.requested_at != requirement.evaluation_time):
            failures.append("REQUIREMENT_BINDING_MISMATCH")
        bindings = (
            ("TASK", requirement.required_task_id, evidence.task_id),
            ("PLAN", requirement.required_plan_id, evidence.plan_id),
            ("PLANNING_REVISION", requirement.required_planning_revision, evidence.planning_revision),
            ("STEP", requirement.required_step_id, evidence.step_id),
            ("CONTEXT", requirement.required_context_id, evidence.context_id),
        )
        for label, expected, actual in bindings:
            if expected is not None and actual != expected:
                failures.append("%s_BINDING_MISMATCH" % label)
        if requirement.required_context_version is not None:
            failures.append(
                "CONTEXT_VERSION_UNAVAILABLE" if evidence.context_version is None
                else "CONTEXT_VERSION_MISMATCH"
            )
        if requirement.required_observation_generation is not None:
            failures.append(
                "OBSERVATION_GENERATION_UNAVAILABLE" if evidence.observation_generation is None
                else "OBSERVATION_GENERATION_MISMATCH"
            )
        if requirement.require_generation_binding and not evidence.generation_binding:
            failures.append("GENERATION_BINDING_UNSATISFIED")
        if (requirement.identity_requirement is not EvidenceIdentityRequirement.NONE
                and (requirement.identity_requirement not in self.descriptor.identity_guarantees
                     or not evidence.identity_binding)):
            failures.append("IDENTITY_REQUIREMENT_UNSATISFIED")
        if (not evidence.freshness_binding or evidence.captured_at is None
                or requirement.evaluation_time < evidence.captured_at
                or requirement.evaluation_time - evidence.captured_at > requirement.maximum_age_seconds):
            failures.append("EVIDENCE_STALE")
        facts = {item.semantic: item for item in evidence.facts}
        for claim in requirement.claims:
            fact = facts.get(claim.semantic)
            if fact is None:
                failures.append("%s_UNAVAILABLE" % claim.semantic.value)
                continue
            if fact.state is not claim.expected_state:
                failures.append("%s_STATE_MISMATCH" % claim.semantic.value)
            if not fact.direct or fact.provenance not in claim.accepted_provenance:
                failures.append("%s_PROVENANCE_UNACCEPTED" % claim.semantic.value)
        unique_failures = tuple(dict.fromkeys(failures))
        return EvidenceValidationResult(
            EvidenceValidationStatus.INVALID if unique_failures else EvidenceValidationStatus.VALID,
            unique_failures,
        )


class EvidenceRoutingPurpose(Enum):
    """Why Risk is routing; it is not itself an authorization decision."""

    AUTHORIZATION = "AUTHORIZATION"
    VERIFICATION = "VERIFICATION"
    DIAGNOSTIC = "DIAGNOSTIC"


class ShadowEvidenceRoutingStatus(Enum):
    SUITABLE = "SUITABLE"
    AMBIGUOUS = "AMBIGUOUS"
    NO_SUITABLE_PROVIDER = "NO_SUITABLE_PROVIDER"


class EvidenceRoutingCandidateStatus(Enum):
    SUITABLE = "SUITABLE"
    UNAVAILABLE = "UNAVAILABLE"
    PROVIDER_NOT_PERMITTED = "PROVIDER_NOT_PERMITTED"
    SCOPE_MISMATCH = "SCOPE_MISMATCH"
    PRIVACY_INCOMPATIBLE = "PRIVACY_INCOMPATIBLE"
    UNSUPPORTED_SEMANTIC = "UNSUPPORTED_SEMANTIC"
    IDENTITY_INSUFFICIENT = "IDENTITY_INSUFFICIENT"
    PROVENANCE_INSUFFICIENT = "PROVENANCE_INSUFFICIENT"
    FRESHNESS_INSUFFICIENT = "FRESHNESS_INSUFFICIENT"
    NON_GRANTABLE = "NON_GRANTABLE"
    COMBINATION_FORBIDDEN = "COMBINATION_FORBIDDEN"
    AMBIGUOUS = "AMBIGUOUS"


@dataclass(frozen=True)
class ShadowEvidenceRoutingCandidate:
    """Per-provider contract verdict; metadata only, never an authority token."""

    provider_id: str
    provider_kind: EvidenceProviderKind
    grade: EvidenceGrade
    scope: EvidenceProviderScope
    authorization_grantable: bool
    semantic_suitability: bool
    authorization_route_suitability: bool
    status: EvidenceRoutingCandidateStatus
    rejection_reasons: tuple[str, ...]

    def __post_init__(self) -> None:
        _evidence_contract_identifier(self.provider_id, "provider_id")
        if (not isinstance(self.provider_kind, EvidenceProviderKind)
                or not isinstance(self.grade, EvidenceGrade)
                or not isinstance(self.scope, EvidenceProviderScope)):
            raise TypeError("typed provider metadata is required")
        for name in ("authorization_grantable", "semantic_suitability", "authorization_route_suitability"):
            if type(getattr(self, name)) is not bool:
                raise TypeError("%s must be a boolean" % name)
        if not isinstance(self.status, EvidenceRoutingCandidateStatus):
            raise TypeError("typed candidate status is required")
        if (not isinstance(self.rejection_reasons, tuple)
                or any(not isinstance(item, str) or not item for item in self.rejection_reasons)):
            raise TypeError("rejection reasons must be an immutable string tuple")
        if self.status is EvidenceRoutingCandidateStatus.SUITABLE and self.rejection_reasons:
            raise ValueError("suitable candidate cannot carry rejection reasons")
        if self.status is not EvidenceRoutingCandidateStatus.SUITABLE and not self.rejection_reasons:
            raise ValueError("rejected candidate requires at least one rejection reason")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "provider_id": self.provider_id,
            "provider_kind": self.provider_kind.value,
            "grade": self.grade.value,
            "scope": self.scope.value,
            "authorization_grantable": self.authorization_grantable,
            "semantic_suitability": self.semantic_suitability,
            "authorization_route_suitability": self.authorization_route_suitability,
            "status": self.status.value,
            "rejection_reasons": list(self.rejection_reasons),
        }


@dataclass(frozen=True)
class ShadowEvidenceRoutingResult:
    """Immutable shadow routing outcome with no authorization or execution semantics."""

    routing_purpose: EvidenceRoutingPurpose
    requirement_id: str
    capability_id: str
    action_class: str
    combination_policy: EvidenceCombinationPolicy
    status: ShadowEvidenceRoutingStatus
    recommended_provider_id: str | None
    candidates: tuple[ShadowEvidenceRoutingCandidate, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.routing_purpose, EvidenceRoutingPurpose):
            raise TypeError("typed routing purpose is required")
        for name in ("requirement_id", "capability_id", "action_class"):
            _evidence_contract_identifier(getattr(self, name), name)
        if not isinstance(self.combination_policy, EvidenceCombinationPolicy):
            raise TypeError("typed combination policy is required")
        if not isinstance(self.status, ShadowEvidenceRoutingStatus):
            raise TypeError("typed routing status is required")
        if self.recommended_provider_id is not None:
            _evidence_contract_identifier(self.recommended_provider_id, "recommended_provider_id")
        if (not isinstance(self.candidates, tuple)
                or any(not isinstance(item, ShadowEvidenceRoutingCandidate) for item in self.candidates)):
            raise TypeError("candidates must be an immutable typed tuple")
        suitable = [item for item in self.candidates if item.status is EvidenceRoutingCandidateStatus.SUITABLE]
        if self.status is ShadowEvidenceRoutingStatus.SUITABLE:
            if len(suitable) != 1 or self.recommended_provider_id != suitable[0].provider_id:
                raise ValueError("suitable routing requires exactly one recommended provider")
        if self.status is ShadowEvidenceRoutingStatus.AMBIGUOUS and len(suitable) < 2:
            raise ValueError("ambiguous routing requires at least two suitable candidates")
        if self.status is ShadowEvidenceRoutingStatus.NO_SUITABLE_PROVIDER:
            if suitable or self.recommended_provider_id is not None:
                raise ValueError("no-suitable-provider routing cannot recommend a provider")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "routing_purpose": self.routing_purpose.value,
            "requirement_id": self.requirement_id,
            "capability_id": self.capability_id,
            "action_class": self.action_class,
            "combination_policy": self.combination_policy.value,
            "status": self.status.value,
            "recommended_provider_id": self.recommended_provider_id,
            "candidates": [item.safe_summary() for item in self.candidates],
        }


class EvidenceProviderRouter:
    """Shadow contract router: which provider could try to satisfy a requirement.

    Selection is not authorization. The router reads only immutable
    requirement and descriptor contracts plus safe availability metadata;
    it never captures, validates live evidence, or touches Risk, Executor,
    or the Verifier. Evidence grades are capability classifications and are
    never used to order, score, or compare candidates.
    """

    _REJECTION_PRIORITY = (
        EvidenceRoutingCandidateStatus.PROVIDER_NOT_PERMITTED,
        EvidenceRoutingCandidateStatus.SCOPE_MISMATCH,
        EvidenceRoutingCandidateStatus.PRIVACY_INCOMPATIBLE,
        EvidenceRoutingCandidateStatus.UNSUPPORTED_SEMANTIC,
        EvidenceRoutingCandidateStatus.IDENTITY_INSUFFICIENT,
        EvidenceRoutingCandidateStatus.PROVENANCE_INSUFFICIENT,
        EvidenceRoutingCandidateStatus.FRESHNESS_INSUFFICIENT,
        EvidenceRoutingCandidateStatus.COMBINATION_FORBIDDEN,
    )
    _CONTRACT_FAILURE_STATUSES = frozenset(_REJECTION_PRIORITY)

    @staticmethod
    def _descriptor_of(provider: Any) -> GovernedEvidenceProviderDescriptor:
        try:
            descriptor = provider if isinstance(provider, GovernedEvidenceProviderDescriptor) else getattr(provider, "descriptor")
        except AttributeError:
            raise TypeError("governed evidence provider descriptor is required") from None
        if not isinstance(descriptor, GovernedEvidenceProviderDescriptor):
            raise TypeError("governed evidence provider descriptor is required")
        return descriptor

    @staticmethod
    def _check_purpose_stamp(
        requirement: EvidenceRequirement,
        purpose: EvidenceRoutingPurpose,
    ) -> None:
        """Fail closed when the requested purpose exceeds the Risk stamp."""
        stamped = getattr(requirement, "routing_purpose", None)
        if purpose is EvidenceRoutingPurpose.AUTHORIZATION and stamped is not EvidenceRoutingPurpose.AUTHORIZATION:
            raise ValueError(
                "AUTHORIZATION routing requires a Risk-stamped authorization-grade requirement")
        if (purpose is EvidenceRoutingPurpose.VERIFICATION
                and stamped not in (None, EvidenceRoutingPurpose.VERIFICATION)):
            raise ValueError(
                "VERIFICATION routing requires an unstamped or verification-stamped requirement")

    def evaluate(
        self,
        requirement: EvidenceRequirement,
        providers: Iterable[Any],
        purpose: EvidenceRoutingPurpose,
        *,
        availability: Mapping[str, bool] | None = None,
    ) -> ShadowEvidenceRoutingResult:
        if not isinstance(requirement, EvidenceRequirement):
            raise TypeError("EvidenceRequirement is required")
        if not isinstance(purpose, EvidenceRoutingPurpose):
            raise TypeError("typed routing purpose is required")
        self._check_purpose_stamp(requirement, purpose)
        if availability is not None:
            if not isinstance(availability, Mapping) or any(
                    not isinstance(key, str) or type(value) is not bool
                    for key, value in availability.items()):
                raise TypeError("availability must map provider ids to booleans")
        descriptors = sorted(
            (self._descriptor_of(provider) for provider in providers),
            key=lambda item: item.provider_id,
        )
        seen_ids = [item.provider_id for item in descriptors]
        if len(set(seen_ids)) != len(seen_ids):
            raise ValueError("provider descriptors must be unique by provider_id")
        correlated = requirement.combination_policy is EvidenceCombinationPolicy.EXPLICIT_CORRELATED
        required_semantics = {claim.semantic for claim in requirement.claims}
        candidates: list[ShadowEvidenceRoutingCandidate] = []
        for descriptor in descriptors:
            if availability is None:
                candidate_availability: bool | None = None
            else:
                # An explicit availability map is authoritative: an unlisted
                # provider is unknown, never assumed available.
                candidate_availability = availability.get(descriptor.provider_id, False)
            candidates.append(self._evaluate_candidate(
                requirement, descriptor, purpose,
                availability=candidate_availability,
                correlated=correlated,
                required_semantics=required_semantics,
            ))
        candidates_tuple = tuple(candidates)
        suitable = tuple(
            item for item in candidates_tuple
            if item.status is EvidenceRoutingCandidateStatus.SUITABLE
        )
        if len(suitable) == 1:
            status = ShadowEvidenceRoutingStatus.SUITABLE
            recommended: str | None = suitable[0].provider_id
        elif len(suitable) > 1:
            status = ShadowEvidenceRoutingStatus.AMBIGUOUS
            recommended = None
        else:
            status = ShadowEvidenceRoutingStatus.NO_SUITABLE_PROVIDER
            recommended = None
        return ShadowEvidenceRoutingResult(
            routing_purpose=purpose,
            requirement_id=requirement.requirement_id,
            capability_id=requirement.capability_id,
            action_class=requirement.action_class,
            combination_policy=requirement.combination_policy,
            status=status,
            recommended_provider_id=recommended,
            candidates=candidates_tuple,
        )

    @classmethod
    def _evaluate_candidate(
        cls,
        requirement: EvidenceRequirement,
        descriptor: GovernedEvidenceProviderDescriptor,
        purpose: EvidenceRoutingPurpose,
        *,
        availability: bool | None,
        correlated: bool,
        required_semantics: set[EvidenceSemantic],
    ) -> ShadowEvidenceRoutingCandidate:
        reasons: dict[EvidenceRoutingCandidateStatus, list[str]] = {}

        def reject(status: EvidenceRoutingCandidateStatus, reason: str) -> None:
            reasons.setdefault(status, []).append(reason)

        if correlated:
            reject(EvidenceRoutingCandidateStatus.COMBINATION_FORBIDDEN, "COMBINATION_FORBIDDEN")
        else:
            if (requirement.permitted_provider_ids
                    and descriptor.provider_id not in requirement.permitted_provider_ids):
                reject(EvidenceRoutingCandidateStatus.PROVIDER_NOT_PERMITTED, "PROVIDER_ID_NOT_PERMITTED")
            if (requirement.permitted_provider_kinds
                    and descriptor.provider_kind not in requirement.permitted_provider_kinds):
                reject(EvidenceRoutingCandidateStatus.PROVIDER_NOT_PERMITTED, "PROVIDER_KIND_NOT_PERMITTED")
            if (requirement.permitted_provider_scopes
                    and descriptor.scope not in requirement.permitted_provider_scopes):
                reject(EvidenceRoutingCandidateStatus.SCOPE_MISMATCH, "SCOPE_MISMATCH")
            if descriptor.privacy_class is not requirement.privacy_class:
                reject(EvidenceRoutingCandidateStatus.PRIVACY_INCOMPATIBLE, "PRIVACY_INCOMPATIBLE")
            missing = required_semantics - descriptor.supported_semantics
            if missing:
                reject(EvidenceRoutingCandidateStatus.UNSUPPORTED_SEMANTIC,
                       "UNSUPPORTED_SEMANTIC(%s)" % ",".join(sorted(item.value for item in missing)))
            if (requirement.identity_requirement is not EvidenceIdentityRequirement.NONE
                    and requirement.identity_requirement not in descriptor.identity_guarantees):
                reject(EvidenceRoutingCandidateStatus.IDENTITY_INSUFFICIENT, "IDENTITY_INSUFFICIENT")
            for claim in requirement.claims:
                if not claim.accepted_provenance & descriptor.provenance_guarantees:
                    reject(EvidenceRoutingCandidateStatus.PROVENANCE_INSUFFICIENT,
                           "PROVENANCE_INSUFFICIENT(%s)" % claim.semantic.value)
            if (requirement.require_generation_binding
                    and not any("GENERATION" in item for item in descriptor.freshness_capabilities)):
                reject(EvidenceRoutingCandidateStatus.FRESHNESS_INSUFFICIENT, "FRESHNESS_INSUFFICIENT")
            if (purpose is EvidenceRoutingPurpose.AUTHORIZATION
                    and not descriptor.authorization_grantable):
                reject(EvidenceRoutingCandidateStatus.NON_GRANTABLE, "NON_GRANTABLE")
        if availability is False:
            reject(EvidenceRoutingCandidateStatus.UNAVAILABLE, "UNAVAILABLE")
        contract_failures = [status for status in cls._REJECTION_PRIORITY if status in reasons]
        semantic_suitable = not contract_failures
        if not semantic_suitable:
            status = contract_failures[0]
        elif availability is False:
            status = EvidenceRoutingCandidateStatus.UNAVAILABLE
        elif purpose is EvidenceRoutingPurpose.AUTHORIZATION and not descriptor.authorization_grantable:
            status = EvidenceRoutingCandidateStatus.NON_GRANTABLE
        else:
            status = EvidenceRoutingCandidateStatus.SUITABLE
        rejection_reasons = tuple(
            reason
            for ordered in cls._REJECTION_PRIORITY
            for reason in reasons.get(ordered, ())
        ) + tuple(reasons.get(EvidenceRoutingCandidateStatus.NON_GRANTABLE, ())) + tuple(
            reasons.get(EvidenceRoutingCandidateStatus.UNAVAILABLE, ()))
        if status is EvidenceRoutingCandidateStatus.SUITABLE:
            rejection_reasons = ()
        return ShadowEvidenceRoutingCandidate(
            provider_id=descriptor.provider_id,
            provider_kind=descriptor.provider_kind,
            grade=descriptor.grade,
            scope=descriptor.scope,
            authorization_grantable=descriptor.authorization_grantable,
            semantic_suitability=semantic_suitable,
            authorization_route_suitability=semantic_suitable and descriptor.authorization_grantable,
            status=status,
            rejection_reasons=rejection_reasons,
        )


class InputTextEvidenceRequirementBuilder:
    """Risk-owned translation of the current input_text policy into a requirement.

    The builder only converts the current Risk policy into one immutable
    EvidenceRequirement. It cannot capture evidence, select providers,
    authorize, grant, execute, or access a device. Claim states, provenance,
    identity, scope, and combination policy mirror the live input_text
    authorization path without weakening any predicate.
    """

    _DIRECT_PROVENANCE = frozenset(SemanticSearchFieldEvidence.DIRECT_SOURCES)
    _ROLE_PROVENANCE = frozenset(SemanticSearchFieldEvidence.ROLE_SOURCES)
    _SNAPSHOT_PROVENANCE = frozenset({"direct_snapshot"})
    _CAPABILITY_ID = "input_text"
    _ACTION_CLASS = "INPUT_TEXT"
    _VERIFIER_CONTRACT = "SEMANTIC_INPUT_TEXT_VERIFICATION_V1"
    _NATIVE_PROVENANCE = {
        EvidenceSemantic.EDITABLE: frozenset({"DIRECT_NATIVE_GETTER"}),
        EvidenceSemantic.ENABLED: frozenset({"DIRECT_NATIVE_GETTER"}),
        EvidenceSemantic.TARGET_HIDDEN: frozenset({"DIRECT_NATIVE_GETTER"}),
        EvidenceSemantic.CONTROLLED_PRESENTATION:
            frozenset({"CONTROLLED_FIXTURE_PRESENTATION_COMPOSITE"}),
    }

    @classmethod
    def _claim(cls, semantic: EvidenceSemantic, expected_state: EvidenceState,
               accepted_provenance: frozenset[str]) -> EvidenceClaimRequirement:
        return EvidenceClaimRequirement(
            semantic=semantic,
            expected_state=expected_state,
            accepted_provenance=accepted_provenance,
        )

    @classmethod
    def _requirement(
        cls,
        requirement_id: str,
        evaluation_time: int,
        *,
        claims: tuple[EvidenceClaimRequirement, ...],
        identity_requirement: EvidenceIdentityRequirement,
        permitted_provider_kinds: frozenset[EvidenceProviderKind],
        permitted_provider_scopes: frozenset[EvidenceProviderScope],
        require_generation_binding: bool,
        routing_purpose: EvidenceRoutingPurpose,
        task_id: str | None = None,
        context_id: str | None = None,
        context_version: int | None = None,
        observation_generation: str | None = None,
    ) -> GovernedEvidenceRequirement:
        return GovernedEvidenceRequirement(
            requirement_id=requirement_id,
            capability_id=cls._CAPABILITY_ID,
            action_class=cls._ACTION_CLASS,
            claims=claims,
            identity_requirement=identity_requirement,
            maximum_age_seconds=SemanticSearchTransactionStore.DEFAULT_TTL_SECONDS,
            evaluation_time=evaluation_time,
            permitted_provider_ids=frozenset(),
            permitted_provider_kinds=permitted_provider_kinds,
            permitted_provider_scopes=permitted_provider_scopes,
            combination_policy=EvidenceCombinationPolicy.SINGLE_PROVIDER_ONLY,
            privacy_class=EvidencePrivacyClass.SAFE_TYPED_METADATA,
            confirmation_requirement=EvidenceConfirmationRequirement.NOT_REQUIRED,
            verifier_contract=cls._VERIFIER_CONTRACT,
            required_task_id=task_id,
            required_context_id=context_id,
            required_context_version=context_version,
            required_observation_generation=observation_generation,
            require_generation_binding=require_generation_binding,
            routing_purpose=routing_purpose,
        )

    @classmethod
    def production_input_text(
        cls,
        requirement_id: str,
        evaluation_time: int,
        *,
        task_id: str | None = None,
        context_id: str | None = None,
        context_version: int | None = None,
        observation_generation: str | None = None,
    ) -> EvidenceRequirement:
        """Full production input_text requirement mirroring the live Risk policy."""
        claims = (
            cls._claim(EvidenceSemantic.ROLE_ALLOWED, EvidenceState.TRUE, cls._ROLE_PROVENANCE),
            cls._claim(EvidenceSemantic.EDITABLE, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
            cls._claim(EvidenceSemantic.SECURE, EvidenceState.FALSE, cls._DIRECT_PROVENANCE),
            cls._claim(EvidenceSemantic.ENABLED, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
            cls._claim(EvidenceSemantic.PRESENTATION, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
            cls._claim(EvidenceSemantic.ACTIONABLE, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
            cls._claim(EvidenceSemantic.FOCUS, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
            cls._claim(EvidenceSemantic.SAME_LEAF_IDENTITY, EvidenceState.TRUE, cls._SNAPSHOT_PROVENANCE),
            cls._claim(EvidenceSemantic.SNAPSHOT_FRESHNESS, EvidenceState.TRUE, cls._SNAPSHOT_PROVENANCE),
            cls._claim(EvidenceSemantic.EXPECTED_VALUE_MATCH, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
        )
        return cls._requirement(
            requirement_id,
            evaluation_time,
            claims=claims,
            identity_requirement=EvidenceIdentityRequirement.SAME_PROVIDER_LEAF,
            permitted_provider_kinds=frozenset({
                EvidenceProviderKind.STRUCTURAL_AX,
                EvidenceProviderKind.CONTROLLED_NATIVE,
            }),
            permitted_provider_scopes=frozenset({EvidenceProviderScope.PRODUCTION_AX}),
            require_generation_binding=True,
            routing_purpose=EvidenceRoutingPurpose.AUTHORIZATION,
            task_id=task_id,
            context_id=context_id,
            context_version=context_version,
            observation_generation=observation_generation,
        )

    @classmethod
    def ax_structural_focus(
        cls,
        requirement_id: str,
        evaluation_time: int,
        *,
        task_id: str | None = None,
        context_id: str | None = None,
        context_version: int | None = None,
    ) -> EvidenceRequirement:
        claims = (
            cls._claim(EvidenceSemantic.FOCUS, EvidenceState.TRUE, cls._DIRECT_PROVENANCE),
        )
        return cls._requirement(
            requirement_id,
            evaluation_time,
            claims=claims,
            identity_requirement=EvidenceIdentityRequirement.SAME_PROVIDER_LEAF,
            permitted_provider_kinds=frozenset({
                EvidenceProviderKind.STRUCTURAL_AX,
                EvidenceProviderKind.CONTROLLED_NATIVE,
            }),
            permitted_provider_scopes=frozenset({EvidenceProviderScope.PRODUCTION_AX}),
            require_generation_binding=True,
            routing_purpose=EvidenceRoutingPurpose.DIAGNOSTIC,
            task_id=task_id,
            context_id=context_id,
            context_version=context_version,
        )

    @classmethod
    def native_claim(cls, semantic: EvidenceSemantic, expected_state: EvidenceState) -> EvidenceClaimRequirement:
        accepted = cls._NATIVE_PROVENANCE.get(semantic)
        if accepted is None:
            raise ValueError("controlled Native L3 does not support semantic %s" % semantic.value)
        return cls._claim(semantic, expected_state, accepted)

    _AX_LIVE_DIAGNOSTIC_SEMANTICS = frozenset({
        EvidenceSemantic.ROLE_ALLOWED, EvidenceSemantic.EDITABLE, EvidenceSemantic.SECURE,
        EvidenceSemantic.ENABLED, EvidenceSemantic.PRESENTATION, EvidenceSemantic.ACTIONABLE,
        EvidenceSemantic.FOCUS,
    })

    @classmethod
    def ax_live_diagnostic_observation(
        cls,
        requirement_id: str,
        evaluation_time: int,
        claims: tuple[EvidenceClaimRequirement, ...],
        *,
        task_id: str | None = None,
        context_id: str | None = None,
        context_version: int | None = None,
    ) -> GovernedEvidenceRequirement:
        """DIAGNOSTIC-stamped requirement for facts live AX can actually prove.

        Only AX state semantics with host-direct provenance are accepted; the
        correlation/generation claims the current live AX capture cannot prove
        (same-leaf snapshot identity, snapshot freshness, expected-value match)
        are rejected here so the diagnostic profile stays truthful.
        """
        if not claims:
            raise ValueError("AX live diagnostic requires claims")
        for claim in claims:
            if claim.semantic not in cls._AX_LIVE_DIAGNOSTIC_SEMANTICS:
                raise ValueError(
                    "live AX cannot prove semantic %s; diagnostic profile rejects it"
                    % claim.semantic.value)
            if not claim.accepted_provenance <= cls._DIRECT_PROVENANCE:
                raise ValueError(
                    "AX live diagnostic provenance must be host-direct for %s"
                    % claim.semantic.value)
        return cls._requirement(
            requirement_id,
            evaluation_time,
            claims=claims,
            identity_requirement=EvidenceIdentityRequirement.NONE,
            permitted_provider_kinds=frozenset({EvidenceProviderKind.STRUCTURAL_AX}),
            permitted_provider_scopes=frozenset({EvidenceProviderScope.PRODUCTION_AX}),
            require_generation_binding=False,
            routing_purpose=EvidenceRoutingPurpose.DIAGNOSTIC,
            task_id=task_id,
            context_id=context_id,
            context_version=context_version,
        )

    @classmethod
    def controlled_native_diagnostic(
        cls,
        requirement_id: str,
        evaluation_time: int,
        claims: tuple[EvidenceClaimRequirement, ...],
        *,
        identity_requirement: EvidenceIdentityRequirement = EvidenceIdentityRequirement.EXACT_TARGET,
        task_id: str | None = None,
        context_id: str | None = None,
        context_version: int | None = None,
    ) -> EvidenceRequirement:
        if not claims:
            raise ValueError("controlled Native diagnostic requires claims")
        for claim in claims:
            accepted = cls._NATIVE_PROVENANCE.get(claim.semantic)
            if accepted is None:
                raise ValueError("controlled Native L3 does not support semantic %s" % claim.semantic.value)
            if claim.accepted_provenance != accepted:
                raise ValueError(
                    "controlled Native diagnostic provenance must be the sealed Native provenance"
                    " for %s" % claim.semantic.value)
        return cls._requirement(
            requirement_id,
            evaluation_time,
            claims=claims,
            identity_requirement=identity_requirement,
            permitted_provider_kinds=frozenset({EvidenceProviderKind.CONTROLLED_NATIVE}),
            permitted_provider_scopes=frozenset({EvidenceProviderScope.CONTROLLED_FIXTURE_ONLY}),
            require_generation_binding=True,
            routing_purpose=EvidenceRoutingPurpose.DIAGNOSTIC,
            task_id=task_id,
            context_id=context_id,
            context_version=context_version,
        )


class ShadowRiskDivergenceClass(Enum):
    """Diagnostic-only comparison of legacy Risk against the shadow route.

    None of these classes is an authorization outcome. Route availability
    only says that, at the contract level, some provider could attempt
    evidence acquisition in a future architecture.
    """

    LEGACY_AUTHORIZED_ROUTE_AVAILABLE = "LEGACY_AUTHORIZED_ROUTE_AVAILABLE"
    LEGACY_AUTHORIZED_NO_SUITABLE_ROUTE = "LEGACY_AUTHORIZED_NO_SUITABLE_ROUTE"
    LEGACY_AUTHORIZED_ROUTE_AMBIGUOUS = "LEGACY_AUTHORIZED_ROUTE_AMBIGUOUS"
    LEGACY_DENIED_ROUTE_AVAILABLE = "LEGACY_DENIED_ROUTE_AVAILABLE"
    LEGACY_DENIED_NO_SUITABLE_ROUTE = "LEGACY_DENIED_NO_SUITABLE_ROUTE"
    LEGACY_DENIED_ROUTE_AMBIGUOUS = "LEGACY_DENIED_ROUTE_AMBIGUOUS"
    SHADOW_EVALUATION_ERROR = "SHADOW_EVALUATION_ERROR"


@dataclass(frozen=True)
class LegacyRiskDecisionSnapshot:
    """Privacy-safe echo of an authoritative legacy Risk decision.

    It carries only the decision flag, capability/action identifiers, the
    failed legacy predicate codes, and context identifiers. It never
    re-executes Risk, never contains input text, field values, evidence,
    or receipt/grant material.
    """

    authorized: bool
    capability_id: str
    action_class: str
    failed_predicates: tuple[str, ...]
    task_id: str | None = None
    context_id: str | None = None
    context_version: int | None = None

    def __post_init__(self) -> None:
        if type(self.authorized) is not bool:
            raise TypeError("legacy authorized flag must be a boolean")
        for name in ("capability_id", "action_class"):
            _evidence_contract_identifier(getattr(self, name), name)
        if (not isinstance(self.failed_predicates, tuple) or len(self.failed_predicates) > 32
                or any(not isinstance(item, str) or not item or len(item) > 128
                       for item in self.failed_predicates)):
            raise TypeError("failed predicates must be a bounded tuple of predicate codes")
        if len(set(self.failed_predicates)) != len(self.failed_predicates):
            raise ValueError("failed predicate codes must be unique")
        for name in ("task_id", "context_id"):
            value = getattr(self, name)
            if value is not None:
                _evidence_contract_identifier(value, name)
        if self.context_version is not None and (type(self.context_version) is not int
                                                 or self.context_version < 1):
            raise ValueError("context_version must be a positive integer")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "authorized": self.authorized,
            "capability_id": self.capability_id,
            "action_class": self.action_class,
            "failed_predicates": list(self.failed_predicates),
            "task_id": self.task_id,
            "context_id": self.context_id,
            "context_version": self.context_version,
        }


@dataclass(frozen=True)
class ShadowRiskDivergenceRecord:
    """Immutable shadow audit record; it authorizes nothing and carries no evidence."""

    capability_id: str
    action_class: str
    legacy_authorized: bool
    legacy_failed_predicates: tuple[str, ...]
    divergence_class: ShadowRiskDivergenceClass
    routing_status: ShadowEvidenceRoutingStatus | None = None
    recommended_provider_id: str | None = None
    requirement_id: str | None = None
    error_category: str | None = None

    def __post_init__(self) -> None:
        for name in ("capability_id", "action_class"):
            _evidence_contract_identifier(getattr(self, name), name)
        if (not isinstance(self.legacy_failed_predicates, tuple)
                or any(not isinstance(item, str) or not item for item in self.legacy_failed_predicates)):
            raise TypeError("legacy failed predicates must be an immutable string tuple")
        if not isinstance(self.divergence_class, ShadowRiskDivergenceClass):
            raise TypeError("typed divergence class is required")
        if self.routing_status is not None and not isinstance(self.routing_status, ShadowEvidenceRoutingStatus):
            raise TypeError("typed routing status is required")
        if self.requirement_id is not None:
            _evidence_contract_identifier(self.requirement_id, "requirement_id")
        if self.recommended_provider_id is not None:
            _evidence_contract_identifier(self.recommended_provider_id, "recommended_provider_id")
        if self.error_category is not None:
            _evidence_contract_identifier(self.error_category, "error_category")
        if self.divergence_class is ShadowRiskDivergenceClass.SHADOW_EVALUATION_ERROR:
            if self.error_category is None or self.routing_status is not None \
                    or self.recommended_provider_id is not None or self.requirement_id is not None:
                raise ValueError("shadow error record carries only the error category")
        else:
            if self.routing_status is None or self.error_category is not None:
                raise ValueError("non-error shadow record requires a routing status and no error")
            expected = {
                ShadowEvidenceRoutingStatus.SUITABLE: "ROUTE_AVAILABLE",
                ShadowEvidenceRoutingStatus.AMBIGUOUS: "ROUTE_AMBIGUOUS",
                ShadowEvidenceRoutingStatus.NO_SUITABLE_PROVIDER: "NO_SUITABLE_ROUTE",
            }[self.routing_status]
            if not self.divergence_class.value.endswith(expected):
                raise ValueError("divergence class does not match the routing status")
            if self.routing_status is ShadowEvidenceRoutingStatus.SUITABLE:
                if self.recommended_provider_id is None:
                    raise ValueError("route-available record must identify the candidate provider")
            elif self.recommended_provider_id is not None:
                raise ValueError("only route-available records may name a candidate provider")
        if type(self.legacy_authorized) is not bool:
            raise TypeError("legacy authorized flag must be a boolean")
        if (self.divergence_class is not ShadowRiskDivergenceClass.SHADOW_EVALUATION_ERROR
                and self.legacy_authorized
                is not self.divergence_class.value.startswith("LEGACY_AUTHORIZED")):
            raise ValueError("divergence class does not match the legacy decision flag")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "capability_id": self.capability_id,
            "action_class": self.action_class,
            "legacy_authorized": self.legacy_authorized,
            "legacy_failed_predicates": list(self.legacy_failed_predicates),
            "divergence_class": self.divergence_class.value,
            "routing_status": None if self.routing_status is None else self.routing_status.value,
            "recommended_provider_id": self.recommended_provider_id,
            "requirement_id": self.requirement_id,
            "error_category": self.error_category,
        }


class ShadowRiskEvidenceEvaluator:
    """Diagnostic-only shadow auditor beside the authoritative legacy Risk path.

    For a privacy-safe legacy decision snapshot it rebuilds the Risk-owned
    input_text requirement through the P2 builder, routes it through the P2
    router, and records one immutable divergence classification. It never
    authorizes, grants, captures evidence, executes, verifies, or changes any
    legacy object; evaluation failures are isolated into SHADOW_EVALUATION_ERROR.
    """

    def __init__(self, router: EvidenceProviderRouter | None = None) -> None:
        self._router = router if router is not None else EvidenceProviderRouter()

    @property
    def router(self) -> EvidenceProviderRouter:
        return self._router

    def evaluate_input_text(
        self,
        legacy_decision: LegacyRiskDecisionSnapshot,
        *,
        requirement_id: str,
        evaluation_time: int,
        providers: Iterable[Any],
        availability: Mapping[str, bool] | None = None,
    ) -> ShadowRiskDivergenceRecord:
        if not isinstance(legacy_decision, LegacyRiskDecisionSnapshot):
            raise TypeError("LegacyRiskDecisionSnapshot is required")
        if legacy_decision.capability_id != InputTextEvidenceRequirementBuilder._CAPABILITY_ID \
                or legacy_decision.action_class != InputTextEvidenceRequirementBuilder._ACTION_CLASS:
            raise ValueError("shadow evaluator is scoped to the input_text capability")
        try:
            requirement = InputTextEvidenceRequirementBuilder.production_input_text(
                requirement_id,
                evaluation_time,
                task_id=legacy_decision.task_id,
                context_id=legacy_decision.context_id,
                context_version=legacy_decision.context_version,
            )
            routing = self._router.evaluate(
                requirement,
                providers,
                EvidenceRoutingPurpose.AUTHORIZATION,
                availability=availability,
            )
        except Exception as error:
            return ShadowRiskDivergenceRecord(
                capability_id=legacy_decision.capability_id,
                action_class=legacy_decision.action_class,
                legacy_authorized=legacy_decision.authorized,
                legacy_failed_predicates=legacy_decision.failed_predicates,
                divergence_class=ShadowRiskDivergenceClass.SHADOW_EVALUATION_ERROR,
                error_category=type(error).__name__,
            )
        status_to_suffix = {
            ShadowEvidenceRoutingStatus.SUITABLE: "ROUTE_AVAILABLE",
            ShadowEvidenceRoutingStatus.AMBIGUOUS: "ROUTE_AMBIGUOUS",
            ShadowEvidenceRoutingStatus.NO_SUITABLE_PROVIDER: "NO_SUITABLE_ROUTE",
        }
        prefix = "LEGACY_AUTHORIZED" if legacy_decision.authorized else "LEGACY_DENIED"
        divergence_class = ShadowRiskDivergenceClass("%s_%s" % (prefix, status_to_suffix[routing.status]))
        return ShadowRiskDivergenceRecord(
            capability_id=legacy_decision.capability_id,
            action_class=legacy_decision.action_class,
            legacy_authorized=legacy_decision.authorized,
            legacy_failed_predicates=legacy_decision.failed_predicates,
            divergence_class=divergence_class,
            routing_status=routing.status,
            recommended_provider_id=routing.recommended_provider_id,
            requirement_id=requirement.requirement_id,
        )


class EvidenceAcquisitionStatus(Enum):
    """Typed acquisition outcome; failures carry no raw evidence."""

    SUCCESS = "SUCCESS"
    ROUTE_UNAVAILABLE = "ROUTE_UNAVAILABLE"
    CAPTURE_UNAVAILABLE = "CAPTURE_UNAVAILABLE"
    CAPTURE_FAILED = "CAPTURE_FAILED"
    VALIDATION_FAILED = "VALIDATION_FAILED"
    STALE_EVIDENCE = "STALE_EVIDENCE"
    CONTEXT_MISMATCH = "CONTEXT_MISMATCH"
    REQUEST_BINDING_MISMATCH = "REQUEST_BINDING_MISMATCH"
    PROVIDER_MISMATCH = "PROVIDER_MISMATCH"
    REQUIREMENT_MISMATCH = "REQUIREMENT_MISMATCH"
    ATTEMPT_MISMATCH = "ATTEMPT_MISMATCH"
    PRIVACY_REJECTED = "PRIVACY_REJECTED"


@dataclass(frozen=True)
class BoundEvidenceCaptureRequest(EvidenceCaptureRequest):
    """Capture request stamped by the acquisition runtime with a fresh attempt id.

    The stamp is runtime-owned: a caller-supplied attempt id never gains
    trust because the runtime always rebinds the request with its own.
    """

    capture_attempt_id: str = ""

    def __post_init__(self) -> None:
        super().__post_init__()
        _evidence_contract_identifier(self.capture_attempt_id, "capture_attempt_id")


@dataclass(frozen=True)
class GovernedEvidenceReference:
    """Deterministic, privacy-safe identity of one sealed evidence artifact."""

    digest: str

    def __post_init__(self) -> None:
        if (not isinstance(self.digest, str) or len(self.digest) != 64
                or any(character not in "0123456789abcdef" for character in self.digest)):
            raise ValueError("evidence reference must be a lowercase SHA-256 hex digest")


class GovernedEvidenceSealToken:
    """Opaque, runtime-held seal capability; object identity is the trust anchor.

    Mirrors the existing ``_MCPExecutionAuthority`` carrier pattern: the token
    is created and held privately by one runtime instance, is never serialized
    or derived from evidence content, and seal acceptance compares identity,
    not type. Callers can instantiate the class, but the instance will not be
    identical to the runtime's token, so forged evidence fails seal checks.
    """

    __slots__ = ("_runtime_tag",)

    def __init__(self) -> None:
        self._runtime_tag = uuid4().hex

    def __repr__(self) -> str:  # pragma: no cover - opaque by design
        return "GovernedEvidenceSealToken(opaque)"


@dataclass(frozen=True)
class ValidatedGovernedEvidence:
    """Sealed capture+validate outcome; evidence, never authorization.

    Construction is runtime-controlled through a ``GovernedEvidenceSealToken``
    checked by identity. It carries no ALLOW, receipt, grant, binding,
    dispatch, ledger, VERIFIED, or success field, and the underlying evidence
    payload stays inside the reused ``GovernedEvidenceResult`` envelope.
    """

    capability_id: str
    action_class: str
    routing_purpose: EvidenceRoutingPurpose
    capture_attempt_id: str
    requirement_id: str
    result: GovernedEvidenceResult[Any]
    validation_status: EvidenceValidationStatus
    validation_failure_codes: tuple[str, ...]
    evidence_reference: GovernedEvidenceReference
    seal_token: GovernedEvidenceSealToken

    def __post_init__(self) -> None:
        for name in ("capability_id", "action_class", "requirement_id"):
            _evidence_contract_identifier(getattr(self, name), name)
        if not isinstance(self.routing_purpose, EvidenceRoutingPurpose):
            raise TypeError("typed routing purpose is required")
        _evidence_contract_identifier(self.capture_attempt_id, "capture_attempt_id")
        if not isinstance(self.result, GovernedEvidenceResult):
            raise TypeError("typed governed evidence result is required")
        if self.result.capture_status is not EvidenceCaptureStatus.CAPTURED:
            raise ValueError("only captured evidence can be sealed")
        if not isinstance(self.validation_status, EvidenceValidationStatus) \
                or self.validation_status is not EvidenceValidationStatus.VALID:
            raise ValueError("only valid validation can be sealed")
        if (not isinstance(self.validation_failure_codes, tuple) or self.validation_failure_codes):
            raise ValueError("sealed evidence cannot carry validation failure codes")
        if not isinstance(self.evidence_reference, GovernedEvidenceReference):
            raise TypeError("typed evidence reference is required")
        if not isinstance(self.seal_token, GovernedEvidenceSealToken):
            raise TypeError("runtime seal token is required")
        if (self.result.requirement_id != self.requirement_id
                or self.result.capability_id != self.capability_id
                or self.result.action_class != self.action_class):
            raise ValueError("sealed evidence must match the captured result binding")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "provider_id": self.result.provider_id,
            "provider_kind": self.result.provider_kind.value,
            "grade": self.result.grade.value,
            "provider_scope": self.result.scope.value,
            "routing_purpose": self.routing_purpose.value,
            "requirement_id": self.requirement_id,
            "capability_id": self.capability_id,
            "action_class": self.action_class,
            "capture_attempt_id": self.capture_attempt_id,
            "evidence_reference": self.evidence_reference.digest,
            "captured_at": self.result.captured_at,
            "observation_generation": self.result.observation_generation,
            "captured_semantics": [item.semantic.value for item in self.result.facts],
            "identity_binding": self.result.identity_binding,
            "freshness_binding": self.result.freshness_binding,
            "generation_binding": self.result.generation_binding,
            "validation_status": self.validation_status.value,
        }


def _governed_evidence_reference_envelope(
    result: GovernedEvidenceResult[Any],
    requirement_id: str,
    routing_purpose: EvidenceRoutingPurpose,
    capture_attempt_id: str,
) -> dict[str, Any]:
    """Canonical, order-independent, privacy-safe digest input."""
    return {
        "schema": "governed-evidence-reference-v1",
        "provider_id": result.provider_id,
        "provider_kind": result.provider_kind.value,
        "grade": result.grade.value,
        "provider_scope": result.scope.value,
        "routing_purpose": routing_purpose.value,
        "requirement_id": requirement_id,
        "capability_id": result.capability_id,
        "action_class": result.action_class,
        "capture_attempt_id": capture_attempt_id,
        "task_id": result.task_id,
        "plan_id": result.plan_id,
        "planning_revision": result.planning_revision,
        "step_id": result.step_id,
        "target_ref": result.target_ref,
        "context_id": result.context_id,
        "context_version": result.context_version,
        "observation_generation": result.observation_generation,
        "requested_at": result.requested_at,
        "captured_at": result.captured_at,
        "facts": sorted(
            (
                {
                    "semantic": fact.semantic.value,
                    "state": fact.state.value,
                    "provenance": fact.provenance,
                    "direct": fact.direct,
                    "presence": fact.presence,
                    "getter": fact.getter,
                }
                for fact in result.facts
            ),
            key=lambda item: (item["semantic"], item["state"], item["provenance"]),
        ),
        "identity_binding": result.identity_binding,
        "freshness_binding": result.freshness_binding,
        "generation_binding": result.generation_binding,
        "privacy_class": result.privacy_class.value,
        "source_provider_id": result.source_provider_id,
        "target_class": result.target_class,
        "failure_codes": list(result.failure_codes),
        "validation_status": EvidenceValidationStatus.VALID.value,
        "validation_failure_codes": [],
    }


def _governed_evidence_digest(envelope: dict[str, Any]) -> str:
    encoded = json.dumps(
        envelope,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        default=lambda value: (_ for _ in ()).throw(
            ValueError("evidence digest envelope must be JSON-serializable")),
    )
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class GovernedEvidenceAcquisitionResult:
    """Typed acquisition outcome; failures expose only safe metadata."""

    status: EvidenceAcquisitionStatus
    requirement_id: str
    capability_id: str
    provider_id: str | None
    capture_attempt_id: str | None
    evidence: ValidatedGovernedEvidence | None = None
    failure_detail: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not isinstance(self.status, EvidenceAcquisitionStatus):
            raise TypeError("typed acquisition status is required")
        for name in ("requirement_id", "capability_id"):
            _evidence_contract_identifier(getattr(self, name), name)
        for name in ("provider_id", "capture_attempt_id"):
            value = getattr(self, name)
            if value is not None:
                _evidence_contract_identifier(value, name)
        if (not isinstance(self.failure_detail, tuple)
                or any(not isinstance(item, str) or not item or len(item) > 256
                       for item in self.failure_detail)):
            raise TypeError("failure detail must be a bounded string tuple")
        if self.status is EvidenceAcquisitionStatus.SUCCESS:
            if not isinstance(self.evidence, ValidatedGovernedEvidence):
                raise ValueError("successful acquisition must carry sealed evidence")
            if self.failure_detail:
                raise ValueError("successful acquisition cannot carry failure detail")
        elif self.evidence is not None:
            raise ValueError("failed acquisition cannot carry sealed evidence")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "status": self.status.value,
            "requirement_id": self.requirement_id,
            "capability_id": self.capability_id,
            "provider_id": self.provider_id,
            "capture_attempt_id": self.capture_attempt_id,
            "failure_detail": list(self.failure_detail),
            "evidence": None if self.evidence is None else self.evidence.safe_summary(),
        }


class GovernedEvidenceAcquisitionRuntime:
    """Single-responsibility capture→validate→seal trust boundary.

    For one Risk-owned requirement, one router-selected provider, and one
    base capture request, the runtime stamps a fresh attempt id, performs
    exactly one capture, re-checks every provider/request/requirement
    binding, runs exactly one validation, and only then seals immutable
    validated evidence. It never selects providers, authorizes, grants,
    executes, writes a ledger, verifies success, or replans, and it is never
    invoked by the production call graph.
    """

    def __init__(self) -> None:
        self._seal_token = GovernedEvidenceSealToken()
        self.acquisition_count = 0
        self.sealed_evidence_count = 0

    @property
    def acquisition_calls(self) -> int:
        return self.acquisition_count

    @staticmethod
    def _descriptor_of(provider: Any) -> GovernedEvidenceProviderDescriptor:
        try:
            descriptor = getattr(provider, "descriptor")
        except AttributeError:
            raise TypeError("governed evidence provider is required") from None
        if not isinstance(descriptor, GovernedEvidenceProviderDescriptor):
            raise TypeError("governed evidence provider is required")
        return descriptor

    @staticmethod
    def _bound_request(base_request: EvidenceCaptureRequest) -> BoundEvidenceCaptureRequest:
        if not isinstance(base_request, EvidenceCaptureRequest):
            raise TypeError("EvidenceCaptureRequest is required")
        fields_map = {item.name: getattr(base_request, item.name)
                      for item in fields(base_request)}
        fields_map.pop("capture_attempt_id", None)
        return BoundEvidenceCaptureRequest(capture_attempt_id=str(uuid4()), **fields_map)

    def _failure(
        self,
        requirement: GovernedEvidenceRequirement,
        status: EvidenceAcquisitionStatus,
        provider_id: str | None,
        attempt_id: str | None,
        *detail: str,
    ) -> GovernedEvidenceAcquisitionResult:
        return GovernedEvidenceAcquisitionResult(
            status=status,
            requirement_id=requirement.requirement_id,
            capability_id=requirement.capability_id,
            provider_id=provider_id,
            capture_attempt_id=attempt_id,
            failure_detail=tuple(dict.fromkeys(detail)),
        )

    @staticmethod
    def _check_request_binding(
        requirement: GovernedEvidenceRequirement,
        request: BoundEvidenceCaptureRequest,
    ) -> tuple[str, ...]:
        mismatches: list[str] = []
        bindings = (
            ("TASK", requirement.required_task_id, request.task_id),
            ("PLAN", requirement.required_plan_id, request.plan_id),
            ("PLANNING_REVISION", requirement.required_planning_revision, request.planning_revision),
            ("STEP", requirement.required_step_id, request.step_id),
            ("CONTEXT", requirement.required_context_id, request.context_id),
            ("CONTEXT_VERSION", requirement.required_context_version, request.context_version),
            ("OBSERVATION_GENERATION", requirement.required_observation_generation,
             request.observation_generation),
        )
        for label, expected, actual in bindings:
            if expected is not None and actual != expected:
                mismatches.append("%s_BINDING_MISMATCH" % label)
        if request.requirement_id != requirement.requirement_id:
            mismatches.append("REQUEST_REQUIREMENT_MISMATCH")
        return mismatches

    @staticmethod
    def _check_result_binding(
        requirement: GovernedEvidenceRequirement,
        request: BoundEvidenceCaptureRequest,
        result: GovernedEvidenceResult[Any],
    ) -> list[tuple[EvidenceAcquisitionStatus, str]]:
        failures: list[tuple[EvidenceAcquisitionStatus, str]] = []
        if result.requested_at != request.requested_at:
            failures.append((EvidenceAcquisitionStatus.REQUEST_BINDING_MISMATCH,
                             "REQUESTED_AT_MISMATCH"))
        bindings = (
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "TASK",
             requirement.required_task_id, result.task_id),
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "PLAN",
             requirement.required_plan_id, result.plan_id),
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "PLANNING_REVISION",
             requirement.required_planning_revision, result.planning_revision),
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "STEP",
             requirement.required_step_id, result.step_id),
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "CONTEXT",
             requirement.required_context_id, result.context_id),
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "CONTEXT_VERSION",
             requirement.required_context_version, result.context_version),
            (EvidenceAcquisitionStatus.CONTEXT_MISMATCH, "OBSERVATION_GENERATION",
             requirement.required_observation_generation, result.observation_generation),
        )
        for status, label, expected, actual in bindings:
            if expected is not None and actual != expected:
                failures.append((status, "%s_BINDING_MISMATCH" % label))
        if result.target_ref is not None and result.target_ref != request.target_ref:
            failures.append((EvidenceAcquisitionStatus.REQUEST_BINDING_MISMATCH,
                             "TARGET_REF_MISMATCH"))
        if result.captured_at is None:
            failures.append((EvidenceAcquisitionStatus.STALE_EVIDENCE, "CAPTURE_TIME_UNAVAILABLE"))
        elif (result.captured_at > requirement.evaluation_time
              or requirement.evaluation_time - result.captured_at > requirement.maximum_age_seconds):
            failures.append((EvidenceAcquisitionStatus.STALE_EVIDENCE, "EVIDENCE_STALE"))
        return failures

    def acquire(
        self,
        *,
        requirement: GovernedEvidenceRequirement,
        provider: Any,
        base_request: EvidenceCaptureRequest,
    ) -> GovernedEvidenceAcquisitionResult:
        if not isinstance(requirement, GovernedEvidenceRequirement):
            raise TypeError("Risk-stamped GovernedEvidenceRequirement is required")
        if requirement.routing_purpose is None:
            raise ValueError("acquisition requires a purpose-stamped requirement")
        descriptor = self._descriptor_of(provider)
        provider_id = descriptor.provider_id
        self.acquisition_count += 1
        if (requirement.routing_purpose is EvidenceRoutingPurpose.AUTHORIZATION
                and not descriptor.authorization_grantable):
            return self._failure(requirement, EvidenceAcquisitionStatus.PROVIDER_MISMATCH,
                                 provider_id, None, "NON_GRANTABLE")
        request_mismatches = self._check_request_binding(requirement, base_request) \
            if isinstance(base_request, BoundEvidenceCaptureRequest) else ()
        bound_request = self._bound_request(base_request)
        if request_mismatches:
            return self._failure(requirement, EvidenceAcquisitionStatus.REQUEST_BINDING_MISMATCH,
                                 provider_id, bound_request.capture_attempt_id, *request_mismatches)
        result = provider.capture(bound_request)
        if not isinstance(result, GovernedEvidenceResult):
            return self._failure(requirement, EvidenceAcquisitionStatus.CAPTURE_FAILED,
                                 provider_id, bound_request.capture_attempt_id,
                                 "MALFORMED_PROVIDER_RESULT")
        if (result.provider_id != provider_id
                or result.provider_kind is not descriptor.provider_kind
                or result.grade is not descriptor.grade
                or result.scope is not descriptor.scope):
            return self._failure(requirement, EvidenceAcquisitionStatus.PROVIDER_MISMATCH,
                                 provider_id, bound_request.capture_attempt_id,
                                 "PROVIDER_IDENTITY_MISMATCH")
        if (result.requirement_id != requirement.requirement_id
                or result.capability_id != requirement.capability_id
                or result.action_class != requirement.action_class):
            return self._failure(requirement, EvidenceAcquisitionStatus.REQUIREMENT_MISMATCH,
                                 provider_id, bound_request.capture_attempt_id,
                                 "REQUIREMENT_BINDING_MISMATCH")
        if result.capture_status is EvidenceCaptureStatus.UNAVAILABLE:
            return self._failure(requirement, EvidenceAcquisitionStatus.CAPTURE_UNAVAILABLE,
                                 provider_id, bound_request.capture_attempt_id,
                                 *(result.failure_codes or ("CAPTURE_UNAVAILABLE",)))
        if result.capture_status is not EvidenceCaptureStatus.CAPTURED:
            return self._failure(requirement, EvidenceAcquisitionStatus.CAPTURE_FAILED,
                                 provider_id, bound_request.capture_attempt_id,
                                 *(result.failure_codes or ("CAPTURE_FAILED",)))
        if result.privacy_class is not requirement.privacy_class:
            return self._failure(requirement, EvidenceAcquisitionStatus.PRIVACY_REJECTED,
                                 provider_id, bound_request.capture_attempt_id,
                                 "PRIVACY_CLASS_MISMATCH")
        for status, detail in self._check_result_binding(requirement, bound_request, result):
            return self._failure(requirement, status, provider_id,
                                 bound_request.capture_attempt_id, detail)
        validation = provider.validate(result, requirement)
        if not isinstance(validation, EvidenceValidationResult):
            return self._failure(requirement, EvidenceAcquisitionStatus.VALIDATION_FAILED,
                                 provider_id, bound_request.capture_attempt_id,
                                 "MALFORMED_VALIDATION_RESULT")
        if validation.status is not EvidenceValidationStatus.VALID or validation.failure_codes:
            return self._failure(requirement, EvidenceAcquisitionStatus.VALIDATION_FAILED,
                                 provider_id, bound_request.capture_attempt_id,
                                 *(validation.failure_codes or ("VALIDATION_FAILED",)))
        reference = GovernedEvidenceReference(digest=_governed_evidence_digest(
            _governed_evidence_reference_envelope(
                result, requirement.requirement_id,
                requirement.routing_purpose, bound_request.capture_attempt_id)))
        evidence = ValidatedGovernedEvidence(
            capability_id=requirement.capability_id,
            action_class=requirement.action_class,
            routing_purpose=requirement.routing_purpose,
            capture_attempt_id=bound_request.capture_attempt_id,
            requirement_id=requirement.requirement_id,
            result=result,
            validation_status=validation.status,
            validation_failure_codes=validation.failure_codes,
            evidence_reference=reference,
            seal_token=self._seal_token,
        )
        self.sealed_evidence_count += 1
        return GovernedEvidenceAcquisitionResult(
            status=EvidenceAcquisitionStatus.SUCCESS,
            requirement_id=requirement.requirement_id,
            capability_id=requirement.capability_id,
            provider_id=provider_id,
            capture_attempt_id=bound_request.capture_attempt_id,
            evidence=evidence,
        )

    def verify_seal(self, evidence: Any) -> bool:
        """Future-consumer check: identity seal plus recomputed digest."""
        if not isinstance(evidence, ValidatedGovernedEvidence):
            return False
        if evidence.seal_token is not self._seal_token:
            return False
        expected = GovernedEvidenceReference(digest=_governed_evidence_digest(
            _governed_evidence_reference_envelope(
                evidence.result, evidence.requirement_id, evidence.routing_purpose,
                evidence.capture_attempt_id)))
        return expected.digest == evidence.evidence_reference.digest


class AXL2LiveShadowAcquisition:
    """Explicit, production-dormant AX L2 live shadow capture entrypoint.

    The only sanctioned P4B flow: a Risk-owned requirement routes through the
    P2 router; only an exact AX L2 recommendation proceeds to exactly one live
    read-only ``observe_semantic_search_page`` capture; the observation is
    wrapped by the existing ``AXL2GovernedEvidenceProvider`` (no second AX
    parser) and sealed by the P4A acquisition runtime or fails closed with a
    truthful typed reason. It never touches RiskController, legacy input
    grants, binding stores, the Executor, the Ledger, or the Verifier, and it
    is never invoked by the production call graph.
    """

    _AX_PROVIDER_ID = AXL2GovernedEvidenceProvider._DESCRIPTOR.provider_id

    def __init__(
        self,
        *,
        observe_page: Callable[..., SemanticSearchPageObservation],
        acquisition_runtime: GovernedEvidenceAcquisitionRuntime | None = None,
        router: EvidenceProviderRouter | None = None,
    ) -> None:
        if not callable(observe_page):
            raise TypeError("observe_page capture source is required")
        self._observe_page = observe_page
        self._runtime = acquisition_runtime if acquisition_runtime is not None \
            else GovernedEvidenceAcquisitionRuntime()
        self._router = router if router is not None else EvidenceProviderRouter()
        self.live_capture_count = 0
        self.route_count = 0

    @property
    def acquisition_runtime(self) -> GovernedEvidenceAcquisitionRuntime:
        return self._runtime

    def route(self, requirement: GovernedEvidenceRequirement,
              providers: Iterable[Any]) -> ShadowEvidenceRoutingResult:
        if not isinstance(requirement, GovernedEvidenceRequirement) or requirement.routing_purpose is None:
            raise TypeError("purpose-stamped GovernedEvidenceRequirement is required")
        self.route_count += 1
        return self._router.evaluate(requirement, providers, requirement.routing_purpose)

    def acquire(
        self,
        requirement: GovernedEvidenceRequirement,
        request_builder: Callable[[SemanticSearchPageObservation], EvidenceCaptureRequest],
        *,
        task_id: str,
        context_id: str,
        providers: Iterable[Any] | None = None,
        candidate_providers: Iterable[Any] = (),
    ) -> GovernedEvidenceAcquisitionResult:
        if not isinstance(requirement, GovernedEvidenceRequirement) or requirement.routing_purpose is None:
            raise TypeError("purpose-stamped GovernedEvidenceRequirement is required")
        if not callable(request_builder):
            raise TypeError("request builder is required")
        routing = self.route(requirement, providers if providers is not None else candidate_providers)
        if (routing.status is not ShadowEvidenceRoutingStatus.SUITABLE
                or routing.recommended_provider_id != self._AX_PROVIDER_ID):
            # Router result is not authority; without an exact AX route there
            # is no capture at all - diagnostic or otherwise.
            return GovernedEvidenceAcquisitionResult(
                status=EvidenceAcquisitionStatus.ROUTE_UNAVAILABLE,
                requirement_id=requirement.requirement_id,
                capability_id=requirement.capability_id,
                provider_id=None,
                capture_attempt_id=None,
                failure_detail=("ROUTING_%s" % routing.status.value,),
            )
        self.live_capture_count += 1
        observation = self._observe_page(task_id=task_id, context_id=context_id)
        provider = AXL2GovernedEvidenceProvider(observation)
        try:
            base_request = request_builder(observation)
        except Exception:
            return GovernedEvidenceAcquisitionResult(
                status=EvidenceAcquisitionStatus.REQUEST_BINDING_MISMATCH,
                requirement_id=requirement.requirement_id,
                capability_id=requirement.capability_id,
                provider_id=self._AX_PROVIDER_ID,
                capture_attempt_id=None,
                failure_detail=("REQUEST_BUILDER_FAILED",),
            )
        return self._runtime.acquire(
            requirement=requirement, provider=provider, base_request=base_request)


class ValidatedGovernedInputEvidenceAdapter:
    """Bounded AX-only bridge from sealed governed evidence to input policy input.

    It reads only facts already present in runtime-sealed evidence and maps
    them onto the existing normalized input model. It cannot add evidence,
    infer states, weaken provenance, or manufacture same-leaf/generation
    facts: anything the governed AX model does not express (selector
    presence, snapshot correlation) maps to its truthful unavailable state.
    Controlled Native evidence is rejected: it belongs to its own adapters.
    """

    _SUPPORTED_PROVIDER_IDS = frozenset({AXL2GovernedEvidenceProvider._DESCRIPTOR.provider_id})

    @staticmethod
    def _state(value: EvidenceState) -> str:
        return {
            EvidenceState.TRUE: "TRUE",
            EvidenceState.FALSE: "FALSE",
            EvidenceState.NOT_APPLICABLE: "NOT_APPLICABLE",
        }.get(value, "UNAVAILABLE")

    @classmethod
    def adapt(cls, evidence: ValidatedGovernedEvidence) -> NormalizedInputAuthorizationEvidence:
        if not isinstance(evidence, ValidatedGovernedEvidence):
            raise TypeError("ValidatedGovernedEvidence is required")
        result = evidence.result
        if result.provider_id not in cls._SUPPORTED_PROVIDER_IDS:
            raise ValueError("governed input adapter supports only the AX L2 provider")
        facts = {fact.semantic: fact for fact in result.facts}

        def state_of(semantic: EvidenceSemantic) -> str:
            fact = facts.get(semantic)
            return cls._state(fact.state) if fact is not None else "UNAVAILABLE"

        def direct_of(semantic: EvidenceSemantic) -> bool:
            fact = facts.get(semantic)
            return bool(fact.direct) if fact is not None else False

        role_allowed = state_of(EvidenceSemantic.ROLE_ALLOWED) == "TRUE"
        return NormalizedInputAuthorizationEvidence(
            provider=result.provider_id,
            scope=result.scope.value,
            grantable=True,
            source_valid=True,
            same_target=state_of(EvidenceSemantic.SAME_LEAF_IDENTITY) == "TRUE",
            role_allowed=role_allowed,
            role_provenance_valid=direct_of(EvidenceSemantic.ROLE_ALLOWED),
            editable_state=state_of(EvidenceSemantic.EDITABLE),
            editable_provenance_valid=direct_of(EvidenceSemantic.EDITABLE),
            secure_state=state_of(EvidenceSemantic.SECURE),
            secure_provenance_valid=direct_of(EvidenceSemantic.SECURE),
            enabled_state=state_of(EvidenceSemantic.ENABLED),
            enabled_provenance_valid=direct_of(EvidenceSemantic.ENABLED),
            presentation_state=state_of(EvidenceSemantic.PRESENTATION),
            presentation_provenance_valid=direct_of(EvidenceSemantic.PRESENTATION),
            actionable_state=state_of(EvidenceSemantic.ACTIONABLE),
            actionable_provenance_valid=direct_of(EvidenceSemantic.ACTIONABLE),
            focus_state=state_of(EvidenceSemantic.FOCUS),
            focus_provenance_valid=direct_of(EvidenceSemantic.FOCUS),
            # Selector presence is not represented in the governed AX fact
            # model; mapping anything else would manufacture evidence.
            selector_state="UNAVAILABLE",
            # Sealed evidence is bound to its acquisition request by the
            # runtime, matching the legacy AX adapter's request-bound truth.
            fresh_request_binding=True,
        )


class CanonicalShadowEvaluationStatus(Enum):
    EVALUATED = "EVALUATED"
    EVIDENCE_NOT_VALIDATED = "EVIDENCE_NOT_VALIDATED"
    SEAL_INVALID = "SEAL_INVALID"
    UNSUPPORTED_CAPABILITY = "UNSUPPORTED_CAPABILITY"
    UNSUPPORTED_PROVIDER = "UNSUPPORTED_PROVIDER"
    REQUIREMENT_MISMATCH = "REQUIREMENT_MISMATCH"
    PURPOSE_MISMATCH = "PURPOSE_MISMATCH"


@dataclass(frozen=True)
class CanonicalEvidenceShadowEvaluation:
    """Immutable shadow policy verdict; never a Risk authorization."""

    requirement_id: str
    capability_id: str
    provider_id: str | None
    evidence_reference: str | None
    routing_purpose: EvidenceRoutingPurpose
    evaluator_id: str
    predicates: tuple[str, ...]
    status: CanonicalShadowEvaluationStatus
    policy_verdict: str | None = None
    failed_predicates: tuple[str, ...] = ()
    blocked_detail: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        for name in ("requirement_id", "capability_id"):
            _evidence_contract_identifier(getattr(self, name), name)
        for name in ("provider_id", "evidence_reference"):
            value = getattr(self, name)
            if value is not None:
                _evidence_contract_identifier(value, name)
        if not isinstance(self.routing_purpose, EvidenceRoutingPurpose):
            raise TypeError("typed routing purpose is required")
        _evidence_contract_identifier(self.evaluator_id, "evaluator_id")
        if (not isinstance(self.predicates, tuple)
                or any(not isinstance(item, str) or not item for item in self.predicates)):
            raise TypeError("predicates must be an immutable string tuple")
        if not isinstance(self.status, CanonicalShadowEvaluationStatus):
            raise TypeError("typed shadow evaluation status is required")
        if self.status is CanonicalShadowEvaluationStatus.EVALUATED:
            if self.policy_verdict not in {"ALLOW", "DENY"} or self.provider_id is None \
                    or self.evidence_reference is None:
                raise ValueError("evaluated verdict requires ALLOW/DENY and evidence identity")
        else:
            if self.policy_verdict is not None:
                raise ValueError("blocked evaluation cannot carry a policy verdict")
            if not self.blocked_detail:
                raise ValueError("blocked evaluation requires a truthful detail")
        if (not isinstance(self.failed_predicates, tuple)
                or any(not isinstance(item, str) or not item for item in self.failed_predicates)):
            raise TypeError("failed predicates must be an immutable string tuple")
        if (not isinstance(self.blocked_detail, tuple)
                or any(not isinstance(item, str) or not item for item in self.blocked_detail)):
            raise TypeError("blocked detail must be an immutable string tuple")

    def safe_summary(self) -> dict[str, Any]:
        return {
            "requirement_id": self.requirement_id,
            "capability_id": self.capability_id,
            "provider_id": self.provider_id,
            "evidence_reference": self.evidence_reference,
            "routing_purpose": self.routing_purpose.value,
            "evaluator_id": self.evaluator_id,
            "predicates": list(self.predicates),
            "status": self.status.value,
            "policy_verdict": self.policy_verdict,
            "failed_predicates": list(self.failed_predicates),
            "blocked_detail": list(self.blocked_detail),
        }


class InputEvidenceCanonicalShadowEvaluator:
    """Shadow-only canonical policy bridge for input_text governed evidence.

    Only runtime-sealed, digest-verified, requirement-, purpose-, and
    provider-matched evidence reaches the one existing
    ``InputAuthorizationPredicateEvaluator``; every gate failure is a typed
    blocked result and the evaluator is never invoked. The verdict is a
    diagnostic shadow output: canonical ALLOW is not a Risk authorization.
    """

    _EVALUATOR_ID = "input_authorization_policy.v1"
    _CAPABILITY_ID = InputTextEvidenceRequirementBuilder._CAPABILITY_ID

    def __init__(self, acquisition_runtime: GovernedEvidenceAcquisitionRuntime) -> None:
        if not isinstance(acquisition_runtime, GovernedEvidenceAcquisitionRuntime):
            raise TypeError("GovernedEvidenceAcquisitionRuntime is required")
        self._runtime = acquisition_runtime
        self.evaluated_count = 0
        self.blocked_count = 0

    def evaluate(
        self,
        evidence: Any,
        requirement: GovernedEvidenceRequirement,
        *,
        predicates: tuple[str, ...] | None = None,
    ) -> CanonicalEvidenceShadowEvaluation:
        if not isinstance(requirement, GovernedEvidenceRequirement) or requirement.routing_purpose is None:
            raise TypeError("purpose-stamped GovernedEvidenceRequirement is required")
        selected_predicates = tuple(predicates) if predicates is not None \
            else InputAuthorizationPredicateEvaluator.NATIVE_DIAGNOSTIC_PREDICATES

        def blocked(status: CanonicalShadowEvaluationStatus,
                    *detail: str) -> CanonicalEvidenceShadowEvaluation:
            self.blocked_count += 1
            sealed = evidence if isinstance(evidence, ValidatedGovernedEvidence) else None
            return CanonicalEvidenceShadowEvaluation(
                requirement_id=requirement.requirement_id,
                capability_id=requirement.capability_id,
                provider_id=sealed.result.provider_id if sealed is not None else None,
                evidence_reference=sealed.evidence_reference.digest if sealed is not None else None,
                routing_purpose=requirement.routing_purpose,
                evaluator_id=self._EVALUATOR_ID,
                predicates=selected_predicates,
                status=status,
                blocked_detail=tuple(dict.fromkeys(detail)),
            )

        if not isinstance(evidence, ValidatedGovernedEvidence):
            return blocked(CanonicalShadowEvaluationStatus.EVIDENCE_NOT_VALIDATED,
                           "EVIDENCE_NOT_SEALED")
        if not self._runtime.verify_seal(evidence):
            return blocked(CanonicalShadowEvaluationStatus.SEAL_INVALID, "SEAL_OR_DIGEST_INVALID")
        if evidence.result.provider_id not in ValidatedGovernedInputEvidenceAdapter._SUPPORTED_PROVIDER_IDS:
            return blocked(CanonicalShadowEvaluationStatus.UNSUPPORTED_PROVIDER,
                           "PROVIDER_NOT_INPUT_AX")
        if requirement.capability_id != self._CAPABILITY_ID:
            return blocked(CanonicalShadowEvaluationStatus.UNSUPPORTED_CAPABILITY,
                           "CAPABILITY_NOT_INPUT_TEXT")
        if evidence.routing_purpose is not requirement.routing_purpose:
            return blocked(CanonicalShadowEvaluationStatus.PURPOSE_MISMATCH,
                           "ROUTING_PURPOSE_MISMATCH")
        if evidence.requirement_id != requirement.requirement_id:
            return blocked(CanonicalShadowEvaluationStatus.REQUIREMENT_MISMATCH,
                           "REQUIREMENT_IDENTITY_MISMATCH")
        normalized = ValidatedGovernedInputEvidenceAdapter.adapt(evidence)
        evaluation = InputAuthorizationPredicateEvaluator.evaluate(
            normalized, predicates=selected_predicates)
        self.evaluated_count += 1
        return CanonicalEvidenceShadowEvaluation(
            requirement_id=requirement.requirement_id,
            capability_id=requirement.capability_id,
            provider_id=evidence.result.provider_id,
            evidence_reference=evidence.evidence_reference.digest,
            routing_purpose=requirement.routing_purpose,
            evaluator_id=self._EVALUATOR_ID,
            predicates=selected_predicates,
            status=CanonicalShadowEvaluationStatus.EVALUATED,
            policy_verdict=evaluation.decision,
            failed_predicates=evaluation.failed_predicates,
        )


@dataclass(frozen=True)
class BoundSemanticSearchTransaction:
    """Public, redacted metadata for one private semantic search transaction."""

    transaction_id: str
    query_authority: str
    task_id: str
    context_id: str
    observation_version: int
    page_fingerprint: str
    expires_at: int

    def schema(self) -> dict[str, Any]:
        return {
            "semantic_search_transaction_version": SEMANTIC_SEARCH_TRANSACTION_VERSION,
            "transaction_id": self.transaction_id,
            "query_authority": self.query_authority,
            "task_id": self.task_id,
            "context_id": self.context_id,
            "observation_version": self.observation_version,
            "page_fingerprint": self.page_fingerprint,
            "expires_at": self.expires_at,
            "query_content_access": "none",
            "selector_content_access": "none",
        }

    def registry_snapshot(self) -> Snapshot:
        return Snapshot(
            frontmost_name="",
            frontmost_bundle_id="",
            element_count=1,
            source="AX",
            elements=({"text": "search", "clickable": True},),
        )


class SemanticSearchTransactionStore:
    """Process-local, task-scoped TEST-51 query and field authority.

    The store has no persistence API. It retains only the minimum private query
    and selector values needed while a single task is active. Each action claim
    is consumed before dispatch, and every verification consumes a fresh page
    observation bound to the same task/context.
    """

    DEFAULT_TTL_SECONDS = 60
    MAX_QUERY_LENGTH = 512
    TRUSTED_AUTHORITIES = frozenset({"EXPLICIT_USER", "RICH_CONTEXT"})

    def __init__(self, ttl_seconds: int = DEFAULT_TTL_SECONDS) -> None:
        if ttl_seconds < 1:
            raise ValueError("semantic search transaction ttl must be positive")
        self.ttl_seconds = int(ttl_seconds)
        self._transactions: dict[str, dict[str, Any]] = {}
        self._lock = threading.RLock()

    def begin_explicit(
        self,
        query: str,
        observation: SemanticSearchPageObservation,
        *,
        task_id: str,
        context_id: str,
        now: int | None = None,
    ) -> BoundSemanticSearchTransaction:
        return self.begin(
            query,
            observation,
            task_id=task_id,
            context_id=context_id,
            query_authority="EXPLICIT_USER",
            now=now,
        )

    def begin(
        self,
        query: str,
        observation: SemanticSearchPageObservation,
        *,
        task_id: str,
        context_id: str,
        query_authority: str,
        context_resolution: dict[str, Any] | None = None,
        now: int | None = None,
    ) -> BoundSemanticSearchTransaction:
        normalized_query = self._validate_query(query)
        authority = str(query_authority or "").strip().upper()
        if authority not in self.TRUSTED_AUTHORITIES:
            raise SemanticSearchPolicyError("UNTRUSTED_CONTENT: query authority is not trusted")
        if authority == "RICH_CONTEXT":
            resolution = context_resolution if isinstance(context_resolution, dict) else {}
            if resolution.get("status") != "RESOLVED":
                raise SemanticSearchPolicyError("NEEDS_CLARIFICATION: rich context did not resolve uniquely")
            if not resolution.get("trusted") or not resolution.get("fresh"):
                raise SemanticSearchPolicyError("UNTRUSTED_CONTENT: rich context is not trusted and fresh")
            if int(resolution.get("candidate_count") or 0) != 1:
                raise SemanticSearchPolicyError("NEEDS_CLARIFICATION: rich context is ambiguous")
        self._validate_observation_scope(observation, task_id, context_id)
        eligible = [field for field in observation.fields if field.eligible()]
        if len(eligible) > 1:
            raise SemanticSearchPolicyError("NEEDS_CLARIFICATION: multiple eligible semantic text fields")
        if len(eligible) != 1:
            raise SemanticSearchPolicyError("INELIGIBLE: no unique editable AX text field")

        current_time = int(time.time()) if now is None else int(now)
        transaction_id = str(uuid4())
        bound = BoundSemanticSearchTransaction(
            transaction_id=transaction_id,
            query_authority=authority,
            task_id=task_id,
            context_id=context_id,
            observation_version=observation.observation_version,
            page_fingerprint=observation.page_fingerprint,
            expires_at=current_time + self.ttl_seconds,
        )
        with self._lock:
            self._purge(current_time)
            self._transactions[transaction_id] = {
                "bound": bound,
                "query": normalized_query,
                "field_ref": eligible[0].field_ref,
                "selector_text": eligible[0].selector_text,
                "latest_observation_version": observation.observation_version,
                "latest_page_fingerprint": observation.page_fingerprint,
                "latest_device_generation": observation.device_generation,
                "claimed_steps": set(),
                "focus_verified": False,
                "entry_verified": False,
                "submission_verified": False,
                "pre_submit_fingerprint": None,
                "submit_dispatched": False,
            }
        return bound

    def claim(
        self,
        transaction_id: str,
        step: str,
        *,
        task_id: str,
        context_id: str,
        observation_version: int | None = None,
        now: int | None = None,
    ) -> dict[str, Any]:
        current_time = int(time.time()) if now is None else int(now)
        normalized_step = str(step or "").strip().upper()
        with self._lock:
            entry = self._entry(transaction_id, current_time)
            self._validate_bound_scope(entry, task_id, context_id)
            latest_version = int(entry["latest_observation_version"])
            if observation_version is not None and int(observation_version) != latest_version:
                raise SemanticSearchPolicyError("STALE_CONTEXT: observation version was superseded")
            if normalized_step in entry["claimed_steps"]:
                raise SemanticSearchPolicyError("CONSUMED: semantic search step is one-time")
            if normalized_step == "FOCUS":
                arguments = {"text": entry["selector_text"], "match": "exact"}
            elif normalized_step == "INPUT":
                if not entry["focus_verified"]:
                    raise SemanticSearchPolicyError("INELIGIBLE: field focus is not verified")
                arguments = {"text": entry["query"]}
            elif normalized_step == "SUBMIT":
                if not entry["entry_verified"]:
                    raise SemanticSearchPolicyError("INELIGIBLE: query entry is not verified")
                entry["pre_submit_fingerprint"] = entry["latest_page_fingerprint"]
                entry["submit_dispatched"] = True
                arguments = {"key": "enter"}
            else:
                raise SemanticSearchPolicyError("INELIGIBLE: unsupported semantic search step")
            entry["claimed_steps"].add(normalized_step)
            return dict(arguments)

    def observe(
        self,
        transaction_id: str,
        observation: SemanticSearchPageObservation,
        *,
        task_id: str,
        context_id: str,
    ) -> None:
        with self._lock:
            entry = self._entry(transaction_id)
            self._validate_bound_scope(entry, task_id, context_id)
            self._validate_observation_scope(observation, task_id, context_id)
            if observation.observation_version <= int(entry["latest_observation_version"]):
                raise SemanticSearchPolicyError("STALE_CONTEXT: observation is not fresh")
            if observation.device_generation == entry["latest_device_generation"]:
                raise SemanticSearchPolicyError("STALE_CONTEXT: device snapshot was reused")
            entry["latest_observation_version"] = observation.observation_version
            entry["latest_page_fingerprint"] = observation.page_fingerprint
            entry["latest_device_generation"] = observation.device_generation

    def verify_focus(
        self,
        transaction_id: str,
        observation: SemanticSearchPageObservation,
        *,
        task_id: str,
        context_id: str,
    ) -> dict[str, Any]:
        self.observe(transaction_id, observation, task_id=task_id, context_id=context_id)
        with self._lock:
            entry = self._entry(transaction_id)
            matches = [field for field in observation.fields if field.field_ref == entry["field_ref"]]
            passed = len(matches) == 1 and matches[0].eligible() and matches[0].focus_is_verified()
            entry["focus_verified"] = passed
            return {"passed": passed, "verification_result": "FIELD_FOCUS_VERIFIED" if passed else "FIELD_FOCUS_NOT_VERIFIED"}

    def verify_query_entry(
        self,
        transaction_id: str,
        observation: SemanticSearchPageObservation,
        *,
        task_id: str,
        context_id: str,
    ) -> dict[str, Any]:
        self.observe(transaction_id, observation, task_id=task_id, context_id=context_id)
        with self._lock:
            entry = self._entry(transaction_id)
            matches = [field for field in observation.fields if field.field_ref == entry["field_ref"]]
            passed = (
                len(matches) == 1
                and matches[0].eligible()
                and matches[0].focus_is_verified()
                and matches[0].expected_value_is_verified()
            )
            entry["entry_verified"] = passed
            if passed:
                entry["pre_submit_fingerprint"] = observation.page_fingerprint
            return {"passed": passed, "verification_result": "QUERY_ENTRY_VERIFIED" if passed else "QUERY_ENTRY_NOT_VERIFIED"}

    def verify_submission(
        self,
        transaction_id: str,
        observation: SemanticSearchPageObservation,
        *,
        task_id: str,
        context_id: str,
    ) -> dict[str, Any]:
        self.observe(transaction_id, observation, task_id=task_id, context_id=context_id)
        with self._lock:
            entry = self._entry(transaction_id)
            changed = observation.page_fingerprint != entry.get("pre_submit_fingerprint")
            passed = bool(entry["submit_dispatched"] and changed and observation.result_state)
            entry["submission_verified"] = passed
            return {
                "passed": passed,
                "verification_result": "SEARCH_SUBMISSION_VERIFIED" if passed else "SEARCH_SUBMISSION_NOT_VERIFIED",
                "fresh_post_submit_state": changed,
            }

    def state(self, transaction_id: str) -> dict[str, Any]:
        with self._lock:
            entry = self._entry(transaction_id)
            return {
                "focus_verified": bool(entry["focus_verified"]),
                "entry_verified": bool(entry["entry_verified"]),
                "submission_verified": bool(entry["submission_verified"]),
                "submit_dispatched": bool(entry["submit_dispatched"]),
                "latest_observation_version": int(entry["latest_observation_version"]),
            }

    def public_binding(self, transaction_id: str) -> BoundSemanticSearchTransaction:
        """Return only the redacted contract needed by Planner/Executor."""

        with self._lock:
            return self._entry(transaction_id)["bound"]

    def expected_query_for_verification(
        self,
        transaction_id: str,
        *,
        task_id: str,
        context_id: str,
    ) -> str:
        """Return the private query only to the verifier's digest boundary."""

        with self._lock:
            entry = self._entry(transaction_id)
            self._validate_bound_scope(entry, task_id, context_id)
            return str(entry["query"])

    @classmethod
    def _validate_query(cls, value: Any) -> str:
        if not isinstance(value, str):
            raise SemanticSearchPolicyError("MALFORMED_QUERY: search query must be text")
        normalized = unicodedata.normalize("NFC", value).strip()
        if not normalized:
            raise SemanticSearchPolicyError("EMPTY_QUERY: search query is empty")
        if len(normalized) > cls.MAX_QUERY_LENGTH:
            raise SemanticSearchPolicyError("EXCESSIVE_QUERY: search query is too long")
        for character in normalized:
            category = unicodedata.category(character)
            if category in {"Cc", "Cs"} or character in {"\u202a", "\u202b", "\u202c", "\u202d", "\u202e", "\u2066", "\u2067", "\u2068", "\u2069"}:
                raise SemanticSearchPolicyError("MALFORMED_QUERY: control or bidi characters are not allowed")
        return normalized

    @staticmethod
    def _validate_observation_scope(observation: Any, task_id: str, context_id: str) -> None:
        if not isinstance(observation, SemanticSearchPageObservation):
            raise SemanticSearchPolicyError("STALE_CONTEXT: semantic page observation is required")
        if observation.source != "AX":
            raise SemanticSearchPolicyError("INELIGIBLE: only fresh AX evidence may authorize action")
        if observation.task_id != task_id or observation.context_id != context_id:
            raise SemanticSearchPolicyError("STALE_CONTEXT: observation scope does not match task")
        if observation.observation_version < 1 or not observation.page_fingerprint:
            raise SemanticSearchPolicyError("STALE_CONTEXT: observation version is invalid")
        if not observation.snapshot_is_correlated():
            raise SemanticSearchPolicyError("STALE_CONTEXT: direct same-snapshot evidence is unavailable")

    @staticmethod
    def _validate_bound_scope(entry: dict[str, Any], task_id: str, context_id: str) -> None:
        bound = entry["bound"]
        if bound.task_id != task_id or bound.context_id != context_id:
            raise SemanticSearchPolicyError("CROSS_TASK: semantic search binding scope mismatch")

    def _entry(self, transaction_id: str, now: int | None = None) -> dict[str, Any]:
        # Explicit action claims enforce expiry. Verification and state reads
        # may use fixture clocks or an already-dispatched transaction and must
        # not silently mix those clocks with wall time.
        if now is not None:
            self._purge(int(now))
        entry = self._transactions.get(str(transaction_id))
        if entry is None:
            raise SemanticSearchPolicyError("STALE_CONTEXT: semantic search transaction is unavailable")
        return entry

    def _purge(self, now: int) -> None:
        expired = [
            transaction_id
            for transaction_id, entry in self._transactions.items()
            if entry["bound"].expires_at <= now
        ]
        for transaction_id in expired:
            del self._transactions[transaction_id]


@dataclass(frozen=True)
class BoundInstalledApp:
    """Public metadata for one private, non-replayable installed-app target.

    The app name and bundle identifier never leave
    :class:`InstalledAppLaunchBindingStore`. Planner and audit surfaces see
    only this opaque, short-lived reference and aggregate candidate metadata.
    """

    binding_version: str
    binding_id: str
    target_kind: str
    candidate_count: int
    expires_at: int

    SAFE_KEYS = frozenset({"binding_version", "binding_id", "target_kind", "candidate_count", "expires_at"})
    UUID_PATTERN = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")

    def schema(self) -> dict[str, Any]:
        return {
            "binding_version": self.binding_version,
            "binding_id": self.binding_id,
            "target_kind": self.target_kind,
            "candidate_count": self.candidate_count,
            "expires_at": self.expires_at,
        }

    def input_summary(self) -> dict[str, Any]:
        return {
            "target_present": True,
            "target_class": "installed_app",
            "candidate_count": self.candidate_count,
        }

    def validate_public_schema(self) -> None:
        if self.binding_version != BOUND_INSTALLED_APP_LAUNCH_VERSION:
            raise InstalledAppLaunchBindingError("installed-app binding has an unsupported version")
        if set(self.schema()) != self.SAFE_KEYS or not self.UUID_PATTERN.fullmatch(self.binding_id):
            raise InstalledAppLaunchBindingError("installed-app binding has an invalid public schema")
        if self.target_kind != "installed_app" or self.candidate_count != 1:
            raise InstalledAppLaunchBindingError("installed-app binding must represent one installed application")
        if not isinstance(self.expires_at, int) or self.expires_at < 0:
            raise InstalledAppLaunchBindingError("installed-app binding expiry is invalid")

    def registry_snapshot(self) -> Snapshot:
        """Expose only a generic capability token to the unchanged SkillRegistry."""

        self.validate_public_schema()
        return Snapshot("", "", 1, "runtime_binding", ({"text": "app", "clickable": False},))


@dataclass(frozen=True)
class BoundInstalledAppContextReference:
    """Public, scoped reference to one private installed-app identity.

    This is not an executable binding.  It is a short-lived context item that
    can be resolved by the Rich Context layer.  Only the same private binding
    store may later turn it into a one-time :class:`BoundInstalledApp` after
    the normal Planner, Risk, Executor, and Verifier path is selected.
    """

    binding_version: str
    context_reference: str
    target_kind: str
    candidate_count: int
    expires_at: int

    SAFE_KEYS = frozenset({"binding_version", "context_reference", "target_kind", "candidate_count", "expires_at"})
    REFERENCE_PATTERN = re.compile(r"^app\.context\.[0-9a-f]{32}$")

    def schema(self) -> dict[str, Any]:
        return {
            "binding_version": self.binding_version,
            "context_reference": self.context_reference,
            "target_kind": self.target_kind,
            "candidate_count": self.candidate_count,
            "expires_at": self.expires_at,
        }

    def validate_public_schema(self) -> None:
        if self.binding_version != BOUND_INSTALLED_APP_LAUNCH_VERSION:
            raise InstalledAppLaunchBindingError("installed-app context reference has an unsupported version")
        if set(self.schema()) != self.SAFE_KEYS or not self.REFERENCE_PATTERN.fullmatch(self.context_reference):
            raise InstalledAppLaunchBindingError("installed-app context reference has an invalid public schema")
        if self.target_kind != "installed_app" or self.candidate_count != 1:
            raise InstalledAppLaunchBindingError("installed-app context reference must represent one installed application")
        if not isinstance(self.expires_at, int) or self.expires_at < 0:
            raise InstalledAppLaunchBindingError("installed-app context reference expiry is invalid")


class AppTargetResolver:
    """Resolve user-facing app names against one current installed inventory.

    Names and optional deterministic aliases are discovery inputs only. The
    resolver returns canonical bundle identifiers from the supplied inventory;
    an alias can never manufacture an installed application or become the
    downstream authorization identity.
    """

    APP_LIST_KEYS = ("apps", "applications", "items")
    BUNDLE_ID_KEYS = ("bundle_id", "bundleId", "identifier")
    NAME_KEYS = (
        "name",
        "display_name",
        "displayName",
        "localized_name",
        "localizedName",
        "label",
    )
    APP_ID_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9.-]{1,255}$")

    def __init__(self, aliases: Mapping[str, Iterable[str]] | None = None) -> None:
        normalized_aliases: dict[str, tuple[str, ...]] = {}
        for phrase, targets in (aliases or {}).items():
            normalized_phrase = self.normalize_phrase(phrase)
            if isinstance(targets, str):
                raw_targets = (targets,)
            else:
                raw_targets = tuple(targets)
            normalized_targets = tuple(sorted({self.normalize_phrase(item) for item in raw_targets}))
            if not normalized_targets:
                raise InstalledAppLaunchBindingError("installed-app alias must name at least one display label")
            normalized_aliases[normalized_phrase] = normalized_targets
        self._aliases = normalized_aliases

    @staticmethod
    def normalize_phrase(value: Any) -> str:
        if not isinstance(value, str) or any(token in value for token in ("\x00", "\r", "\n")):
            raise InstalledAppLaunchBindingError("installed-app request must be bounded plain text")
        normalized = " ".join(unicodedata.normalize("NFC", value).split())
        if not normalized or len(normalized) > 128:
            raise InstalledAppLaunchBindingError("installed-app request must be non-empty and bounded")
        return normalized.casefold()

    def resolve_candidates(self, payload: dict[str, Any], requested_app: str) -> tuple[str, ...]:
        request = self.normalize_phrase(requested_app)
        if not isinstance(payload, dict):
            raise InstalledAppLaunchBindingError("installed app inventory is invalid")
        raw_apps = next(
            (payload.get(key) for key in self.APP_LIST_KEYS if isinstance(payload.get(key), list)),
            None,
        )
        if not isinstance(raw_apps, list):
            raise InstalledAppLaunchBindingError("installed app inventory has no supported application list")

        alias_targets = frozenset(self._aliases.get(request, ()))
        matched: set[str] = set()
        for app in raw_apps:
            if not isinstance(app, dict):
                continue
            bundle_id = next((app.get(key) for key in self.BUNDLE_ID_KEYS if app.get(key)), None)
            if not isinstance(bundle_id, str) or not self.APP_ID_PATTERN.fullmatch(bundle_id):
                continue
            names = {
                self.normalize_phrase(app.get(key))
                for key in self.NAME_KEYS
                if isinstance(app.get(key), str) and app.get(key).strip()
            }
            direct_name_match = request in names
            direct_bundle_match = request == self.normalize_phrase(bundle_id)
            alias_name_match = bool(alias_targets.intersection(names))
            if direct_name_match or direct_bundle_match or alias_name_match:
                matched.add(bundle_id)
        return tuple(sorted(matched))


@dataclass(frozen=True)
class TargetDisambiguationResult:
    """Typed result of resolving one current installed-app inventory.

    ``selected_bundle_id`` is an internal handoff to the binding store.  It is
    deliberately excluded from ``public_summary`` so a clarification or
    blocked result cannot become a Bundle ID injection surface.
    """

    status: str
    reason_code: str
    candidate_count: int
    selected_bundle_id: str | None = field(default=None, repr=False)

    def resolved(self) -> bool:
        return self.status == "RESOLVED" and isinstance(self.selected_bundle_id, str)

    def public_summary(self) -> dict[str, Any]:
        return {
            "status": self.status,
            "reason_code": self.reason_code,
            "candidate_count": self.candidate_count,
        }


class TargetDisambiguationPolicy:
    """Apply deterministic, source-gated installed-app target resolution.

    The current MCP ``list_apps`` contract exposes only bundle ID, localized
    name, and type, so normal name resolution intentionally remains
    exact-and-unique.  Optional structural metadata is accepted only when it
    carries the explicit live LaunchServices provenance and contract version;
    untrusted or partial metadata cannot narrow a candidate set.
    """

    TRUSTED_METADATA_KEYS = ("trustedMetadata", "trusted_metadata")
    TRUSTED_METADATA_PROVENANCE = "live_launchservices"
    TRUSTED_METADATA_VERSION = "m1.installed-app-metadata.v1"
    APPLICATION_CLASSES = frozenset({"application", "extension"})

    def __init__(self, resolver: AppTargetResolver | None = None) -> None:
        if resolver is not None and not isinstance(resolver, AppTargetResolver):
            raise TypeError("resolver must use AppTargetResolver")
        self._resolver = resolver or AppTargetResolver()

    def resolve(
        self,
        payload: dict[str, Any],
        requested_app: str,
        *,
        semantic_role: str | None = None,
    ) -> TargetDisambiguationResult:
        candidates = self._candidate_records(payload, requested_app)
        if not candidates:
            return TargetDisambiguationResult("TARGET_NOT_FOUND", "TARGET_RESOLUTION_FAILED", 0)
        if len(candidates) == 1 and semantic_role is None:
            return TargetDisambiguationResult(
                "RESOLVED", "UNIQUE_EXACT_MATCH", 1, self._bundle_id(candidates[0])
            )

        metadata = self._trusted_metadata(candidates)
        if metadata is None:
            reason = "TARGET_METADATA_INSUFFICIENT" if len(candidates) > 1 else "TARGET_ROLE_UNRESOLVED"
            status = "TARGET_AMBIGUOUS" if len(candidates) > 1 else "TARGET_METADATA_INSUFFICIENT"
            return TargetDisambiguationResult(status, reason, len(candidates))

        if semantic_role is not None:
            return self._resolve_role(candidates, metadata, semantic_role)

        launchable = [
            self._bundle_id(app)
            for app, item in zip(candidates, metadata)
            if item["launchable"]
            and item["application_class"] == "application"
            and not item["is_extension"]
        ]
        if len(launchable) == 1:
            return TargetDisambiguationResult("RESOLVED", "TRUSTED_STRUCTURAL_METADATA", 1, launchable[0])
        return TargetDisambiguationResult("TARGET_AMBIGUOUS", "TARGET_AMBIGUOUS", len(candidates))

    def _candidate_records(self, payload: dict[str, Any], requested_app: str) -> list[dict[str, Any]]:
        candidate_ids = frozenset(self._resolver.resolve_candidates(payload, requested_app))
        if not isinstance(payload, dict):
            return []
        raw_apps = next(
            (payload.get(key) for key in self._resolver.APP_LIST_KEYS if isinstance(payload.get(key), list)),
            None,
        )
        if not isinstance(raw_apps, list):
            return []
        records = []
        for app in raw_apps:
            if not isinstance(app, dict):
                continue
            bundle_id = self._bundle_id(app)
            if bundle_id in candidate_ids:
                records.append(app)
        return records

    def _trusted_metadata(self, candidates: list[dict[str, Any]]) -> list[dict[str, Any]] | None:
        metadata = []
        for app in candidates:
            item = next((app.get(key) for key in self.TRUSTED_METADATA_KEYS if isinstance(app.get(key), dict)), None)
            if not isinstance(item, dict):
                return None
            if item.get("provenance") != self.TRUSTED_METADATA_PROVENANCE:
                return None
            if item.get("version") != self.TRUSTED_METADATA_VERSION:
                return None
            if not isinstance(item.get("launchable"), bool):
                return None
            if item.get("application_class") not in self.APPLICATION_CLASSES:
                return None
            if not isinstance(item.get("is_extension"), bool):
                return None
            role = item.get("application_role")
            if role is not None:
                try:
                    role = self._resolver.normalize_phrase(role)
                except InstalledAppLaunchBindingError:
                    return None
            metadata.append({
                "launchable": item["launchable"],
                "application_class": item["application_class"],
                "is_extension": item["is_extension"],
                "application_role": role,
            })
        return metadata

    def _resolve_role(
        self,
        candidates: list[dict[str, Any]],
        metadata: list[dict[str, Any]],
        semantic_role: str,
    ) -> TargetDisambiguationResult:
        try:
            role = self._resolver.normalize_phrase(semantic_role)
        except InstalledAppLaunchBindingError:
            return TargetDisambiguationResult("TARGET_ROLE_UNRESOLVED", "TARGET_ROLE_UNRESOLVED", len(candidates))
        role_indexes = [index for index, item in enumerate(metadata) if item["application_role"] == role]
        if not role_indexes:
            return TargetDisambiguationResult("TARGET_ROLE_UNRESOLVED", "TARGET_ROLE_UNRESOLVED", len(candidates))
        valid_indexes = [
            index for index in role_indexes
            if metadata[index]["launchable"]
            and metadata[index]["application_class"] == "application"
            and not metadata[index]["is_extension"]
        ]
        if len(valid_indexes) != len(role_indexes):
            return TargetDisambiguationResult(
                "TARGET_ROLE_IDENTITY_MISMATCH", "TARGET_ROLE_IDENTITY_MISMATCH", len(candidates)
            )
        if len(valid_indexes) != 1:
            return TargetDisambiguationResult("TARGET_AMBIGUOUS", "TARGET_AMBIGUOUS", len(candidates))
        return TargetDisambiguationResult(
            "RESOLVED", "SEMANTIC_ROLE_VALIDATED", 1, self._bundle_id(candidates[valid_indexes[0]])
        )

    @staticmethod
    def _bundle_id(app: dict[str, Any]) -> str:
        return next((value for value in (app.get(key) for key in AppTargetResolver.BUNDLE_ID_KEYS) if isinstance(value, str)), "")


class InstalledAppLaunchBindingStore:
    """Retain one exact installed-app identity only through a single dispatch.

    This transient store is deliberately neither Memory nor task persistence.
    A binding can be claimed once for exactly ``launch_app``; verification may
    compare the current frontmost bundle internally, after which the caller
    discards it. No public API returns the private name or bundle identifier.
    """

    MAX_BINDINGS = 8
    DEFAULT_TTL_SECONDS = 30
    APP_ID_PATTERN = AppTargetResolver.APP_ID_PATTERN
    CONTEXT_SCOPE_PATTERN = re.compile(r"^(task|workspace)\.[a-z0-9][a-z0-9_.-]{2,127}$")

    def __init__(
        self,
        ttl_seconds: int = DEFAULT_TTL_SECONDS,
        capacity: int = MAX_BINDINGS,
        *,
        target_resolver: AppTargetResolver | None = None,
        target_disambiguation_policy: TargetDisambiguationPolicy | None = None,
    ) -> None:
        if ttl_seconds < 1 or capacity < 1:
            raise ValueError("installed-app binding ttl and capacity must be positive")
        if target_resolver is not None and not isinstance(target_resolver, AppTargetResolver):
            raise TypeError("target_resolver must use AppTargetResolver")
        if target_disambiguation_policy is not None and not isinstance(target_disambiguation_policy, TargetDisambiguationPolicy):
            raise TypeError("target_disambiguation_policy must use TargetDisambiguationPolicy")
        self.ttl_seconds = int(ttl_seconds)
        self.capacity = int(capacity)
        self._target_resolver = target_resolver or AppTargetResolver()
        self._target_disambiguation = target_disambiguation_policy or TargetDisambiguationPolicy(self._target_resolver)
        self._private_bindings: dict[str, dict[str, Any]] = {}
        self._private_context_targets: dict[str, dict[str, Any]] = {}
        self._lock = threading.RLock()

    def bind_unique(
        self,
        inventory_payload: dict[str, Any],
        requested_app: str,
        *,
        semantic_role: str | None = None,
        now: int | None = None,
    ) -> BoundInstalledApp:
        """Create a binding only after deterministic target disambiguation."""

        resolution = self._target_disambiguation.resolve(
            inventory_payload, requested_app, semantic_role=semantic_role
        )
        if not resolution.resolved():
            raise InstalledAppLaunchBindingError(
                "installed app resolution blocked: " + resolution.reason_code
            )
        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            return self._new_binding(str(resolution.selected_bundle_id), current_time + self.ttl_seconds)

    def establish_context_reference(
        self,
        inventory_payload: dict[str, Any],
        requested_app: str,
        *,
        task_scope: str,
        workspace_scope: str,
        semantic_role: str | None = None,
        now: int | None = None,
    ) -> BoundInstalledAppContextReference:
        """Create an opaque, task/workspace-scoped reference from one exact app.

        The returned object contains no display name, bundle ID, inventory, or
        action parameters.  It exists only to let the read-only context resolver
        refer to a freshly observed application without becoming an execution
        port itself.
        """

        resolution = self._target_disambiguation.resolve(
            inventory_payload, requested_app, semantic_role=semantic_role
        )
        if not resolution.resolved():
            raise InstalledAppLaunchBindingError(
                "installed app context blocked: " + resolution.reason_code
            )
        self._scope(task_scope, "task_scope")
        self._scope(workspace_scope, "workspace_scope")
        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            self._require_capacity()
            reference = BoundInstalledAppContextReference(
                BOUND_INSTALLED_APP_LAUNCH_VERSION,
                "app.context." + uuid4().hex,
                "installed_app",
                1,
                current_time + self.ttl_seconds,
            )
            reference.validate_public_schema()
            self._private_context_targets[reference.context_reference] = {
                "bundle_id": resolution.selected_bundle_id,
                "task_scope": task_scope,
                "workspace_scope": workspace_scope,
                "expires_at": reference.expires_at,
            }
            return reference

    def bind_unique_from_context(
        self,
        context_reference: str,
        *,
        task_scope: str,
        workspace_scope: str,
        now: int | None = None,
    ) -> BoundInstalledApp:
        """Lower a resolved opaque reference to one existing runtime binding.

        This method deliberately performs no inventory lookup and returns no
        private identity.  Scope, freshness, and capacity are rechecked before
        a new one-time dispatch binding is issued.
        """

        if not isinstance(context_reference, str) or not BoundInstalledAppContextReference.REFERENCE_PATTERN.fullmatch(context_reference):
            raise InstalledAppLaunchBindingError("installed-app context reference is invalid")
        self._scope(task_scope, "task_scope")
        self._scope(workspace_scope, "workspace_scope")
        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            entry = self._private_context_targets.get(context_reference)
            if entry is None:
                raise InstalledAppLaunchBindingError("installed-app context reference is unavailable or expired")
            if not hmac.compare_digest(str(entry.get("task_scope") or ""), task_scope):
                raise InstalledAppLaunchBindingError("installed-app context reference task scope does not match")
            if not hmac.compare_digest(str(entry.get("workspace_scope") or ""), workspace_scope):
                raise InstalledAppLaunchBindingError("installed-app context reference workspace scope does not match")
            bundle_id = entry.get("bundle_id")
            if not isinstance(bundle_id, str) or not self.APP_ID_PATTERN.fullmatch(bundle_id):
                raise InstalledAppLaunchBindingError("installed-app context reference contains an invalid private application identifier")
            # A resolved context reference is an ephemeral bridge, not a
            # reusable action token. Consume it before issuing the one-time
            # dispatch binding so TEST-46 recovery must re-observe and re-plan.
            del self._private_context_targets[context_reference]
            return self._new_binding(bundle_id, int(entry["expires_at"]))

    def validate_request(self, requested_app: Any) -> None:
        """Reject malformed target requests before reading a private inventory."""

        self._request(requested_app)

    def claim(self, binding_id: str, *, tool: str, step_id: str, now: int | None = None) -> dict[str, Any]:
        """Materialize the sole private launch argument immediately before dispatch."""

        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            entry = self._private_bindings.get(str(binding_id))
            if entry is None or entry.get("claimed"):
                raise InstalledAppLaunchBindingError("installed-app binding is unavailable, expired, or already claimed")
            if tool != "launch_app" or step_id != "launch-bound-installed-app":
                raise InstalledAppLaunchBindingError("installed-app binding does not authorize this step")
            bundle_id = entry.get("bundle_id")
            if not isinstance(bundle_id, str) or not self.APP_ID_PATTERN.fullmatch(bundle_id):
                raise InstalledAppLaunchBindingError("installed-app binding contains an invalid private application identifier")
            entry["claimed"] = True
            return {"bundle_id": bundle_id}

    def matches(self, binding_id: str, bundle_id: Any, *, now: int | None = None) -> bool:
        """Compare a frontmost identifier privately without returning either value."""

        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            entry = self._private_bindings.get(str(binding_id))
            return bool(
                entry
                and entry.get("claimed") is True
                and isinstance(bundle_id, str)
                and hmac.compare_digest(str(entry.get("bundle_id") or ""), bundle_id)
            )

    def discard(self, binding_id: str) -> None:
        with self._lock:
            self._private_bindings.pop(str(binding_id), None)

    def _new_binding(self, bundle_id: str, expires_at: int) -> BoundInstalledApp:
        self._require_capacity()
        binding = BoundInstalledApp(
            BOUND_INSTALLED_APP_LAUNCH_VERSION,
            str(uuid4()),
            "installed_app",
            1,
            expires_at,
        )
        binding.validate_public_schema()
        self._private_bindings[binding.binding_id] = {
            "bundle_id": bundle_id,
            "expires_at": binding.expires_at,
            "claimed": False,
        }
        return binding

    def _require_capacity(self) -> None:
        if len(self._private_bindings) + len(self._private_context_targets) >= self.capacity:
            raise InstalledAppLaunchBindingError("installed-app binding capacity reached")

    @classmethod
    def _scope(cls, value: Any, field: str) -> str:
        if not isinstance(value, str) or not cls.CONTEXT_SCOPE_PATTERN.fullmatch(value):
            raise InstalledAppLaunchBindingError("%s must be an opaque task or workspace scope" % field)
        return value

    @classmethod
    def _request(cls, value: Any) -> str:
        return AppTargetResolver.normalize_phrase(value)

    @classmethod
    def _matching_apps(cls, payload: dict[str, Any], request: str) -> list[str]:
        return list(AppTargetResolver().resolve_candidates(payload, request))

    def _purge_expired(self, current_time: int) -> None:
        for binding_id in [
            item for item, entry in self._private_bindings.items() if int(entry.get("expires_at") or 0) <= current_time
        ]:
            del self._private_bindings[binding_id]
        for reference in [
            item for item, entry in self._private_context_targets.items() if int(entry.get("expires_at") or 0) <= current_time
        ]:
            del self._private_context_targets[reference]


@dataclass(frozen=True)
class PublicDestinationContextReference:
    """Opaque TEST-50 context reference for one private destination label."""

    binding_version: str
    context_reference: str
    reference_type: str
    candidate_count: int
    expires_at: int

    REFERENCE_PATTERN = re.compile(r"^destination\.context\.[0-9a-f]{32}$")

    def validate_public_schema(self) -> None:
        if self.binding_version != PUBLIC_DESTINATION_CONTEXT_MAPS_VERSION:
            raise PublicDestinationBindingError("public-destination context version is unsupported")
        if not self.REFERENCE_PATTERN.fullmatch(self.context_reference):
            raise PublicDestinationBindingError("public-destination context reference is invalid")
        if self.reference_type != "public_destination" or self.candidate_count != 1:
            raise PublicDestinationBindingError("public-destination context must represent one candidate")
        if not isinstance(self.expires_at, int) or self.expires_at < 0:
            raise PublicDestinationBindingError("public-destination context expiry is invalid")


@dataclass(frozen=True)
class BoundPublicDestination:
    """Public metadata for one task-scoped, one-use destination binding."""

    binding_version: str
    binding_id: str
    reference_type: str
    candidate_count: int
    expires_at: int

    UUID_PATTERN = re.compile(r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$")

    def validate_public_schema(self) -> None:
        if self.binding_version != PUBLIC_DESTINATION_CONTEXT_MAPS_VERSION:
            raise PublicDestinationBindingError("public-destination binding version is unsupported")
        if not self.UUID_PATTERN.fullmatch(self.binding_id):
            raise PublicDestinationBindingError("public-destination binding identifier is invalid")
        if self.reference_type != "public_destination" or self.candidate_count != 1:
            raise PublicDestinationBindingError("public-destination binding must represent one candidate")
        if not isinstance(self.expires_at, int) or self.expires_at < 0:
            raise PublicDestinationBindingError("public-destination binding expiry is invalid")

    def input_summary(self) -> dict[str, Any]:
        self.validate_public_schema()
        return {
            "destination_present": True,
            "destination_length_bucket": "redacted",
            "destination_class": "public_destination",
        }


class PublicDestinationBindingStore:
    """Process-local authority bridge from trusted context to MapLinkAdapter.

    The normalized destination exists only in this transient store. Context
    references and dispatch bindings are independently single-use, scoped to
    one task/workspace, and consumed before the action attempt so TEST-46
    recovery must re-observe and re-plan instead of replaying an old target.
    """

    DEFAULT_TTL_SECONDS = 30
    MAX_BINDINGS = 8
    SCOPE_PATTERN = re.compile(r"^(task|workspace)\.[a-z0-9][a-z0-9_.-]{2,127}$")
    TRUSTED_SOURCES = frozenset({"CURRENT_TURN", "ACTIVE_TASK"})
    TRUSTED_AUTHORITIES = frozenset({"EXPLICIT_USER", "TASK_BOUND"})
    ALLOWED_PERMISSION_STATES = frozenset({"REFERENCE_ALLOWED"})
    ALLOWED_DESTINATION_CLASSES = frozenset({"PUBLIC_DESTINATION"})

    def __init__(self, ttl_seconds: int = DEFAULT_TTL_SECONDS, capacity: int = MAX_BINDINGS) -> None:
        if ttl_seconds < 1 or capacity < 1:
            raise ValueError("public-destination binding ttl and capacity must be positive")
        self.ttl_seconds = int(ttl_seconds)
        self.capacity = int(capacity)
        self._contexts: dict[str, dict[str, Any]] = {}
        self._bindings: dict[str, dict[str, Any]] = {}
        self._lock = threading.RLock()

    def establish_context_reference(
        self,
        destination: str,
        *,
        task_scope: str,
        workspace_scope: str,
        source_class: str,
        authority: str,
        confidence: int,
        permission_state: str,
        destination_class: str,
        now: int | None = None,
    ) -> PublicDestinationContextReference:
        """Validate once and retain only the normalized public label privately."""

        self._scope(task_scope, "task_scope")
        self._scope(workspace_scope, "workspace_scope")
        if source_class not in self.TRUSTED_SOURCES:
            raise PublicDestinationBindingError("destination source cannot grant action authority")
        if authority not in self.TRUSTED_AUTHORITIES:
            raise PublicDestinationBindingError("destination authority is not explicit or task-bound")
        if permission_state not in self.ALLOWED_PERMISSION_STATES:
            raise PublicDestinationBindingError("destination reference permission is unavailable")
        if destination_class not in self.ALLOWED_DESTINATION_CLASSES:
            raise PublicDestinationBindingError("only public destinations are supported")
        if isinstance(confidence, bool) or not isinstance(confidence, int) or not 0 <= confidence <= 1000:
            raise PublicDestinationBindingError("destination confidence is invalid")
        adapter = MapLinkAdapter(destination)
        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            self._require_capacity()
            reference = PublicDestinationContextReference(
                PUBLIC_DESTINATION_CONTEXT_MAPS_VERSION,
                "destination.context." + uuid4().hex,
                "public_destination",
                1,
                current_time + self.ttl_seconds,
            )
            reference.validate_public_schema()
            self._contexts[reference.context_reference] = {
                "destination": adapter.destination,
                "task_scope": task_scope,
                "workspace_scope": workspace_scope,
                "source_class": source_class,
                "authority": authority,
                "confidence": confidence,
                "permission_state": permission_state,
                "destination_class": destination_class,
                "expires_at": reference.expires_at,
            }
            return reference

    def bind_unique_from_resolution(
        self,
        resolution: dict[str, Any],
        *,
        task_scope: str,
        workspace_scope: str,
        now: int | None = None,
    ) -> tuple[BoundPublicDestination, str]:
        """Lower one safe resolver result without exposing its destination."""

        self._scope(task_scope, "task_scope")
        self._scope(workspace_scope, "workspace_scope")
        current_time = int(time.time()) if now is None else int(now)
        if not isinstance(resolution, dict):
            raise PublicDestinationBindingError("destination resolution must be structured")
        if resolution.get("status") != "RESOLVED" or resolution.get("resolved_type") != "public_destination":
            raise PublicDestinationBindingError("destination resolution is not uniquely resolved")
        if resolution.get("execution_authority") != "none" or resolution.get("replay_allowed") is not False:
            raise PublicDestinationBindingError("context resolution cannot grant action or replay authority")
        reference_value = resolution.get("resolved_reference")
        if not isinstance(reference_value, str) or not PublicDestinationContextReference.REFERENCE_PATTERN.fullmatch(reference_value):
            raise PublicDestinationBindingError("destination resolution reference is unsupported")
        evidence = resolution.get("evidence")
        if not isinstance(evidence, list) or len(evidence) != 1 or not isinstance(evidence[0], dict):
            raise PublicDestinationBindingError("destination resolution requires one safe evidence reference")
        context_id = evidence[0].get("context_item_ref")
        if not isinstance(context_id, str):
            raise PublicDestinationBindingError("destination context item reference is unavailable")
        ContextReferenceResolver._opaque_ref(context_id, "context_item_ref")
        with self._lock:
            self._purge_expired(current_time)
            entry = self._contexts.get(reference_value)
            if entry is None:
                raise PublicDestinationBindingError("destination context is unavailable or already consumed")
            checks = (
                hmac.compare_digest(str(entry["task_scope"]), task_scope),
                hmac.compare_digest(str(entry["workspace_scope"]), workspace_scope),
                resolution.get("scope") == entry["source_class"],
                evidence[0].get("source") == entry["source_class"],
                evidence[0].get("authority") == entry["authority"],
                evidence[0].get("verification_status") == "VERIFIED",
                resolution.get("confidence") == entry["confidence"],
                entry["permission_state"] == "REFERENCE_ALLOWED",
                entry["destination_class"] == "PUBLIC_DESTINATION",
            )
            if not all(checks):
                raise PublicDestinationBindingError("destination context contract does not match its private binding")
            # Consume before creating the dispatch binding. A failure after
            # this point requires fresh context instead of replay.
            del self._contexts[reference_value]
            self._require_capacity()
            binding = BoundPublicDestination(
                PUBLIC_DESTINATION_CONTEXT_MAPS_VERSION,
                str(uuid4()),
                "public_destination",
                1,
                int(entry["expires_at"]),
            )
            binding.validate_public_schema()
            self._bindings[binding.binding_id] = {
                "destination": entry["destination"],
                "task_scope": task_scope,
                "workspace_scope": workspace_scope,
                "source_class": entry["source_class"],
                "authority": entry["authority"],
                "confidence": entry["confidence"],
                "permission_state": entry["permission_state"],
                "expires_at": binding.expires_at,
                "consumed": False,
            }
            return binding, context_id

    def consume_adapter(self, binding_id: str, *, now: int | None = None) -> MapLinkAdapter:
        """Consume one binding before creating the existing typed adapter."""

        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            entry = self._bindings.get(str(binding_id))
            if entry is None or entry.get("consumed") is True:
                raise PublicDestinationBindingError("destination binding is unavailable, expired, or consumed")
            entry["consumed"] = True
            return MapLinkAdapter(str(entry["destination"]))

    def was_consumed(self, binding_id: str, *, now: int | None = None) -> bool:
        current_time = int(time.time()) if now is None else int(now)
        with self._lock:
            self._purge_expired(current_time)
            entry = self._bindings.get(str(binding_id))
            return bool(entry and entry.get("consumed") is True)

    def discard(self, binding_id: str) -> None:
        with self._lock:
            self._bindings.pop(str(binding_id), None)

    @classmethod
    def _scope(cls, value: Any, field: str) -> str:
        if not isinstance(value, str) or not cls.SCOPE_PATTERN.fullmatch(value):
            raise PublicDestinationBindingError("%s must be an opaque task or workspace scope" % field)
        return value

    def _require_capacity(self) -> None:
        if len(self._contexts) + len(self._bindings) >= self.capacity:
            raise PublicDestinationBindingError("public-destination binding capacity reached")

    def _purge_expired(self, current_time: int) -> None:
        for collection in (self._contexts, self._bindings):
            for key in [name for name, value in collection.items() if int(value.get("expires_at") or 0) <= current_time]:
                del collection[key]


@dataclass(frozen=True)
class Intent:
    kind: str
    query: str = ""


@dataclass(frozen=True)
class ToolDescriptor:
    """The portion of a live MCP tool definition relevant to agent selection."""

    name: str
    description: str
    required_arguments: tuple[str, ...]


class MCPClient:
    """Small JSON-RPC client that accepts the MCP server's structured reply."""

    READ_ONLY_TOOLS = frozenset(
        {
            "describe_screen",
            "get_frontmost_app",
            "get_ui_elements",
            "get_element_at_point",
            "get_screen_info",
            "list_apps",
            "list_running_apps",
            "get_app_info",
        }
    )

    def __init__(self, url: str = DEFAULT_MCP_URL, timeout: float = 20.0) -> None:
        self.url = url
        self.timeout = timeout
        self._execution_authority = _MCPExecutionAuthority()
        self._execution_port = _ExecutorMCPPort(self, self._execution_authority)
        self._semantic_search_observation_version = 0
        self._semantic_search_observation_lock = threading.Lock()

    def list_tool_descriptors(self) -> dict[str, ToolDescriptor]:
        result = self._rpc("tools/list", {})
        tools = result.get("tools") or []
        descriptors = {}
        for tool in tools:
            if not isinstance(tool, dict) or not isinstance(tool.get("name"), str):
                continue
            schema = tool.get("inputSchema") or {}
            required = schema.get("required") if isinstance(schema, dict) else []
            if not isinstance(required, list):
                required = []
            descriptors[tool["name"]] = ToolDescriptor(
                name=tool["name"],
                description=str(tool.get("description") or ""),
                required_arguments=tuple(value for value in required if isinstance(value, str)),
            )
        return descriptors

    def list_tools(self) -> set[str]:
        return set(self.list_tool_descriptors())

    def call_tool(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        """Call only an allow-listed read-only MCP tool.

        This compatibility method preserves the TEST-11 through TEST-24
        observation surface. Interaction and other action-capable tools must
        use the private Executor-owned port returned by ``_executor_port``.
        """

        if name not in self.READ_ONLY_TOOLS:
            raise MCPExecutionBoundaryError(
                "%s is action-capable and may be called only through PlanExecutor" % name
            )
        return self._call_tool_payload(name, arguments)

    def _executor_port(self) -> _ExecutorMCPPort:
        """Return the private action port used only by :class:`PlanExecutor`."""

        return self._execution_port

    def _execute_tool(
        self,
        authority: _MCPExecutionAuthority,
        name: str,
        arguments: dict[str, Any],
    ) -> dict[str, Any]:
        if authority is not self._execution_authority:
            raise MCPExecutionBoundaryError("MCP action requires Executor-owned authority")
        return self._call_tool_payload(name, arguments)

    def _call_tool_payload(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        result = self._rpc("tools/call", {"name": name, "arguments": arguments})
        if result.get("isError"):
            raise MCPCallError(self._content_text(result) or "%s returned an error" % name)

        structured = result.get("structuredContent")
        if isinstance(structured, dict):
            return structured

        text = self._content_text(result)
        if text:
            try:
                decoded = json.loads(text)
            except json.JSONDecodeError:
                return {"text": text}
            if isinstance(decoded, dict):
                return decoded
        return {}

    def _temporary_visual_session_payload(self, session_id: str) -> dict[str, Any]:
        """Read one opaque TEST-44.3 native visual session through its private port.

        This bridge is intentionally outside ``call_tool`` and absent from the
        generic tool list. It cannot accept OCR text, geometry, action
        parameters, or a recognition request chosen by a Planner.
        """

        normalized = str(session_id or "").strip()
        if re.fullmatch(r"visualsession\.[0-9a-f]{32}", normalized) is None:
            raise LocalVisualAnalysisError("local visual session identifier is invalid")
        try:
            return self._call_tool_payload(
                "analyze_visual_session",
                {"session_id": normalized, "recognition_mode": "accurate"},
            )
        except MCPCallError as error:
            raise LocalVisualAnalysisError("local visual recognition unavailable") from error

    def _create_temporary_visual_session_grant(self) -> "DeviceVisualSessionGrant":
        """Issue one device-owned grant for the private local-vision bridge.

        The grant endpoint is not part of the public read-only tool surface.
        It accepts no user content or caller-selected authorization fields.
        """

        try:
            payload = self._call_tool_payload("create_visual_session", {})
        except MCPCallError as error:
            raise LocalVisualAnalysisError("local visual authorization unavailable") from error
        return DeviceVisualSessionGrant.from_payload(payload)

    def _read_screen_payload(self, include_ocr: bool = False) -> dict[str, Any]:
        """The sole MCP bridge exposed to the read-only provider layer."""

        return self.call_tool(
            "describe_screen",
            {
                "include_screenshot": False,
                "include_ocr": include_ocr,
                "clickable_only": False,
            },
        )

    def describe(self, include_ocr: bool = False) -> Snapshot:
        """Legacy Snapshot contract retained for TEST-11 through TEST-20."""

        return Snapshot.from_payload(self._read_screen_payload(include_ocr=include_ocr))

    def observe(self) -> Observation:
        """Return AX-first state and use OCR only after AX has no safe elements."""

        router = ObservationProviderRouter(
            (
                AXObservationProvider(),
                VisionObservationProvider(),
                OCRObservationProvider(lambda: self._read_screen_payload(include_ocr=True)),
                VLMObservationProvider(),
            )
        )
        return router.observe(lambda: self._read_screen_payload(include_ocr=False))

    def observe_semantics(self) -> SemanticObservation:
        """Return a TEST-23 aggregate derived only from the provider Observation."""

        return SemanticObservationIntelligence().summarize(self.observe())

    def observe_planner_context(self) -> PlannerSemanticContext:
        """Read one provider-backed screen state and expose only TEST-24 context."""

        return PlannerSemanticContext.from_semantic_observation(self.observe_semantics())

    def observe_semantic_search_page(
        self,
        *,
        task_id: str,
        context_id: str,
        expected_query: str | None = None,
    ) -> SemanticSearchPageObservation:
        """Normalize one AX crawl without inventing a device snapshot.

        When verification needs an expected query, only its SHA-256 digest is
        sent to the device. The device returns a tri-state match and never the
        raw leaf value or the digest.
        """

        arguments: dict[str, Any] = {
            "clickable_only": False,
            "include_semantic_state": True,
        }
        if expected_query is not None:
            arguments["semantic_expected_value_sha256"] = hashlib.sha256(
                expected_query.encode("utf-8", "surrogatepass")
            ).hexdigest()
        payload = self.call_tool("get_ui_elements", arguments)
        device_identity = self._semantic_search_device_identity(payload)
        raw_elements = payload.get("elements") or payload.get("ui_elements") or []
        if not isinstance(raw_elements, list):
            raw_elements = []
        fields: list[SemanticSearchFieldEvidence] = []
        fingerprint_elements: list[dict[str, Any]] = []
        result_markers = 0
        for raw in raw_elements:
            if not isinstance(raw, dict):
                continue
            state = raw.get("semantic_state") if isinstance(raw.get("semantic_state"), dict) else {}
            role_entry = state.get("semantic_role") if isinstance(state, dict) else None
            semantic_role = str(role_entry.get("value") if isinstance(role_entry, dict) else "").casefold()
            if semantic_role in {"link", "cell", "result", "web_area", "browser"}:
                result_markers += 1
            evidence = SemanticSearchFieldEvidence.from_compact_element(raw)
            if evidence is not None:
                fields.append(evidence)
                fingerprint_elements.append(evidence.safe_summary())
            elif semantic_role:
                fingerprint_elements.append({"role": semantic_role, "semantic_state": "incomplete"})
        fingerprint_payload = {
            "device_identity": device_identity,
            "element_count": len(raw_elements),
            "elements": fingerprint_elements,
        }
        page_fingerprint = "page." + hashlib.sha256(
            json.dumps(fingerprint_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
        ).hexdigest()
        with self._semantic_search_observation_lock:
            self._semantic_search_observation_version += 1
            version = self._semantic_search_observation_version
        return SemanticSearchPageObservation(
            source="AX",
            observed_at=int(time.time()),
            observation_version=version,
            page_fingerprint=page_fingerprint,
            task_id=task_id,
            context_id=context_id,
            fields=tuple(fields),
            result_state=result_markers >= 2,
            freshness_source="host_derived",
            device_generation=None,
            device_generation_source="unavailable",
        )

    @staticmethod
    def _semantic_search_device_identity(payload: Any) -> dict[str, Any]:
        if not isinstance(payload, dict):
            raise MCPCallError("semantic observation identity payload is invalid")
        containers = [payload]
        for key in ("frontmost", "frontmostContext"):
            if key in payload:
                if not isinstance(payload[key], dict):
                    raise MCPCallError("semantic observation identity is invalid")
                containers.append(payload[key])
        result: dict[str, Any] = {}
        aliases = {
            "bundle": ("bundleId", "bundle_id", "frontmost_bundle_id"),
            "pid": ("pid",), "context": ("contextId", "context_id"),
            "display": ("displayId", "display_id"),
        }
        for field, keys in aliases.items():
            values = []
            for container in containers:
                for key in keys:
                    if key not in container:
                        continue
                    value = container[key]
                    if field == "bundle":
                        valid = isinstance(value, str) and len(value) <= 255 and all(
                            character.isascii() and (character.isalnum() or character in "._-") for character in value
                        )
                    else:
                        valid = type(value) is int and 0 <= value <= 2**32 - 1
                    if not valid:
                        raise MCPCallError("semantic observation identity type is invalid")
                    if value not in ("", 0):
                        values.append(value)
            if len(set(values)) > 1:
                raise MCPCallError("semantic observation identity mismatch")
            result[field] = values[0] if values else None
        return result

    @staticmethod
    def _semantic_search_role(value: str) -> str | None:
        normalized = str(value or "").casefold().replace("_", "").replace("-", "")
        if "searchfield" in normalized or normalized == "search":
            return "search_field"
        if any(token in normalized for token in ("textfield", "textarea", "textview")):
            return "text_field"
        return None

    @staticmethod
    def _semantic_search_rect(value: dict[str, Any]) -> tuple[float, float, float, float] | None:
        raw = value.get("rect") or value.get("frame") or value.get("visibleFrame")
        if isinstance(raw, dict):
            try:
                return (
                    float(raw.get("x", raw.get("left"))),
                    float(raw.get("y", raw.get("top"))),
                    float(raw.get("width")),
                    float(raw.get("height")),
                )
            except (TypeError, ValueError):
                return None
        if isinstance(raw, (list, tuple)) and len(raw) == 4:
            try:
                return tuple(float(item) for item in raw)  # type: ignore[return-value]
            except (TypeError, ValueError):
                return None
        return None

    def _rpc(self, method: str, params: dict[str, Any]) -> dict[str, Any]:
        auth_token = os.environ.get("PHONEHARNESS_MCP_TOKEN", "").strip()
        if not auth_token:
            raise MCPCallError("MCP auth token is not configured; set PHONEHARNESS_MCP_TOKEN")
        request_body = json.dumps(
            {"jsonrpc": "2.0", "id": str(uuid4()), "method": method, "params": params}
        ).encode("utf-8")
        request = urllib.request.Request(
            self.url,
            data=request_body,
            headers={
                "Content-Type": "application/json",
                "Accept": "application/json, text/event-stream",
                "X-MCP-Token": auth_token,
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                raw = response.read().decode("utf-8")
        except (urllib.error.URLError, TimeoutError) as error:
            raise MCPCallError("MCP endpoint unavailable: %s" % error) from error

        try:
            envelope = json.loads(raw)
        except json.JSONDecodeError as error:
            raise MCPCallError("MCP returned non-JSON data") from error

        if not isinstance(envelope, dict):
            raise MCPCallError("MCP returned an invalid JSON-RPC envelope")
        if "error" in envelope:
            message = envelope["error"].get("message", "unknown MCP error")
            raise MCPCallError("MCP error: %s" % message)
        result = envelope.get("result")
        if not isinstance(result, dict):
            raise MCPCallError("MCP response omitted result")
        return result

    @staticmethod
    def _content_text(result: dict[str, Any]) -> str:
        content = result.get("content") or []
        values = []
        for item in content:
            if isinstance(item, dict) and isinstance(item.get("text"), str):
                values.append(item["text"])
        return "\n".join(values)


class GoalParser:
    """Deliberately small TEST-11 goal language with explicit safety bounds."""

    OBSERVE_PATTERN = re.compile(r"(?:描述|观察|读取|识别).*(?:屏幕|界面|当前)|(?:describe|observe|read).*(?:screen|current)", re.I)
    SEARCH_PATTERN = re.compile(
        r"^(?:(?:在当前(?:界面|页面)?(?:中)?(?:搜索|查找))|(?:搜索|查找)|(?:search\s+(?:the\s+)?current(?:\s+page)?\s+for))\s+(.+)$",
        re.I,
    )
    VERIFY_PATTERN = re.compile(r"^(?:验证|确认).*(?:包含|含有)\s*[：:]?\s*(.+)$", re.I)
    LAUNCH_PATTERN = re.compile(
        r"^(?:打开|启动|运行)\s*[：:]?\s*(.+)$|^(?:open|launch|run)\s+(?:the\s+)?(.+)$",
        re.I,
    )

    def parse(self, goal: str) -> Intent:
        normalized = goal.strip()
        if not normalized:
            return Intent("unsupported")
        if self.OBSERVE_PATTERN.search(normalized):
            return Intent("observe")
        search = self.SEARCH_PATTERN.match(normalized)
        if search:
            query = search.group(1).strip().strip("\"'")
            return Intent("search_current", query) if query else Intent("unsupported")
        verify = self.VERIFY_PATTERN.match(normalized)
        if verify:
            query = verify.group(1).strip().strip("\"'")
            return Intent("verify_visible", query) if query else Intent("unsupported")
        launch = self.LAUNCH_PATTERN.match(normalized)
        if launch:
            target = (launch.group(1) or launch.group(2) or "").strip().strip("\"'")
            return Intent("launch_installed_app", target) if target else Intent("unsupported")
        return Intent("unsupported")


class AgentMemoryStore:
    """Persist bounded, privacy-minimized Agent Brain memory records.

    TEST-14's optional ``record_plan`` API remains a legacy compatibility
    record. TEST-20's formal runtime interface is ``AgentMemoryLayer`` below;
    it uses this same private JSONL file and never writes planning-time data.
    Neither schema is a transcript: both exclude goals, queries, UI/OCR text,
    screenshots, action arguments, and raw MCP responses.
    """

    MAX_RECORD_BYTES = 4096
    MAX_TEXT_LENGTH = 160
    MAX_TOOLS = 24

    def __init__(self, path: str | Path = DEFAULT_MEMORY_PATH, capacity: int = 100) -> None:
        if capacity < 1:
            raise ValueError("memory capacity must be at least one record")
        self.path = Path(path).expanduser()
        self.capacity = capacity
        self.lock_path = self.path.with_name(".%s.lock" % self.path.name)

    def record_plan(self, plan: dict[str, Any]) -> dict[str, Any]:
        """Store TEST-14 legacy planning metadata for explicit callers only."""

        observation = plan.get("observation") if isinstance(plan.get("observation"), dict) else {}
        frontmost = observation.get("frontmost") if isinstance(observation.get("frontmost"), dict) else {}
        entry = {
            "schema_version": "1.0",
            "memory_version": MEMORY_VERSION,
            "record_id": str(uuid4()),
            "recorded_at": int(time.time()),
            "record_type": "plan",
            "outcome": self._limited_text(plan.get("status"), 32),
            "intent": self._limited_text(plan.get("intent"), 64),
            "frontmost": {
                "name": self._limited_text(frontmost.get("name")),
                "bundle_id": self._limited_text(frontmost.get("bundle_id")),
            },
            "element_count": self._nonnegative_integer(observation.get("element_count")),
            "observation_source": self._limited_text(observation.get("source"), 64),
            "selected_tools": self._selected_tools(plan.get("selected_tools")),
        }
        self._append_bounded(entry)
        return entry

    def recent(self, limit: int = 10, bundle_id: str | None = None) -> list[dict[str, Any]]:
        """Return newest-first records, optionally limited to one foreground app."""

        if limit < 1:
            raise ValueError("memory read limit must be at least one")
        self._ensure_private_location()
        with self._locked():
            normalized_bundle = str(bundle_id or "")
            records = [record for record in self._read_records_unlocked() if record.get("record_type") == "plan"]
            if normalized_bundle:
                records = [
                    record
                    for record in records
                    if isinstance(record.get("frontmost"), dict)
                    and record["frontmost"].get("bundle_id") == normalized_bundle
                ]
            return [self._copy(record) for record in reversed(records[-limit:])]

    def records(self) -> list[dict[str, Any]]:
        """Return a consistent private snapshot for formal memory consumers."""

        self._ensure_private_location()
        with self._locked():
            return [self._copy(record) for record in self._read_records_unlocked()]

    def _read_records(self) -> list[dict[str, Any]]:
        """Compatibility snapshot for pre-TEST-40 callers.

        New code should call :meth:`records`; keeping this narrow alias avoids
        silently regressing existing read-only callers while providing the same
        cross-process consistency guarantee.
        """

        return self.records()

    def _append_bounded(self, entry: dict[str, Any]) -> None:
        self._ensure_private_location()
        with self._locked():
            records = self._read_records_unlocked()
            if len(records) >= self.capacity:
                keep = max(0, self.capacity - 1)
                records = records[-keep:] if keep else []
                self._replace_records([*records, entry])
                return
            self._append_line(entry)

    def _ensure_private_location(self) -> None:
        self.path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        self._assert_private_location()

    def _assert_private_location(self) -> None:
        if not self.path.parent.exists():
            return
        directory_mode = stat.S_IMODE(self.path.parent.stat().st_mode)
        if directory_mode & 0o077:
            raise OSError("agent memory directory must not be group/world accessible")
        for candidate in (self.path, self.lock_path):
            if candidate.exists():
                file_mode = stat.S_IMODE(candidate.stat().st_mode)
                if file_mode & 0o077:
                    raise OSError("agent memory files must not be group/world accessible")

    def _locked(self) -> Any:
        return _PrivateFileLock(self.lock_path)

    def _read_records_unlocked(self) -> list[dict[str, Any]]:
        if not self.path.exists():
            return []
        records = []
        with self.path.open("r", encoding="utf-8") as source:
            for line in source:
                try:
                    record = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(record, dict):
                    continue
                if record.get("schema_version") == "1.0" and record.get("memory_version") == MEMORY_VERSION:
                    records.append(record)
                    continue
                if (
                    record.get("schema_version") == "2.0"
                    and record.get("memory_version") == MEMORY_LAYER_VERSION
                    and record.get("record_type") in AgentMemoryLayer.RECORD_TYPES
                ):
                    records.append(record)
                    continue
                if (
                    record.get("schema_version") == PERSONAL_INTELLIGENCE_SCHEMA_VERSION
                    and record.get("memory_version") == PERSONAL_INTELLIGENCE_VERSION
                    and record.get("record_type") in PERSONAL_INTELLIGENCE_RECORD_TYPES
                ):
                    records.append(record)
                    continue
                if (
                    record.get("schema_version") == HUMAN_TEACHING_SCHEMA_VERSION
                    and record.get("memory_version") == HUMAN_TEACHING_VERSION
                    and record.get("record_type") in HUMAN_TEACHING_RECORD_TYPES
                ):
                    records.append(record)
                    continue
                if (
                    record.get("schema_version") == CAPABILITY_GRADUATION_SCHEMA_VERSION
                    and record.get("memory_version") == CAPABILITY_GRADUATION_VERSION
                    and record.get("record_type") in CAPABILITY_GRADUATION_RECORD_TYPES
                ):
                    records.append(record)
        return records

    def _append_line(self, entry: dict[str, Any]) -> None:
        payload = self._encoded_line(entry)
        descriptor = os.open(self.path, os.O_APPEND | os.O_CREAT | os.O_WRONLY, 0o600)
        try:
            os.fchmod(descriptor, 0o600)
            self._write_all(descriptor, payload)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)

    def _replace_records(self, records: list[dict[str, Any]]) -> None:
        temporary = self.path.with_name(".%s.%s.tmp" % (self.path.name, uuid4()))
        descriptor = os.open(temporary, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        try:
            os.fchmod(descriptor, 0o600)
            for record in records:
                self._write_all(descriptor, self._encoded_line(record))
            os.fsync(descriptor)
        except BaseException:
            temporary.unlink(missing_ok=True)
            raise
        finally:
            os.close(descriptor)
        os.replace(temporary, self.path)
        directory_descriptor = os.open(self.path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_descriptor)
        finally:
            os.close(directory_descriptor)

    def _encoded_line(self, entry: dict[str, Any]) -> bytes:
        payload = (json.dumps(entry, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
        if len(payload) > self.MAX_RECORD_BYTES:
            raise ValueError("sanitized memory record exceeds the bounded record size")
        return payload

    @staticmethod
    def _write_all(descriptor: int, payload: bytes) -> None:
        total = 0
        while total < len(payload):
            written = os.write(descriptor, payload[total:])
            if written <= 0:
                raise OSError("unable to write agent memory")
            total += written

    @staticmethod
    def _copy(value: dict[str, Any]) -> dict[str, Any]:
        return json.loads(json.dumps(value))

    @classmethod
    def _limited_text(cls, value: Any, maximum: int | None = None) -> str:
        return str(value or "").strip()[: maximum or cls.MAX_TEXT_LENGTH]

    @staticmethod
    def _nonnegative_integer(value: Any) -> int:
        try:
            return max(0, int(value))
        except (TypeError, ValueError):
            return 0

    @classmethod
    def _selected_tools(cls, values: Any) -> list[str]:
        if not isinstance(values, (list, tuple, set, frozenset)):
            return []
        unique = []
        for value in values:
            tool = cls._limited_text(value, 96)
            if tool and tool not in unique:
                unique.append(tool)
            if len(unique) == cls.MAX_TOOLS:
                break
        return unique


class MemoryPolicyError(ValueError):
    """A TEST-20 memory write or read violates the formal memory contract."""


class AgentMemoryLayer:
    """TEST-20 formal summary layer backed by the existing ``AgentMemoryStore``.

    This layer writes only after a verifier pass, a terminal task completion,
    or a bounded error classification. It is advisory-only: callers can obtain
    a privacy-minimized context explicitly, but it cannot select a Skill,
    alter a Plan, skip observation, bypass Risk Control, or invoke a tool.
    """

    SCHEMA_VERSION = "2.0"
    RECORD_TYPES = frozenset({"task_memory", "skill_memory", "environment_memory"})
    TASK_STATES = frozenset({"completed", "failed", "blocked", "cancelled", "interrupted"})
    ERROR_TYPES = frozenset(
        {
            "goal_not_supported",
            "read_only_scope_rejected",
            "planner_blocked",
            "risk_rejected",
            "verification_failed",
            "execution_failed",
            "runtime_session_missing",
            "mcp_unavailable",
        }
    )
    WRITE_BOUNDARIES = frozenset({"verifier_pass", "task_completed", "classified_error"})
    IDENTIFIER_PATTERN = re.compile(r"^[a-z][a-z0-9_.-]{2,127}$")
    VERSION_PATTERN = re.compile(r"^\d+\.\d+\.\d+$")
    MAX_TASK_SUMMARIES = 12
    MAX_SKILL_SUMMARIES = 24
    MAX_CAPABILITIES = 24
    MAX_TOOLS = 48

    def __init__(self, store: AgentMemoryStore) -> None:
        if not isinstance(store, AgentMemoryStore):
            raise TypeError("TEST-20 memory layer requires an AgentMemoryStore")
        self._store = store

    def record_task_completion(
        self,
        *,
        task_state: str,
        completion_result: str,
        verifier_passed: bool,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Write a task summary only after a verified completed task."""

        if task_state != "completed" or completion_result != "passed" or verifier_passed is not True:
            raise MemoryPolicyError("task memory requires a completed task with verifier_passed=True")
        return self._append(
            {
                "record_type": "task_memory",
                "write_boundary": "task_completed",
                "task_state": "completed",
                "completion_result": "passed",
                "error_type": None,
            },
            recorded_at=recorded_at,
        )

    def record_classified_task_error(
        self,
        *,
        task_state: str,
        error_type: str,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Write only a fixed error category after the task has stopped."""

        if task_state not in self.TASK_STATES or task_state == "completed":
            raise MemoryPolicyError("classified task memory requires a non-completed terminal state")
        normalized_error = self._error_type(error_type)
        return self._append(
            {
                "record_type": "task_memory",
                "write_boundary": "classified_error",
                "task_state": task_state,
                "completion_result": "not_completed",
                "error_type": normalized_error,
            },
            recorded_at=recorded_at,
        )

    def record_skill_verification(
        self,
        *,
        skill_id: str,
        version: str,
        verifier_passed: bool,
        error_type: str | None = None,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Write Skill reliability metadata only from a verified result."""

        normalized_skill = self._identifier(skill_id, "skill_id")
        normalized_version = self._version(version)
        if verifier_passed is True:
            if error_type is not None:
                raise MemoryPolicyError("successful Skill verification cannot include an error type")
            boundary = "verifier_pass"
            status = "passed"
            normalized_error = None
        elif verifier_passed is False:
            boundary = "classified_error"
            status = "failed"
            normalized_error = self._error_type(error_type)
        else:
            raise MemoryPolicyError("Skill memory requires an explicit verifier result")
        return self._append(
            {
                "record_type": "skill_memory",
                "write_boundary": boundary,
                "skill_id": normalized_skill,
                "version": normalized_version,
                "verification_status": status,
                "error_type": normalized_error,
            },
            recorded_at=recorded_at,
        )

    def record_verified_environment(
        self,
        *,
        platform_support: Iterable[str],
        verified_capabilities: Iterable[str],
        available_tools: Iterable[str],
        verifier_passed: bool,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Write platform/capability facts only after a verifier pass."""

        if verifier_passed is not True:
            raise MemoryPolicyError("environment memory requires verifier_passed=True")
        platforms = self._labels(platform_support, "platform_support", self.MAX_CAPABILITIES)
        if not platforms or any(platform not in DEFAULT_SKILL_PLATFORMS for platform in platforms):
            raise MemoryPolicyError("environment platform metadata is unsupported")
        return self._append(
            {
                "record_type": "environment_memory",
                "write_boundary": "verifier_pass",
                "platform_support": platforms,
                "verified_capabilities": self._labels(
                    verified_capabilities,
                    "verified_capabilities",
                    self.MAX_CAPABILITIES,
                ),
                "available_tools": self._labels(available_tools, "available_tools", self.MAX_TOOLS),
            },
            recorded_at=recorded_at,
        )

    def planner_context(self) -> dict[str, Any]:
        """Return advisory summaries through the only future Planner read API.

        DynamicPlanner does not call this method in TEST-20. A later Planner
        integration must opt in at this boundary and continue through fresh
        Observation, Skill selection, Risk Control, execution, and verification.
        """

        records = [record for record in self._store.records() if self._is_formal_record(record)]
        task_records = [record for record in records if record["record_type"] == "task_memory"]
        skill_records = [record for record in records if record["record_type"] == "skill_memory"]
        environment_records = [record for record in records if record["record_type"] == "environment_memory"]

        task_memory = [
            {
                "task_state": record["task_state"],
                "completion_result": record["completion_result"],
                "error_type": record["error_type"],
                "recorded_at": record["recorded_at"],
            }
            for record in reversed(task_records[-self.MAX_TASK_SUMMARIES :])
        ]
        skill_memory = self._skill_summaries(skill_records)
        environment_memory = self._environment_summary(environment_records)
        return {
            "memory_layer_version": MEMORY_LAYER_VERSION,
            "mode": "advisory_only",
            "decision_effect": "none",
            "requires_fresh_observation": True,
            "requires_skill_registry": True,
            "requires_risk_controller": True,
            "requires_verifier": True,
            "task_memory": task_memory,
            "skill_memory": skill_memory,
            "environment_memory": environment_memory,
        }

    def _append(self, fields: dict[str, Any], *, recorded_at: int | None) -> dict[str, Any]:
        entry = {
            "schema_version": self.SCHEMA_VERSION,
            "memory_version": MEMORY_LAYER_VERSION,
            "record_id": str(uuid4()),
            "recorded_at": int(time.time()) if recorded_at is None else int(recorded_at),
            **fields,
        }
        if not self._is_formal_record(entry):
            raise MemoryPolicyError("formal memory record did not satisfy the schema")
        self._store._append_bounded(entry)
        return json.loads(json.dumps(entry))

    def _skill_summaries(self, records: list[dict[str, Any]]) -> list[dict[str, Any]]:
        aggregates: dict[tuple[str, str], dict[str, Any]] = {}
        for record in records:
            key = (record["skill_id"], record["version"])
            aggregate = aggregates.setdefault(
                key,
                {
                    "skill_id": key[0],
                    "version": key[1],
                    "use_count": 0,
                    "success_count": 0,
                    "failure_count": 0,
                    "last_verified": {"status": "unknown", "recorded_at": 0},
                },
            )
            aggregate["use_count"] += 1
            if record["verification_status"] == "passed":
                aggregate["success_count"] += 1
            else:
                aggregate["failure_count"] += 1
            if int(record["recorded_at"]) >= int(aggregate["last_verified"]["recorded_at"]):
                aggregate["last_verified"] = {
                    "status": record["verification_status"],
                    "recorded_at": record["recorded_at"],
                }
        return [aggregates[key] for key in sorted(aggregates)][: self.MAX_SKILL_SUMMARIES]

    @staticmethod
    def _environment_summary(records: list[dict[str, Any]]) -> dict[str, Any] | None:
        if not records:
            return None
        record = records[-1]
        return {
            "platform_support": list(record["platform_support"]),
            "verified_capabilities": list(record["verified_capabilities"]),
            "available_tools": list(record["available_tools"]),
            "recorded_at": record["recorded_at"],
        }

    @classmethod
    def _is_formal_record(cls, record: Any) -> bool:
        if not isinstance(record, dict):
            return False
        common = {"schema_version", "memory_version", "record_id", "recorded_at", "record_type", "write_boundary"}
        if record.get("schema_version") != cls.SCHEMA_VERSION or record.get("memory_version") != MEMORY_LAYER_VERSION:
            return False
        if not isinstance(record.get("record_id"), str) or not record.get("record_id"):
            return False
        if not isinstance(record.get("recorded_at"), int) or int(record["recorded_at"]) < 0:
            return False
        record_type = record.get("record_type")
        if record_type == "task_memory":
            expected = common | {"task_state", "completion_result", "error_type"}
            return (
                set(record) == expected
                and record.get("write_boundary") in {"task_completed", "classified_error"}
                and record.get("task_state") in cls.TASK_STATES
                and record.get("completion_result") in {"passed", "not_completed"}
                and (record.get("error_type") is None or record.get("error_type") in cls.ERROR_TYPES)
                and (
                    (record.get("write_boundary") == "task_completed"
                    and record.get("task_state") == "completed"
                    and record.get("completion_result") == "passed"
                    and record.get("error_type") is None)
                    or (record.get("write_boundary") == "classified_error"
                        and record.get("task_state") != "completed"
                        and record.get("completion_result") == "not_completed"
                        and record.get("error_type") in cls.ERROR_TYPES)
                )
            )
        if record_type == "skill_memory":
            expected = common | {"skill_id", "version", "verification_status", "error_type"}
            passed = (
                record.get("write_boundary") == "verifier_pass"
                and record.get("verification_status") == "passed"
                and record.get("error_type") is None
            )
            failed = (
                record.get("write_boundary") == "classified_error"
                and record.get("verification_status") == "failed"
                and record.get("error_type") in cls.ERROR_TYPES
            )
            return (
                set(record) == expected
                and isinstance(record.get("skill_id"), str)
                and cls.IDENTIFIER_PATTERN.fullmatch(record["skill_id"]) is not None
                and isinstance(record.get("version"), str)
                and cls.VERSION_PATTERN.fullmatch(record["version"]) is not None
                and (passed or failed)
            )
        if record_type == "environment_memory":
            expected = common | {"platform_support", "verified_capabilities", "available_tools"}
            return (
                set(record) == expected
                and record.get("write_boundary") == "verifier_pass"
                and cls._valid_label_list(record.get("platform_support"), cls.MAX_CAPABILITIES)
                and cls._valid_label_list(record.get("verified_capabilities"), cls.MAX_CAPABILITIES)
                and cls._valid_label_list(record.get("available_tools"), cls.MAX_TOOLS)
                and all(platform in DEFAULT_SKILL_PLATFORMS for platform in record["platform_support"])
            )
        return False

    @classmethod
    def _identifier(cls, value: Any, field: str) -> str:
        normalized = str(value or "").strip()
        if cls.IDENTIFIER_PATTERN.fullmatch(normalized) is None:
            raise MemoryPolicyError("%s must be a bounded identifier" % field)
        return normalized

    @classmethod
    def _version(cls, value: Any) -> str:
        normalized = str(value or "").strip()
        if cls.VERSION_PATTERN.fullmatch(normalized) is None:
            raise MemoryPolicyError("Skill memory version must use semantic versioning")
        return normalized

    @classmethod
    def _error_type(cls, value: Any) -> str:
        normalized = str(value or "").strip()
        if normalized not in cls.ERROR_TYPES:
            raise MemoryPolicyError("memory error type must be a fixed classification")
        return normalized

    @classmethod
    def _labels(cls, values: Iterable[str], field: str, maximum: int) -> list[str]:
        if isinstance(values, (str, bytes)):
            raise MemoryPolicyError("%s must be a sequence of metadata labels" % field)
        try:
            iterator = iter(values)
        except TypeError as error:
            raise MemoryPolicyError("%s must be a sequence of metadata labels" % field) from error
        labels = []
        for value in iterator:
            label = cls._identifier(value, field)
            if label not in labels:
                labels.append(label)
            if len(labels) > maximum:
                raise MemoryPolicyError("%s exceeds its bounded size" % field)
        return labels

    @classmethod
    def _valid_label_list(cls, values: Any, maximum: int) -> bool:
        if not isinstance(values, list) or len(values) > maximum:
            return False
        return all(isinstance(value, str) and cls.IDENTIFIER_PATTERN.fullmatch(value) for value in values)


class PersonalIntelligencePolicyError(ValueError):
    """A TEST-28 Personal Intelligence record violates its privacy contract."""


class DecisionEvidenceLayer:
    """Store only confirmed, metadata-only outcomes for future Experience Replay.

    This layer cannot select a capability, change a recommendation, invoke a
    planner, call MCP, or replay a past action.  It records generic source and
    lifecycle metadata plus confirmed outcome, confidence, and duration only.
    """

    RECORD_TYPE = "decision_evidence"
    SOURCE_TYPES = frozenset(
        {"native_shortcut", "learned_workflow", "skill_package", "computer_use", "external_tool"}
    )
    LIFECYCLES = frozenset({"DISCOVERED", "AVAILABLE", "VERIFIED", "PREFERRED", "DEPRECATED"})
    OUTCOMES = frozenset({"passed", "failed"})
    MAX_DURATION_MS = 600000

    def __init__(self, store: AgentMemoryStore) -> None:
        if not isinstance(store, AgentMemoryStore):
            raise TypeError("DecisionEvidenceLayer requires an AgentMemoryStore")
        self._store = store

    def record_confirmed_result(
        self,
        *,
        source_type: str,
        lifecycle: str,
        outcome: str,
        confidence: float,
        duration_ms: int,
        result_confirmed: bool,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Persist one outcome only after a verifier or classifier confirms it."""

        if result_confirmed is not True:
            raise PersonalIntelligencePolicyError("decision evidence requires a confirmed result")
        normalized_source = self._enum(source_type, self.SOURCE_TYPES, "source_type")
        normalized_lifecycle = self._enum(lifecycle, self.LIFECYCLES, "lifecycle")
        normalized_outcome = self._enum(outcome, self.OUTCOMES, "outcome")
        normalized_confidence = self._confidence(confidence)
        normalized_duration = self._duration(duration_ms)
        entry = {
            "schema_version": PERSONAL_INTELLIGENCE_SCHEMA_VERSION,
            "memory_version": PERSONAL_INTELLIGENCE_VERSION,
            "record_id": str(uuid4()),
            "recorded_at": self._timestamp(recorded_at),
            "record_type": self.RECORD_TYPE,
            "write_boundary": "verifier_pass" if normalized_outcome == "passed" else "classified_result",
            "source_type": normalized_source,
            "lifecycle": normalized_lifecycle,
            "outcome": normalized_outcome,
            "confidence": normalized_confidence,
            "duration_ms": normalized_duration,
        }
        if not self.is_valid_record(entry):
            raise PersonalIntelligencePolicyError("decision evidence record did not satisfy the schema")
        self._store._append_bounded(entry)
        return json.loads(json.dumps(entry))

    def summary(self) -> list[dict[str, Any]]:
        """Return aggregate evidence only; individual records never leave this layer."""

        aggregates: dict[tuple[str, str], dict[str, Any]] = {}
        for record in self._records():
            key = (record["source_type"], record["lifecycle"])
            aggregate = aggregates.setdefault(
                key,
                {
                    "source_type": key[0],
                    "lifecycle": key[1],
                    "selection_count": 0,
                    "success_count": 0,
                    "failure_count": 0,
                    "confidence_total": 0.0,
                    "duration_total_ms": 0,
                    "last_recorded_at": 0,
                },
            )
            aggregate["selection_count"] += 1
            aggregate["success_count"] += 1 if record["outcome"] == "passed" else 0
            aggregate["failure_count"] += 1 if record["outcome"] == "failed" else 0
            aggregate["confidence_total"] += float(record["confidence"])
            aggregate["duration_total_ms"] += int(record["duration_ms"])
            aggregate["last_recorded_at"] = max(int(aggregate["last_recorded_at"]), int(record["recorded_at"]))
        summaries = []
        for key in sorted(aggregates):
            aggregate = aggregates[key]
            count = aggregate["selection_count"]
            summaries.append(
                {
                    "source_type": aggregate["source_type"],
                    "lifecycle": aggregate["lifecycle"],
                    "selection_count": count,
                    "success_count": aggregate["success_count"],
                    "failure_count": aggregate["failure_count"],
                    "mean_confidence": round(aggregate["confidence_total"] / count, 6),
                    "mean_duration_ms": round(aggregate["duration_total_ms"] / count, 3),
                    "last_recorded_at": aggregate["last_recorded_at"],
                }
            )
        return summaries

    def _records(self) -> list[dict[str, Any]]:
        return [record for record in self._store.records() if self.is_valid_record(record)]

    @classmethod
    def is_valid_record(cls, record: Any) -> bool:
        common = {"schema_version", "memory_version", "record_id", "recorded_at", "record_type", "write_boundary"}
        expected = common | {"source_type", "lifecycle", "outcome", "confidence", "duration_ms"}
        if not isinstance(record, dict) or set(record) != expected:
            return False
        if (
            record.get("schema_version") != PERSONAL_INTELLIGENCE_SCHEMA_VERSION
            or record.get("memory_version") != PERSONAL_INTELLIGENCE_VERSION
            or record.get("record_type") != cls.RECORD_TYPE
            or not isinstance(record.get("record_id"), str)
            or not record.get("record_id")
            or isinstance(record.get("recorded_at"), bool)
            or not isinstance(record.get("recorded_at"), int)
            or int(record["recorded_at"]) < 0
            or record.get("source_type") not in cls.SOURCE_TYPES
            or record.get("lifecycle") not in cls.LIFECYCLES
            or record.get("outcome") not in cls.OUTCOMES
        ):
            return False
        confidence = record.get("confidence")
        duration = record.get("duration_ms")
        expected_boundary = "verifier_pass" if record.get("outcome") == "passed" else "classified_result"
        return (
            record.get("write_boundary") == expected_boundary
            and not isinstance(confidence, bool)
            and isinstance(confidence, (int, float))
            and 0.0 <= float(confidence) <= 1.0
            and not isinstance(duration, bool)
            and isinstance(duration, int)
            and 0 <= duration <= cls.MAX_DURATION_MS
        )

    @staticmethod
    def _enum(value: Any, allowed: frozenset[str], field: str) -> str:
        normalized = str(value or "").strip()
        if normalized not in allowed:
            raise PersonalIntelligencePolicyError("%s must be an allow-listed metadata value" % field)
        return normalized

    @staticmethod
    def _confidence(value: Any) -> float:
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not 0.0 <= float(value) <= 1.0:
            raise PersonalIntelligencePolicyError("confidence must be between 0.0 and 1.0")
        return float(value)

    @classmethod
    def _duration(cls, value: Any) -> int:
        if isinstance(value, bool) or not isinstance(value, int) or not 0 <= value <= cls.MAX_DURATION_MS:
            raise PersonalIntelligencePolicyError("duration_ms must be a bounded non-negative integer")
        return value

    @staticmethod
    def _timestamp(value: int | None) -> int:
        timestamp = int(time.time()) if value is None else value
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise PersonalIntelligencePolicyError("recorded_at must be a non-negative timestamp")
        return timestamp


class PersonalIntelligenceCore:
    """Privacy-minimized personal model with no autonomous decision effect.

    TEST-28 intentionally models only explicit, allow-listed user preferences
    plus generic verified results.  It is not a transcript, profile scraper,
    task planner, action executor, or App-specific automation subsystem.
    """

    RECORD_TYPES = frozenset({"personal_preference", "habit_summary", "task_result_summary"})
    MODELS = {
        "preference": {
            "privacy_retention": frozenset({"minimal", "standard"}),
            "automation_consent": frozenset({"always_confirm", "risk_based_confirm"}),
        },
        "decision_preference": {
            "candidate_priority": frozenset({"reliability_first", "privacy_first", "simplicity_first"}),
            "ambiguity_resolution": frozenset({"require_confirmation"}),
        },
        "communication_style": {
            "detail_level": frozenset({"concise", "balanced", "detailed"}),
            "instruction_format": frozenset({"stepwise", "summary_first"}),
            "language_mode": frozenset({"zh", "en", "bilingual"}),
        },
    }
    HABIT_IDS = frozenset({"read_only_observation", "semantic_verification", "low_risk_interaction"})
    TASK_RESULT_TYPES = frozenset(
        {"read_only_observation", "semantic_verification", "capability_evaluation", "low_risk_interaction"}
    )
    MAX_TASK_SUMMARIES = 12

    def __init__(self, store: AgentMemoryStore) -> None:
        if not isinstance(store, AgentMemoryStore):
            raise TypeError("PersonalIntelligenceCore requires an AgentMemoryStore")
        self._store = store
        self.decision_evidence = DecisionEvidenceLayer(store)

    def record_confirmed_preference(
        self,
        *,
        model: str,
        preference_key: str,
        preference_value: str,
        confirmed_by_user: bool,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Write an allow-listed preference only after explicit user confirmation."""

        if confirmed_by_user is not True:
            raise PersonalIntelligencePolicyError("personal preferences require explicit user confirmation")
        normalized_model = self._model(model)
        normalized_key = self._preference_key(normalized_model, preference_key)
        normalized_value = self._preference_value(normalized_model, normalized_key, preference_value)
        return self._append(
            {
                "record_type": "personal_preference",
                "write_boundary": "explicit_user_confirmation",
                "model": normalized_model,
                "preference_key": normalized_key,
                "preference_value": normalized_value,
            },
            recorded_at=recorded_at,
        )

    def record_verified_habit(
        self,
        *,
        habit_id: str,
        verifier_passed: bool,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Record one generic, successful pattern event after verification only."""

        if verifier_passed is not True:
            raise PersonalIntelligencePolicyError("habit statistics require verifier_passed=True")
        normalized_habit = self._enum(habit_id, self.HABIT_IDS, "habit_id")
        return self._append(
            {
                "record_type": "habit_summary",
                "write_boundary": "verifier_pass",
                "habit_id": normalized_habit,
                "verification_status": "passed",
            },
            recorded_at=recorded_at,
        )

    def record_successful_task_summary(
        self,
        *,
        summary_type: str,
        task_completed: bool,
        verifier_passed: bool,
        recorded_at: int | None = None,
    ) -> dict[str, Any]:
        """Record a bounded generic success summary, never a Goal or Plan."""

        if task_completed is not True or verifier_passed is not True:
            raise PersonalIntelligencePolicyError("task summary requires a completed verifier-passed task")
        normalized_type = self._enum(summary_type, self.TASK_RESULT_TYPES, "summary_type")
        return self._append(
            {
                "record_type": "task_result_summary",
                "write_boundary": "task_completed",
                "task_state": "completed",
                "completion_result": "passed",
                "summary_type": normalized_type,
            },
            recorded_at=recorded_at,
        )

    def record_decision_evidence(self, **kwargs: Any) -> dict[str, Any]:
        """Delegate future Experience Replay metadata to its dedicated layer."""

        return self.decision_evidence.record_confirmed_result(**kwargs)

    def advisory_context(self) -> dict[str, Any]:
        """Return safe model summaries with an explicit zero decision effect."""

        records = [record for record in self._store.records() if self.is_valid_record(record)]
        return {
            "personal_intelligence_version": PERSONAL_INTELLIGENCE_VERSION,
            "mode": "advisory_only",
            "decision_effect": "none",
            "requires_explicit_planner_opt_in": True,
            "requires_fresh_observation": True,
            "requires_solution_evaluation": True,
            "requires_risk_controller": True,
            "requires_verifier": True,
            "preference_model": self._preference_summary(records, "preference"),
            "habit_model": self._habit_summary(records),
            "decision_preference_model": self._preference_summary(records, "decision_preference"),
            "communication_style_model": self._preference_summary(records, "communication_style"),
            "successful_task_summaries": self._task_summary(records),
            "decision_evidence": self.decision_evidence.summary(),
        }

    def _append(self, fields: dict[str, Any], *, recorded_at: int | None) -> dict[str, Any]:
        entry = {
            "schema_version": PERSONAL_INTELLIGENCE_SCHEMA_VERSION,
            "memory_version": PERSONAL_INTELLIGENCE_VERSION,
            "record_id": str(uuid4()),
            "recorded_at": self._timestamp(recorded_at),
            **fields,
        }
        if not self.is_valid_record(entry):
            raise PersonalIntelligencePolicyError("personal intelligence record did not satisfy the schema")
        self._store._append_bounded(entry)
        return json.loads(json.dumps(entry))

    @classmethod
    def is_valid_record(cls, record: Any) -> bool:
        common = {"schema_version", "memory_version", "record_id", "recorded_at", "record_type", "write_boundary"}
        if not isinstance(record, dict):
            return False
        if (
            record.get("schema_version") != PERSONAL_INTELLIGENCE_SCHEMA_VERSION
            or record.get("memory_version") != PERSONAL_INTELLIGENCE_VERSION
            or record.get("record_type") not in cls.RECORD_TYPES
            or not isinstance(record.get("record_id"), str)
            or not record.get("record_id")
            or isinstance(record.get("recorded_at"), bool)
            or not isinstance(record.get("recorded_at"), int)
            or int(record["recorded_at"]) < 0
        ):
            return False
        if record["record_type"] == "personal_preference":
            expected = common | {"model", "preference_key", "preference_value"}
            model = record.get("model")
            key = record.get("preference_key")
            value = record.get("preference_value")
            return (
                set(record) == expected
                and record.get("write_boundary") == "explicit_user_confirmation"
                and model in cls.MODELS
                and key in cls.MODELS[model]
                and value in cls.MODELS[model][key]
            )
        if record["record_type"] == "habit_summary":
            expected = common | {"habit_id", "verification_status"}
            return (
                set(record) == expected
                and record.get("write_boundary") == "verifier_pass"
                and record.get("habit_id") in cls.HABIT_IDS
                and record.get("verification_status") == "passed"
            )
        expected = common | {"task_state", "completion_result", "summary_type"}
        return (
            set(record) == expected
            and record.get("write_boundary") == "task_completed"
            and record.get("task_state") == "completed"
            and record.get("completion_result") == "passed"
            and record.get("summary_type") in cls.TASK_RESULT_TYPES
        )

    @classmethod
    def _preference_summary(cls, records: list[dict[str, Any]], model: str) -> list[dict[str, Any]]:
        latest: dict[str, dict[str, Any]] = {}
        for record in records:
            if record["record_type"] != "personal_preference" or record["model"] != model:
                continue
            current = latest.get(record["preference_key"])
            if current is None or int(record["recorded_at"]) >= int(current["recorded_at"]):
                latest[record["preference_key"]] = record
        return [
            {
                "preference_key": key,
                "preference_value": latest[key]["preference_value"],
                "confirmed_at": latest[key]["recorded_at"],
            }
            for key in sorted(latest)
        ]

    @classmethod
    def _habit_summary(cls, records: list[dict[str, Any]]) -> list[dict[str, Any]]:
        aggregate: dict[str, dict[str, int]] = {}
        for record in records:
            if record["record_type"] != "habit_summary":
                continue
            habit = record["habit_id"]
            current = aggregate.setdefault(habit, {"verified_count": 0, "last_verified": 0})
            current["verified_count"] += 1
            current["last_verified"] = max(current["last_verified"], int(record["recorded_at"]))
        return [
            {
                "habit_id": habit,
                "verified_count": aggregate[habit]["verified_count"],
                "last_verified": aggregate[habit]["last_verified"],
            }
            for habit in sorted(aggregate)
        ]

    @classmethod
    def _task_summary(cls, records: list[dict[str, Any]]) -> list[dict[str, Any]]:
        summaries = [
            {"summary_type": record["summary_type"], "completed_at": record["recorded_at"]}
            for record in records
            if record["record_type"] == "task_result_summary"
        ]
        return list(reversed(summaries[-cls.MAX_TASK_SUMMARIES :]))

    @classmethod
    def _model(cls, value: Any) -> str:
        return cls._enum(value, frozenset(cls.MODELS), "model")

    @classmethod
    def _preference_key(cls, model: str, value: Any) -> str:
        return cls._enum(value, frozenset(cls.MODELS[model]), "preference_key")

    @classmethod
    def _preference_value(cls, model: str, key: str, value: Any) -> str:
        return cls._enum(value, cls.MODELS[model][key], "preference_value")

    @staticmethod
    def _enum(value: Any, allowed: frozenset[str], field: str) -> str:
        normalized = str(value or "").strip()
        if normalized not in allowed:
            raise PersonalIntelligencePolicyError("%s must be an allow-listed metadata value" % field)
        return normalized

    @staticmethod
    def _timestamp(value: int | None) -> int:
        timestamp = int(time.time()) if value is None else value
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise PersonalIntelligencePolicyError("recorded_at must be a non-negative timestamp")
        return timestamp


class IdentityConsentPolicyError(ValueError):
    """TEST-36 identity, consent, audit, or permission-policy contract failed."""


