class ShortcutRegistry:
    """A metadata adapter from declared Shortcuts to capability methods only."""

    SHORTCUT_ID_PATTERN = re.compile(r"^shortcut\.[a-z][a-z0-9_.-]{2,127}$")

    def __init__(self, methods: CapabilityMethodRegistry) -> None:
        if not isinstance(methods, CapabilityMethodRegistry):
            raise CapabilityIntelligenceError("methods must be a CapabilityMethodRegistry")
        self.methods = methods
        self._shortcuts: dict[str, ShortcutDefinition] = {}

    def register(self, shortcut: ShortcutDefinition) -> dict[str, Any]:
        if not isinstance(shortcut, ShortcutDefinition) or not self.SHORTCUT_ID_PATTERN.fullmatch(shortcut.shortcut_id):
            raise CapabilityIntelligenceError("shortcut_id must be a stable lowercase identifier")
        if shortcut.shortcut_id in self._shortcuts:
            raise CapabilityIntelligenceError("shortcut_id must be unique")
        method = shortcut.as_method()
        self.methods.register(method)
        self._shortcuts[shortcut.shortcut_id] = shortcut
        contract = method.contract()
        contract["shortcut_id"] = shortcut.shortcut_id
        contract["shortcut_action_graph"] = "not_stored"
        return contract

    def contracts(self) -> list[dict[str, Any]]:
        result = []
        for shortcut in self._shortcuts.values():
            method = self.methods.get(shortcut.as_method().method_id)
            if method is not None:
                method["shortcut_id"] = shortcut.shortcut_id
                method["shortcut_action_graph"] = "not_stored"
                result.append(method)
        return result


