class AppIntentRegistry:
    """Prepare App Intent exposure contracts without implementing iOS entry code."""

    INTENT_ID_PATTERN = re.compile(r"^appintent\.[a-z][a-z0-9_.-]{2,127}$")
    EXPOSURES = frozenset({"start_agent_task", "run_skill", "check_task_status", "create_automation"})

    def __init__(self, methods: CapabilityMethodRegistry) -> None:
        if not isinstance(methods, CapabilityMethodRegistry):
            raise CapabilityIntelligenceError("methods must be a CapabilityMethodRegistry")
        self.methods = methods
        self._intents: dict[str, AppIntentDefinition] = {}

    def register(self, intent: AppIntentDefinition) -> dict[str, Any]:
        if not isinstance(intent, AppIntentDefinition) or not self.INTENT_ID_PATTERN.fullmatch(intent.intent_id):
            raise CapabilityIntelligenceError("intent_id must be a stable lowercase identifier")
        if intent.exposure not in self.EXPOSURES:
            raise CapabilityIntelligenceError("unsupported App Intent exposure")
        if intent.intent_id in self._intents:
            raise CapabilityIntelligenceError("intent_id must be unique")
        method = intent.as_method()
        self.methods.register(method)
        self._intents[intent.intent_id] = intent
        contract = method.contract()
        contract["intent_id"] = intent.intent_id
        contract["exposure"] = intent.exposure
        contract["ios_entrypoint"] = "not_implemented"
        return contract

    def contracts(self) -> list[dict[str, Any]]:
        result = []
        for intent in self._intents.values():
            method = self.methods.get(intent.as_method().method_id)
            if method is not None:
                method["intent_id"] = intent.intent_id
                method["exposure"] = intent.exposure
                method["ios_entrypoint"] = "not_implemented"
                result.append(method)
        return result


@dataclass(frozen=True)
class SkillManifest:
    """Governance metadata for a Skill candidate, separate from runtime selection.

    A manifest cannot be selected by ``SkillRegistry`` and has no executable
    route.  It becomes useful only after later graduation explicitly creates or
    updates a separately reviewed ``SkillDefinition``.
    """

    skill_id: str
    name: str
    description: str
    version: str
    domain: str
    source: str
    trust_state: str
    lifecycle: str
    required_capabilities: tuple[str, ...]
    dependencies: tuple[str, ...]
    requested_permissions: tuple[str, ...]
    risk_level: str
    verifier: str
    platform_support: tuple[str, ...]
    evidence: CapabilityEvidence = CapabilityEvidence()
    verification_status: str = "not_tested"

    def contract(self) -> dict[str, Any]:
        attempts = self.evidence.success_count + self.evidence.failure_count
        return {
            "skill_governance_version": CAPABILITY_SKILL_GOVERNANCE_VERSION,
            "skill_id": self.skill_id,
            "name": self.name,
            "description": self.description,
            "version": self.version,
            "domain": self.domain,
            "source": self.source,
            "trust_state": self.trust_state,
            "lifecycle": self.lifecycle,
            "required_capabilities": list(self.required_capabilities),
            "dependencies": list(self.dependencies),
            "requested_permissions": list(self.requested_permissions),
            "risk_level": self.risk_level,
            "verifier": self.verifier,
            "platform_support": list(self.platform_support),
            "verification_status": self.verification_status,
            "evidence": self.evidence.summary(),
            "usage_history": {
                "attempt_count": attempts,
                "success_count": self.evidence.success_count,
                "failure_count": self.evidence.failure_count,
                "success_rate": (self.evidence.success_count / attempts) if attempts else None,
            },
            "selection_authority": "none",
            "execution_authority": "none",
        }


@dataclass(frozen=True)
class SkillGovernanceAuditRecord:
    """An immutable metadata-only record of one manifest lifecycle event."""

    skill_id: str
    previous_lifecycle: str | None
    lifecycle: str
    reason_code: str
    timestamp: int

    def contract(self) -> dict[str, Any]:
        return {
            "skill_id": self.skill_id,
            "previous_lifecycle": self.previous_lifecycle,
            "lifecycle": self.lifecycle,
            "reason_code": self.reason_code,
            "timestamp": self.timestamp,
        }


class SkillGovernanceCatalog:
    """Track review and trust for candidates without changing SkillRegistry.

    This companion catalog is intentionally not another Skill selector.  The
    existing SkillRegistry remains the sole runtime selector.  This catalog
    exposes review state so TEST-32 graduation can later decide whether a
    candidate is eligible to become an independently reviewed SkillDefinition.
    """

    SOURCES = frozenset({"built_in", "user_created", "user_taught", "external_candidate"})
    TRUST_STATES = frozenset({"untrusted", "reviewed", "user_confirmed", "platform_trusted"})
    LIFECYCLES = frozenset({"CREATED", "CANDIDATE", "REVIEWED", "VERIFIED", "ACTIVE", "SUSPENDED", "ARCHIVED"})
    VERIFICATION_STATUSES = CapabilityMethodRegistry.VERIFICATION_STATUSES
    TRANSITIONS = {
        "CREATED": frozenset({"CANDIDATE", "ARCHIVED"}),
        "CANDIDATE": frozenset({"REVIEWED", "SUSPENDED", "ARCHIVED"}),
        "REVIEWED": frozenset({"VERIFIED", "SUSPENDED", "ARCHIVED"}),
        "VERIFIED": frozenset({"ACTIVE", "SUSPENDED", "ARCHIVED"}),
        "ACTIVE": frozenset({"SUSPENDED", "ARCHIVED"}),
        "SUSPENDED": frozenset({"REVIEWED", "ARCHIVED"}),
        "ARCHIVED": frozenset(),
    }
    REASON_PATTERN = CapabilityCatalog.METADATA_LABEL_PATTERN

    def __init__(self, manifests: Iterable[SkillManifest] = ()) -> None:
        self._manifests: dict[str, SkillManifest] = {}
        self._audit: list[SkillGovernanceAuditRecord] = []
        for manifest in manifests:
            self.register(manifest)

    def register(self, manifest: SkillManifest, *, timestamp: int | None = None) -> dict[str, Any]:
        self._validate(manifest)
        if manifest.skill_id in self._manifests:
            raise CapabilityIntelligenceError("manifest skill_id must be unique")
        if manifest.lifecycle not in {"CREATED", "CANDIDATE"}:
            raise CapabilityIntelligenceError("new manifest must start as CREATED or CANDIDATE")
        created_at = self._timestamp(timestamp)
        self._manifests[manifest.skill_id] = manifest
        self._audit.append(
            SkillGovernanceAuditRecord(
                skill_id=manifest.skill_id,
                previous_lifecycle=None,
                lifecycle=manifest.lifecycle,
                reason_code="manifest_registered",
                timestamp=created_at,
            )
        )
        return manifest.contract()

    def get(self, skill_id: str) -> dict[str, Any] | None:
        manifest = self._manifests.get(skill_id)
        return manifest.contract() if manifest is not None else None

    def contracts(self) -> list[dict[str, Any]]:
        return [manifest.contract() for manifest in self._manifests.values()]

    def audit_records(self, *, skill_id: str | None = None) -> list[dict[str, Any]]:
        return [record.contract() for record in self._audit if skill_id is None or record.skill_id == skill_id]

    def transition(
        self,
        skill_id: str,
        lifecycle: str,
        *,
        reason_code: str,
        timestamp: int | None = None,
    ) -> dict[str, Any]:
        manifest = self._manifests.get(skill_id)
        if manifest is None:
            raise CapabilityIntelligenceError("unknown manifest skill_id")
        if lifecycle not in self.TRANSITIONS[manifest.lifecycle]:
            raise CapabilityIntelligenceError("manifest lifecycle transition is not allowed")
        if not self.REASON_PATTERN.fullmatch(reason_code):
            raise CapabilityIntelligenceError("reason_code must be bounded metadata")
        replacement = replace(manifest, lifecycle=lifecycle)
        self._validate(replacement)
        event_time = self._timestamp(timestamp)
        self._manifests[skill_id] = replacement
        self._audit.append(
            SkillGovernanceAuditRecord(
                skill_id=skill_id,
                previous_lifecycle=manifest.lifecycle,
                lifecycle=lifecycle,
                reason_code=reason_code,
                timestamp=event_time,
            )
        )
        return replacement.contract()

    def record_evidence(
        self,
        skill_id: str,
        *,
        passed: bool,
        confidence: float,
        verification_status: str,
        timestamp: int | None = None,
    ) -> dict[str, Any]:
        manifest = self._manifests.get(skill_id)
        if manifest is None:
            raise CapabilityIntelligenceError("unknown manifest skill_id")
        if verification_status not in self.VERIFICATION_STATUSES:
            raise CapabilityIntelligenceError("unsupported manifest verification_status")
        if passed != (verification_status in {"static_pass", "device_pass"}):
            raise CapabilityIntelligenceError("verification status must match verification result")
        evidence = manifest.evidence.record(passed=passed, confidence=confidence, verified_at=timestamp)
        replacement = replace(manifest, evidence=evidence, verification_status=verification_status)
        self._validate(replacement)
        self._manifests[skill_id] = replacement
        self._audit.append(
            SkillGovernanceAuditRecord(
                skill_id=skill_id,
                previous_lifecycle=manifest.lifecycle,
                lifecycle=replacement.lifecycle,
                reason_code="verification_recorded",
                timestamp=self._timestamp(timestamp),
            )
        )
        return replacement.contract()

    @classmethod
    def _validate(cls, manifest: SkillManifest) -> None:
        if not isinstance(manifest, SkillManifest):
            raise CapabilityIntelligenceError("only SkillManifest instances can be registered")
        if not SkillRegistry.SKILL_ID_PATTERN.fullmatch(manifest.skill_id):
            raise CapabilityIntelligenceError("skill_id must use a stable lowercase identifier")
        if not isinstance(manifest.name, str) or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(manifest.name):
            raise CapabilityIntelligenceError("manifest name must be bounded metadata")
        if not isinstance(manifest.description, str) or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(manifest.description):
            raise CapabilityIntelligenceError("manifest description must be bounded metadata")
        if not SkillRegistry.SEMVER_PATTERN.fullmatch(manifest.version):
            raise CapabilityIntelligenceError("manifest version must be semantic major.minor.patch")
        if not isinstance(manifest.domain, str) or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(manifest.domain):
            raise CapabilityIntelligenceError("manifest domain must be bounded metadata")
        if manifest.source not in cls.SOURCES:
            raise CapabilityIntelligenceError("unsupported manifest source")
        if manifest.trust_state not in cls.TRUST_STATES:
            raise CapabilityIntelligenceError("unsupported manifest trust_state")
        if manifest.lifecycle not in cls.LIFECYCLES:
            raise CapabilityIntelligenceError("unsupported manifest lifecycle")
        if manifest.risk_level not in SkillRegistry.RISK_LEVELS:
            raise CapabilityIntelligenceError("unsupported manifest risk_level")
        if manifest.verification_status not in cls.VERIFICATION_STATUSES:
            raise CapabilityIntelligenceError("unsupported manifest verification_status")
        if not isinstance(manifest.evidence, CapabilityEvidence):
            raise CapabilityIntelligenceError("manifest evidence must use CapabilityEvidence")
        for field_name, values, required in (
            ("required_capabilities", manifest.required_capabilities, True),
            ("dependencies", manifest.dependencies, False),
            ("requested_permissions", manifest.requested_permissions, False),
            ("platform_support", manifest.platform_support, True),
        ):
            if required and not values:
                raise CapabilityIntelligenceError("%s must not be empty" % field_name)
            if not isinstance(values, tuple) or any(
                not isinstance(value, str) or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(value)
                for value in values
            ):
                raise CapabilityIntelligenceError("%s must contain bounded metadata labels" % field_name)
            if len(values) != len(set(values)):
                raise CapabilityIntelligenceError("%s cannot contain duplicates" % field_name)
        if manifest.skill_id in manifest.dependencies:
            raise CapabilityIntelligenceError("manifest cannot depend on itself")
        if manifest.source == "external_candidate" and manifest.lifecycle in {"VERIFIED", "ACTIVE"}:
            raise CapabilityIntelligenceError("external candidates cannot become verified or active in TEST-40.3")
        if manifest.lifecycle == "ACTIVE":
            evidence = manifest.evidence
            if (
                manifest.verification_status != "device_pass"
                or manifest.trust_state not in {"user_confirmed", "platform_trusted"}
                or evidence.success_count < 1
                or evidence.last_verified is None
                or evidence.confidence < CapabilityMethodRegistry.MIN_ACTIVE_CONFIDENCE
            ):
                raise CapabilityIntelligenceError("active manifests require user/platform trust and device evidence")

    @staticmethod
    def _timestamp(value: int | None) -> int:
        timestamp = int(time.time()) if value is None else value
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise CapabilityIntelligenceError("timestamp must be a non-negative integer")
        return timestamp


class SolutionEvaluationError(ValueError):
    """A TEST-27 solution evaluation request violates its safe contract."""


@dataclass(frozen=True)
class SolutionEvaluationPolicy:
    """Explicit, stable scoring weights for transparent solution evaluation.

    A score represents a recommendation only.  It is never a Risk Controller
    decision, a plan, an execution authorization, or an instruction to call an
    MCP tool.  The policy intentionally evaluates only TEST-26 metadata.
    """

    lifecycle_weight: float = 0.30
    evidence_weight: float = 0.30
    source_weight: float = 0.20
    simplicity_weight: float = 0.10
    risk_exposure_weight: float = 0.10
    tie_epsilon: float = 0.000001

    def __post_init__(self) -> None:
        values = (
            self.lifecycle_weight,
            self.evidence_weight,
            self.source_weight,
            self.simplicity_weight,
            self.risk_exposure_weight,
        )
        if any(isinstance(value, bool) or not isinstance(value, (int, float)) for value in values):
            raise SolutionEvaluationError("solution evaluation weights must be numeric")
        if any(float(value) < 0.0 or float(value) > 1.0 for value in values):
            raise SolutionEvaluationError("solution evaluation weights must be between 0.0 and 1.0")
        if abs(sum(float(value) for value in values) - 1.0) > 0.000001:
            raise SolutionEvaluationError("solution evaluation weights must sum to 1.0")
        if isinstance(self.tie_epsilon, bool) or not isinstance(self.tie_epsilon, (int, float)):
            raise SolutionEvaluationError("tie_epsilon must be numeric")
        if not 0.0 <= float(self.tie_epsilon) <= 0.1:
            raise SolutionEvaluationError("tie_epsilon must be between 0.0 and 0.1")

    def summary(self) -> dict[str, Any]:
        """Return the full scoring policy for audit without task or UI data."""

        return {
            "solution_evaluation_version": SOLUTION_EVALUATION_VERSION,
            "weights": {
                "lifecycle": float(self.lifecycle_weight),
                "evidence": float(self.evidence_weight),
                "source": float(self.source_weight),
                "simplicity": float(self.simplicity_weight),
                "risk_exposure": float(self.risk_exposure_weight),
            },
            "tie_epsilon": float(self.tie_epsilon),
            "score_scales": {
                "lifecycle": SolutionEvaluator.LIFECYCLE_SCORES.copy(),
                "source_type": SolutionEvaluator.SOURCE_TYPE_SCORES.copy(),
                "risk_level": SolutionEvaluator.RISK_EXPOSURE_SCORES.copy(),
            },
            "downstream_gates": {
                "planner_required": True,
                "risk_controller_required": True,
                "executor_required": True,
                "verifier_required": True,
            },
        }


@dataclass(frozen=True)
class SolutionCandidateEvaluation:
    """One capability score and its auditable, metadata-only rationale."""

    candidate: CapabilityCandidate
    score: float | None
    rank: int | None
    score_components: dict[str, float]
    reason_codes: tuple[str, ...]

    def summary(self) -> dict[str, Any]:
        definition = self.candidate.definition
        return {
            "capability_id": definition.capability_id,
            "version": definition.version,
            "source_type": definition.source_type,
            "lifecycle": self.candidate.lifecycle,
            "risk_level": definition.risk_level,
            "eligible": self.candidate.eligible,
            "score": self.score,
            "rank": self.rank,
            "score_components": dict(self.score_components),
            "reason_codes": list(self.reason_codes),
            "required_tool_count": len(definition.required_tools),
            "dependency_count": len(definition.dependencies),
            "requires_downstream_planner": True,
            "requires_risk_controller": True,
            "requires_executor": True,
            "requires_verifier": True,
        }


@dataclass(frozen=True)
class SolutionEvaluation:
    """A ranking result that cannot select, authorize, or execute a solution."""

    status: str
    policy: SolutionEvaluationPolicy
    candidates: tuple[SolutionCandidateEvaluation, ...]
    recommended_capability_id: str | None
    recommendation_reason_codes: tuple[str, ...]

    STATUSES = frozenset({"recommended", "ambiguous", "no_eligible_candidates"})

    def __post_init__(self) -> None:
        if self.status not in self.STATUSES:
            raise SolutionEvaluationError("unsupported solution evaluation status")
        if self.status == "recommended" and self.recommended_capability_id is None:
            raise SolutionEvaluationError("recommended status requires a capability identifier")
        if self.status != "recommended" and self.recommended_capability_id is not None:
            raise SolutionEvaluationError("only recommended status may return a capability identifier")

    def summary(self) -> dict[str, Any]:
        """Serialize scores and a recommendation without raw capability payloads."""

        recommendation = None
        if self.recommended_capability_id is not None:
            selected = next(
                item for item in self.candidates if item.candidate.definition.capability_id == self.recommended_capability_id
            )
            recommendation = {
                "capability_id": self.recommended_capability_id,
                "score": selected.score,
                "reason_codes": list(self.recommendation_reason_codes),
                "requires_downstream_planner": True,
                "requires_risk_controller": True,
                "requires_executor": True,
                "requires_verifier": True,
            }
        return {
            "solution_evaluation_version": SOLUTION_EVALUATION_VERSION,
            "status": self.status,
            "policy": self.policy.summary(),
            "candidate_count": len(self.candidates),
            "eligible_candidate_count": sum(1 for item in self.candidates if item.candidate.eligible),
            "candidates": [item.summary() for item in self.candidates],
            "recommendation": recommendation,
        }


class SolutionEvaluator:
    """Score trusted capability candidates without calling any runtime layer.

    The evaluator accepts only the TEST-26 ``CapabilityEvaluation`` value.  It
    has no Goal, Planner, Risk Controller, Executor, Verifier, MCP client, or
    device connection.  Its output remains advisory and requires every
    downstream gate before any later execution can occur.
    """

    LIFECYCLE_SCORES = {
        "DISCOVERED": 0.25,
        "AVAILABLE": 0.55,
        "VERIFIED": 0.80,
        "PREFERRED": 0.95,
        "DEPRECATED": 0.0,
    }
    SOURCE_TYPE_SCORES = {
        "native_shortcut": 1.0,
        "native_capability_link": 0.95,
        "learned_workflow": 0.85,
        "skill_package": 0.70,
        "computer_use": 0.40,
        "external_tool": 0.35,
    }
    RISK_EXPOSURE_SCORES = {
        "read_only": 0.75,
        "interaction": 0.50,
        "high_risk": 0.25,
    }

    def __init__(self, policy: SolutionEvaluationPolicy | None = None) -> None:
        self.policy = policy if policy is not None else SolutionEvaluationPolicy()
        if not isinstance(self.policy, SolutionEvaluationPolicy):
            raise SolutionEvaluationError("policy must be a SolutionEvaluationPolicy")

    def evaluate(self, capability_evaluation: CapabilityEvaluation) -> SolutionEvaluation:
        """Score eligible capability metadata and fail closed on an exact tie."""

        if not isinstance(capability_evaluation, CapabilityEvaluation):
            raise SolutionEvaluationError("capability_evaluation must be a CapabilityEvaluation")
        eligible = []
        rejected = []
        for candidate in capability_evaluation.candidates:
            if not candidate.eligible:
                rejected.append(
                    SolutionCandidateEvaluation(
                        candidate=candidate,
                        score=None,
                        rank=None,
                        score_components={},
                        reason_codes=("ineligible_capability",) + candidate.reason_codes,
                    )
                )
                continue
            eligible.append(self._score_candidate(candidate))

        ranked = sorted(
            eligible,
            key=lambda item: (-float(item.score), item.candidate.definition.capability_id),
        )
        ranked = [
            SolutionCandidateEvaluation(
                candidate=item.candidate,
                score=item.score,
                rank=index,
                score_components=item.score_components,
                reason_codes=item.reason_codes,
            )
            for index, item in enumerate(ranked, start=1)
        ]
        all_candidates = tuple(ranked + sorted(rejected, key=lambda item: item.candidate.definition.capability_id))

        if not ranked:
            return SolutionEvaluation(
                status="no_eligible_candidates",
                policy=self.policy,
                candidates=all_candidates,
                recommended_capability_id=None,
                recommendation_reason_codes=("no_eligible_capabilities",),
            )
        if len(ranked) > 1 and abs(float(ranked[0].score) - float(ranked[1].score)) <= self.policy.tie_epsilon:
            return SolutionEvaluation(
                status="ambiguous",
                policy=self.policy,
                candidates=all_candidates,
                recommended_capability_id=None,
                recommendation_reason_codes=("top_candidate_score_tie", "human_or_planner_resolution_required"),
            )
        selected = ranked[0]
        return SolutionEvaluation(
            status="recommended",
            policy=self.policy,
            candidates=all_candidates,
            recommended_capability_id=selected.candidate.definition.capability_id,
            recommendation_reason_codes=("highest_transparent_score",) + selected.reason_codes,
        )

    def _score_candidate(self, candidate: CapabilityCandidate) -> SolutionCandidateEvaluation:
        definition = candidate.definition
        lifecycle_score = self.LIFECYCLE_SCORES[candidate.lifecycle]
        source_score = self.SOURCE_TYPE_SCORES[definition.source_type]
        evidence_score, evidence_reason = self._evidence_score(definition.evidence)
        simplicity_score = 1.0 / (1.0 + len(definition.required_tools) + len(definition.dependencies))
        risk_score = self.RISK_EXPOSURE_SCORES[definition.risk_level]
        components = {
            "lifecycle": lifecycle_score,
            "evidence": evidence_score,
            "source": source_score,
            "simplicity": simplicity_score,
            "risk_exposure": risk_score,
        }
        score = (
            self.policy.lifecycle_weight * lifecycle_score
            + self.policy.evidence_weight * evidence_score
            + self.policy.source_weight * source_score
            + self.policy.simplicity_weight * simplicity_score
            + self.policy.risk_exposure_weight * risk_score
        )
        reasons = (
            "requirements_satisfied",
            "lifecycle_%s" % candidate.lifecycle.lower(),
            "source_type_%s" % definition.source_type,
            evidence_reason,
            "risk_%s_requires_downstream_assessment" % definition.risk_level,
            "contract_complexity_tools_%d_dependencies_%d" % (len(definition.required_tools), len(definition.dependencies)),
        )
        return SolutionCandidateEvaluation(
            candidate=candidate,
            score=round(float(score), 6),
            rank=None,
            score_components={name: round(float(value), 6) for name, value in components.items()},
            reason_codes=reasons,
        )

    @staticmethod
    def _evidence_score(evidence: CapabilityEvidence) -> tuple[float, str]:
        total = evidence.success_count + evidence.failure_count
        if total == 0:
            return 0.50, "evidence_unverified_baseline"
        success_rate = evidence.success_count / total
        score = (success_rate + float(evidence.confidence)) / 2.0
        return score, "evidence_aggregate_verified"


class SolutionEvaluationLayer:
    """TEST-27 read-only facade for transparent capability recommendations.

    This facade has no MCP, Planner, Risk Controller, Executor, Verifier, or
    task state.  It cannot turn a score into an action and does not retain its
    input or output beyond the caller's process.
    """

    def __init__(self, evaluator: SolutionEvaluator | None = None) -> None:
        self.evaluator = evaluator if evaluator is not None else SolutionEvaluator()
        if not isinstance(self.evaluator, SolutionEvaluator):
            raise SolutionEvaluationError("evaluator must be a SolutionEvaluator")

    def evaluate_candidates(self, capability_evaluation: CapabilityEvaluation) -> SolutionEvaluation:
        return self.evaluator.evaluate(capability_evaluation)


class AdaptiveIntelligenceRouterError(ValueError):
    """A TEST-30 intelligence-routing request violates its metadata contract."""


ADAPTIVE_INTELLIGENCE_SOURCES = frozenset(
    {
        "deterministic_capability",
        "native_shortcut",
        "learned_workflow",
        "learned_skill",
        "local_model",
        "hybrid_model",
        "cloud_model",
        "human_teaching_request",
    }
)
ADAPTIVE_ROUTER_REASON_CODES = frozenset(
    {
        "solution_recommended",
        "solution_not_recommended",
        "deterministic_evidence_verified",
        "deterministic_limited_trial",
        "deterministic_evidence_insufficient",
        "learned_evidence_verified",
        "learned_evidence_insufficient",
        "source_unavailable",
        "privacy_cloud_blocked",
        "predicted_success_highest",
        "historical_evidence_applied",
        "source_priority_tiebreak",
        "latency_tiebreak",
        "cost_tiebreak",
        "low_confidence",
        "task_repeatable",
        "teaching_available",
        "no_reliable_existing_capability",
        "trust_pre_authorized",
        "trust_requires_confirmation",
        "critical_action_blocked",
        "no_eligible_source",
        "unresolved_equivalent_sources",
    }
)


@dataclass(frozen=True)
class IntelligenceSourceProfile:
    """One bounded, non-executable intelligence-source candidate.

    The profile contains only aggregate scoring metadata.  It cannot carry a
    goal, application identifier, interface data, model prompt, or action.
    """

    source: str
    available: bool
    predicted_success: float
    latency_class: str
    cost_class: str
    evidence: CapabilityEvidence = CapabilityEvidence()

    LATENCY_CLASSES = frozenset({"fast", "standard", "slow"})
    COST_CLASSES = frozenset({"none", "low", "medium", "high"})

    def __post_init__(self) -> None:
        if self.source not in ADAPTIVE_INTELLIGENCE_SOURCES:
            raise AdaptiveIntelligenceRouterError("unsupported intelligence source")
        if not isinstance(self.available, bool):
            raise AdaptiveIntelligenceRouterError("available must be boolean")
        if isinstance(self.predicted_success, bool) or not isinstance(self.predicted_success, (int, float)):
            raise AdaptiveIntelligenceRouterError("predicted_success must be numeric")
        if not 0.0 <= float(self.predicted_success) <= 1.0:
            raise AdaptiveIntelligenceRouterError("predicted_success must be between 0.0 and 1.0")
        if self.latency_class not in self.LATENCY_CLASSES:
            raise AdaptiveIntelligenceRouterError("unsupported latency_class")
        if self.cost_class not in self.COST_CLASSES:
            raise AdaptiveIntelligenceRouterError("unsupported cost_class")
        if not isinstance(self.evidence, CapabilityEvidence):
            raise AdaptiveIntelligenceRouterError("evidence must use CapabilityEvidence")

    def summary(self) -> dict[str, Any]:
        """Return source metadata suitable for an in-memory audit report."""

        return {
            "source": self.source,
            "available": self.available,
            "predicted_success": float(self.predicted_success),
            "latency_class": self.latency_class,
            "cost_class": self.cost_class,
            "evidence": self.evidence.summary(),
        }


@dataclass(frozen=True)
class IntelligenceRoutingRequest:
    """Sanitized context used to recommend an intelligence source.

    Every field is an allow-listed class or aggregate statistic.  This schema
    deliberately has no free-form task field and is never persisted here.
    """

    task_complexity: str
    aggregate_confidence: float
    risk_level: str
    task_repeatability: str
    privacy_class: str
    trust_tier: str
    preference: str
    teaching_available: bool
    source_profiles: tuple[IntelligenceSourceProfile, ...]
    limited_trial: bool = False

    COMPLEXITIES = frozenset({"low", "medium", "high"})
    REPEATABILITY = frozenset({"unknown", "unlikely", "likely"})
    PRIVACY_CLASSES = frozenset({"local_only", "cloud_approved", "sensitive"})
    TRUST_TIERS = frozenset({"low", "medium", "high", "critical"})
    PREFERENCES = frozenset({"experience_first", "prefer_local", "prefer_cloud", "prefer_teaching"})

    def __post_init__(self) -> None:
        if self.task_complexity not in self.COMPLEXITIES:
            raise AdaptiveIntelligenceRouterError("unsupported task_complexity")
        if isinstance(self.aggregate_confidence, bool) or not isinstance(self.aggregate_confidence, (int, float)):
            raise AdaptiveIntelligenceRouterError("aggregate_confidence must be numeric")
        if not 0.0 <= float(self.aggregate_confidence) <= 1.0:
            raise AdaptiveIntelligenceRouterError("aggregate_confidence must be between 0.0 and 1.0")
        if self.risk_level not in SkillRegistry.RISK_LEVELS:
            raise AdaptiveIntelligenceRouterError("unsupported risk_level")
        if self.task_repeatability not in self.REPEATABILITY:
            raise AdaptiveIntelligenceRouterError("unsupported task_repeatability")
        if self.privacy_class not in self.PRIVACY_CLASSES:
            raise AdaptiveIntelligenceRouterError("unsupported privacy_class")
        if self.trust_tier not in self.TRUST_TIERS:
            raise AdaptiveIntelligenceRouterError("unsupported trust_tier")
        if self.preference not in self.PREFERENCES:
            raise AdaptiveIntelligenceRouterError("unsupported preference")
        if not isinstance(self.teaching_available, bool):
            raise AdaptiveIntelligenceRouterError("teaching_available must be boolean")
        if not isinstance(self.limited_trial, bool):
            raise AdaptiveIntelligenceRouterError("limited_trial must be boolean")
        if not isinstance(self.source_profiles, tuple) or not self.source_profiles:
            raise AdaptiveIntelligenceRouterError("source_profiles must be a non-empty tuple")
        if any(not isinstance(profile, IntelligenceSourceProfile) for profile in self.source_profiles):
            raise AdaptiveIntelligenceRouterError("source_profiles must contain IntelligenceSourceProfile values")
        sources = [profile.source for profile in self.source_profiles]
        if len(sources) != len(set(sources)):
            raise AdaptiveIntelligenceRouterError("source_profiles cannot contain duplicate sources")


@dataclass(frozen=True)
class IntelligencePathRecommendation:
    """A safe recommendation that carries no provider, tool, or action handle."""

    status: str
    recommended_source: str | None
    confidence: float | None
    reason_codes: tuple[str, ...]
    fallback_source: str | None
    requires_confirmation: bool
    privacy_boundary: str

    STATUSES = frozenset({"recommended", "needs_human_teaching", "ambiguous", "blocked"})
    PRIVACY_BOUNDARIES = frozenset(
        {"local_only", "cloud_minimum_context", "owner_confirmed_metadata_only", "no_action"}
    )

    def __post_init__(self) -> None:
        if self.status not in self.STATUSES:
            raise AdaptiveIntelligenceRouterError("unsupported recommendation status")
        if self.status in {"recommended", "needs_human_teaching"}:
            if self.recommended_source not in ADAPTIVE_INTELLIGENCE_SOURCES:
                raise AdaptiveIntelligenceRouterError("a recommendation requires a supported source")
            if isinstance(self.confidence, bool) or not isinstance(self.confidence, (int, float)):
                raise AdaptiveIntelligenceRouterError("a recommendation requires numeric confidence")
            if not 0.0 <= float(self.confidence) <= 1.0:
                raise AdaptiveIntelligenceRouterError("confidence must be between 0.0 and 1.0")
        elif self.recommended_source is not None or self.confidence is not None:
            raise AdaptiveIntelligenceRouterError("unresolved recommendations cannot name a source")
        if self.fallback_source is not None and self.fallback_source not in ADAPTIVE_INTELLIGENCE_SOURCES:
            raise AdaptiveIntelligenceRouterError("fallback_source must be a supported source")
        if self.fallback_source is not None and self.fallback_source == self.recommended_source:
            raise AdaptiveIntelligenceRouterError("fallback_source must differ from recommended_source")
        if not self.reason_codes or any(code not in ADAPTIVE_ROUTER_REASON_CODES for code in self.reason_codes):
            raise AdaptiveIntelligenceRouterError("reason_codes must use the fixed router taxonomy")
        if not isinstance(self.requires_confirmation, bool):
            raise AdaptiveIntelligenceRouterError("requires_confirmation must be boolean")
        if self.privacy_boundary not in self.PRIVACY_BOUNDARIES:
            raise AdaptiveIntelligenceRouterError("unsupported privacy_boundary")

    def summary(self) -> dict[str, Any]:
        """Return the public TEST-30 recommendation contract."""

        return {
            "adaptive_intelligence_router_version": ADAPTIVE_INTELLIGENCE_ROUTER_VERSION,
            "status": self.status,
            "recommended_source": self.recommended_source,
            "confidence": None if self.confidence is None else float(self.confidence),
            "reason_codes": list(self.reason_codes),
            "fallback_source": self.fallback_source,
            "requires_confirmation": self.requires_confirmation,
            "privacy_boundary": self.privacy_boundary,
        }


class AdaptiveIntelligenceRouter:
    """Recommend a bounded intelligence source from sanitized metadata only."""

    SOURCES = ADAPTIVE_INTELLIGENCE_SOURCES
    MIN_RELIABLE_SUCCESS = 0.75
    MIN_CONTEXT_CONFIDENCE = 0.60
    SUCCESS_EQUIVALENCE = 0.05
    SOURCE_PRIORITY = {
        "deterministic_capability": 0,
        "learned_skill": 1,
        "learned_workflow": 2,
        "native_shortcut": 3,
        "local_model": 4,
        "hybrid_model": 5,
        "cloud_model": 6,
    }
    LATENCY_PRIORITY = {"fast": 0, "standard": 1, "slow": 2}
    COST_PRIORITY = {"none": 0, "low": 1, "medium": 2, "high": 3}
    CLOUD_SOURCES = frozenset({"hybrid_model", "cloud_model"})
    LEARNED_SOURCES = frozenset({"learned_workflow", "learned_skill"})

    def recommend(
        self,
        solution_evaluation: SolutionEvaluation,
        request: IntelligenceRoutingRequest,
    ) -> IntelligencePathRecommendation:
        """Return one advisory path without retaining or invoking either input."""

        if not isinstance(solution_evaluation, SolutionEvaluation):
            raise AdaptiveIntelligenceRouterError("solution_evaluation must be a SolutionEvaluation")
        if not isinstance(request, IntelligenceRoutingRequest):
            raise AdaptiveIntelligenceRouterError("request must be an IntelligenceRoutingRequest")
        if request.trust_tier == "critical":
            return IntelligencePathRecommendation(
                status="blocked",
                recommended_source=None,
                confidence=None,
                reason_codes=("critical_action_blocked",),
                fallback_source=None,
                requires_confirmation=True,
                privacy_boundary="no_action",
            )

        eligible, eligibility_reasons = self._eligible_profiles(solution_evaluation, request)
        teaching_profile = next(
            (
                profile
                for profile in request.source_profiles
                if profile.source == "human_teaching_request" and profile.available and request.teaching_available
            ),
            None,
        )
        reliable = [profile for profile in eligible if self._is_reliable(profile, request)]
        if teaching_profile is not None and self._should_recommend_teaching(solution_evaluation, request, reliable):
            fallback = self._best_source(eligible, request)
            return IntelligencePathRecommendation(
                status="needs_human_teaching",
                recommended_source="human_teaching_request",
                confidence=round(float(request.aggregate_confidence), 6),
                reason_codes=self._teaching_reasons(solution_evaluation, request),
                fallback_source=None if fallback is None else fallback.source,
                requires_confirmation=True,
                privacy_boundary="owner_confirmed_metadata_only",
            )
        if not eligible:
            reason = "no_eligible_source"
            if "privacy_cloud_blocked" in eligibility_reasons:
                reason = "privacy_cloud_blocked"
            return IntelligencePathRecommendation(
                status="blocked",
                recommended_source=None,
                confidence=None,
                reason_codes=(reason,),
                fallback_source=None,
                requires_confirmation=True,
                privacy_boundary="no_action",
            )

        selected = self._best_source(eligible, request)
        if selected is None:
            return IntelligencePathRecommendation(
                status="ambiguous",
                recommended_source=None,
                confidence=None,
                reason_codes=("unresolved_equivalent_sources",),
                fallback_source=None,
                requires_confirmation=True,
                privacy_boundary="no_action",
            )
        fallback = self._best_source(tuple(profile for profile in eligible if profile != selected), request)
        confidence = min(float(request.aggregate_confidence), float(selected.predicted_success))
        confirmation = request.trust_tier != "low" or request.risk_level != "read_only"
        reasons = ["predicted_success_highest"]
        if selected.evidence.success_count + selected.evidence.failure_count:
            reasons.append("historical_evidence_applied")
        if confirmation:
            reasons.append("trust_requires_confirmation")
        else:
            reasons.append("trust_pre_authorized")
        if selected.source == "deterministic_capability":
            reasons.insert(0, "solution_recommended")
            reasons.insert(
                1,
                "deterministic_limited_trial"
                if request.limited_trial and not self._has_verified_evidence(selected.evidence)
                else "deterministic_evidence_verified",
            )
        if selected.source in self.LEARNED_SOURCES:
            reasons.insert(0, "learned_evidence_verified")
        return IntelligencePathRecommendation(
            status="recommended",
            recommended_source=selected.source,
            confidence=round(confidence, 6),
            reason_codes=tuple(reasons),
            fallback_source=None if fallback is None else fallback.source,
            requires_confirmation=confirmation,
            privacy_boundary=(
                "cloud_minimum_context" if selected.source in self.CLOUD_SOURCES else "local_only"
            ),
        )

    def _eligible_profiles(
        self,
        solution_evaluation: SolutionEvaluation,
        request: IntelligenceRoutingRequest,
    ) -> tuple[tuple[IntelligenceSourceProfile, ...], tuple[str, ...]]:
        eligible: list[IntelligenceSourceProfile] = []
        reasons: list[str] = []
        for profile in request.source_profiles:
            if profile.source == "human_teaching_request":
                continue
            if not profile.available:
                reasons.append("source_unavailable")
                continue
            if profile.source == "deterministic_capability":
                if solution_evaluation.status != "recommended":
                    reasons.append("solution_not_recommended")
                    continue
                if not self._has_verified_evidence(profile.evidence) and not request.limited_trial:
                    reasons.append("deterministic_evidence_insufficient")
                    continue
            if profile.source in self.LEARNED_SOURCES and not self._has_verified_evidence(profile.evidence):
                reasons.append("learned_evidence_insufficient")
                continue
            if profile.source in self.CLOUD_SOURCES and request.privacy_class != "cloud_approved":
                reasons.append("privacy_cloud_blocked")
                continue
            eligible.append(profile)
        return tuple(eligible), tuple(reasons)

    def _should_recommend_teaching(
        self,
        solution_evaluation: SolutionEvaluation,
        request: IntelligenceRoutingRequest,
        reliable: list[IntelligenceSourceProfile],
    ) -> bool:
        return not reliable and (
            solution_evaluation.status != "recommended"
            or float(request.aggregate_confidence) < self.MIN_CONTEXT_CONFIDENCE
            or request.task_repeatability == "likely"
            or request.preference == "prefer_teaching"
        )

    def _teaching_reasons(
        self,
        solution_evaluation: SolutionEvaluation,
        request: IntelligenceRoutingRequest,
    ) -> tuple[str, ...]:
        reasons = ["teaching_available", "no_reliable_existing_capability"]
        if solution_evaluation.status != "recommended":
            reasons.append("solution_not_recommended")
        if float(request.aggregate_confidence) < self.MIN_CONTEXT_CONFIDENCE:
            reasons.append("low_confidence")
        if request.task_repeatability == "likely":
            reasons.append("task_repeatable")
        return tuple(reasons)

    def _best_source(
        self,
        profiles: tuple[IntelligenceSourceProfile, ...] | list[IntelligenceSourceProfile],
        request: IntelligenceRoutingRequest,
    ) -> IntelligenceSourceProfile | None:
        if not profiles:
            return None
        top_success = max(float(profile.predicted_success) for profile in profiles)
        materially_equivalent = [
            profile
            for profile in profiles
            if top_success - float(profile.predicted_success) <= self.SUCCESS_EQUIVALENCE
        ]
        return min(
            materially_equivalent,
            key=lambda profile: (
                self._preference_priority(profile.source, request.preference),
                self.SOURCE_PRIORITY[profile.source],
                self.LATENCY_PRIORITY[profile.latency_class],
                self.COST_PRIORITY[profile.cost_class],
            ),
        )

    def _preference_priority(self, source: str, preference: str) -> int:
        if preference == "prefer_local" and source == "local_model":
            return -1
        if preference == "prefer_cloud" and source in self.CLOUD_SOURCES:
            return -1
        return 0

    @classmethod
    def _has_verified_evidence(cls, evidence: CapabilityEvidence) -> bool:
        return (
            evidence.success_count >= 1
            and evidence.last_verified is not None
            and float(evidence.confidence) >= cls.MIN_CONTEXT_CONFIDENCE
        )

    def _is_reliable(self, profile: IntelligenceSourceProfile, request: IntelligenceRoutingRequest) -> bool:
        return (
            float(request.aggregate_confidence) >= self.MIN_CONTEXT_CONFIDENCE
            and float(profile.predicted_success) >= self.MIN_RELIABLE_SUCCESS
        )


class IntelligenceOrchestrationError(ValueError):
    """A TEST-41 advisory orchestration request violates its safe contract."""


INTELLIGENCE_ORCHESTRATION_VERSION = "test-41.0"


@dataclass(frozen=True)
class TaskClassification:
    """A deterministic classification of an existing bounded intent kind.

    This object deliberately records only an allow-listed intent kind and a
    semantic task class.  It never accepts or returns the raw user goal, query,
    prompt, document, or screen content that originally produced the intent.
    """

    intent_kind: str
    task_class: str
    confidence: float
    status: str
    reason_codes: tuple[str, ...]

    TASK_CLASSES = frozenset(
        {
            "information_retrieval",
            "reasoning",
            "translation",
            "vision_understanding",
            "device_operation",
            "planning",
            "learning",
            "business_knowledge",
            "automation",
            "unknown",
        }
    )
    STATUSES = frozenset({"classified", "needs_clarification"})
    REASON_CODES = frozenset({"intent_mapping", "unsupported_intent"})

    def __post_init__(self) -> None:
        if not isinstance(self.intent_kind, str) or not self.intent_kind:
            raise IntelligenceOrchestrationError("intent_kind must be a non-empty bounded label")
        if self.task_class not in self.TASK_CLASSES:
            raise IntelligenceOrchestrationError("unsupported task_class")
        if isinstance(self.confidence, bool) or not isinstance(self.confidence, (int, float)):
            raise IntelligenceOrchestrationError("classification confidence must be numeric")
        if not 0.0 <= float(self.confidence) <= 1.0:
            raise IntelligenceOrchestrationError("classification confidence must be between 0.0 and 1.0")
        if self.status not in self.STATUSES:
            raise IntelligenceOrchestrationError("unsupported classification status")
        if not self.reason_codes or any(code not in self.REASON_CODES for code in self.reason_codes):
            raise IntelligenceOrchestrationError("classification reason_codes must use the fixed taxonomy")
        if self.status == "classified" and self.task_class == "unknown":
            raise IntelligenceOrchestrationError("unknown task_class requires clarification")
        if self.status == "needs_clarification" and self.task_class != "unknown":
            raise IntelligenceOrchestrationError("clarification status requires unknown task_class")

    def summary(self) -> dict[str, Any]:
        return {
            "intent_kind": self.intent_kind,
            "task_class": self.task_class,
            "confidence": float(self.confidence),
            "status": self.status,
            "reason_codes": list(self.reason_codes),
        }


class TaskClassifier:
    """Classify only declared intent labels; raw goal parsing stays upstream."""

    INTENT_TASK_CLASSES = {
        "observe": "information_retrieval",
        "verify_visible": "information_retrieval",
        "search_current": "device_operation",
        "map_link": "device_operation",
        "launch_installed_app": "device_operation",
        "reason": "reasoning",
        "translate": "translation",
        "vision_understand": "vision_understanding",
        "plan": "planning",
        "learn": "learning",
        "knowledge_query": "business_knowledge",
        "automation_request": "automation",
    }

    def classify(self, intent_kind: str) -> TaskClassification:
        if not isinstance(intent_kind, str) or not intent_kind or len(intent_kind) > 128:
            raise IntelligenceOrchestrationError("intent_kind must be a non-empty bounded label")
        task_class = self.INTENT_TASK_CLASSES.get(intent_kind)
        if task_class is None:
            return TaskClassification(
                # Never echo an arbitrary caller label. This keeps the advisory
                # contract safe even if a caller incorrectly passes user text.
                intent_kind="unknown",
                task_class="unknown",
                confidence=0.0,
                status="needs_clarification",
                reason_codes=("unsupported_intent",),
            )
        return TaskClassification(
            intent_kind=intent_kind,
            task_class=task_class,
            confidence=1.0,
            status="classified",
            reason_codes=("intent_mapping",),
        )


@dataclass(frozen=True)
class SkillAdvisoryProfile:
    """A governed Skill compatibility profile with no runtime selection power."""

    manifest: SkillManifest
    supported_task_classes: tuple[str, ...]
    predicted_success: float
    available: bool = True

    def __post_init__(self) -> None:
        if not isinstance(self.manifest, SkillManifest):
            raise IntelligenceOrchestrationError("manifest must be a SkillManifest")
        if not self.supported_task_classes or any(
            task_class not in TaskClassification.TASK_CLASSES.difference({"unknown"})
            for task_class in self.supported_task_classes
        ):
            raise IntelligenceOrchestrationError("supported_task_classes must contain supported classes")
        if len(self.supported_task_classes) != len(set(self.supported_task_classes)):
            raise IntelligenceOrchestrationError("supported_task_classes cannot contain duplicates")
        if isinstance(self.predicted_success, bool) or not isinstance(self.predicted_success, (int, float)):
            raise IntelligenceOrchestrationError("predicted_success must be numeric")
        if not 0.0 <= float(self.predicted_success) <= 1.0:
            raise IntelligenceOrchestrationError("predicted_success must be between 0.0 and 1.0")
        if not isinstance(self.available, bool):
            raise IntelligenceOrchestrationError("available must be boolean")


class SkillAdvisoryRanker:
    """Rank manifest metadata for Planner review without selecting a runtime Skill."""

    def recommend(
        self,
        task_classification: TaskClassification,
        solution_evaluation: SolutionEvaluation,
        profiles: tuple[SkillAdvisoryProfile, ...],
    ) -> dict[str, Any]:
        if not isinstance(task_classification, TaskClassification):
            raise IntelligenceOrchestrationError("task_classification must use TaskClassification")
        if not isinstance(solution_evaluation, SolutionEvaluation):
            raise IntelligenceOrchestrationError("solution_evaluation must use SolutionEvaluation")
        if any(not isinstance(profile, SkillAdvisoryProfile) for profile in profiles):
            raise IntelligenceOrchestrationError("skill profiles must use SkillAdvisoryProfile")
        selected_capability = solution_evaluation.recommended_capability_id
        candidates = []
        for profile in profiles:
            manifest = profile.manifest
            eligible = (
                profile.available
                and manifest.lifecycle == "ACTIVE"
                and manifest.verification_status == "device_pass"
                and task_classification.task_class in profile.supported_task_classes
                and (selected_capability is None or selected_capability in manifest.required_capabilities)
            )
            reasons = []
            if not profile.available:
                reasons.append("skill_unavailable")
            if manifest.lifecycle != "ACTIVE":
                reasons.append("skill_not_active")
            if manifest.verification_status != "device_pass":
                reasons.append("skill_not_device_verified")
            if task_classification.task_class not in profile.supported_task_classes:
                reasons.append("task_class_not_supported")
            if selected_capability is not None and selected_capability not in manifest.required_capabilities:
                reasons.append("capability_not_declared")
            evidence = manifest.evidence
            attempts = evidence.success_count + evidence.failure_count
            success_rate = evidence.success_count / attempts if attempts else 0.0
            score = None
            if eligible:
                score = round(
                    (0.55 * float(profile.predicted_success))
                    + (0.30 * float(evidence.confidence))
                    + (0.15 * success_rate),
                    6,
                )
                reasons.append("governed_skill_metadata_eligible")
            candidates.append(
                {
                    "skill_id": manifest.skill_id,
                    "version": manifest.version,
                    "domain": manifest.domain,
                    "lifecycle": manifest.lifecycle,
                    "verification_status": manifest.verification_status,
                    "eligible": eligible,
                    "score": score,
                    "reason_codes": reasons,
                }
            )
        eligible = sorted(
            (candidate for candidate in candidates if candidate["eligible"]),
            key=lambda candidate: (-float(candidate["score"] or 0.0), str(candidate["skill_id"])),
        )
        return {
            "status": "recommended" if eligible else "no_eligible_skill_profiles",
            "recommended_skill": eligible[0] if eligible else None,
            "candidates": candidates,
            "reason_codes": ["planner_must_select_runtime_skill"],
            "next_gate": "planner_skill_registry",
            "selection_authority": "none",
        }


@dataclass(frozen=True)
class IntelligenceCapabilityProfile:
    """A declared intelligence option without a model/provider/action handle."""

    profile_id: str
    source_kind: str
    available: bool
    predicted_success: float
    latency_class: str
    cost_class: str
    offline_available: bool
    allowed_privacy_classes: tuple[str, ...]
    estimated_token_upper_bound: int
    evidence: CapabilityEvidence = CapabilityEvidence()

    SOURCE_KINDS = frozenset(
        {
            "local_rule",
            "private_knowledge",
            "deterministic_capability",
            "native_shortcut",
            "learned_workflow",
            "learned_skill",
            "local_small_model",
            "local_large_model",
            "human_teaching_request",
            "hybrid_model",
            "cloud_model",
        }
    )
    PRIVACY_CLASSES = frozenset({"public_metadata", "personal", "business", "customer", "sensitive"})
    ROUTER_SOURCE = {
        "local_rule": "deterministic_capability",
        "private_knowledge": "deterministic_capability",
        "deterministic_capability": "deterministic_capability",
        "native_shortcut": "native_shortcut",
        "learned_workflow": "learned_workflow",
        "learned_skill": "learned_skill",
        "local_small_model": "local_model",
        "local_large_model": "local_model",
        "human_teaching_request": "human_teaching_request",
        "hybrid_model": "hybrid_model",
        "cloud_model": "cloud_model",
    }

    def __post_init__(self) -> None:
        if not isinstance(self.profile_id, str) or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(self.profile_id):
            raise IntelligenceOrchestrationError("profile_id must be a stable metadata label")
        if self.source_kind not in self.SOURCE_KINDS:
            raise IntelligenceOrchestrationError("unsupported intelligence profile source_kind")
        if not isinstance(self.available, bool) or not isinstance(self.offline_available, bool):
            raise IntelligenceOrchestrationError("availability values must be boolean")
        if isinstance(self.predicted_success, bool) or not isinstance(self.predicted_success, (int, float)):
            raise IntelligenceOrchestrationError("predicted_success must be numeric")
        if not 0.0 <= float(self.predicted_success) <= 1.0:
            raise IntelligenceOrchestrationError("predicted_success must be between 0.0 and 1.0")
        if self.latency_class not in IntelligenceSourceProfile.LATENCY_CLASSES:
            raise IntelligenceOrchestrationError("unsupported profile latency_class")
        if self.cost_class not in IntelligenceSourceProfile.COST_CLASSES:
            raise IntelligenceOrchestrationError("unsupported profile cost_class")
        if not self.allowed_privacy_classes or any(
            privacy_class not in self.PRIVACY_CLASSES for privacy_class in self.allowed_privacy_classes
        ):
            raise IntelligenceOrchestrationError("allowed_privacy_classes must be supported")
        if len(self.allowed_privacy_classes) != len(set(self.allowed_privacy_classes)):
            raise IntelligenceOrchestrationError("allowed_privacy_classes cannot contain duplicates")
        if isinstance(self.estimated_token_upper_bound, bool) or not isinstance(self.estimated_token_upper_bound, int):
            raise IntelligenceOrchestrationError("estimated_token_upper_bound must be an integer")
        if not 0 <= self.estimated_token_upper_bound <= 1_000_000:
            raise IntelligenceOrchestrationError("estimated_token_upper_bound is outside the bounded range")
        if not isinstance(self.evidence, CapabilityEvidence):
            raise IntelligenceOrchestrationError("profile evidence must use CapabilityEvidence")

    @property
    def router_source(self) -> str:
        return self.ROUTER_SOURCE[self.source_kind]

    def summary(self) -> dict[str, Any]:
        return {
            "profile_id": self.profile_id,
            "source_kind": self.source_kind,
            "router_source": self.router_source,
            "available": self.available,
            "offline_available": self.offline_available,
            "predicted_success": float(self.predicted_success),
            "latency_class": self.latency_class,
            "cost_class": self.cost_class,
            "allowed_privacy_classes": list(self.allowed_privacy_classes),
            "estimated_token_upper_bound": self.estimated_token_upper_bound,
            "evidence": self.evidence.summary(),
        }


@dataclass(frozen=True)
class PrivacyRoutingDecision:
    """Safe routing metadata derived from existing permission eligibility."""

    data_class: str
    permission_eligible: bool
    cloud_eligible: bool
    reason_codes: tuple[str, ...]

    REASON_CODES = frozenset({"permission_denied", "public_cloud_candidate", "local_only_data_class"})

    def __post_init__(self) -> None:
        if self.data_class not in IntelligenceCapabilityProfile.PRIVACY_CLASSES:
            raise IntelligenceOrchestrationError("unsupported data_class")
        if not isinstance(self.permission_eligible, bool) or not isinstance(self.cloud_eligible, bool):
            raise IntelligenceOrchestrationError("privacy eligibility values must be boolean")
        if not self.reason_codes or any(code not in self.REASON_CODES for code in self.reason_codes):
            raise IntelligenceOrchestrationError("privacy reason_codes must use the fixed taxonomy")

    def summary(self) -> dict[str, Any]:
        return {
            "data_class": self.data_class,
            "permission_eligible": self.permission_eligible,
            "cloud_eligible": self.cloud_eligible,
            "reason_codes": list(self.reason_codes),
        }


class PrivacyRoutingAdapter:
    """Convert an existing PermissionDecision to a cloud-eligibility boundary."""

    def evaluate(self, decision: PermissionDecision, *, data_class: str) -> PrivacyRoutingDecision:
        if not isinstance(decision, PermissionDecision):
            raise IntelligenceOrchestrationError("permission decision must use PermissionDecision")
        if data_class not in IntelligenceCapabilityProfile.PRIVACY_CLASSES:
            raise IntelligenceOrchestrationError("unsupported data_class")
        if not decision.eligible:
            return PrivacyRoutingDecision(data_class, False, False, ("permission_denied",))
        if data_class == "public_metadata":
            return PrivacyRoutingDecision(data_class, True, True, ("public_cloud_candidate",))
        return PrivacyRoutingDecision(data_class, True, False, ("local_only_data_class",))


@dataclass(frozen=True)
class TokenBudgetPolicy:
    """A declared upper bound, not telemetry from a live model request."""

    maximum_estimated_tokens: int
    maximum_cost_class: str

    def __post_init__(self) -> None:
        if isinstance(self.maximum_estimated_tokens, bool) or not isinstance(self.maximum_estimated_tokens, int):
            raise IntelligenceOrchestrationError("maximum_estimated_tokens must be an integer")
        if not 0 <= self.maximum_estimated_tokens <= 1_000_000:
            raise IntelligenceOrchestrationError("maximum_estimated_tokens is outside the bounded range")
        if self.maximum_cost_class not in IntelligenceSourceProfile.COST_CLASSES:
            raise IntelligenceOrchestrationError("unsupported maximum_cost_class")


@dataclass(frozen=True)
class CloudApprovalRequest:
    """A provider-neutral request for explicit human approval; it cannot call cloud AI."""

    status: str
    profile_id: str
    reason_codes: tuple[str, ...]
    privacy_class: str
    estimated_token_upper_bound: int
    estimated_cost_class: str
    fallback_source: str | None

    STATUSES = frozenset({"pending_approval", "blocked_by_privacy", "blocked_by_budget"})
    REASON_CODES = frozenset(
        {
            "local_capability_insufficient",
            "local_confidence_low",
            "task_complexity_high",
            "predicted_success_improvement",
            "privacy_public_metadata_only",
            "budget_exceeded",
        }
    )

    def __post_init__(self) -> None:
        if self.status not in self.STATUSES:
            raise IntelligenceOrchestrationError("unsupported cloud approval status")
        if not isinstance(self.profile_id, str) or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(self.profile_id):
            raise IntelligenceOrchestrationError("cloud approval profile_id must be a metadata label")
        if not self.reason_codes or any(code not in self.REASON_CODES for code in self.reason_codes):
            raise IntelligenceOrchestrationError("cloud approval reason_codes must use the fixed taxonomy")
        if self.privacy_class not in IntelligenceCapabilityProfile.PRIVACY_CLASSES:
            raise IntelligenceOrchestrationError("unsupported cloud approval privacy_class")
        if isinstance(self.estimated_token_upper_bound, bool) or not isinstance(self.estimated_token_upper_bound, int):
            raise IntelligenceOrchestrationError("cloud approval token bound must be an integer")
        if self.estimated_token_upper_bound < 0:
            raise IntelligenceOrchestrationError("cloud approval token bound cannot be negative")
        if self.estimated_cost_class not in IntelligenceSourceProfile.COST_CLASSES:
            raise IntelligenceOrchestrationError("unsupported cloud approval cost class")
        if self.fallback_source is not None and self.fallback_source not in ADAPTIVE_INTELLIGENCE_SOURCES:
            raise IntelligenceOrchestrationError("unsupported cloud approval fallback source")

    def summary(self) -> dict[str, Any]:
        return {
            "status": self.status,
            "profile_id": self.profile_id,
            "reason_codes": list(self.reason_codes),
            "privacy_class": self.privacy_class,
            "estimated_token_upper_bound": self.estimated_token_upper_bound,
            "estimated_cost_class": self.estimated_cost_class,
            "fallback_source": self.fallback_source,
            "allowed_user_decisions": ["approve_once", "decline", "teach"],
            "provider_call_authority": "none",
        }


@dataclass(frozen=True)
class IntelligenceOrchestrationRequest:
    """Sanitized metadata consumed by TEST-41 without persistence or action authority."""

    intent_kind: str
    capability_evaluation: CapabilityEvaluation
    permission_decision: PermissionDecision
    available_permissions: tuple[str, ...]
    available_platforms: tuple[str, ...]
    task_complexity: str
    aggregate_confidence: float
    risk_level: str
    task_repeatability: str
    trust_tier: str
    preference: str
    teaching_available: bool
    data_class: str
    offline_mode: bool
    token_budget: TokenBudgetPolicy
    intelligence_profiles: tuple[IntelligenceCapabilityProfile, ...]
    skill_profiles: tuple[SkillAdvisoryProfile, ...] = ()
    limited_trial_approval_id: str | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.intent_kind, str) or not self.intent_kind or len(self.intent_kind) > 128:
            raise IntelligenceOrchestrationError("intent_kind must be a non-empty bounded label")
        if not isinstance(self.capability_evaluation, CapabilityEvaluation):
            raise IntelligenceOrchestrationError("capability_evaluation must use CapabilityEvaluation")
        if not isinstance(self.permission_decision, PermissionDecision):
            raise IntelligenceOrchestrationError("permission_decision must use PermissionDecision")
        CapabilityEvaluator._metadata_set(self.available_permissions, "available_permissions")
        CapabilityEvaluator._metadata_set(self.available_platforms, "available_platforms")
        if self.task_complexity not in IntelligenceRoutingRequest.COMPLEXITIES:
            raise IntelligenceOrchestrationError("unsupported task_complexity")
        if isinstance(self.aggregate_confidence, bool) or not isinstance(self.aggregate_confidence, (int, float)):
            raise IntelligenceOrchestrationError("aggregate_confidence must be numeric")
        if not 0.0 <= float(self.aggregate_confidence) <= 1.0:
            raise IntelligenceOrchestrationError("aggregate_confidence must be between 0.0 and 1.0")
        if self.risk_level not in SkillRegistry.RISK_LEVELS:
            raise IntelligenceOrchestrationError("unsupported risk_level")
        if self.task_repeatability not in IntelligenceRoutingRequest.REPEATABILITY:
            raise IntelligenceOrchestrationError("unsupported task_repeatability")
        if self.trust_tier not in IntelligenceRoutingRequest.TRUST_TIERS:
            raise IntelligenceOrchestrationError("unsupported trust_tier")
        if self.preference not in IntelligenceRoutingRequest.PREFERENCES:
            raise IntelligenceOrchestrationError("unsupported preference")
        if not isinstance(self.teaching_available, bool) or not isinstance(self.offline_mode, bool):
            raise IntelligenceOrchestrationError("teaching_available and offline_mode must be boolean")
        if self.data_class not in IntelligenceCapabilityProfile.PRIVACY_CLASSES:
            raise IntelligenceOrchestrationError("unsupported data_class")
        if not isinstance(self.token_budget, TokenBudgetPolicy):
            raise IntelligenceOrchestrationError("token_budget must use TokenBudgetPolicy")
        if not self.intelligence_profiles or any(
            not isinstance(profile, IntelligenceCapabilityProfile) for profile in self.intelligence_profiles
        ):
            raise IntelligenceOrchestrationError("intelligence_profiles must contain IntelligenceCapabilityProfile values")
        if len({profile.profile_id for profile in self.intelligence_profiles}) != len(self.intelligence_profiles):
            raise IntelligenceOrchestrationError("intelligence profile identifiers must be unique")
        if any(not isinstance(profile, SkillAdvisoryProfile) for profile in self.skill_profiles):
            raise IntelligenceOrchestrationError("skill_profiles must use SkillAdvisoryProfile")
        if self.limited_trial_approval_id is not None and (
            not isinstance(self.limited_trial_approval_id, str)
            or not CapabilityCatalog.METADATA_LABEL_PATTERN.fullmatch(self.limited_trial_approval_id)
        ):
            raise IntelligenceOrchestrationError("limited_trial_approval_id must be an opaque metadata label")


@dataclass(frozen=True)
class IntelligenceOrchestrationRecommendation:
    """Privacy-safe TEST-41 result that cannot perform planning or execution."""

    status: str
    task_classification: TaskClassification
    privacy: PrivacyRoutingDecision
    solution_evaluation: dict[str, Any] | None
    skill_advisory: dict[str, Any] | None
    method_advisory: dict[str, Any] | None
    intelligence_path: dict[str, Any] | None
    cloud_approval: CloudApprovalRequest | None
    reason_codes: tuple[str, ...]

    STATUSES = frozenset(
        {"recommended", "blocked", "needs_clarification", "offline_limited", "needs_human_teaching", "needs_cloud_approval"}
    )
    REASON_CODES = frozenset(
        {
            "permission_denied",
            "unknown_task_requires_clarification",
            "no_eligible_capability",
            "offline_no_eligible_source",
            "human_teaching_recommended",
            "cloud_approval_required",
            "orchestration_recommended",
        }
    )

    def __post_init__(self) -> None:
        if self.status not in self.STATUSES:
            raise IntelligenceOrchestrationError("unsupported orchestration status")
        if not isinstance(self.task_classification, TaskClassification):
            raise IntelligenceOrchestrationError("task_classification must use TaskClassification")
        if not isinstance(self.privacy, PrivacyRoutingDecision):
            raise IntelligenceOrchestrationError("privacy must use PrivacyRoutingDecision")
        if not self.reason_codes or any(code not in self.REASON_CODES for code in self.reason_codes):
            raise IntelligenceOrchestrationError("orchestration reason_codes must use the fixed taxonomy")
        if self.status == "needs_cloud_approval" and self.cloud_approval is None:
            raise IntelligenceOrchestrationError("cloud approval status requires CloudApprovalRequest")

    def summary(self) -> dict[str, Any]:
        return {
            "intelligence_orchestration_version": INTELLIGENCE_ORCHESTRATION_VERSION,
            "status": self.status,
            "task_classification": self.task_classification.summary(),
            "privacy": self.privacy.summary(),
            "solution_evaluation": self.solution_evaluation,
            "skill_advisory": self.skill_advisory,
            "method_advisory": self.method_advisory,
            "intelligence_path": self.intelligence_path,
            "cloud_approval": None if self.cloud_approval is None else self.cloud_approval.summary(),
            "reason_codes": list(self.reason_codes),
            "next_gate": "planner_risk_executor_verifier",
            "execution_authority": "none",
        }


class IntelligenceOrchestrationLayer:
    """Compose existing read-only intelligence results without executing any path.

    The class has no model/provider client, MCP client, Planner, Risk Controller,
    Executor, Verifier, Skill Registry, persistent store, Shortcut runner, or
    App Intent adapter. Its recommendation remains advisory until the existing
    runtime re-observes, plans, authorizes, executes, and verifies.
    """

    CLOUD_ROUTER_SOURCES = frozenset({"hybrid_model", "cloud_model"})

    def __init__(
        self,
        method_registry: CapabilityMethodRegistry,
        *,
        solution_layer: SolutionEvaluationLayer | None = None,
        adaptive_router: AdaptiveIntelligenceRouter | None = None,
        task_classifier: TaskClassifier | None = None,
        privacy_adapter: PrivacyRoutingAdapter | None = None,
        skill_ranker: SkillAdvisoryRanker | None = None,
    ) -> None:
        if not isinstance(method_registry, CapabilityMethodRegistry):
            raise IntelligenceOrchestrationError("method_registry must use CapabilityMethodRegistry")
        self._method_registry = method_registry
        self._solution_layer = solution_layer if solution_layer is not None else SolutionEvaluationLayer()
        self._adaptive_router = adaptive_router if adaptive_router is not None else AdaptiveIntelligenceRouter()
        self._task_classifier = task_classifier if task_classifier is not None else TaskClassifier()
        self._privacy_adapter = privacy_adapter if privacy_adapter is not None else PrivacyRoutingAdapter()
        self._skill_ranker = skill_ranker if skill_ranker is not None else SkillAdvisoryRanker()
        if not isinstance(self._solution_layer, SolutionEvaluationLayer):
            raise IntelligenceOrchestrationError("solution_layer must use SolutionEvaluationLayer")
        if not isinstance(self._adaptive_router, AdaptiveIntelligenceRouter):
            raise IntelligenceOrchestrationError("adaptive_router must use AdaptiveIntelligenceRouter")

    def recommend(self, request: IntelligenceOrchestrationRequest) -> IntelligenceOrchestrationRecommendation:
        """Return a recommendation from declared metadata without retaining or invoking it."""

        if not isinstance(request, IntelligenceOrchestrationRequest):
            raise IntelligenceOrchestrationError("request must use IntelligenceOrchestrationRequest")
        classification = self._task_classifier.classify(request.intent_kind)
        privacy = self._privacy_adapter.evaluate(request.permission_decision, data_class=request.data_class)
        if not privacy.permission_eligible:
            return IntelligenceOrchestrationRecommendation(
                "blocked", classification, privacy, None, None, None, None, None, ("permission_denied",)
            )
        if classification.status == "needs_clarification":
            return IntelligenceOrchestrationRecommendation(
                "needs_clarification",
                classification,
                privacy,
                None,
                None,
                None,
                None,
                None,
                ("unknown_task_requires_clarification",),
            )
        solution = self._solution_layer.evaluate_candidates(request.capability_evaluation)
        solution_summary = solution.summary()
        if solution.recommended_capability_id is None:
            return IntelligenceOrchestrationRecommendation(
                "blocked",
                classification,
                privacy,
                solution_summary,
                None,
                None,
                None,
                None,
                ("no_eligible_capability",),
            )
        skill_advisory = self._skill_ranker.recommend(classification, solution, request.skill_profiles)
        if request.limited_trial_approval_id is None:
            method_advisory = self._method_registry.recommend(
                solution.recommended_capability_id,
                available_permissions=request.available_permissions,
                available_platforms=request.available_platforms,
            )
        else:
            method_advisory = self._method_registry.recommend_limited_trial(
                solution.recommended_capability_id,
                available_permissions=request.available_permissions,
                available_platforms=request.available_platforms,
                trial_approval_id=request.limited_trial_approval_id,
            )
        routed_profiles = self._eligible_profiles(request, privacy)
        if not routed_profiles:
            return IntelligenceOrchestrationRecommendation(
                "offline_limited" if request.offline_mode else "blocked",
                classification,
                privacy,
                solution_summary,
                skill_advisory,
                method_advisory,
                None,
                None,
                ("offline_no_eligible_source" if request.offline_mode else "no_eligible_capability",),
            )
        router_request, profile_by_router_source = self._router_request(request, privacy, routed_profiles)
        path = self._adaptive_router.recommend(solution, router_request)
        path_summary = path.summary()
        if path.status == "needs_human_teaching":
            return IntelligenceOrchestrationRecommendation(
                "needs_human_teaching",
                classification,
                privacy,
                solution_summary,
                skill_advisory,
                method_advisory,
                path_summary,
                None,
                ("human_teaching_recommended",),
            )
        if path.recommended_source in self.CLOUD_ROUTER_SOURCES:
            profile = profile_by_router_source[path.recommended_source]
            approval = self._cloud_approval(profile, path, request, privacy)
            if approval.status == "pending_approval":
                return IntelligenceOrchestrationRecommendation(
                    "needs_cloud_approval",
                    classification,
                    privacy,
                    solution_summary,
                    skill_advisory,
                    method_advisory,
                    path_summary,
                    approval,
                    ("cloud_approval_required",),
                )
            return IntelligenceOrchestrationRecommendation(
                "blocked",
                classification,
                privacy,
                solution_summary,
                skill_advisory,
                method_advisory,
                path_summary,
                approval,
                ("no_eligible_capability",),
            )
        if path.status != "recommended":
            return IntelligenceOrchestrationRecommendation(
                "blocked",
                classification,
                privacy,
                solution_summary,
                skill_advisory,
                method_advisory,
                path_summary,
                None,
                ("no_eligible_capability",),
            )
        return IntelligenceOrchestrationRecommendation(
            "recommended",
            classification,
            privacy,
            solution_summary,
            skill_advisory,
            method_advisory,
            path_summary,
            None,
            ("orchestration_recommended",),
        )

    @staticmethod
    def _eligible_profiles(
        request: IntelligenceOrchestrationRequest,
        privacy: PrivacyRoutingDecision,
    ) -> tuple[IntelligenceCapabilityProfile, ...]:
        eligible = []
        for profile in request.intelligence_profiles:
            if not profile.available or request.data_class not in profile.allowed_privacy_classes:
                continue
            if request.offline_mode and not profile.offline_available:
                continue
            if profile.router_source in IntelligenceOrchestrationLayer.CLOUD_ROUTER_SOURCES and not privacy.cloud_eligible:
                continue
            if profile.estimated_token_upper_bound > request.token_budget.maximum_estimated_tokens:
                continue
            if IntelligenceOrchestrationLayer._cost_exceeds(profile.cost_class, request.token_budget.maximum_cost_class):
                continue
            eligible.append(profile)
        return tuple(eligible)

    @staticmethod
    def _cost_exceeds(cost_class: str, maximum_cost_class: str) -> bool:
        return AdaptiveIntelligenceRouter.COST_PRIORITY[cost_class] > AdaptiveIntelligenceRouter.COST_PRIORITY[
            maximum_cost_class
        ]

    @staticmethod
    def _router_privacy_class(privacy: PrivacyRoutingDecision) -> str:
        if privacy.cloud_eligible:
            return "cloud_approved"
        if privacy.data_class == "sensitive":
            return "sensitive"
        return "local_only"

    def _router_request(
        self,
        request: IntelligenceOrchestrationRequest,
        privacy: PrivacyRoutingDecision,
        profiles: tuple[IntelligenceCapabilityProfile, ...],
    ) -> tuple[IntelligenceRoutingRequest, dict[str, IntelligenceCapabilityProfile]]:
        grouped: dict[str, list[IntelligenceCapabilityProfile]] = {}
        for profile in profiles:
            grouped.setdefault(profile.router_source, []).append(profile)
        chosen = {
            source: self._best_profile(candidates)
            for source, candidates in grouped.items()
        }
        source_profiles = tuple(
            IntelligenceSourceProfile(
                source=source,
                available=True,
                predicted_success=profile.predicted_success,
                latency_class=profile.latency_class,
                cost_class=profile.cost_class,
                evidence=profile.evidence,
            )
            for source, profile in sorted(chosen.items())
        )
        return (
            IntelligenceRoutingRequest(
                task_complexity=request.task_complexity,
                aggregate_confidence=request.aggregate_confidence,
                risk_level=request.risk_level,
                task_repeatability=request.task_repeatability,
                privacy_class=self._router_privacy_class(privacy),
                trust_tier=request.trust_tier,
                preference=request.preference,
                teaching_available=request.teaching_available,
                source_profiles=source_profiles,
                limited_trial=request.limited_trial_approval_id is not None,
            ),
            chosen,
        )

    @staticmethod
    def _best_profile(profiles: list[IntelligenceCapabilityProfile]) -> IntelligenceCapabilityProfile:
        return min(
            profiles,
            key=lambda profile: (
                -float(profile.predicted_success),
                AdaptiveIntelligenceRouter.LATENCY_PRIORITY[profile.latency_class],
                AdaptiveIntelligenceRouter.COST_PRIORITY[profile.cost_class],
                profile.profile_id,
            ),
        )

    @staticmethod
    def _cloud_approval(
        profile: IntelligenceCapabilityProfile,
        path: IntelligencePathRecommendation,
        request: IntelligenceOrchestrationRequest,
        privacy: PrivacyRoutingDecision,
    ) -> CloudApprovalRequest:
        if not privacy.cloud_eligible:
            return CloudApprovalRequest(
                "blocked_by_privacy",
                profile.profile_id,
                ("privacy_public_metadata_only",),
                request.data_class,
                profile.estimated_token_upper_bound,
                profile.cost_class,
                path.fallback_source,
            )
        if profile.estimated_token_upper_bound > request.token_budget.maximum_estimated_tokens or (
            IntelligenceOrchestrationLayer._cost_exceeds(profile.cost_class, request.token_budget.maximum_cost_class)
        ):
            return CloudApprovalRequest(
                "blocked_by_budget",
                profile.profile_id,
                ("budget_exceeded",),
                request.data_class,
                profile.estimated_token_upper_bound,
                profile.cost_class,
                path.fallback_source,
            )
        reasons = ["predicted_success_improvement", "privacy_public_metadata_only"]
        if request.task_complexity == "high":
            reasons.append("task_complexity_high")
        elif request.aggregate_confidence < AdaptiveIntelligenceRouter.MIN_CONTEXT_CONFIDENCE:
            reasons.append("local_confidence_low")
        else:
            reasons.append("local_capability_insufficient")
        return CloudApprovalRequest(
            "pending_approval",
            profile.profile_id,
            tuple(reasons),
            request.data_class,
            profile.estimated_token_upper_bound,
            profile.cost_class,
            path.fallback_source,
        )


class HumanTeachingPolicyError(ValueError):
    """A TEST-31 teaching request violates the candidate-only contract."""


@dataclass(frozen=True)
class TeachingIntentAssessment:
    """An ephemeral intent classification that never retains user wording."""

    intent: str
    confidence: float
    reason_codes: tuple[str, ...]

    INTENTS = frozenset({"teaching", "normal_request", "ambiguous"})
    REASON_CODES = frozenset(
        {
            "explicit_teaching_marker",
            "explicit_one_time_marker",
            "conflicting_intent_markers",
            "no_teaching_marker",
        }
    )

    def __post_init__(self) -> None:
        if self.intent not in self.INTENTS:
            raise HumanTeachingPolicyError("unsupported teaching intent")
        if isinstance(self.confidence, bool) or not isinstance(self.confidence, (int, float)):
            raise HumanTeachingPolicyError("teaching confidence must be numeric")
        if not 0.0 <= float(self.confidence) <= 1.0:
            raise HumanTeachingPolicyError("teaching confidence must be between 0.0 and 1.0")
        if not self.reason_codes or any(code not in self.REASON_CODES for code in self.reason_codes):
            raise HumanTeachingPolicyError("teaching reasons must use the fixed taxonomy")

    def summary(self) -> dict[str, Any]:
        return {
            "intent": self.intent,
            "confidence": float(self.confidence),
            "reason_codes": list(self.reason_codes),
        }


@dataclass(frozen=True)
class TeachingRuleOutline:
    """A user-confirmable metadata outline, not a captured operation trace."""

    rule_type: str
    candidate_kind: str
    risk_level: str

    RULE_TYPES = frozenset({"reusable_handling", "reusable_workflow", "correction_preference"})
    CANDIDATE_KINDS = frozenset({"local_rule", "skill", "shortcut", "workflow"})
    SUMMARY_CODES = {
        "reusable_handling": "reusable_handling_rule",
        "reusable_workflow": "reusable_workflow_rule",
        "correction_preference": "future_correction_preference",
    }

    def __post_init__(self) -> None:
        if self.rule_type not in self.RULE_TYPES:
            raise HumanTeachingPolicyError("unsupported teaching rule_type")
        if self.candidate_kind not in self.CANDIDATE_KINDS:
            raise HumanTeachingPolicyError("unsupported teaching candidate_kind")
        if self.risk_level not in SkillRegistry.RISK_LEVELS:
            raise HumanTeachingPolicyError("unsupported teaching risk_level")

    def summary(self) -> dict[str, Any]:
        return {
            "rule_type": self.rule_type,
            "summary_code": self.SUMMARY_CODES[self.rule_type],
            "candidate_kind": self.candidate_kind,
            "risk_level": self.risk_level,
        }


@dataclass(frozen=True)
class TeachingProposal:
    """A transient proposal awaiting a specific human confirmation."""

    proposal_id: str
    intent: TeachingIntentAssessment
    outline: TeachingRuleOutline
    status: str

    STATUSES = frozenset({"awaiting_confirmation", "rejected"})

    def __post_init__(self) -> None:
        if not isinstance(self.proposal_id, str) or not self.proposal_id:
            raise HumanTeachingPolicyError("proposal_id must be a non-empty opaque identifier")
        if not isinstance(self.intent, TeachingIntentAssessment) or self.intent.intent != "teaching":
            raise HumanTeachingPolicyError("a teaching proposal requires teaching intent")
        if not isinstance(self.outline, TeachingRuleOutline):
            raise HumanTeachingPolicyError("proposal outline must use TeachingRuleOutline")
        if self.status not in self.STATUSES:
            raise HumanTeachingPolicyError("unsupported teaching proposal status")

    def summary(self) -> dict[str, Any]:
        return {
            "proposal_id": self.proposal_id,
            "status": self.status,
            "intent": self.intent.summary(),
            "rule": self.outline.summary(),
            "requires_explicit_user_confirmation": True,
            "retained": False,
        }


@dataclass(frozen=True)
class TeachingCapabilityCandidate:
    """A metadata-only promotion candidate, never a registered capability."""

    candidate_id: str
    proposal_id: str
    outline: TeachingRuleOutline
    status: str
    confidence: float | None = None

    STATUSES = frozenset({"rejected", "pending_validation", "validated", "validation_failed"})

    def __post_init__(self) -> None:
        if not isinstance(self.candidate_id, str) or not self.candidate_id:
            raise HumanTeachingPolicyError("candidate_id must be a non-empty opaque identifier")
        if not isinstance(self.proposal_id, str) or not self.proposal_id:
            raise HumanTeachingPolicyError("candidate proposal_id must be a non-empty opaque identifier")
        if not isinstance(self.outline, TeachingRuleOutline):
            raise HumanTeachingPolicyError("candidate outline must use TeachingRuleOutline")
        if self.status not in self.STATUSES:
            raise HumanTeachingPolicyError("unsupported teaching candidate status")
        if self.status in {"validated", "validation_failed"}:
            if isinstance(self.confidence, bool) or not isinstance(self.confidence, (int, float)):
                raise HumanTeachingPolicyError("validated candidate requires numeric confidence")
            if not 0.0 <= float(self.confidence) <= 1.0:
                raise HumanTeachingPolicyError("candidate confidence must be between 0.0 and 1.0")
        elif self.confidence is not None:
            raise HumanTeachingPolicyError("unvalidated candidate cannot have confidence")

    def summary(self) -> dict[str, Any]:
        return {
            "candidate_id": self.candidate_id,
            "proposal_id": self.proposal_id,
            "status": self.status,
            "rule": self.outline.summary(),
            "confidence": None if self.confidence is None else float(self.confidence),
            "requires_validation": self.status == "pending_validation",
            "possible_upgrade": self.outline.candidate_kind if self.status == "validated" else None,
            "requires_planner": True,
            "requires_risk_controller": True,
            "requires_executor": True,
            "requires_verifier": True,
        }


class HumanTeachingLayer:
    """Create explicit, private, validator-gated learning candidates.

    TEST-31 accepts one transient user message only for intent classification.
    It neither retains that message nor records raw UI/actions.  A candidate is
    persisted only after explicit confirmation and an external verifier result.
    Promotion is a future proposal, never an automatic Skill, Shortcut,
    Workflow, or local-rule creation step.
    """

    RECORD_TYPE = "teaching_capability_candidate"
    MAX_MESSAGE_CHARACTERS = 4096
    TEACHING_MARKERS = frozenset(
        {
            "以后都这样处理",
            "以后这样处理",
            "记住这个流程",
            "记住这个规则",
            "下次都这样",
            "teach you",
            "remember this workflow",
        }
    )
    ONE_TIME_MARKERS = frozenset({"帮我做一次", "只做一次", "这次帮我", "do this once", "one-time"})

    def __init__(self, store: AgentMemoryStore) -> None:
        if not isinstance(store, AgentMemoryStore):
            raise TypeError("HumanTeachingLayer requires an AgentMemoryStore")
        self._store = store

    def detect_intent(self, user_message: str) -> TeachingIntentAssessment:
        """Classify wording in-process, without returning or retaining it."""

        if not isinstance(user_message, str) or not user_message.strip():
            raise HumanTeachingPolicyError("user message must be a non-empty string")
        if len(user_message) > self.MAX_MESSAGE_CHARACTERS:
            raise HumanTeachingPolicyError("user message exceeds the bounded transient input limit")
        normalized = user_message.casefold()
        has_teaching_marker = any(marker.casefold() in normalized for marker in self.TEACHING_MARKERS)
        has_one_time_marker = any(marker.casefold() in normalized for marker in self.ONE_TIME_MARKERS)
        if has_teaching_marker and has_one_time_marker:
            return TeachingIntentAssessment("ambiguous", 0.50, ("conflicting_intent_markers",))
        if has_teaching_marker:
            return TeachingIntentAssessment("teaching", 0.95, ("explicit_teaching_marker",))
        if has_one_time_marker:
            return TeachingIntentAssessment("normal_request", 0.95, ("explicit_one_time_marker",))
        return TeachingIntentAssessment("ambiguous", 0.0, ("no_teaching_marker",))

    def propose(
        self,
        intent: TeachingIntentAssessment,
        outline: TeachingRuleOutline,
    ) -> TeachingProposal:
        """Create a transient, confirmable proposal from safe metadata only."""

        if not isinstance(intent, TeachingIntentAssessment):
            raise HumanTeachingPolicyError("proposal requires TeachingIntentAssessment")
        if intent.intent != "teaching":
            raise HumanTeachingPolicyError("only explicit teaching intent may create a proposal")
        if not isinstance(outline, TeachingRuleOutline):
            raise HumanTeachingPolicyError("proposal requires TeachingRuleOutline")
        return TeachingProposal(
            proposal_id=str(uuid4()),
            intent=intent,
            outline=outline,
            status="awaiting_confirmation",
        )

    def confirm(self, proposal: TeachingProposal, *, confirmed_by_user: bool) -> TeachingCapabilityCandidate:
        """Turn only an explicit confirmation into a validation candidate."""

        if not isinstance(proposal, TeachingProposal):
            raise HumanTeachingPolicyError("confirmation requires TeachingProposal")
        if proposal.status != "awaiting_confirmation":
            raise HumanTeachingPolicyError("only pending proposals may be confirmed")
        if not isinstance(confirmed_by_user, bool):
            raise HumanTeachingPolicyError("confirmed_by_user must be boolean")
        return TeachingCapabilityCandidate(
            candidate_id=str(uuid4()),
            proposal_id=proposal.proposal_id,
            outline=proposal.outline,
            status="pending_validation" if confirmed_by_user else "rejected",
        )

    def record_validation(
        self,
        candidate: TeachingCapabilityCandidate,
        *,
        verifier_passed: bool,
        confidence: float,
        validated_at: int | None = None,
    ) -> TeachingCapabilityCandidate:
        """Persist only a confirmed candidate's verifier-classified outcome."""

        if not isinstance(candidate, TeachingCapabilityCandidate):
            raise HumanTeachingPolicyError("validation requires TeachingCapabilityCandidate")
        if candidate.status != "pending_validation":
            raise HumanTeachingPolicyError("only pending candidates may be validated")
        if not isinstance(verifier_passed, bool):
            raise HumanTeachingPolicyError("verifier_passed must be boolean")
        normalized_confidence = self._confidence(confidence)
        result = TeachingCapabilityCandidate(
            candidate_id=candidate.candidate_id,
            proposal_id=candidate.proposal_id,
            outline=candidate.outline,
            status="validated" if verifier_passed else "validation_failed",
            confidence=normalized_confidence,
        )
        entry = {
            "schema_version": HUMAN_TEACHING_SCHEMA_VERSION,
            "memory_version": HUMAN_TEACHING_VERSION,
            "record_id": str(uuid4()),
            "recorded_at": self._timestamp(validated_at),
            "record_type": self.RECORD_TYPE,
            "write_boundary": "verifier_pass" if verifier_passed else "classified_result",
            "rule_type": result.outline.rule_type,
            "candidate_kind": result.outline.candidate_kind,
            "risk_level": result.outline.risk_level,
            "validation_status": "passed" if verifier_passed else "failed",
            "confidence": normalized_confidence,
        }
        if not self.is_valid_record(entry):
            raise HumanTeachingPolicyError("teaching validation record did not satisfy the schema")
        self._store._append_bounded(entry)
        return result

    def advisory_context(self) -> dict[str, Any]:
        """Expose aggregate validated candidates without a decision effect."""

        aggregates: dict[tuple[str, str, str], dict[str, Any]] = {}
        for record in self._records():
            key = (record["rule_type"], record["candidate_kind"], record["risk_level"])
            aggregate = aggregates.setdefault(
                key,
                {
                    "rule_type": key[0],
                    "candidate_kind": key[1],
                    "risk_level": key[2],
                    "validated_count": 0,
                    "failed_count": 0,
                    "confidence_total": 0.0,
                    "last_validated_at": 0,
                },
            )
            aggregate["validated_count"] += 1 if record["validation_status"] == "passed" else 0
            aggregate["failed_count"] += 1 if record["validation_status"] == "failed" else 0
            aggregate["confidence_total"] += float(record["confidence"])
            aggregate["last_validated_at"] = max(aggregate["last_validated_at"], int(record["recorded_at"]))
        summaries = []
        for key in sorted(aggregates):
            aggregate = aggregates[key]
            total = aggregate["validated_count"] + aggregate["failed_count"]
            summaries.append(
                {
                    "rule_type": aggregate["rule_type"],
                    "candidate_kind": aggregate["candidate_kind"],
                    "risk_level": aggregate["risk_level"],
                    "validated_count": aggregate["validated_count"],
                    "failed_count": aggregate["failed_count"],
                    "mean_confidence": round(aggregate["confidence_total"] / total, 6),
                    "last_validated_at": aggregate["last_validated_at"],
                    "promotion_requires_future_review": True,
                }
            )
        return {
            "human_teaching_version": HUMAN_TEACHING_VERSION,
            "mode": "candidate_only",
            "decision_effect": "none",
            "requires_explicit_user_confirmation": True,
            "requires_validation": True,
            "requires_planner": True,
            "requires_risk_controller": True,
            "requires_executor": True,
            "requires_verifier": True,
            "validated_candidate_summaries": summaries,
        }

    def _records(self) -> list[dict[str, Any]]:
        return [record for record in self._store.records() if self.is_valid_record(record)]

    @classmethod
    def is_valid_record(cls, record: Any) -> bool:
        expected = {
            "schema_version",
            "memory_version",
            "record_id",
            "recorded_at",
            "record_type",
            "write_boundary",
            "rule_type",
            "candidate_kind",
            "risk_level",
            "validation_status",
            "confidence",
        }
        if not isinstance(record, dict) or set(record) != expected:
            return False
        if (
            record.get("schema_version") != HUMAN_TEACHING_SCHEMA_VERSION
            or record.get("memory_version") != HUMAN_TEACHING_VERSION
            or record.get("record_type") != cls.RECORD_TYPE
            or not isinstance(record.get("record_id"), str)
            or not record.get("record_id")
            or isinstance(record.get("recorded_at"), bool)
            or not isinstance(record.get("recorded_at"), int)
            or int(record["recorded_at"]) < 0
            or record.get("rule_type") not in TeachingRuleOutline.RULE_TYPES
            or record.get("candidate_kind") not in TeachingRuleOutline.CANDIDATE_KINDS
            or record.get("risk_level") not in SkillRegistry.RISK_LEVELS
            or record.get("validation_status") not in {"passed", "failed"}
        ):
            return False
        confidence = record.get("confidence")
        expected_boundary = "verifier_pass" if record.get("validation_status") == "passed" else "classified_result"
        return (
            record.get("write_boundary") == expected_boundary
            and not isinstance(confidence, bool)
            and isinstance(confidence, (int, float))
            and 0.0 <= float(confidence) <= 1.0
        )

    @staticmethod
    def _confidence(value: Any) -> float:
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not 0.0 <= float(value) <= 1.0:
            raise HumanTeachingPolicyError("candidate confidence must be between 0.0 and 1.0")
        return float(value)

    @staticmethod
    def _timestamp(value: int | None) -> int:
        timestamp = int(time.time()) if value is None else value
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise HumanTeachingPolicyError("validated_at must be a non-negative timestamp")
        return timestamp


class CapabilityGraduationPolicyError(ValueError):
    """TEST-32 lifecycle or trust-evidence constraints were violated."""


@dataclass(frozen=True)
class CapabilityTrustAssessment:
    """A non-executable trust recommendation for one lifecycle candidate.

    ``trust_level`` is deliberately an evidence classification, not an
    authorization. TEST-32 never turns a level into an automatic action. The
    future Trust Evolution Engine may consume this contract only after its own
    review and the existing Planner/Risk/Executor/Verifier boundaries remain
    mandatory.
    """

    trust_level: int
    eligible_for_trusted: bool
    eligible_for_activation: bool
    requires_explicit_user_confirmation: bool
    reason_codes: tuple[str, ...]

    def __post_init__(self) -> None:
        if self.trust_level not in {0, 1, 2, 3}:
            raise CapabilityGraduationPolicyError("trust level must be between 0 and 3")
        if not self.reason_codes:
            raise CapabilityGraduationPolicyError("trust assessment needs at least one reason code")

    def summary(self) -> dict[str, Any]:
        return {
            "trust_level": self.trust_level,
            "eligible_for_trusted": self.eligible_for_trusted,
            "eligible_for_activation": self.eligible_for_activation,
            "requires_explicit_user_confirmation": self.requires_explicit_user_confirmation,
            "reason_codes": list(self.reason_codes),
            "effective_automation_level": 0,
            "automation_effect": "none",
        }


@dataclass(frozen=True)
class CapabilityGraduationState:
    """Safe lifecycle metadata for a future capability, not the capability.

    The state contains no goal, rule wording, App identity, UI state, action
    history, or replayable parameters. ``DISCOVERED`` is intentionally
    transient. It enters private persistence only after an owner nominates a
    candidate or a TEST-31 verified teaching candidate is imported.
    """

    graduation_id: str
    capability_kind: str
    origin: str
    risk_level: str
    lifecycle: str
    success_count: int
    failure_count: int
    user_confirmation_count: int
    frequency_count: int
    confidence_total: float
    last_verified_at: int | None
    trust_level: int
    created_at: int
    updated_at: int

    def __post_init__(self) -> None:
        if not isinstance(self.graduation_id, str) or not self.graduation_id:
            raise CapabilityGraduationPolicyError("graduation_id must be a non-empty opaque identifier")
        if self.capability_kind not in TeachingRuleOutline.CANDIDATE_KINDS:
            raise CapabilityGraduationPolicyError("unsupported capability kind")
        if self.origin not in CapabilityGraduationEngine.ORIGINS:
            raise CapabilityGraduationPolicyError("unsupported capability origin")
        if self.risk_level not in SkillRegistry.RISK_LEVELS:
            raise CapabilityGraduationPolicyError("unsupported capability risk level")
        if self.lifecycle not in CapabilityGraduationEngine.LIFECYCLES:
            raise CapabilityGraduationPolicyError("unsupported graduation lifecycle")
        for field_name, value in (
            ("success_count", self.success_count),
            ("failure_count", self.failure_count),
            ("user_confirmation_count", self.user_confirmation_count),
            ("frequency_count", self.frequency_count),
            ("created_at", self.created_at),
            ("updated_at", self.updated_at),
        ):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise CapabilityGraduationPolicyError("%s must be a non-negative integer" % field_name)
        if self.frequency_count < self.verification_count:
            raise CapabilityGraduationPolicyError("frequency count cannot be lower than validation count")
        if isinstance(self.confidence_total, bool) or not isinstance(self.confidence_total, (int, float)):
            raise CapabilityGraduationPolicyError("confidence_total must be numeric")
        if not 0.0 <= float(self.confidence_total) <= float(self.verification_count):
            raise CapabilityGraduationPolicyError("confidence_total must be bounded by validation count")
        if self.last_verified_at is not None:
            if isinstance(self.last_verified_at, bool) or not isinstance(self.last_verified_at, int):
                raise CapabilityGraduationPolicyError("last_verified_at must be a timestamp or None")
            if self.last_verified_at < 0:
                raise CapabilityGraduationPolicyError("last_verified_at must be non-negative")
        elif self.verification_count:
            raise CapabilityGraduationPolicyError("validation outcomes require last_verified_at")
        if self.updated_at < self.created_at:
            raise CapabilityGraduationPolicyError("updated_at cannot precede created_at")
        if self.trust_level not in {0, 1, 2, 3}:
            raise CapabilityGraduationPolicyError("trust_level must be between 0 and 3")

    @property
    def verification_count(self) -> int:
        return self.success_count + self.failure_count

    @property
    def mean_confidence(self) -> float | None:
        if not self.verification_count:
            return None
        return round(float(self.confidence_total) / self.verification_count, 6)

    @property
    def validation_state(self) -> str:
        if not self.verification_count:
            return "pending" if self.lifecycle == "VALIDATING" else "not_started"
        if self.success_count and self.failure_count:
            return "mixed"
        return "passed" if self.success_count else "failed"

    def summary(self) -> dict[str, Any]:
        return {
            "graduation_id": self.graduation_id,
            "capability_kind": self.capability_kind,
            "origin": self.origin,
            "risk_level": self.risk_level,
            "lifecycle": self.lifecycle,
            "validation_state": self.validation_state,
            "success_count": self.success_count,
            "failure_count": self.failure_count,
            "user_confirmation_count": self.user_confirmation_count,
            "frequency_count": self.frequency_count,
            "mean_confidence": self.mean_confidence,
            "last_verified_at": self.last_verified_at,
            "trust_level": self.trust_level,
            "capability_created": False,
            "automation_effect": "none",
            "requires_planner": True,
            "requires_risk_controller": True,
            "requires_executor": True,
            "requires_verifier": True,
        }


class CapabilityGraduationEngine:
    """Manage candidate lifecycle evidence without publishing capabilities.

    TEST-32 is a state and trust contract. It cannot register or modify a
    Skill, create a Shortcut, run a Workflow, change routing, call an MCP
    client, or select a device action. Persistent records are fixed-schema
    aggregate metadata only and can be read only as a future advisory context.
    """

    RECORD_TYPE = "capability_graduation_state"
    ORIGINS = frozenset({"human_teaching", "validated_experience"})
    LIFECYCLES = frozenset(
        {"DISCOVERED", "CANDIDATE", "TEACHING", "VALIDATING", "TRUSTED", "ACTIVE", "DEPRECATED"}
    )
    TRANSITIONS = {
        "DISCOVERED": frozenset({"CANDIDATE", "DEPRECATED"}),
        "CANDIDATE": frozenset({"TEACHING", "VALIDATING", "DEPRECATED"}),
        "TEACHING": frozenset({"VALIDATING", "DEPRECATED"}),
        "VALIDATING": frozenset({"VALIDATING", "TRUSTED", "DEPRECATED"}),
        "TRUSTED": frozenset({"ACTIVE", "VALIDATING", "DEPRECATED"}),
        "ACTIVE": frozenset({"VALIDATING", "DEPRECATED"}),
        "DEPRECATED": frozenset(),
    }
    DEPRECATION_REASONS = frozenset({"owner_superseded", "policy_incompatible", "validation_failure", "owner_retired"})
    MINIMUM_EVIDENCE = {
        "read_only": {"success": 2, "frequency": 2, "confidence": 0.80},
        "interaction": {"success": 3, "frequency": 3, "confidence": 0.85},
        "high_risk": {"success": 3, "frequency": 3, "confidence": 0.90},
    }

    def __init__(self, store: AgentMemoryStore) -> None:
        if not isinstance(store, AgentMemoryStore):
            raise TypeError("CapabilityGraduationEngine requires an AgentMemoryStore")
        self._store = store

    def discover(
        self,
        *,
        capability_kind: str,
        risk_level: str,
        observed_frequency: int,
        discovered_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Return a transient repeat-pattern candidate without persisting it."""

        frequency = self._positive_integer(observed_frequency, "observed_frequency")
        timestamp = self._timestamp(discovered_at, "discovered_at")
        return CapabilityGraduationState(
            graduation_id=str(uuid4()),
            capability_kind=self._capability_kind(capability_kind),
            origin="validated_experience",
            risk_level=self._risk_level(risk_level),
            lifecycle="DISCOVERED",
            success_count=0,
            failure_count=0,
            user_confirmation_count=0,
            frequency_count=frequency,
            confidence_total=0.0,
            last_verified_at=None,
            trust_level=0,
            created_at=timestamp,
            updated_at=timestamp,
        )

    def nominate_candidate(
        self,
        state: CapabilityGraduationState,
        *,
        confirmed_by_user: bool,
        nominated_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Persist a discovered candidate only after explicit owner approval."""

        self._require_lifecycle(state, "DISCOVERED")
        self._require_confirmation(confirmed_by_user)
        candidate = self._transition(
            state,
            "CANDIDATE",
            updated_at=self._timestamp(nominated_at, "nominated_at"),
            user_confirmation_count=state.user_confirmation_count + 1,
        )
        self._persist(candidate, "explicit_user_confirmation")
        return candidate

    def begin_teaching(
        self,
        state: CapabilityGraduationState,
        *,
        confirmed_by_user: bool,
        teaching_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Move an owner-approved candidate into an explicit teaching session."""

        self._require_lifecycle(state, "CANDIDATE")
        self._require_confirmation(confirmed_by_user)
        teaching = self._transition(
            state,
            "TEACHING",
            updated_at=self._timestamp(teaching_at, "teaching_at"),
            user_confirmation_count=state.user_confirmation_count + 1,
        )
        self._persist(teaching, "teaching_confirmation")
        return teaching

    def submit_for_validation(
        self,
        state: CapabilityGraduationState,
        *,
        confirmed_by_user: bool,
        submitted_at: int | None = None,
    ) -> CapabilityGraduationState:
        """End explicit teaching and open a verifier-gated validation state."""

        self._require_lifecycle(state, "TEACHING")
        self._require_confirmation(confirmed_by_user)
        validating = self._transition(
            state,
            "VALIDATING",
            updated_at=self._timestamp(submitted_at, "submitted_at"),
            user_confirmation_count=state.user_confirmation_count + 1,
        )
        self._persist(validating, "teaching_confirmation")
        return validating

    def begin_validation(
        self,
        state: CapabilityGraduationState,
        *,
        opened_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Open validation for an already owner-nominated candidate."""

        self._require_lifecycle(state, "CANDIDATE")
        validating = self._transition(state, "VALIDATING", updated_at=self._timestamp(opened_at, "opened_at"))
        self._persist(validating, "explicit_user_confirmation")
        return validating

    def import_validated_teaching(
        self,
        candidate: TeachingCapabilityCandidate,
        *,
        imported_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Explicitly admit TEST-31 verified metadata as fresh validation evidence.

        The source candidate remains a TEST-31 object. This method copies only
        its kind, risk category, verifier result, and bounded confidence into a
        new TEST-32 identifier. It neither creates nor registers the proposed
        capability.
        """

        if not isinstance(candidate, TeachingCapabilityCandidate):
            raise CapabilityGraduationPolicyError("teaching import requires TeachingCapabilityCandidate")
        if candidate.status != "validated" or candidate.confidence is None:
            raise CapabilityGraduationPolicyError("only a TEST-31 validated candidate may enter graduation")
        timestamp = self._timestamp(imported_at, "imported_at")
        state = CapabilityGraduationState(
            graduation_id=str(uuid4()),
            capability_kind=candidate.outline.candidate_kind,
            origin="human_teaching",
            risk_level=candidate.outline.risk_level,
            lifecycle="VALIDATING",
            success_count=1,
            failure_count=0,
            user_confirmation_count=1,
            frequency_count=1,
            confidence_total=float(candidate.confidence),
            last_verified_at=timestamp,
            trust_level=1,
            created_at=timestamp,
            updated_at=timestamp,
        )
        self._persist(state, "verifier_pass")
        return state

    def record_validation(
        self,
        state: CapabilityGraduationState,
        *,
        verifier_passed: bool,
        confidence: float,
        observed_frequency_increment: int = 1,
        validated_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Store a classified verifier result and possibly mark it trusted.

        This method consumes a boolean outcome from the existing verifier
        boundary. It never invokes a verifier itself, and an evidence-qualified
        ``TRUSTED`` state is still non-executable in this TEST.
        """

        self._require_lifecycle(state, "VALIDATING")
        if not isinstance(verifier_passed, bool):
            raise CapabilityGraduationPolicyError("verifier_passed must be boolean")
        normalized_confidence = self._confidence(confidence)
        frequency_increment = self._positive_integer(observed_frequency_increment, "observed_frequency_increment")
        timestamp = self._timestamp(validated_at, "validated_at")
        evaluated = replace(
            state,
            success_count=state.success_count + (1 if verifier_passed else 0),
            failure_count=state.failure_count + (0 if verifier_passed else 1),
            frequency_count=state.frequency_count + frequency_increment,
            confidence_total=float(state.confidence_total) + normalized_confidence,
            last_verified_at=timestamp,
            updated_at=timestamp,
        )
        assessment = self.assess_trust(evaluated)
        lifecycle = "TRUSTED" if assessment.eligible_for_trusted else "VALIDATING"
        result = replace(evaluated, lifecycle=lifecycle, trust_level=assessment.trust_level)
        self._persist(result, "verifier_pass" if verifier_passed else "classified_result")
        return result

    def activate(
        self,
        state: CapabilityGraduationState,
        *,
        confirmed_by_user: bool,
        activated_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Record owner-approved future availability without executing it."""

        self._require_lifecycle(state, "TRUSTED")
        self._require_confirmation(confirmed_by_user)
        active = self._transition(
            state,
            "ACTIVE",
            updated_at=self._timestamp(activated_at, "activated_at"),
            user_confirmation_count=state.user_confirmation_count + 1,
        )
        self._persist(active, "owner_activation")
        return active

    def begin_revalidation(
        self,
        state: CapabilityGraduationState,
        *,
        confirmed_by_user: bool,
        reopened_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Reopen a trusted or active candidate for owner-approved review.

        Revalidation is metadata-only. It does not replay a prior workflow,
        call a verifier, change an existing capability, or suspend the
        downstream Planner/Risk/Executor/Verifier requirements.
        """

        if not isinstance(state, CapabilityGraduationState) or state.lifecycle not in {"TRUSTED", "ACTIVE"}:
            raise CapabilityGraduationPolicyError("revalidation requires TRUSTED or ACTIVE lifecycle")
        self._require_confirmation(confirmed_by_user)
        validating = self._transition(
            state,
            "VALIDATING",
            updated_at=self._timestamp(reopened_at, "reopened_at"),
            user_confirmation_count=state.user_confirmation_count + 1,
            trust_level=1,
        )
        self._persist(validating, "owner_revalidation")
        return validating

    def deprecate(
        self,
        state: CapabilityGraduationState,
        *,
        reason_code: str,
        confirmed_by_user: bool,
        deprecated_at: int | None = None,
    ) -> CapabilityGraduationState:
        """Retire an old candidate through an owner-confirmed fixed reason."""

        if not isinstance(state, CapabilityGraduationState):
            raise CapabilityGraduationPolicyError("deprecation requires CapabilityGraduationState")
        if state.lifecycle == "DEPRECATED":
            raise CapabilityGraduationPolicyError("deprecated candidates are terminal")
        if reason_code not in self.DEPRECATION_REASONS:
            raise CapabilityGraduationPolicyError("unsupported deprecation reason")
        self._require_confirmation(confirmed_by_user)
        retired = self._transition(
            state,
            "DEPRECATED",
            updated_at=self._timestamp(deprecated_at, "deprecated_at"),
            user_confirmation_count=state.user_confirmation_count + 1,
        )
        self._persist(retired, "owner_deprecation")
        return retired

    def assess_trust(self, state: CapabilityGraduationState) -> CapabilityTrustAssessment:
        """Classify evidence without changing the candidate or any policy."""

        if not isinstance(state, CapabilityGraduationState):
            raise CapabilityGraduationPolicyError("trust assessment requires CapabilityGraduationState")
        minimums = self.MINIMUM_EVIDENCE[state.risk_level]
        reasons: list[str] = []
        if state.lifecycle in {"DISCOVERED", "CANDIDATE", "TEACHING"}:
            reasons.append("validation_not_open")
        if state.user_confirmation_count < 1:
            reasons.append("owner_confirmation_missing")
        if state.success_count < minimums["success"]:
            reasons.append("success_evidence_insufficient")
        if state.frequency_count < minimums["frequency"]:
            reasons.append("frequency_evidence_insufficient")
        if state.mean_confidence is None or state.mean_confidence < minimums["confidence"]:
            reasons.append("confidence_evidence_insufficient")
        if state.failure_count:
            reasons.append("failure_evidence_present")
        qualified = not reasons and state.lifecycle in {"VALIDATING", "TRUSTED", "ACTIVE"}
        if qualified:
            trust_level = 2
            reasons.append("validated_evidence_threshold_met")
        elif state.verification_count:
            trust_level = 1
        else:
            trust_level = 0
        return CapabilityTrustAssessment(
            trust_level=trust_level,
            eligible_for_trusted=qualified and state.lifecycle == "VALIDATING",
            eligible_for_activation=qualified and state.lifecycle == "TRUSTED",
            requires_explicit_user_confirmation=True,
            reason_codes=tuple(reasons),
        )

    def advisory_context(self) -> dict[str, Any]:
        """Return grouped persisted metadata with no decision or action effect."""

        current: dict[str, dict[str, Any]] = {}
        for record in self._records():
            current[record["graduation_id"]] = record
        aggregates: dict[tuple[str, str, str, str, int], dict[str, Any]] = {}
        for record in current.values():
            key = (
                record["capability_kind"],
                record["origin"],
                record["risk_level"],
                record["lifecycle"],
                record["trust_level"],
            )
            aggregate = aggregates.setdefault(
                key,
                {
                    "capability_kind": key[0],
                    "origin": key[1],
                    "risk_level": key[2],
                    "lifecycle": key[3],
                    "trust_level": key[4],
                    "capability_count": 0,
                    "success_count": 0,
                    "failure_count": 0,
                    "user_confirmation_count": 0,
                    "frequency_count": 0,
                    "confidence_total": 0.0,
                    "validation_count": 0,
                    "last_verified_at": None,
                },
            )
            aggregate["capability_count"] += 1
            aggregate["success_count"] += record["success_count"]
            aggregate["failure_count"] += record["failure_count"]
            aggregate["user_confirmation_count"] += record["user_confirmation_count"]
            aggregate["frequency_count"] += record["frequency_count"]
            aggregate["confidence_total"] += float(record["confidence_total"])
            aggregate["validation_count"] += record["success_count"] + record["failure_count"]
            timestamp = record["last_verified_at"]
            if isinstance(timestamp, int) and (aggregate["last_verified_at"] is None or timestamp > aggregate["last_verified_at"]):
                aggregate["last_verified_at"] = timestamp
        summaries = []
        for key in sorted(aggregates):
            aggregate = aggregates[key]
            validation_count = aggregate.pop("validation_count")
            confidence_total = aggregate.pop("confidence_total")
            summaries.append(
                {
                    **aggregate,
                    "mean_confidence": None if not validation_count else round(confidence_total / validation_count, 6),
                }
            )
        return {
            "capability_graduation_version": CAPABILITY_GRADUATION_VERSION,
            "mode": "lifecycle_only",
            "decision_effect": "none",
            "automation_effect": "none",
            "requires_explicit_user_confirmation": True,
            "requires_planner": True,
            "requires_risk_controller": True,
            "requires_executor": True,
            "requires_verifier": True,
            "trust_evolution_engine": "future_only",
            "capability_summaries": summaries,
        }

    def _records(self) -> list[dict[str, Any]]:
        return [record for record in self._store.records() if self.is_valid_record(record)]

    def _persist(self, state: CapabilityGraduationState, write_boundary: str) -> None:
        entry = {
            "schema_version": CAPABILITY_GRADUATION_SCHEMA_VERSION,
            "memory_version": CAPABILITY_GRADUATION_VERSION,
            "record_id": str(uuid4()),
            "recorded_at": state.updated_at,
            "record_type": self.RECORD_TYPE,
            "write_boundary": write_boundary,
            "graduation_id": state.graduation_id,
            "capability_kind": state.capability_kind,
            "origin": state.origin,
            "risk_level": state.risk_level,
            "lifecycle": state.lifecycle,
            "validation_state": state.validation_state,
            "success_count": state.success_count,
            "failure_count": state.failure_count,
            "user_confirmation_count": state.user_confirmation_count,
            "frequency_count": state.frequency_count,
            "confidence_total": round(float(state.confidence_total), 6),
            "last_verified_at": state.last_verified_at,
            "trust_level": state.trust_level,
            "created_at": state.created_at,
            "updated_at": state.updated_at,
        }
        if not self.is_valid_record(entry):
            raise CapabilityGraduationPolicyError("graduation record did not satisfy the privacy schema")
        self._store._append_bounded(entry)

    def _transition(self, state: CapabilityGraduationState, lifecycle: str, **changes: Any) -> CapabilityGraduationState:
        if not isinstance(state, CapabilityGraduationState):
            raise CapabilityGraduationPolicyError("lifecycle transition requires CapabilityGraduationState")
        if lifecycle not in self.TRANSITIONS[state.lifecycle]:
            raise CapabilityGraduationPolicyError("invalid lifecycle transition: %s -> %s" % (state.lifecycle, lifecycle))
        return replace(state, lifecycle=lifecycle, **changes)

    @classmethod
    def is_valid_record(cls, record: Any) -> bool:
        expected = {
            "schema_version",
            "memory_version",
            "record_id",
            "recorded_at",
            "record_type",
            "write_boundary",
            "graduation_id",
            "capability_kind",
            "origin",
            "risk_level",
            "lifecycle",
            "validation_state",
            "success_count",
            "failure_count",
            "user_confirmation_count",
            "frequency_count",
            "confidence_total",
            "last_verified_at",
            "trust_level",
            "created_at",
            "updated_at",
        }
        if not isinstance(record, dict) or set(record) != expected:
            return False
        if (
            record.get("schema_version") != CAPABILITY_GRADUATION_SCHEMA_VERSION
            or record.get("memory_version") != CAPABILITY_GRADUATION_VERSION
            or record.get("record_type") != cls.RECORD_TYPE
            or not isinstance(record.get("record_id"), str)
            or not record.get("record_id")
            or not isinstance(record.get("graduation_id"), str)
            or not record.get("graduation_id")
            or record.get("capability_kind") not in TeachingRuleOutline.CANDIDATE_KINDS
            or record.get("origin") not in cls.ORIGINS
            or record.get("risk_level") not in SkillRegistry.RISK_LEVELS
            or record.get("lifecycle") not in cls.LIFECYCLES - {"DISCOVERED"}
            or record.get("write_boundary") not in {
                "explicit_user_confirmation",
                "teaching_confirmation",
                "verifier_pass",
                "classified_result",
                "owner_activation",
                "owner_revalidation",
                "owner_deprecation",
            }
        ):
            return False
        try:
            state = CapabilityGraduationState(
                graduation_id=record["graduation_id"],
                capability_kind=record["capability_kind"],
                origin=record["origin"],
                risk_level=record["risk_level"],
                lifecycle=record["lifecycle"],
                success_count=record["success_count"],
                failure_count=record["failure_count"],
                user_confirmation_count=record["user_confirmation_count"],
                frequency_count=record["frequency_count"],
                confidence_total=record["confidence_total"],
                last_verified_at=record["last_verified_at"],
                trust_level=record["trust_level"],
                created_at=record["created_at"],
                updated_at=record["updated_at"],
            )
        except CapabilityGraduationPolicyError:
            return False
        return (
            isinstance(record.get("recorded_at"), int)
            and not isinstance(record.get("recorded_at"), bool)
            and record["recorded_at"] == state.updated_at
            and record.get("validation_state") == state.validation_state
            and record.get("trust_level") != 3
        )

    @staticmethod
    def _capability_kind(value: str) -> str:
        if value not in TeachingRuleOutline.CANDIDATE_KINDS:
            raise CapabilityGraduationPolicyError("unsupported capability kind")
        return value

    @staticmethod
    def _risk_level(value: str) -> str:
        if value not in SkillRegistry.RISK_LEVELS:
            raise CapabilityGraduationPolicyError("unsupported capability risk level")
        return value

    @staticmethod
    def _confidence(value: Any) -> float:
        if isinstance(value, bool) or not isinstance(value, (int, float)) or not 0.0 <= float(value) <= 1.0:
            raise CapabilityGraduationPolicyError("confidence must be between 0.0 and 1.0")
        return float(value)

    @staticmethod
    def _positive_integer(value: Any, field_name: str) -> int:
        if isinstance(value, bool) or not isinstance(value, int) or value < 1:
            raise CapabilityGraduationPolicyError("%s must be a positive integer" % field_name)
        return value

    @staticmethod
    def _timestamp(value: int | None, field_name: str) -> int:
        timestamp = int(time.time()) if value is None else value
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise CapabilityGraduationPolicyError("%s must be a non-negative timestamp" % field_name)
        return timestamp

    @staticmethod
    def _require_confirmation(value: bool) -> None:
        if value is not True:
            raise CapabilityGraduationPolicyError("explicit user confirmation is required")

    @staticmethod
    def _require_lifecycle(state: CapabilityGraduationState, lifecycle: str) -> None:
        if not isinstance(state, CapabilityGraduationState) or state.lifecycle != lifecycle:
            raise CapabilityGraduationPolicyError("operation requires %s lifecycle" % lifecycle)


class ExecutionAdapterError(ValueError):
    """A native execution adapter received an unsafe or unsupported request."""


class ExecutionAdapter:
    """Declarative adapter base; adapters never own planning or authorization."""

    FUTURE_ADAPTER_TYPES = frozenset(
        {"shortcut_adapter", "app_intent_adapter", "mcp_adapter", "ax_adapter", "vision_adapter"}
    )

    @property
    def adapter_id(self) -> str:
        raise NotImplementedError


@dataclass(frozen=True)
class MapLinkAdapter(ExecutionAdapter):
    """Build one bounded legacy Apple Maps link for an approved public destination.

    The adapter owns no transport, does not observe the device, and cannot
    dispatch its link. The transient URL exists only inside an Executor plan;
    all public summaries use metadata that cannot reconstruct the destination.
    """

    destination: str

    ADAPTER_ID = "adapter.maps_legacy_link.v1"
    MAX_DESTINATION_LENGTH = 128
    DESTINATION_PATTERN = re.compile(r"^[\w\s,.'()/\-]+$", re.UNICODE)

    def __post_init__(self) -> None:
        if not isinstance(self.destination, str):
            raise ExecutionAdapterError("destination must be text")
        if any(unicodedata.category(character).startswith("C") for character in self.destination):
            raise ExecutionAdapterError("destination cannot contain URL or control syntax")
        normalized = " ".join(self.destination.split())
        if not normalized or len(normalized) > self.MAX_DESTINATION_LENGTH:
            raise ExecutionAdapterError("destination must be non-empty and bounded")
        lowered = normalized.casefold()
        if (
            any(token in normalized for token in ("://", "?", "#", "%", "&", "="))
            or lowered.startswith("www.")
            or lowered.startswith("maps.apple.")
        ):
            raise ExecutionAdapterError("destination cannot contain URL or control syntax")
        if not self.DESTINATION_PATTERN.fullmatch(normalized):
            raise ExecutionAdapterError("destination contains unsupported characters")
        object.__setattr__(self, "destination", normalized)

    @property
    def adapter_id(self) -> str:
        return self.ADAPTER_ID

    def map_url(self) -> str:
        """Return an iOS 17-compatible Apple Maps legacy link for one Executor step."""

        encoded_query = urllib.parse.urlencode({"q": self.destination})
        url = "http://maps.apple.com/?%s" % encoded_query
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme != "http" or parsed.netloc != "maps.apple.com" or parsed.path != "/":
            raise ExecutionAdapterError("generated map link failed validation")
        if urllib.parse.parse_qs(parsed.query).get("q") != [self.destination]:
            raise ExecutionAdapterError("generated map link lost its destination")
        return url

    def input_summary(self) -> dict[str, Any]:
        return {
            "destination_present": True,
            "destination_length_bucket": self._length_bucket(len(self.destination)),
            "destination_class": "public_destination",
        }

    def planner_steps(self) -> list[dict[str, Any]]:
        return [
            {
                "id": "dispatch-apple-maps-link",
                "tool": "open_url",
                "arguments": {"url": self.map_url()},
                "reason": "Dispatch one validated Apple Maps legacy link through the selected native method.",
            }
        ]

    @staticmethod
    def _length_bucket(length: int) -> str:
        if length <= 16:
            return "short"
        if length <= 64:
            return "medium"
        return "long"


class DynamicPlanPolicyError(ValueError):
    """A TEST-53 Planner contract contains unsafe or malformed metadata."""


_PLANNER_METADATA_PATTERN = re.compile(r"^[a-z][a-z0-9_.-]{2,127}$")


def _planner_metadata(value: Any, field_name: str) -> str:
    normalized = str(value or "").strip()
    if _PLANNER_METADATA_PATTERN.fullmatch(normalized) is None:
        raise DynamicPlanPolicyError("%s must be bounded metadata" % field_name)
    return normalized


def _planner_metadata_tuple(values: Iterable[str], field_name: str) -> tuple[str, ...]:
    normalized = tuple(_planner_metadata(value, field_name) for value in values)
    if len(normalized) != len(set(normalized)):
        raise DynamicPlanPolicyError("%s cannot contain duplicates" % field_name)
    return normalized


@dataclass(frozen=True)
class PlannerConstraintState:
    """One semantic precondition state; never raw UI or user content."""

    name: str
    status: str

    STATUSES = frozenset({"SATISFIED", "MISSING", "UNAVAILABLE", "STALE", "CONFLICTED"})

    def __post_init__(self) -> None:
        object.__setattr__(self, "name", _planner_metadata(self.name, "constraint name"))
        if self.status not in self.STATUSES:
            raise DynamicPlanPolicyError("unsupported Planner constraint status")


@dataclass(frozen=True)
class PlannerAuthorizationFact:
    """Authorization evidence for one same-leaf semantic property."""

    name: str
    value: str
    provenance: str
    same_leaf: bool

    VALUES = frozenset({"TRUE", "FALSE", "UNAVAILABLE"})
    PROVENANCE = frozenset({"DIRECT", "DERIVED", "INFERRED", "UNAVAILABLE"})

    def __post_init__(self) -> None:
        object.__setattr__(self, "name", _planner_metadata(self.name, "authorization fact"))
        if self.value not in self.VALUES:
            raise DynamicPlanPolicyError("unsupported authorization fact value")
        if self.provenance not in self.PROVENANCE:
            raise DynamicPlanPolicyError("unsupported authorization provenance")
        if not isinstance(self.same_leaf, bool):
            raise DynamicPlanPolicyError("same_leaf must be boolean")


@dataclass(frozen=True)
class PlannerReferent:
    """Opaque resolved-reference metadata available to planning."""

    referent_id: str
    kind: str
    resolution_status: str
    freshness: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "referent_id", _planner_metadata(self.referent_id, "referent_id"))
        object.__setattr__(self, "kind", _planner_metadata(self.kind, "referent kind"))
        if self.resolution_status not in {"RESOLVED", "AMBIGUOUS", "UNRESOLVED"}:
            raise DynamicPlanPolicyError("unsupported referent resolution status")
        if self.freshness not in {"FRESH", "STALE", "UNKNOWN"}:
            raise DynamicPlanPolicyError("unsupported referent freshness")


@dataclass(frozen=True)
class PlannerStepResult:
    """Privacy-safe prior-step evidence used only for replanning."""

    step_id: str
    status: str
    reason_code: str
    verifier_status: str

    def __post_init__(self) -> None:
        object.__setattr__(self, "step_id", _planner_metadata(self.step_id, "step result id"))
        object.__setattr__(self, "reason_code", _planner_metadata(self.reason_code, "step result reason"))
        if self.status not in {"PASSED", "FAILED", "BLOCKED", "UNKNOWN_SIDE_EFFECT"}:
            raise DynamicPlanPolicyError("unsupported prior step status")
        if self.verifier_status not in {"PASSED", "FAILED", "UNAVAILABLE", "NOT_RUN"}:
            raise DynamicPlanPolicyError("unsupported verifier status")


@dataclass(frozen=True)
class PlannerCapabilityContext:
    capability_id: str
    lifecycle: str
    available: bool
    required_permissions: tuple[str, ...]
    risk_level: str
    verifier: str
    dependencies: tuple[str, ...]
    platform_support: tuple[str, ...]

    @classmethod
    def from_contract(cls, contract: dict[str, Any], active_skill_ids: frozenset[str]) -> "PlannerCapabilityContext":
        capability_id = _planner_metadata(contract.get("capability_id"), "capability_id")
        lifecycle = str(contract.get("lifecycle") or "")
        skill_id = capability_id.removeprefix("capability.")
        available = lifecycle in {"AVAILABLE", "VERIFIED", "PREFERRED"} or (
            contract.get("source_type") == "skill_package" and skill_id in active_skill_ids
        )
        return cls(
            capability_id=capability_id,
            lifecycle=lifecycle,
            available=available,
            required_permissions=_planner_metadata_tuple(contract.get("required_permissions") or (), "capability permission"),
            risk_level=_planner_metadata(contract.get("risk_level"), "capability risk"),
            verifier=_planner_metadata(contract.get("verifier"), "capability verifier"),
            dependencies=_planner_metadata_tuple(contract.get("dependencies") or (), "capability dependency"),
            platform_support=_planner_metadata_tuple(contract.get("platform_support") or (), "capability platform"),
        )


@dataclass(frozen=True)
class PlannerSkillContext:
    skill_id: str
    name: str
    status: str
    intent_kinds: tuple[str, ...]
    required_tools: tuple[str, ...]
    allowed_tools: tuple[str, ...]
    required_permissions: tuple[str, ...]
    risk_level: str
    preconditions: tuple[str, ...]
    verifier: str
    dependencies: tuple[str, ...]
    platform_support: tuple[str, ...]

    @classmethod
    def from_contract(cls, contract: dict[str, Any]) -> "PlannerSkillContext":
        return cls(
            skill_id=_planner_metadata(contract.get("skill_id"), "skill_id"),
            name=_planner_metadata(contract.get("name"), "skill name"),
            status=_planner_metadata(contract.get("status"), "skill status"),
            intent_kinds=_planner_metadata_tuple(contract.get("intent_kinds") or (), "skill intent"),
            required_tools=_planner_metadata_tuple(contract.get("required_tools") or (), "skill required tool"),
            allowed_tools=_planner_metadata_tuple(contract.get("allowed_tools") or (), "skill allowed tool"),
            required_permissions=_planner_metadata_tuple(contract.get("required_permissions") or (), "skill permission"),
            risk_level=_planner_metadata(contract.get("risk_level"), "skill risk"),
            preconditions=_planner_metadata_tuple(contract.get("preconditions") or (), "skill precondition"),
            verifier=_planner_metadata(contract.get("verifier"), "skill verifier"),
            dependencies=_planner_metadata_tuple(contract.get("dependencies") or (), "skill dependency"),
            platform_support=_planner_metadata_tuple(contract.get("platform_support") or (), "skill platform"),
        )


@dataclass(frozen=True)
class PlannerMethodContext:
    method_id: str
    capability_id: str
    eligible: bool
    score: float | None
    reason_codes: tuple[str, ...]
    risk_level: str
    verifier: str
    platform_support: tuple[str, ...]

    @classmethod
    def from_candidate(cls, candidate: CapabilityMethodCandidate) -> "PlannerMethodContext":
        summary = candidate.summary()
        return cls(
            method_id=_planner_metadata(summary.get("method_id"), "method_id"),
            capability_id=_planner_metadata(summary.get("capability_id"), "method capability_id"),
            eligible=bool(summary.get("eligible")),
            score=float(summary["score"]) if summary.get("score") is not None else None,
            reason_codes=_planner_metadata_tuple(summary.get("reason_codes") or (), "method reason"),
            risk_level=_planner_metadata(summary.get("risk_level"), "method risk"),
            verifier=_planner_metadata(summary.get("verifier"), "method verifier"),
            platform_support=_planner_metadata_tuple(summary.get("platform_support") or (), "method platform"),
        )


@dataclass(frozen=True)
class PlannerInput:
    """Approved semantic context for TEST-53; it cannot contain raw goal data."""

    request_id: str
    goal_class: str
    normalized_intent: str
    task_context_ref: str
    context_version: int
    capabilities: tuple[PlannerCapabilityContext, ...]
    skills: tuple[PlannerSkillContext, ...]
    methods: tuple[PlannerMethodContext, ...]
    available_tools: tuple[str, ...]
    available_permissions: tuple[str, ...]
    available_platforms: tuple[str, ...]
    constraints: tuple[PlannerConstraintState, ...] = ()
    authorization_facts: tuple[PlannerAuthorizationFact, ...] = ()
    resolved_referents: tuple[PlannerReferent, ...] = ()
    prior_step_results: tuple[PlannerStepResult, ...] = ()
    recent_verification_evidence: tuple[str, ...] = ()
    preference_codes: tuple[str, ...] = ()
    sensitivity_codes: tuple[str, ...] = ()
    risk_constraints: tuple[str, ...] = ()
    methods_already_attempted: tuple[str, ...] = ()
    planning_revision: int = 1
    replan_count: int = 0
    maximum_steps: int = 8
    maximum_replans: int = 2

    def __post_init__(self) -> None:
        for field_name in ("request_id", "goal_class", "normalized_intent", "task_context_ref"):
            object.__setattr__(self, field_name, _planner_metadata(getattr(self, field_name), field_name))
        for field_name, value, minimum in (
            ("context_version", self.context_version, 1),
            ("planning_revision", self.planning_revision, 1),
            ("replan_count", self.replan_count, 0),
            ("maximum_steps", self.maximum_steps, 1),
            ("maximum_replans", self.maximum_replans, 0),
        ):
            if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
                raise DynamicPlanPolicyError("%s is outside its allowed range" % field_name)
        if self.maximum_steps > 16 or self.maximum_replans > 2:
            raise DynamicPlanPolicyError("Planner resource bounds exceed TEST-53 policy")
        if self.replan_count > self.maximum_replans or self.planning_revision != self.replan_count + 1:
            raise DynamicPlanPolicyError("planning revision and replan count are inconsistent")
        for field_name, values in (
            ("available_tools", self.available_tools),
            ("available_permissions", self.available_permissions),
            ("available_platforms", self.available_platforms),
            ("recent_verification_evidence", self.recent_verification_evidence),
            ("preference_codes", self.preference_codes),
            ("sensitivity_codes", self.sensitivity_codes),
            ("risk_constraints", self.risk_constraints),
            ("methods_already_attempted", self.methods_already_attempted),
        ):
            object.__setattr__(self, field_name, _planner_metadata_tuple(values, field_name))
        for field_name, values, key in (
            ("capabilities", self.capabilities, lambda value: value.capability_id),
            ("skills", self.skills, lambda value: value.skill_id),
            ("methods", self.methods, lambda value: value.method_id),
            ("constraints", self.constraints, lambda value: value.name),
            ("authorization_facts", self.authorization_facts, lambda value: value.name),
            ("resolved_referents", self.resolved_referents, lambda value: value.referent_id),
        ):
            identifiers = [key(value) for value in values]
            if len(identifiers) != len(set(identifiers)):
                raise DynamicPlanPolicyError("%s cannot contain duplicate identifiers" % field_name)

    @classmethod
    def from_runtime(
        cls,
        *,
        request_id: str,
        goal_class: str,
        normalized_intent: str,
        task_context_ref: str,
        context_version: int,
        capability_catalog: CapabilityCatalog,
        skill_registry: SkillRegistry,
        method_registry: CapabilityMethodRegistry | None,
        available_tools: Iterable[str],
        available_permissions: Iterable[str],
        available_platforms: Iterable[str],
        constraints: Iterable[PlannerConstraintState] = (),
        authorization_facts: Iterable[PlannerAuthorizationFact] = (),
        resolved_referents: Iterable[PlannerReferent] = (),
        prior_step_results: Iterable[PlannerStepResult] = (),
        recent_verification_evidence: Iterable[str] = (),
        preference_codes: Iterable[str] = (),
        sensitivity_codes: Iterable[str] = (),
        risk_constraints: Iterable[str] = (),
    ) -> "PlannerInput":
        if not isinstance(capability_catalog, CapabilityCatalog) or not isinstance(skill_registry, SkillRegistry):
            raise DynamicPlanPolicyError("Planner runtime requires existing Capability and Skill registries")
        skill_contracts = skill_registry.contracts()
        active_skill_ids = frozenset(
            str(contract["skill_id"]) for contract in skill_contracts if contract.get("status") == "active"
        )
        capability_contexts = tuple(
            PlannerCapabilityContext.from_contract(contract, active_skill_ids)
            for contract in capability_catalog.contracts()
        )
        method_contexts: list[PlannerMethodContext] = []
        permissions = tuple(available_permissions)
        platforms = tuple(available_platforms)
        if method_registry is not None:
            if not isinstance(method_registry, CapabilityMethodRegistry) or method_registry.catalog is not capability_catalog:
                raise DynamicPlanPolicyError("method registry must use the provided Capability Catalog")
            for capability in capability_contexts:
                method_contexts.extend(
                    PlannerMethodContext.from_candidate(candidate)
                    for candidate in method_registry.assess(
                        capability.capability_id,
                        available_permissions=permissions,
                        available_platforms=platforms,
                    )
                )
        return cls(
            request_id=request_id,
            goal_class=goal_class,
            normalized_intent=normalized_intent,
            task_context_ref=task_context_ref,
            context_version=context_version,
            capabilities=capability_contexts,
            skills=tuple(PlannerSkillContext.from_contract(contract) for contract in skill_contracts),
            methods=tuple(method_contexts),
            available_tools=tuple(sorted(set(available_tools))),
            available_permissions=tuple(sorted(set(permissions))),
            available_platforms=tuple(sorted(set(platforms))),
            constraints=tuple(constraints),
            authorization_facts=tuple(authorization_facts),
            resolved_referents=tuple(resolved_referents),
            prior_step_results=tuple(prior_step_results),
            recent_verification_evidence=tuple(recent_verification_evidence),
            preference_codes=tuple(preference_codes),
            sensitivity_codes=tuple(sensitivity_codes),
            risk_constraints=tuple(risk_constraints),
        )

    def public_summary(self) -> dict[str, Any]:
        return {
            "dynamic_planner_version": DYNAMIC_PLANNER_BRAIN_VERSION,
            "request_id": self.request_id,
            "goal_class": self.goal_class,
            "normalized_intent": self.normalized_intent,
            "task_context_ref": self.task_context_ref,
            "context_version": self.context_version,
            "planning_revision": self.planning_revision,
            "replan_count": self.replan_count,
            "capability_count": len(self.capabilities),
            "skill_count": len(self.skills),
            "method_count": len(self.methods),
            "referent_count": len(self.resolved_referents),
            "prior_step_result_count": len(self.prior_step_results),
            "sensitivity_codes": list(self.sensitivity_codes),
            "execution_authority": "none",
        }


@dataclass(frozen=True)
class PlannerProposal:
    """Provider-neutral candidate selection with no tool or command fields."""

    candidate_skill_ids: tuple[str, ...]
    reason_codes: tuple[str, ...]

    def __post_init__(self) -> None:
        object.__setattr__(self, "candidate_skill_ids", _planner_metadata_tuple(self.candidate_skill_ids, "candidate skill"))
        object.__setattr__(self, "reason_codes", _planner_metadata_tuple(self.reason_codes, "proposal reason"))


class DeterministicPlanProposalProvider:
    """LLM-free proposal provider for the frozen TEST-53 contract."""

    def propose(self, planner_input: PlannerInput) -> PlannerProposal:
        matches = tuple(
            skill.skill_id
            for skill in planner_input.skills
            if skill.status == "active" and planner_input.normalized_intent in skill.intent_kinds
        )
        reason = "unique_active_skill_match" if len(matches) == 1 else "skill_match_not_unique"
        return PlannerProposal(matches, (reason,))


@dataclass(frozen=True)
class DynamicPlanStep:
    step_id: str
