def _s1_keycode_usage(ch: str) -> int | None:
    """Map a character to its HID keycode usage; None when not dispatchable."""

    if "a" <= ch <= "z":
        return 0x04 + (ord(ch) - ord("a"))
    if "1" <= ch <= "9":
        return 0x1E + (int(ch) - 1)
    if ch == "0":
        return 0x27
    if ch == " ":
        return 0x2C
    return None


class InputTextActionBindingError(ValueError):
    """An opaque input action is stale, forged, or outside its typed contract."""


@dataclass(frozen=True)
class InputTextTargetAuthorization:
    """A Risk-issued handle, not authority merely because its fields are valid."""

    task_id: str
    context_id: str
    context_version: int
    authorization_ref: str
    keyboard: str
    clear_available: bool = False
    paste_point: tuple[float, float] | None = None
    field_ref: str = ""
    observation_version: int = 0
    page_fingerprint: str = ""

    def __post_init__(self) -> None:
        for field_name in ("task_id", "context_id", "authorization_ref", "keyboard"):
            value = getattr(self, field_name)
            if not isinstance(value, str) or not value:
                raise InputTextActionBindingError("%s must be a non-empty opaque value" % field_name)
        if isinstance(self.context_version, bool) or not isinstance(self.context_version, int) or self.context_version < 1:
            raise InputTextActionBindingError("context_version must be positive")
        if self.paste_point is not None:
            if (
                not isinstance(self.paste_point, tuple)
                or len(self.paste_point) != 2
                or any(isinstance(value, bool) or not isinstance(value, (int, float)) for value in self.paste_point)
            ):
                raise InputTextActionBindingError("paste_point must be a private numeric pair")


@dataclass(frozen=True)
class InputTextStrategyPlan:
    """Private strategy output with no transport, binding, or execution authority."""

    text: str = field(repr=False)
    keyboard: str
    strategies: tuple[str, ...]
    sensitive: bool

    def summary(self) -> dict[str, Any]:
        return {
            "strategy_count": len(self.strategies),
            "strategies": list(self.strategies),
            "keyboard": self.keyboard,
            "sensitive": self.sensitive,
            "text_len": len(self.text),
            "text_sha16": hashlib.sha256(self.text.encode("utf-8")).hexdigest()[:16],
            "execution_authority": "none",
        }


class InputTextOrchestrator:
    """Choose S1/S4 candidates only; it never observes or calls a device."""

    KEYBOARD_APPLE = frozenset({"apple_pinyin_9key", "apple_qwerty"})
    S1_MAX_CHARS = 32

    @staticmethod
    def _s1_eligible(text: str) -> bool:
        return bool(text) and len(text) <= InputTextOrchestrator.S1_MAX_CHARS and all(
            _s1_keycode_usage(ch) is not None for ch in text
        )

    def prepare(self, text: str, *, keyboard: str, sensitive: bool = False) -> InputTextStrategyPlan:
        if not isinstance(text, str) or not text:
            raise InputTextActionBindingError("text must be non-empty")
        if not isinstance(keyboard, str) or not keyboard:
            raise InputTextActionBindingError("keyboard must be supplied by prior observation")
        apple = keyboard in self.KEYBOARD_APPLE
        strategies: list[str] = []
        if apple and self._s1_eligible(text):
            strategies.append("s1_keycode")
        if not sensitive:
            strategies.append("s4_clipboard")
        return InputTextStrategyPlan(text=text, keyboard=keyboard, strategies=tuple(strategies), sensitive=bool(sensitive))


@dataclass(frozen=True)
class _InputTextActionBinding:
    binding_id: str
    task_id: str
    context_id: str
    authorization_ref: str
    tool: str
    step_id: str
    arguments: dict[str, Any] = field(repr=False)
    expected_text: str = field(repr=False)
    require_delivery: bool
    target: InputTextTargetAuthorization
    expected_before: str = field(repr=False)
    expected_after: str = field(repr=False)
    consumed: bool = False


class InputTextActionBindingStore:
    """One-time private input payload bindings consumed only by PlanExecutor."""

    _ID_PREFIX = "inputaction."
    _ALLOWED_TOOLS = frozenset({"tap_element", "exp_keycode_tap", "set_clipboard", "long_press"})

    def __init__(self) -> None:
        self._bindings: dict[str, _InputTextActionBinding] = {}
        self._risk: RiskController | None = None
        self._client: MCPClient | None = None
        self._lock = threading.RLock()

    def use_authority(self, risk: RiskController, client: MCPClient) -> None:
        with self._lock:
            if self._risk is not None and (self._risk is not risk or self._client is not client):
                raise InputTextActionBindingError("INPUT_BINDING_AUTHORITY_MISMATCH")
            self._risk, self._client = risk, client

    def create(
        self,
        *,
        target: InputTextTargetAuthorization,
        tool: str,
        step_id: str,
        arguments: dict[str, Any],
        expected_text: str,
        require_delivery: bool,
        expected_before: str = "",
        expected_after: str = "",
    ) -> str:
        with self._lock:
            risk = self._risk
            client = self._client
        if risk is None:
            raise InputTextActionBindingError("INPUT_RISK_AUTHORITY_REQUIRED")
        grant = risk._input_grant(target, text=expected_text, client=client)
        if not grant["started"] or grant["store"] is not self:
            raise InputTextActionBindingError("INPUT_AUTHORIZATION_NOT_RESERVED")
        # Clear/paste selectors have no same-leaf control contract yet. Never
        # substitute a page-wide label or a caller-supplied coordinate for one.
        if (tool != "exp_keycode_tap" or type(arguments) is not dict or set(arguments) != {"page", "usage"}
                or not isinstance(step_id, str) or not step_id
                or type(arguments["page"]) is not int or arguments["page"] != 7
                or type(arguments["usage"]) is not int or not expected_after
                or expected_after[:-1] != expected_before or not expected_text.startswith(expected_after)
                or arguments["usage"] != _s1_keycode_usage(expected_after[-1])
                or len(expected_before) != grant["verified_length"]):
            raise InputTextActionBindingError("INPUT_ACTION_SCHEMA_OR_SEQUENCE_INVALID")
        binding_id = self._ID_PREFIX + uuid4().hex
        with self._lock:
            self._bindings[binding_id] = _InputTextActionBinding(
                binding_id=binding_id,
                task_id=target.task_id,
                context_id=target.context_id,
                authorization_ref=target.authorization_ref,
                tool=tool,
                step_id=step_id,
                arguments=dict(arguments),
                expected_text=expected_text,
                require_delivery=bool(require_delivery),
                target=target,
                expected_before=expected_before,
                expected_after=expected_after,
            )
        return binding_id

    def prepare(self, binding_id: str, *, task_id: str, context_id: str) -> None:
        binding = self._binding(binding_id, task_id=task_id, context_id=context_id)
        self._risk.observe_input_target(binding.target, expected_query=binding.expected_before)

    def claim(self, binding_id: str, *, tool: str, step_id: str, task_id: str, context_id: str,
              risk_controller: RiskController | None = None, client: MCPClient | None = None) -> dict[str, Any]:
        with self._lock:
            binding = self._binding(binding_id, task_id=task_id, context_id=context_id)
            if (binding.consumed or binding.tool != tool or binding.step_id != step_id
                    or risk_controller is not self._risk or client is not self._client):
                raise InputTextActionBindingError("INPUT_BINDING_STALE_OR_MISMATCHED")
        # Fresh observation may cross the existing provider boundary, so it is
        # deliberately outside the binding lock. Claim remains atomic below.
        self.prepare(binding_id, task_id=task_id, context_id=context_id)
        with self._lock:
            binding = self._binding(binding_id, task_id=task_id, context_id=context_id)
            if (binding.consumed or binding.tool != tool or binding.step_id != step_id
                    or risk_controller is not self._risk or client is not self._client):
                raise InputTextActionBindingError("INPUT_BINDING_STALE_OR_MISMATCHED")
            self._bindings[binding_id] = replace(binding, consumed=True)
            return dict(binding.arguments)

    def validate_plan(self, plan: dict[str, Any], risk: RiskController, target: InputTextTargetAuthorization) -> None:
        spec = plan.get("verification") or {}
        with self._lock:
            binding = self._binding(spec.get("input_text_action_binding_id"), task_id=target.task_id, context_id=target.context_id)
            if (risk is not self._risk or binding.target is not target or binding.consumed
                    or spec.get("kind") != "input_text_action_observed"
                    or spec.get("task_id") != target.task_id or spec.get("context_id") != target.context_id
                    or plan.get("steps") != [{"id": binding.step_id, "tool": binding.tool,
                                             "arguments": {"input_text_action_binding_id": binding.binding_id}}]):
                raise InputTextActionBindingError("INPUT_PLAN_AUTHORIZATION_MISMATCH")

    def expected_value(self, binding_id: str, *, task_id: str, context_id: str) -> str:
        with self._lock:
            return self._binding(binding_id, task_id=task_id, context_id=context_id).expected_after

    def verify(self, binding_id: str, *, task_id: str, context_id: str, snapshot: SemanticSearchPageObservation) -> dict[str, Any]:
        with self._lock:
            binding = self._binding(binding_id, task_id=task_id, context_id=context_id)
        if not binding.consumed:
            raise InputTextActionBindingError("input action binding was not dispatched")
        self._risk.check_input_observation(binding.target, snapshot)
        matches = [item for item in snapshot.fields if item.field_ref == binding.target.field_ref]
        observed = len(matches) == 1 and matches[0].expected_value_is_verified()
        if observed:
            grant = self._risk._input_grant(binding.target)
            grant["verified_length"] = len(binding.expected_after)
        return {
            "passed": observed,
            "verification_result": "INPUT_TARGET_VALUE_VERIFIED" if observed else "INPUT_TARGET_VALUE_NOT_VERIFIED",
        }

    def discard(self, target: InputTextTargetAuthorization) -> None:
        with self._lock:
            self._bindings = {key: binding for key, binding in self._bindings.items() if binding.target is not target}

    def _binding(self, binding_id: str, *, task_id: str, context_id: str) -> _InputTextActionBinding:
        with self._lock:
            binding = self._bindings.get(binding_id)
            if binding is None or binding.task_id != task_id or binding.context_id != context_id:
                raise InputTextActionBindingError("input action binding is unavailable or cross-task")
            return binding


class GovernedInputTextRuntime:
    """Execute an already-authorized strategy only through existing governance.

    The orchestration layer emits strategy candidates.  This runtime performs a
    fresh Risk preflight, gives every external action a one-time typed binding
    and a TEST-45 obligation, then delegates dispatch and verification to the
    existing PlanExecutor.  It intentionally has no direct MCP call surface.
    """

    CAPABILITY_ID = "capability.text_input.v1"
    SKILL_NAME = "governed_input_text_attempt"
    CLEAR_LABEL = "清除文本"
    PASTE_LABEL = "粘贴"
    S1_KEYCODE_PAGE = 7

    def __init__(
        self,
        client: Any,
        *,
        capability_method_registry: CapabilityMethodRegistry,
        action_obligation_ledger: ActionObligationLedger,
        risk_controller: RiskController | None = None,
        binding_store: InputTextActionBindingStore | None = None,
        orchestrator: InputTextOrchestrator | None = None,
    ) -> None:
        if not isinstance(capability_method_registry, CapabilityMethodRegistry):
            raise TypeError("governed input requires CapabilityMethodRegistry")
        if not isinstance(action_obligation_ledger, ActionObligationLedger):
            raise TypeError("governed input requires ActionObligationLedger")
        self._client = client
        self._methods = capability_method_registry
        self._ledger = action_obligation_ledger
        self._risk = risk_controller or RiskController()
        self._bindings = binding_store or InputTextActionBindingStore()
        self._bindings.use_authority(self._risk, client)
        self._orchestrator = orchestrator or InputTextOrchestrator()
        self.plan_executor_invocation_count = 0

    def execute(
        self,
        text: str,
        *,
        target: InputTextTargetAuthorization | None,
        sensitive: bool = False,
    ) -> dict[str, Any]:
        if not isinstance(target, InputTextTargetAuthorization):
            return self._blocked("DIRECT_INPUT_AUTHORIZATION_REQUIRED")
        try:
            self._risk.begin_input_target(target, text, sensitive, self._client, self._bindings)
        except (InputTextActionBindingError, UnicodeError):
            return self._blocked("DIRECT_INPUT_AUTHORIZATION_REQUIRED")
        try:
            return self._execute_authorized(text, target=target, sensitive=sensitive)
        finally:
            self._bindings.discard(target)
            self._risk.revoke_input_target(target)

    def _execute_authorized(self, text: str, *, target: InputTextTargetAuthorization, sensitive: bool) -> dict[str, Any]:
        try:
            strategy_plan = self._orchestrator.prepare(text, keyboard=target.keyboard, sensitive=sensitive)
        except InputTextActionBindingError as error:
            return self._blocked(str(error).upper().replace(" ", "_"))
        if not strategy_plan.strategies:
            return self._blocked("NO_SAFE_STRATEGY", strategy_plan=strategy_plan.summary())

        for strategy in strategy_plan.strategies:
            actions = self._actions_for(strategy_plan, target, strategy)
            if not actions:
                continue
            preflight = self._preflight(actions)
            if preflight is not None:
                # A denied candidate has not changed the device. A later
                # candidate may be considered only while this remains true.
                continue
            return self._execute_actions(strategy_plan, target, strategy, actions)
        return self._blocked("RISK_OR_METHOD_BLOCKED", strategy_plan=strategy_plan.summary())

    def _actions_for(
        self,
        strategy_plan: InputTextStrategyPlan,
        target: InputTextTargetAuthorization,
        strategy: str,
    ) -> list[dict[str, Any]]:
        method_id = _INPUT_TEXT_STRATEGY_METHOD_IDS.get(strategy)
        if method_id is None or self._method_contract(method_id) is None:
            return []
        actions: list[dict[str, Any]] = []
        if target.clear_available:
            return []
        if strategy == "s1_keycode":
            for index, char in enumerate(strategy_plan.text, start=1):
                usage = _s1_keycode_usage(char)
                if usage is None:
                    return []
                actions.append(
                    {
                        "tool": "exp_keycode_tap",
                        "arguments": {"page": self.S1_KEYCODE_PAGE, "usage": usage},
                        "delivery": True,
                        "expected_before": strategy_plan.text[:index - 1],
                        "expected_after": strategy_plan.text[:index],
                    }
                )
        elif strategy == "s4_clipboard" and target.paste_point is not None:
            x, y = target.paste_point
            actions.extend(
                (
                    {"tool": "set_clipboard", "arguments": {"text": strategy_plan.text}, "delivery": False},
                    {"tool": "long_press", "arguments": {"x": x, "y": y, "duration": 600}, "delivery": False},
                    {"tool": "tap_element", "arguments": {"text": self.PASTE_LABEL}, "delivery": True},
                )
            )
        else:
            return []
        for action in actions:
            action["method_id"] = method_id
        return actions

    def _preflight(self, actions: list[dict[str, Any]]) -> dict[str, Any] | None:
        for action in actions:
            plan = self._plan_for(action["tool"], "preflight", "unused", "unused", "unused")
            # This non-executable policy probe carries no binding. The real
            # action below must pass assess() again with an issued receipt.
            plan["steps"][0]["arguments"] = {}
            assessment = self._risk.assess(plan)
            if assessment.get("status") != "allowed":
                return assessment
        return None

    def _execute_actions(
        self,
        strategy_plan: InputTextStrategyPlan,
        target: InputTextTargetAuthorization,
        strategy: str,
        actions: list[dict[str, Any]],
    ) -> dict[str, Any]:
        attempts: list[dict[str, Any]] = []
        executor = PlanExecutor(
            self._client,
            risk_controller=self._risk,
            input_text_action_binding_store=self._bindings,
            action_obligation_ledger=self._ledger,
        )
        for index, action in enumerate(actions, start=1):
            try:
                if self._method_contract(action["method_id"]) is None:
                    raise InputTextActionBindingError("INPUT_METHOD_UNAVAILABLE")
                binding_id = self._bindings.create(
                    target=target,
                    tool=action["tool"],
                    step_id="input-action-%02d" % index,
                    arguments=action["arguments"],
                    expected_text=strategy_plan.text,
                    require_delivery=True,
                    expected_before=action.get("expected_before", ""),
                    expected_after=action.get("expected_after", ""),
                )
                self._bindings.prepare(binding_id, task_id=target.task_id, context_id=target.context_id)
                grant = self._risk._input_grant(target)
            except InputTextActionBindingError:
                return self._result(strategy_plan, strategy, attempts, {"status": "blocked"})
            plan = self._plan_for(
                action["tool"],
                "input-action-%02d" % index,
                binding_id,
                target.task_id,
                target.context_id,
            )
            plan["verification"]["input_authorization_ref"] = target.authorization_ref
            assessment = self._risk.assess(plan, grant["receipt"])
            if assessment.get("status") != "allowed":
                return self._result(strategy_plan, strategy, attempts, {"status": "blocked"})
            self.plan_executor_invocation_count += 1
            dispatches_before = executor.external_dispatch_count
            execution = executor.execute(
                plan,
                authorization=grant["receipt"],
                action_obligation=ActionObligationRequest(
                    obligation_ref="inputaction." + uuid4().hex,
                    task_id=target.task_id,
                    context_id=target.context_id,
                    capability_id=self.CAPABILITY_ID,
                    method_id=action["method_id"],
                    risk_level="interaction",
                ),
            )
            ledger = execution.get("action_obligation") if isinstance(execution.get("action_obligation"), dict) else {}
            attempts.append(
                {
                    "attempt_id": index,
                    "strategy": strategy,
                    "method_id": action["method_id"],
                    "status": str(execution.get("status") or "failed"),
                    "ledger_state": str(ledger.get("state") or "UNAVAILABLE"),
                    "verification_result": (execution.get("verification") or {}).get("verification_result"),
                    "dispatch_count": executor.external_dispatch_count - dispatches_before,
                    "text_len": len(strategy_plan.text),
                    "text_sha16": hashlib.sha256(strategy_plan.text.encode("utf-8")).hexdigest()[:16],
                }
            )
            if execution.get("status") != "passed":
                return self._result(strategy_plan, strategy, attempts, execution)
        return self._result(strategy_plan, strategy, attempts, None)

    def _plan_for(self, tool: str, step_id: str, binding_id: str, task_id: str, context_id: str) -> dict[str, Any]:
        skill = {
            "name": self.SKILL_NAME,
            "risk_level": "interaction",
            "allowed_tools": [tool],
        }
        return {
            "status": "ready",
            "selected_tools": [tool],
            "skill_selection": {"status": "ready", "selected_tools": [tool], "skill": skill},
            "steps": [{"id": step_id, "tool": tool, "arguments": {"input_text_action_binding_id": binding_id}}],
            "verification": {
                "kind": "input_text_action_observed",
                "input_text_action_binding_id": binding_id,
                "task_id": task_id,
                "context_id": context_id,
            },
        }

    def _method_contract(self, method_id: str) -> dict[str, Any] | None:
        method = self._methods.get(method_id)
        if not isinstance(method, dict) or method.get("capability_id") != self.CAPABILITY_ID:
            return None
        if method.get("verifier") != "input_text_action_observed":
            return None
        if method.get("lifecycle") != "ACTIVE" or method.get("availability") != "available":
            return None
        health = method.get("method_health")
        if isinstance(health, dict) and health.get("compatibility") == "incompatible":
            return None
        return method

    @staticmethod
    def _result(
        strategy_plan: InputTextStrategyPlan,
        strategy: str,
        attempts: list[dict[str, Any]],
        execution: dict[str, Any] | None,
    ) -> dict[str, Any]:
        return {
            "status": "completed" if execution is None else str(execution.get("status") or "failed"),
            "strategy": strategy,
            "attempts": attempts,
            "dispatched": any(attempt.get("dispatch_count", 0) > 0 for attempt in attempts),
            "delivery": "unverified",
            "semantic_success": "VERIFIER_REQUIRED",
            "text_len": len(strategy_plan.text),
            "text_sha16": hashlib.sha256(strategy_plan.text.encode("utf-8")).hexdigest()[:16],
            "device_action_count": sum(attempt.get("dispatch_count", 0) for attempt in attempts),
        }

    @staticmethod
    def _blocked(reason_code: str, *, strategy_plan: dict[str, Any] | None = None) -> dict[str, Any]:
        return {
            "status": "blocked",
            "reason_code": reason_code,
            "strategy_plan": strategy_plan,
            "attempts": [],
            "dispatched": False,
            "delivery": "unverified",
            "semantic_success": "VERIFIER_REQUIRED",
            "device_action_count": 0,
        }
